    /** pdoc search index */const docs = [{"fullname": "dftscape", "modulename": "dftscape", "kind": "module", "doc": "<h1 id=\"dftscape-critical-point-landscape-exploration\">DFTScape: Critical Point Landscape Exploration</h1>\n\n<p>DFTScape is a specialized framework for systematic exploration of molecular\npotential energy landscapes through advanced search algorithms. It focuses on\ndiscovering and characterizing critical points (minima, saddles, maxima) and\ntheir connectivity using High index saddle dynamics (HiSD) methods.</p>\n\n<h1 id=\"key-features\">Key Features</h1>\n\n<h6 id=\"critical-point-discovery\">Critical Point Discovery:</h6>\n\n<blockquote>\n  <ul>\n  <li>Systematic exploration of potential energy landscapes</li>\n  <li>Discovery of minima, saddles, and maxima using HiSD methods</li>\n  <li>Characterization of critical point properties (energies, Hessians)</li>\n  <li>Automatic classification of stationary point types</li>\n  </ul>\n</blockquote>\n\n<h6 id=\"advanced-search-algorithms\">Advanced Search Algorithms:</h6>\n\n<blockquote>\n  <ul>\n  <li>High index saddle dynamics (HiSD) for critical point finding</li>\n  <li>Upward and downward search directions for comprehensive landscape mapping</li>\n  <li>Parallel search execution with intelligent job queue management</li>\n  <li>Adaptive search strategies based on landscape topology</li>\n  </ul>\n</blockquote>\n\n<h6 id=\"landscape-connectivity-analysis\">Landscape Connectivity Analysis:</h6>\n\n<blockquote>\n  <ul>\n  <li>Construction of searchable critical point graphs</li>\n  <li>Identification of reaction pathways and transition networks</li>\n  <li>Analysis of energy barriers and reaction mechanisms</li>\n  <li>Visualization of connected critical point networks</li>\n  </ul>\n</blockquote>\n\n<h6 id=\"multiple-computational-backends\">Multiple Computational Backends:</h6>\n\n<blockquote>\n  <ul>\n  <li>Psi4: Production quantum chemistry calculations</li>\n  <li>Test: Analytical test functions for algorithm validation</li>\n  <li>Extensible: Easy integration of custom backends (ML-IAP, force fields, etc.)</li>\n  </ul>\n</blockquote>\n\n<h6 id=\"robust-execution-framework\">Robust Execution Framework:</h6>\n\n<blockquote>\n  <ul>\n  <li>Parallel job execution with dependency management</li>\n  <li>Comprehensive checkpointing and recovery capabilities</li>\n  <li>Real-time progress monitoring and analytics</li>\n  <li>Error handling and job failure recovery</li>\n  </ul>\n</blockquote>\n\n<h1 id=\"installation\">Installation</h1>\n\n<p><em>pip installer instruction will be updated after publishing</em></p>\n\n<h2 id=\"manual-installation\">Manual installation</h2>\n\n<p>Clone the repository</p>\n\n<div class=\"pdoc-code codehilite\">\n<pre><span></span><code>git<span class=\"w\"> </span>clone<span class=\"w\"> </span>https://github.com/MLDS-NUS/dftscape.git\n<span class=\"nb\">cd</span><span class=\"w\"> </span>dftscape\n</code></pre>\n</div>\n\n<h3 id=\"step-1-install-uv-and-set-up-the-environment\">\ud83d\udce6 Step 1: Install uv and set up the environment</h3>\n\n<p>Packages are managed with <a href=\"https://docs.astral.sh/uv/\"><code>uv</code></a>.</p>\n\n<p><strong>Install <code>uv</code></strong> \ud83d\udee0\ufe0f</p>\n\n<div class=\"pdoc-code codehilite\">\n<pre><span></span><code>curl<span class=\"w\"> </span>-LsSf<span class=\"w\"> </span>https://astral.sh/uv/install.sh<span class=\"w\"> </span><span class=\"p\">|</span><span class=\"w\"> </span>sh\n</code></pre>\n</div>\n\n<p><strong>Set up the environment</strong> \ud83c\udf0d</p>\n\n<div class=\"pdoc-code codehilite\">\n<pre><span></span><code>uv<span class=\"w\"> </span>python<span class=\"w\"> </span>install<span class=\"w\"> </span><span class=\"m\">3</span>.13\nuv<span class=\"w\"> </span>sync\nuv<span class=\"w\"> </span>pip<span class=\"w\"> </span>install<span class=\"w\"> </span>-e<span class=\"w\"> </span>.\n</code></pre>\n</div>\n\n<h3 id=\"step-2-install-the-psi4-backend\">\ud83d\udd2c Step 2: Install the Psi4 Backend</h3>\n\n<p><em>\ud83d\udd2e More backend support coming in the future!</em></p>\n\n<p>The following is an example for <strong>MacOS Silicon</strong> with <code>python 3.13</code>.\nFind the release suitable for your system <a href=\"https://psicode.org/installs/v191/\">here</a> and substitute accordingly.</p>\n\n<p><strong>Download binary package</strong> \ud83d\udce5</p>\n\n<div class=\"pdoc-code codehilite\">\n<pre><span></span><code>curl<span class=\"w\"> </span><span class=\"s2\">&quot;https://vergil.chemistry.gatech.edu/psicode-download/Psi4conda-1.9.1-py313-MacOSX-arm64.sh&quot;</span><span class=\"w\"> </span>-o<span class=\"w\"> </span>Psi4conda-1.9.1-py313-MacOSX-arm64.sh<span class=\"w\"> </span>--keepalive-time<span class=\"w\"> </span><span class=\"m\">2</span>\n</code></pre>\n</div>\n\n<p><strong>Install the <code>Psi4</code> package</strong> \u2699\ufe0f\n(Assume location is <code>$HOME/psi4-1.9.1</code>)</p>\n\n<div class=\"pdoc-code codehilite\">\n<pre><span></span><code><span class=\"nv\">INSTALL</span><span class=\"o\">=</span><span class=\"s2\">&quot;</span><span class=\"nv\">$HOME</span><span class=\"s2\">/psi4-1.9.1&quot;</span>\nbash<span class=\"w\"> </span>Psi4conda-1.9.1-py313-MacOSX-arm64.sh<span class=\"w\"> </span>-b<span class=\"w\"> </span>-p<span class=\"w\"> </span><span class=\"s2\">&quot;</span><span class=\"nv\">$INSTALL</span><span class=\"s2\">&quot;</span>\n</code></pre>\n</div>\n\n<p>You should now have something like this (check with <code>ls \"$INSTALL\"</code>)</p>\n\n<div class=\"pdoc-code codehilite\">\n<pre><span></span><code><span class=\"nv\">$INSTALL</span>/\n<span class=\"w\">  </span>bin/\n<span class=\"w\">  </span>lib/\n<span class=\"w\">  </span>pkgs/\n<span class=\"w\">  </span>...\n<span class=\"w\">  </span>lib/python3.11/site-packages/psi4/<span class=\"w\">  </span><span class=\"c1\"># &lt;-- the Python module we want to import</span>\n</code></pre>\n</div>\n\n<p><strong>Activate local environment</strong> \ud83d\udd11</p>\n\n<div class=\"pdoc-code codehilite\">\n<pre><span></span><code><span class=\"nb\">source</span><span class=\"w\"> </span>.venv/bin/activate\npython<span class=\"w\"> </span>-V<span class=\"w\">  </span><span class=\"c1\"># &lt;-- verify the version (e.g., 3.13.x)</span>\n</code></pre>\n</div>\n\n<p><strong>Make venv see Psi4</strong> \ud83d\udd17</p>\n\n<div class=\"pdoc-code codehilite\">\n<pre><span></span><code><span class=\"nv\">SP</span><span class=\"o\">=</span><span class=\"k\">$(</span>python<span class=\"w\"> </span>-c<span class=\"w\"> </span><span class=\"s2\">&quot;import sysconfig; print(sysconfig.get_paths()[&#39;purelib&#39;])&quot;</span><span class=\"k\">)</span><span class=\"w\">  </span><span class=\"c1\"># &lt;-- find this venv&#39;s site-packages</span>\n<span class=\"nb\">echo</span><span class=\"w\"> </span><span class=\"s2\">&quot;</span><span class=\"nv\">$INSTALL</span><span class=\"s2\">/lib/python3.13/site-packages&quot;</span><span class=\"w\"> </span>&gt;<span class=\"w\"> </span><span class=\"s2\">&quot;</span><span class=\"nv\">$SP</span><span class=\"s2\">/psi4_external.pth&quot;</span><span class=\"w\">  </span><span class=\"c1\"># &lt;-- write a .pth that adds the installer site-packages to sys.path</span>\n</code></pre>\n</div>\n\n<p><strong>Verify installation</strong> \u2705</p>\n\n<div class=\"pdoc-code codehilite\">\n<pre><span></span><code>python<span class=\"w\"> </span>-<span class=\"w\"> </span><span class=\"s\">&lt;&lt;&#39;PY&#39;</span>\n<span class=\"s\">import sys, psi4</span>\n<span class=\"s\">print(&quot;Python:&quot;, sys.version.split()[0])</span>\n<span class=\"s\">print(&quot;Psi4:&quot;, psi4.__version__)</span>\n<span class=\"s\">print(&quot;Psi4 module from:&quot;, psi4.__file__)</span>\n<span class=\"s\">PY</span>\n</code></pre>\n</div>\n\n<h1 id=\"quick-start\">Quick Start</h1>\n\n<h6 id=\"basic-landscape-exploration\">Basic Landscape Exploration:</h6>\n\n<blockquote>\n  <div class=\"pdoc-code codehilite\">\n<pre><span></span><code><span class=\"gp\">&gt;&gt;&gt; </span><span class=\"kn\">from</span><span class=\"w\"> </span><span class=\"nn\">dftscape.backends</span><span class=\"w\"> </span><span class=\"kn\">import</span> <span class=\"n\">BackendRegistry</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"kn\">from</span><span class=\"w\"> </span><span class=\"nn\">dftscape.core.search_orchestrator</span><span class=\"w\"> </span><span class=\"kn\">import</span> <span class=\"n\">SearchOrchestrator</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"kn\">from</span><span class=\"w\"> </span><span class=\"nn\">dftscape.core.graph</span><span class=\"w\"> </span><span class=\"kn\">import</span> <span class=\"n\">SearchableCriticalPointGraph</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"kn\">from</span><span class=\"w\"> </span><span class=\"nn\">dftscape.core.dynamics</span><span class=\"w\"> </span><span class=\"kn\">import</span> <span class=\"n\">HiSD</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"kn\">from</span><span class=\"w\"> </span><span class=\"nn\">dftscape.core.point</span><span class=\"w\"> </span><span class=\"kn\">import</span> <span class=\"n\">CriticalPoint</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"kn\">from</span><span class=\"w\"> </span><span class=\"nn\">dftscape.common.checkpoint</span><span class=\"w\"> </span><span class=\"kn\">import</span> <span class=\"n\">JSONCheckpointer</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"kn\">import</span><span class=\"w\"> </span><span class=\"nn\">numpy</span><span class=\"w\"> </span><span class=\"k\">as</span><span class=\"w\"> </span><span class=\"nn\">np</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Set up quantum chemistry backend</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">backend</span> <span class=\"o\">=</span> <span class=\"n\">BackendRegistry</span><span class=\"o\">.</span><span class=\"n\">create</span><span class=\"p\">(</span><span class=\"s2\">&quot;psi4&quot;</span><span class=\"p\">,</span>\n<span class=\"gp\">... </span>    <span class=\"n\">cmp_mthd</span><span class=\"o\">=</span><span class=\"s2\">&quot;b3lyp/6-31g*&quot;</span><span class=\"p\">,</span>\n<span class=\"gp\">... </span>    <span class=\"n\">memory</span><span class=\"o\">=</span><span class=\"s2\">&quot;2GB&quot;</span><span class=\"p\">,</span>\n<span class=\"gp\">... </span>    <span class=\"n\">num_threads</span><span class=\"o\">=</span><span class=\"mi\">4</span><span class=\"p\">,</span>\n<span class=\"gp\">... </span>    <span class=\"n\">molecule_xyz</span><span class=\"o\">=</span><span class=\"s2\">&quot;3</span><span class=\"se\">\\n\\n</span><span class=\"s2\">O 0.0 0.0 0.0</span><span class=\"se\">\\n</span><span class=\"s2\">H 0.757 0.586 0.0</span><span class=\"se\">\\n</span><span class=\"s2\">H -0.757 0.586 0.0&quot;</span><span class=\"p\">,</span>\n<span class=\"gp\">... </span>    <span class=\"n\">molecule_directives</span><span class=\"o\">=</span><span class=\"p\">{</span><span class=\"s2\">&quot;charge&quot;</span><span class=\"p\">:</span> <span class=\"mi\">0</span><span class=\"p\">,</span> <span class=\"s2\">&quot;multiplicity&quot;</span><span class=\"p\">:</span> <span class=\"mi\">1</span><span class=\"p\">}</span>\n<span class=\"gp\">... </span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Initialize critical point graph</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">graph</span> <span class=\"o\">=</span> <span class=\"n\">SearchableCriticalPointGraph</span><span class=\"p\">()</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Set up HiSD dynamics</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">hisd</span> <span class=\"o\">=</span> <span class=\"n\">HiSD</span><span class=\"p\">(</span><span class=\"n\">backend</span><span class=\"o\">=</span><span class=\"n\">backend</span><span class=\"p\">,</span> <span class=\"n\">dt</span><span class=\"o\">=</span><span class=\"mf\">0.1</span><span class=\"p\">,</span> <span class=\"o\">...</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Create search orchestrator</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">orchestrator</span> <span class=\"o\">=</span> <span class=\"n\">SearchOrchestrator</span><span class=\"p\">(</span>\n<span class=\"gp\">... </span>    <span class=\"n\">graph</span><span class=\"o\">=</span><span class=\"n\">graph</span><span class=\"p\">,</span>\n<span class=\"gp\">... </span>    <span class=\"n\">hisd_runner</span><span class=\"o\">=</span><span class=\"n\">hisd</span><span class=\"p\">,</span>\n<span class=\"gp\">... </span>    <span class=\"n\">d_max</span><span class=\"o\">=</span><span class=\"mi\">3</span><span class=\"p\">,</span>  <span class=\"c1\"># Maximum search order</span>\n<span class=\"gp\">... </span>    <span class=\"n\">perturbation_magnitude</span><span class=\"o\">=</span><span class=\"mf\">0.1</span>\n<span class=\"gp\">... </span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Load initial critical point (e.g., global minimum)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">checkpointer</span> <span class=\"o\">=</span> <span class=\"n\">JSONCheckpointer</span><span class=\"p\">()</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">initial_point_data</span> <span class=\"o\">=</span> <span class=\"n\">checkpointer</span><span class=\"o\">.</span><span class=\"n\">load</span><span class=\"p\">(</span><span class=\"s2\">&quot;minimum.json&quot;</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">initial_point</span> <span class=\"o\">=</span> <span class=\"n\">CriticalPoint</span><span class=\"o\">.</span><span class=\"n\">from_config</span><span class=\"p\">(</span><span class=\"n\">initial_point_data</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">graph</span><span class=\"o\">.</span><span class=\"n\">add</span><span class=\"p\">(</span><span class=\"n\">initial_point</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Run upward search to find saddles and maxima</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">orchestrator</span><span class=\"o\">.</span><span class=\"n\">run_upward_search</span><span class=\"p\">()</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Analyze discovered critical points</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"sa\">f</span><span class=\"s2\">&quot;Found </span><span class=\"si\">{</span><span class=\"nb\">len</span><span class=\"p\">(</span><span class=\"n\">graph</span><span class=\"o\">.</span><span class=\"n\">nodes</span><span class=\"p\">)</span><span class=\"si\">}</span><span class=\"s2\"> critical points&quot;</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"k\">for</span> <span class=\"n\">node_id</span><span class=\"p\">,</span> <span class=\"n\">point</span> <span class=\"ow\">in</span> <span class=\"n\">graph</span><span class=\"o\">.</span><span class=\"n\">nodes</span><span class=\"o\">.</span><span class=\"n\">items</span><span class=\"p\">():</span>\n<span class=\"gp\">... </span>    <span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"sa\">f</span><span class=\"s2\">&quot;Point </span><span class=\"si\">{</span><span class=\"n\">node_id</span><span class=\"si\">}</span><span class=\"s2\">: Energy = </span><span class=\"si\">{</span><span class=\"n\">point</span><span class=\"o\">.</span><span class=\"n\">energy</span><span class=\"si\">:</span><span class=\"s2\">.6f</span><span class=\"si\">}</span><span class=\"s2\">, Index = </span><span class=\"si\">{</span><span class=\"n\">point</span><span class=\"o\">.</span><span class=\"n\">index</span><span class=\"si\">}</span><span class=\"s2\">&quot;</span><span class=\"p\">)</span>\n</code></pre>\n  </div>\n</blockquote>\n\n<h6 id=\"critical-point-characterization\">Critical Point Characterization:</h6>\n\n<blockquote>\n  <div class=\"pdoc-code codehilite\">\n<pre><span></span><code><span class=\"gp\">&gt;&gt;&gt; </span><span class=\"kn\">from</span><span class=\"w\"> </span><span class=\"nn\">dftscape.core.point</span><span class=\"w\"> </span><span class=\"kn\">import</span> <span class=\"n\">CriticalPoint</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Create critical point from coordinates</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">coords</span> <span class=\"o\">=</span> <span class=\"n\">np</span><span class=\"o\">.</span><span class=\"n\">array</span><span class=\"p\">([</span><span class=\"mf\">0.0</span><span class=\"p\">,</span> <span class=\"mf\">0.0</span><span class=\"p\">,</span> <span class=\"mf\">0.0</span><span class=\"p\">,</span> <span class=\"mf\">0.757</span><span class=\"p\">,</span> <span class=\"mf\">0.586</span><span class=\"p\">,</span> <span class=\"mf\">0.0</span><span class=\"p\">,</span> <span class=\"o\">-</span><span class=\"mf\">0.757</span><span class=\"p\">,</span> <span class=\"mf\">0.586</span><span class=\"p\">,</span> <span class=\"mf\">0.0</span><span class=\"p\">])</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">point</span> <span class=\"o\">=</span> <span class=\"n\">CriticalPoint</span><span class=\"o\">.</span><span class=\"n\">from_state</span><span class=\"p\">(</span><span class=\"n\">coords</span><span class=\"p\">,</span> <span class=\"n\">backend</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Analyze critical point properties</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">eigenvals</span> <span class=\"o\">=</span> <span class=\"n\">np</span><span class=\"o\">.</span><span class=\"n\">linalg</span><span class=\"o\">.</span><span class=\"n\">eigvals</span><span class=\"p\">(</span><span class=\"n\">point</span><span class=\"o\">.</span><span class=\"n\">hessian</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">n_negative</span> <span class=\"o\">=</span> <span class=\"n\">np</span><span class=\"o\">.</span><span class=\"n\">sum</span><span class=\"p\">(</span><span class=\"n\">eigenvals</span> <span class=\"o\">&lt;</span> <span class=\"mi\">0</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">point</span><span class=\"o\">.</span><span class=\"n\">index</span> <span class=\"o\">=</span> <span class=\"n\">n_negative</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"k\">if</span> <span class=\"n\">n_negative</span> <span class=\"o\">==</span> <span class=\"mi\">0</span><span class=\"p\">:</span>\n<span class=\"gp\">... </span>    <span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"s2\">&quot;Minimum found&quot;</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"k\">elif</span> <span class=\"n\">n_negative</span> <span class=\"o\">==</span> <span class=\"mi\">1</span><span class=\"p\">:</span>\n<span class=\"gp\">... </span>    <span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"s2\">&quot;Transition state found&quot;</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"k\">else</span><span class=\"p\">:</span>\n<span class=\"gp\">... </span>    <span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"s2\">&quot;Higher-order saddle found&quot;</span><span class=\"p\">)</span>\n</code></pre>\n  </div>\n</blockquote>\n\n<h1 id=\"architecture-overview\">Architecture Overview</h1>\n\n<p>DFTScape follows a modular architecture designed for systematic landscape exploration:</p>\n\n<h6 id=\"core-components\">Core Components:</h6>\n\n<blockquote>\n  <ul>\n  <li>backends: Computational engines for energy/derivative calculations</li>\n  <li>core: Search algorithms, graph management, and execution coordination</li>\n  <li>checkpoint: Data persistence and recovery for long-running searches</li>\n  </ul>\n</blockquote>\n\n<h6 id=\"search-system\">Search System:</h6>\n\n<blockquote>\n  <p>The search system uses HiSD (High index saddle dynamics) to\n  systematically explore potential energy landscapes. It can search in both\n  upward and downward directions to discover all critical points connected\n  to a given starting point.</p>\n</blockquote>\n\n<h6 id=\"graph-management\">Graph Management:</h6>\n\n<blockquote>\n  <p>Critical points are organized in a searchable graph structure that\n  maintains connectivity information and enables efficient querying of\n  reaction pathways and energy landscapes.</p>\n</blockquote>\n\n<h6 id=\"execution-framework\">Execution Framework:</h6>\n\n<blockquote>\n  <p>The orchestrator manages parallel job execution, dependency tracking,\n  and resource allocation for efficient landscape exploration.</p>\n</blockquote>\n\n<h1 id=\"main-modules\">Main Modules</h1>\n\n<p>dftscape.backends:\n    Computational backend implementations and registry system.</p>\n\n<pre><code>Available backends:\n- Psi4Backend: Production quantum chemistry with Psi4\n- TestBackend: Analytical test functions for validation\n</code></pre>\n\n<p>dftscape.core:\n    Core search functionality and landscape exploration algorithms.</p>\n\n<pre><code>Key components:\n- SearchOrchestrator: Main coordination system for search execution\n- HiSD: High index saddle dynamics for critical point finding\n- SearchableCriticalPointGraph: Graph structure for critical points\n- CriticalPoint: Data structure for stationary point characterization\n</code></pre>\n\n<p>dftscape.checkpoint:\n    Data persistence and recovery system for long-running searches.</p>\n\n<pre><code>Features:\n- Multiple storage formats (NPZ, JSON)\n- Automatic checkpointing during search\n- Recovery from interruptions\n- Export of critical point networks\n</code></pre>\n\n<h1 id=\"implementing-custom-backends\">Implementing Custom Backends</h1>\n\n<p>DFTScape supports custom backend implementations for specialized computational\nmethods. This enables integration of machine learning interatomic potentials,\nforce fields, or any computational method that can provide energies and derivatives.</p>\n\n<h6 id=\"backend-protocol-requirements\">Backend Protocol Requirements:</h6>\n\n<blockquote>\n  <p>All backends must implement the Backend protocol with four methods:</p>\n  \n  <ul>\n  <li>compute_energy(state): Calculate potential energy</li>\n  <li>compute_gradient(state): Calculate nuclear gradients</li>\n  <li>compute_hessian(state): Calculate nuclear Hessian</li>\n  <li>get_xyz(state): Export coordinates in XYZ format</li>\n  </ul>\n</blockquote>\n\n<p>For detailed implementation guidance, see:\n    dftscape.backends package documentation</p>\n\n<h6 id=\"example\">Example:</h6>\n\n<blockquote>\n  <div class=\"pdoc-code codehilite\">\n<pre><span></span><code><span class=\"gp\">&gt;&gt;&gt; </span><span class=\"kn\">from</span><span class=\"w\"> </span><span class=\"nn\">dftscape.backends</span><span class=\"w\"> </span><span class=\"kn\">import</span> <span class=\"n\">BackendRegistry</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"kn\">from</span><span class=\"w\"> </span><span class=\"nn\">dftscape.core.interfaces</span><span class=\"w\"> </span><span class=\"kn\">import</span> <span class=\"n\">Backend</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"nd\">@BackendRegistry</span><span class=\"o\">.</span><span class=\"n\">register</span><span class=\"p\">(</span><span class=\"s2\">&quot;ml_iap&quot;</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"k\">class</span><span class=\"w\"> </span><span class=\"nc\">MLInteratomicPotentialBackend</span><span class=\"p\">(</span><span class=\"n\">Backend</span><span class=\"p\">):</span>\n<span class=\"gp\">... </span>    <span class=\"k\">def</span><span class=\"w\"> </span><span class=\"fm\">__init__</span><span class=\"p\">(</span><span class=\"bp\">self</span><span class=\"p\">,</span> <span class=\"n\">model_path</span><span class=\"p\">:</span> <span class=\"nb\">str</span><span class=\"p\">,</span> <span class=\"n\">atomic_numbers</span><span class=\"p\">:</span> <span class=\"nb\">list</span><span class=\"p\">[</span><span class=\"nb\">int</span><span class=\"p\">]):</span>\n<span class=\"gp\">... </span>        <span class=\"bp\">self</span><span class=\"o\">.</span><span class=\"n\">model</span> <span class=\"o\">=</span> <span class=\"n\">load_ml_model</span><span class=\"p\">(</span><span class=\"n\">model_path</span><span class=\"p\">)</span>\n<span class=\"gp\">... </span>        <span class=\"bp\">self</span><span class=\"o\">.</span><span class=\"n\">atomic_numbers</span> <span class=\"o\">=</span> <span class=\"n\">atomic_numbers</span>\n<span class=\"gp\">...</span>\n<span class=\"gp\">... </span>    <span class=\"k\">def</span><span class=\"w\"> </span><span class=\"nf\">compute_energy</span><span class=\"p\">(</span><span class=\"bp\">self</span><span class=\"p\">,</span> <span class=\"n\">state</span><span class=\"p\">):</span>\n<span class=\"gp\">... </span>        <span class=\"n\">coords</span> <span class=\"o\">=</span> <span class=\"n\">state</span><span class=\"o\">.</span><span class=\"n\">reshape</span><span class=\"p\">(</span><span class=\"o\">-</span><span class=\"mi\">1</span><span class=\"p\">,</span> <span class=\"mi\">3</span><span class=\"p\">)</span>\n<span class=\"gp\">... </span>        <span class=\"k\">return</span> <span class=\"bp\">self</span><span class=\"o\">.</span><span class=\"n\">model</span><span class=\"o\">.</span><span class=\"n\">predict_energy</span><span class=\"p\">(</span><span class=\"n\">coords</span><span class=\"p\">,</span> <span class=\"bp\">self</span><span class=\"o\">.</span><span class=\"n\">atomic_numbers</span><span class=\"p\">)</span>\n<span class=\"gp\">...</span>\n<span class=\"gp\">... </span>    <span class=\"k\">def</span><span class=\"w\"> </span><span class=\"nf\">compute_gradient</span><span class=\"p\">(</span><span class=\"bp\">self</span><span class=\"p\">,</span> <span class=\"n\">state</span><span class=\"p\">):</span>\n<span class=\"gp\">... </span>        <span class=\"n\">coords</span> <span class=\"o\">=</span> <span class=\"n\">state</span><span class=\"o\">.</span><span class=\"n\">reshape</span><span class=\"p\">(</span><span class=\"o\">-</span><span class=\"mi\">1</span><span class=\"p\">,</span> <span class=\"mi\">3</span><span class=\"p\">)</span>\n<span class=\"gp\">... </span>        <span class=\"n\">forces</span> <span class=\"o\">=</span> <span class=\"bp\">self</span><span class=\"o\">.</span><span class=\"n\">model</span><span class=\"o\">.</span><span class=\"n\">predict_forces</span><span class=\"p\">(</span><span class=\"n\">coords</span><span class=\"p\">,</span> <span class=\"bp\">self</span><span class=\"o\">.</span><span class=\"n\">atomic_numbers</span><span class=\"p\">)</span>\n<span class=\"gp\">... </span>        <span class=\"k\">return</span> <span class=\"o\">-</span><span class=\"n\">forces</span><span class=\"o\">.</span><span class=\"n\">flatten</span><span class=\"p\">()</span>  <span class=\"c1\"># Convert forces to gradients</span>\n<span class=\"gp\">...</span>\n<span class=\"gp\">... </span>    <span class=\"k\">def</span><span class=\"w\"> </span><span class=\"nf\">compute_hessian</span><span class=\"p\">(</span><span class=\"bp\">self</span><span class=\"p\">,</span> <span class=\"n\">state</span><span class=\"p\">):</span>\n<span class=\"gp\">... </span>        <span class=\"c1\"># Use finite differences or analytical Hessian if available</span>\n<span class=\"gp\">... </span>        <span class=\"k\">return</span> <span class=\"bp\">self</span><span class=\"o\">.</span><span class=\"n\">_finite_difference_hessian</span><span class=\"p\">(</span><span class=\"n\">state</span><span class=\"p\">)</span>\n<span class=\"gp\">...</span>\n<span class=\"gp\">... </span>    <span class=\"k\">def</span><span class=\"w\"> </span><span class=\"nf\">get_xyz</span><span class=\"p\">(</span><span class=\"bp\">self</span><span class=\"p\">,</span> <span class=\"n\">state</span><span class=\"p\">):</span>\n<span class=\"gp\">... </span>        <span class=\"n\">coords</span> <span class=\"o\">=</span> <span class=\"n\">state</span><span class=\"o\">.</span><span class=\"n\">reshape</span><span class=\"p\">(</span><span class=\"o\">-</span><span class=\"mi\">1</span><span class=\"p\">,</span> <span class=\"mi\">3</span><span class=\"p\">)</span>\n<span class=\"gp\">... </span>        <span class=\"k\">return</span> <span class=\"n\">generate_xyz_string</span><span class=\"p\">(</span><span class=\"n\">coords</span><span class=\"p\">,</span> <span class=\"bp\">self</span><span class=\"o\">.</span><span class=\"n\">atomic_numbers</span><span class=\"p\">)</span>\n</code></pre>\n  </div>\n</blockquote>\n\n<h6 id=\"the-custom-backend-automatically-integrates-with-dftscape-search-algorithms\">The custom backend automatically integrates with DFTScape search algorithms:</h6>\n\n<blockquote>\n  <div class=\"pdoc-code codehilite\">\n<pre><span></span><code><span class=\"gp\">&gt;&gt;&gt; </span><span class=\"kn\">from</span><span class=\"w\"> </span><span class=\"nn\">dftscape.backends</span><span class=\"w\"> </span><span class=\"kn\">import</span> <span class=\"n\">BackendRegistry</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"kn\">from</span><span class=\"w\"> </span><span class=\"nn\">dftscape.core.search_orchestrator</span><span class=\"w\"> </span><span class=\"kn\">import</span> <span class=\"n\">SearchOrchestrator</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"kn\">from</span><span class=\"w\"> </span><span class=\"nn\">dftscape.core.graph</span><span class=\"w\"> </span><span class=\"kn\">import</span> <span class=\"n\">SearchableCriticalPointGraph</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"kn\">from</span><span class=\"w\"> </span><span class=\"nn\">dftscape.core.dynamics</span><span class=\"w\"> </span><span class=\"kn\">import</span> <span class=\"n\">HiSD</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"kn\">from</span><span class=\"w\"> </span><span class=\"nn\">dftscape.core.point</span><span class=\"w\"> </span><span class=\"kn\">import</span> <span class=\"n\">load_critical_point_from_file</span>  <span class=\"c1\"># Assuming this exists</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Initialize critical point graph (added for completeness)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">graph</span> <span class=\"o\">=</span> <span class=\"n\">SearchableCriticalPointGraph</span><span class=\"p\">()</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Load initial critical point (added for completeness)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">initial_point</span> <span class=\"o\">=</span> <span class=\"n\">load_critical_point_from_file</span><span class=\"p\">(</span><span class=\"s2\">&quot;minimum.json&quot;</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">graph</span><span class=\"o\">.</span><span class=\"n\">add_node</span><span class=\"p\">(</span><span class=\"n\">initial_point</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Use custom backend in landscape exploration</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">hisd</span> <span class=\"o\">=</span> <span class=\"n\">HiSD</span><span class=\"p\">(</span><span class=\"n\">backend</span><span class=\"o\">=</span><span class=\"n\">BackendRegistry</span><span class=\"o\">.</span><span class=\"n\">create</span><span class=\"p\">(</span><span class=\"s2\">&quot;ml_iap&quot;</span><span class=\"p\">,</span> <span class=\"n\">model_path</span><span class=\"o\">=</span><span class=\"s2\">&quot;model.pth&quot;</span><span class=\"p\">))</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">orchestrator</span> <span class=\"o\">=</span> <span class=\"n\">SearchOrchestrator</span><span class=\"p\">(</span><span class=\"n\">graph</span><span class=\"o\">=</span><span class=\"n\">graph</span><span class=\"p\">,</span> <span class=\"n\">hisd_runner</span><span class=\"o\">=</span><span class=\"n\">hisd</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">orchestrator</span><span class=\"o\">.</span><span class=\"n\">run_upward_search</span><span class=\"p\">()</span>\n</code></pre>\n  </div>\n</blockquote>\n\n<p>For comprehensive implementation examples and best practices, refer to:\n    dftscape.backends package documentation</p>\n\n<h1 id=\"api-reference\">API Reference</h1>\n\n<h6 id=\"core-classes\">Core Classes:</h6>\n\n<blockquote>\n  <p>BackendRegistry: Registry for computational backends\n  SearchOrchestrator: Main coordination system for landscape exploration\n  HiSD: High index saddle dynamics\n  SearchableCriticalPointGraph: Graph structure for critical points\n  CriticalPoint: Data structure for stationary point characterization</p>\n</blockquote>\n\n<h6 id=\"backend-protocol\">Backend Protocol:</h6>\n\n<blockquote>\n  <p>Backend: Protocol defining computational backend interface\n  Psi4Backend: Psi4 quantum chemistry backend\n  TestBackend: Analytical test function backend</p>\n</blockquote>\n\n<h6 id=\"search-components\">Search Components:</h6>\n\n<blockquote>\n  <p>SearchStrategy: Base class for search algorithm implementations\n  JobTracker: Job lifecycle and dependency management\n  NodeStateManager: Processing state coordination\n  SearchMonitor: Performance tracking and analytics</p>\n</blockquote>\n\n<h6 id=\"data-structures\">Data Structures:</h6>\n\n<blockquote>\n  <p>CriticalPoint: Stationary point with coordinates, energy, gradient, Hessian\n  SearchResult: Search operation result container\n  CheckpointData: Checkpoint data structure for persistence</p>\n</blockquote>\n\n<h1 id=\"contributing-and-extending\">Contributing and Extending</h1>\n\n<p>DFTScape is designed for easy extension and contribution:</p>\n\n<h6 id=\"adding-new-backends\">Adding New Backends:</h6>\n\n<blockquote>\n  <ol>\n  <li>Implement the Backend protocol</li>\n  <li>Register with @BackendRegistry.register decorator</li>\n  <li>Add comprehensive docstrings and examples</li>\n  <li>Include tests and validation</li>\n  </ol>\n</blockquote>\n\n<h6 id=\"adding-new-search-strategies\">Adding New Search Strategies:</h6>\n\n<blockquote>\n  <ol>\n  <li>Extend SearchStrategy base class</li>\n  <li>Implement search logic for critical point discovery</li>\n  <li>Add to search orchestrator with proper configuration</li>\n  <li>Provide usage examples and benchmarks</li>\n  </ol>\n</blockquote>\n\n<h6 id=\"code-quality\">Code Quality:</h6>\n\n<blockquote>\n  <ul>\n  <li>Follow PEP 8 style guidelines</li>\n  <li>Include comprehensive docstrings</li>\n  <li>Add unit tests for new functionality</li>\n  <li>Update documentation for API changes</li>\n  </ul>\n</blockquote>\n\n<h6 id=\"testing\">Testing:</h6>\n\n<blockquote>\n  <ul>\n  <li>Use pytest for unit testing</li>\n  <li>Include integration tests for search algorithms</li>\n  <li>Test against known analytical systems</li>\n  <li>Validate critical point characterization</li>\n  </ul>\n</blockquote>\n\n<h6 id=\"documentation\">Documentation:</h6>\n\n<blockquote>\n  <ul>\n  <li>Update docstrings for all public APIs</li>\n  <li>Add examples to documentation</li>\n  <li>Include mathematical formulations where relevant</li>\n  <li>Document limitations and assumptions</li>\n  </ul>\n</blockquote>\n\n<h1 id=\"see-also\">See Also</h1>\n\n<ul>\n<li>dftscape.backends: Backend implementations and custom backend development</li>\n<li>dftscape.core: Core search algorithms and landscape exploration</li>\n<li>dftscape.checkpoint: Data persistence and recovery</li>\n<li>Documentation: <a href=\"https://dftscape.readthedocs.io/\">https://dftscape.readthedocs.io/</a></li>\n<li>Repository: <a href=\"https://github.com/MLDS-NUS/dftscape\">https://github.com/MLDS-NUS/dftscape</a></li>\n</ul>\n"}, {"fullname": "dftscape.backends", "modulename": "dftscape.backends", "kind": "module", "doc": "<h1 id=\"dftscape-backends-package\">DFTScape Backends Package</h1>\n\n<p>The backends package provides a unified interface for computational engines\nin DFTScape. It supports quantum chemistry calculations, testing frameworks,\nand custom implementations through a pluggable architecture.</p>\n\n<p>The package implements the Backend protocol, allowing seamless integration\nof different computational methods while maintaining consistent APIs for\nenergy, gradient, and Hessian calculations.</p>\n\n<h1 id=\"available-backends\">Available Backends</h1>\n\n<p>Built-in Backends:\n    - Psi4Backend: Production quantum chemistry using Psi4\n    - TestBackend: Analytical test functions for algorithm validation</p>\n\n<h1 id=\"quick-start\">Quick Start</h1>\n\n<p>Using Built-in Backends:</p>\n\n<div class=\"pdoc-code codehilite\">\n<pre><span></span><code><span class=\"gp\">&gt;&gt;&gt; </span><span class=\"kn\">from</span><span class=\"w\"> </span><span class=\"nn\">dftscape.backends</span><span class=\"w\"> </span><span class=\"kn\">import</span> <span class=\"n\">BackendRegistry</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Create a Psi4 backend</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">backend</span> <span class=\"o\">=</span> <span class=\"n\">BackendRegistry</span><span class=\"o\">.</span><span class=\"n\">create</span><span class=\"p\">(</span><span class=\"s2\">&quot;psi4&quot;</span><span class=\"p\">,</span>\n<span class=\"gp\">... </span>    <span class=\"n\">cmp_mthd</span><span class=\"o\">=</span><span class=\"s2\">&quot;b3lyp/6-31g*&quot;</span><span class=\"p\">,</span>\n<span class=\"gp\">... </span>    <span class=\"n\">memory</span><span class=\"o\">=</span><span class=\"s2\">&quot;2GB&quot;</span><span class=\"p\">,</span>\n<span class=\"gp\">... </span>    <span class=\"n\">num_threads</span><span class=\"o\">=</span><span class=\"mi\">4</span><span class=\"p\">,</span>\n<span class=\"gp\">... </span>    <span class=\"n\">molecule_xyz</span><span class=\"o\">=</span><span class=\"s2\">&quot;3</span><span class=\"se\">\\n\\n</span><span class=\"s2\">O 0.0 0.0 0.0</span><span class=\"se\">\\n</span><span class=\"s2\">H 0.757 0.586 0.0</span><span class=\"se\">\\n</span><span class=\"s2\">H -0.757 0.586 0.0&quot;</span><span class=\"p\">,</span>\n<span class=\"gp\">... </span>    <span class=\"n\">molecule_directives</span><span class=\"o\">=</span><span class=\"p\">{</span><span class=\"s2\">&quot;charge&quot;</span><span class=\"p\">:</span> <span class=\"mi\">0</span><span class=\"p\">,</span> <span class=\"s2\">&quot;multiplicity&quot;</span><span class=\"p\">:</span> <span class=\"mi\">1</span><span class=\"p\">}</span>\n<span class=\"gp\">... </span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Use for calculations</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">coords</span> <span class=\"o\">=</span> <span class=\"n\">np</span><span class=\"o\">.</span><span class=\"n\">array</span><span class=\"p\">([</span><span class=\"mf\">0.0</span><span class=\"p\">,</span> <span class=\"mf\">0.0</span><span class=\"p\">,</span> <span class=\"mf\">0.0</span><span class=\"p\">,</span> <span class=\"mf\">0.757</span><span class=\"p\">,</span> <span class=\"mf\">0.586</span><span class=\"p\">,</span> <span class=\"mf\">0.0</span><span class=\"p\">,</span> <span class=\"o\">-</span><span class=\"mf\">0.757</span><span class=\"p\">,</span> <span class=\"mf\">0.586</span><span class=\"p\">,</span> <span class=\"mf\">0.0</span><span class=\"p\">])</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">energy</span> <span class=\"o\">=</span> <span class=\"n\">backend</span><span class=\"o\">.</span><span class=\"n\">compute_energy</span><span class=\"p\">(</span><span class=\"n\">coords</span><span class=\"o\">.</span><span class=\"n\">flatten</span><span class=\"p\">())</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">gradient</span> <span class=\"o\">=</span> <span class=\"n\">backend</span><span class=\"o\">.</span><span class=\"n\">compute_gradient</span><span class=\"p\">(</span><span class=\"n\">coords</span><span class=\"o\">.</span><span class=\"n\">flatten</span><span class=\"p\">())</span>\n</code></pre>\n</div>\n\n<h1 id=\"implementing-custom-backends\">Implementing Custom Backends</h1>\n\n<p>DFTScape supports custom backend implementations through the Backend protocol.\nThis enables integration of specialized computational methods like machine\nlearning interatomic potentials, force fields, or proprietary quantum chemistry\ncodes.</p>\n\n<h2 id=\"backend-protocol-requirements\">Backend Protocol Requirements</h2>\n\n<p>All backends must implement the Backend protocol with these methods:</p>\n\n<ol>\n<li><p>compute_energy(state: np.ndarray) -> float</p>\n\n<ul>\n<li>Compute potential energy for given coordinates</li>\n<li>state: 1D array of shape (3*N,) for N atoms [x1,y1,z1,x2,y2,z2,...]</li>\n<li>Returns: Energy value (float)</li>\n</ul></li>\n<li><p>compute_gradient(state: np.ndarray) -> np.ndarray</p>\n\n<ul>\n<li>Compute nuclear gradients (first derivatives)</li>\n<li>state: Same format as compute_energy</li>\n<li>Returns: Gradient array of shape (3*N,)</li>\n</ul></li>\n<li><p>compute_hessian(state: np.ndarray) -> np.ndarray</p>\n\n<ul>\n<li>Compute nuclear Hessian (second derivatives)</li>\n<li>state: Same format as compute_energy</li>\n<li>Returns: Hessian matrix of shape (3<em>N, 3</em>N)</li>\n</ul></li>\n<li><p>get_xyz(state: np.ndarray) -> str</p>\n\n<ul>\n<li>Export coordinates in XYZ format</li>\n<li>state: Same format as compute_energy</li>\n<li>Returns: XYZ format string</li>\n</ul></li>\n</ol>\n\n<h1 id=\"example-machine-learning-interatomic-potential-backend\">Example: Machine Learning Interatomic Potential Backend</h1>\n\n<p>Here's a complete example of implementing a backend using a machine learning\ninteratomic potential (ML-IAP) like those from NequIP, Allegro, or MACE:</p>\n\n<div class=\"pdoc-code codehilite\">\n<pre><span></span><code><span class=\"gp\">&gt;&gt;&gt; </span><span class=\"kn\">from</span><span class=\"w\"> </span><span class=\"nn\">dftscape.backends</span><span class=\"w\"> </span><span class=\"kn\">import</span> <span class=\"n\">BackendRegistry</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"kn\">from</span><span class=\"w\"> </span><span class=\"nn\">dftscape.core.interfaces</span><span class=\"w\"> </span><span class=\"kn\">import</span> <span class=\"n\">Backend</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"kn\">import</span><span class=\"w\"> </span><span class=\"nn\">numpy</span><span class=\"w\"> </span><span class=\"k\">as</span><span class=\"w\"> </span><span class=\"nn\">np</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"kn\">from</span><span class=\"w\"> </span><span class=\"nn\">typing</span><span class=\"w\"> </span><span class=\"kn\">import</span> <span class=\"n\">Optional</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"nd\">@BackendRegistry</span><span class=\"o\">.</span><span class=\"n\">register</span><span class=\"p\">(</span><span class=\"s2\">&quot;ml_iap&quot;</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"k\">class</span><span class=\"w\"> </span><span class=\"nc\">MLInteratomicPotentialBackend</span><span class=\"p\">(</span><span class=\"n\">Backend</span><span class=\"p\">):</span>\n<span class=\"gp\">... </span><span class=\"w\">    </span><span class=\"sd\">&quot;&quot;&quot;</span>\n<span class=\"gp\">... </span><span class=\"sd\">    Backend for Machine Learning Interatomic Potentials.</span>\n<span class=\"gp\">...</span>\n<span class=\"gp\">... </span><span class=\"sd\">    This backend integrates ML-IAP models (NequIP, Allegro, MACE, etc.)</span>\n<span class=\"gp\">... </span><span class=\"sd\">    for fast energy and force predictions in molecular dynamics and</span>\n<span class=\"gp\">... </span><span class=\"sd\">    geometry optimization.</span>\n<span class=\"gp\">... </span><span class=\"sd\">    &quot;&quot;&quot;</span>\n<span class=\"gp\">...</span>\n<span class=\"gp\">... </span>    <span class=\"k\">def</span><span class=\"w\"> </span><span class=\"fm\">__init__</span><span class=\"p\">(</span><span class=\"bp\">self</span><span class=\"p\">,</span>\n<span class=\"gp\">... </span>                 <span class=\"n\">model_path</span><span class=\"p\">:</span> <span class=\"nb\">str</span><span class=\"p\">,</span>\n<span class=\"gp\">... </span>                 <span class=\"n\">atomic_numbers</span><span class=\"p\">:</span> <span class=\"nb\">list</span><span class=\"p\">[</span><span class=\"nb\">int</span><span class=\"p\">],</span>\n<span class=\"gp\">... </span>                 <span class=\"n\">device</span><span class=\"p\">:</span> <span class=\"nb\">str</span> <span class=\"o\">=</span> <span class=\"s2\">&quot;cpu&quot;</span><span class=\"p\">,</span>\n<span class=\"gp\">... </span>                 <span class=\"o\">**</span><span class=\"n\">kwargs</span><span class=\"p\">):</span>\n<span class=\"gp\">... </span><span class=\"w\">        </span><span class=\"sd\">&quot;&quot;&quot;</span>\n<span class=\"gp\">... </span><span class=\"sd\">        Initialize ML-IAP backend.</span>\n<span class=\"gp\">...</span>\n<span class=\"gp\">... </span><span class=\"sd\">        Args:</span>\n<span class=\"gp\">... </span><span class=\"sd\">            model_path: Path to trained ML model</span>\n<span class=\"gp\">... </span><span class=\"sd\">            atomic_numbers: List of atomic numbers for atoms</span>\n<span class=\"gp\">... </span><span class=\"sd\">            device: Computing device (&#39;cpu&#39; or &#39;cuda&#39;)</span>\n<span class=\"gp\">... </span><span class=\"sd\">            **kwargs: Additional configuration</span>\n<span class=\"gp\">... </span><span class=\"sd\">        &quot;&quot;&quot;</span>\n<span class=\"gp\">... </span>        <span class=\"nb\">super</span><span class=\"p\">()</span><span class=\"o\">.</span><span class=\"fm\">__init__</span><span class=\"p\">()</span>\n<span class=\"gp\">... </span>        <span class=\"bp\">self</span><span class=\"o\">.</span><span class=\"n\">atomic_numbers</span> <span class=\"o\">=</span> <span class=\"n\">np</span><span class=\"o\">.</span><span class=\"n\">array</span><span class=\"p\">(</span><span class=\"n\">atomic_numbers</span><span class=\"p\">)</span>\n<span class=\"gp\">... </span>        <span class=\"bp\">self</span><span class=\"o\">.</span><span class=\"n\">device</span> <span class=\"o\">=</span> <span class=\"n\">device</span>\n<span class=\"gp\">...</span>\n<span class=\"gp\">... </span>        <span class=\"c1\"># Load your ML model here</span>\n<span class=\"gp\">... </span>        <span class=\"c1\"># self.model = load_ml_model(model_path, device=device)</span>\n<span class=\"gp\">... </span>        <span class=\"c1\"># For this example, we&#39;ll use a placeholder</span>\n<span class=\"gp\">... </span>        <span class=\"bp\">self</span><span class=\"o\">.</span><span class=\"n\">model</span> <span class=\"o\">=</span> <span class=\"kc\">None</span>\n<span class=\"gp\">... </span>        <span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"sa\">f</span><span class=\"s2\">&quot;ML-IAP Backend initialized with </span><span class=\"si\">{</span><span class=\"nb\">len</span><span class=\"p\">(</span><span class=\"n\">atomic_numbers</span><span class=\"p\">)</span><span class=\"si\">}</span><span class=\"s2\"> atoms&quot;</span><span class=\"p\">)</span>\n<span class=\"gp\">...</span>\n<span class=\"gp\">... </span>    <span class=\"k\">def</span><span class=\"w\"> </span><span class=\"nf\">compute_energy</span><span class=\"p\">(</span><span class=\"bp\">self</span><span class=\"p\">,</span> <span class=\"n\">state</span><span class=\"p\">:</span> <span class=\"n\">np</span><span class=\"o\">.</span><span class=\"n\">ndarray</span><span class=\"p\">)</span> <span class=\"o\">-&gt;</span> <span class=\"nb\">float</span><span class=\"p\">:</span>\n<span class=\"gp\">... </span><span class=\"w\">        </span><span class=\"sd\">&quot;&quot;&quot;</span>\n<span class=\"gp\">... </span><span class=\"sd\">        Compute energy using ML-IAP model.</span>\n<span class=\"gp\">...</span>\n<span class=\"gp\">... </span><span class=\"sd\">        Args:</span>\n<span class=\"gp\">... </span><span class=\"sd\">            state: 1D array of coordinates [x1,y1,z1,x2,y2,z2,...]</span>\n<span class=\"gp\">...</span>\n<span class=\"gp\">... </span><span class=\"sd\">        Returns:</span>\n<span class=\"gp\">... </span><span class=\"sd\">            float: Predicted energy in atomic units</span>\n<span class=\"gp\">... </span><span class=\"sd\">        &quot;&quot;&quot;</span>\n<span class=\"gp\">... </span>        <span class=\"c1\"># Reshape coordinates to (N, 3)</span>\n<span class=\"gp\">... </span>        <span class=\"n\">coords</span> <span class=\"o\">=</span> <span class=\"n\">state</span><span class=\"o\">.</span><span class=\"n\">reshape</span><span class=\"p\">(</span><span class=\"o\">-</span><span class=\"mi\">1</span><span class=\"p\">,</span> <span class=\"mi\">3</span><span class=\"p\">)</span>\n<span class=\"gp\">... </span>        <span class=\"n\">n_atoms</span> <span class=\"o\">=</span> <span class=\"nb\">len</span><span class=\"p\">(</span><span class=\"n\">coords</span><span class=\"p\">)</span>\n<span class=\"gp\">...</span>\n<span class=\"gp\">... </span>        <span class=\"c1\"># In real implementation:</span>\n<span class=\"gp\">... </span>        <span class=\"c1\"># energy = self.model.predict_energy(coords, self.atomic_numbers)</span>\n<span class=\"gp\">...</span>\n<span class=\"gp\">... </span>        <span class=\"c1\"># Placeholder: simple harmonic potential</span>\n<span class=\"gp\">... </span>        <span class=\"n\">energy</span> <span class=\"o\">=</span> <span class=\"mf\">0.0</span>\n<span class=\"gp\">... </span>        <span class=\"k\">for</span> <span class=\"n\">i</span> <span class=\"ow\">in</span> <span class=\"nb\">range</span><span class=\"p\">(</span><span class=\"n\">n_atoms</span><span class=\"p\">):</span>\n<span class=\"gp\">... </span>            <span class=\"n\">r</span> <span class=\"o\">=</span> <span class=\"n\">np</span><span class=\"o\">.</span><span class=\"n\">linalg</span><span class=\"o\">.</span><span class=\"n\">norm</span><span class=\"p\">(</span><span class=\"n\">coords</span><span class=\"p\">[</span><span class=\"n\">i</span><span class=\"p\">])</span>\n<span class=\"gp\">... </span>            <span class=\"n\">energy</span> <span class=\"o\">+=</span> <span class=\"mf\">0.5</span> <span class=\"o\">*</span> <span class=\"n\">r</span><span class=\"o\">**</span><span class=\"mi\">2</span>  <span class=\"c1\"># Harmonic potential</span>\n<span class=\"gp\">...</span>\n<span class=\"gp\">... </span>        <span class=\"k\">return</span> <span class=\"nb\">float</span><span class=\"p\">(</span><span class=\"n\">energy</span><span class=\"p\">)</span>\n<span class=\"gp\">...</span>\n<span class=\"gp\">... </span>    <span class=\"k\">def</span><span class=\"w\"> </span><span class=\"nf\">compute_gradient</span><span class=\"p\">(</span><span class=\"bp\">self</span><span class=\"p\">,</span> <span class=\"n\">state</span><span class=\"p\">:</span> <span class=\"n\">np</span><span class=\"o\">.</span><span class=\"n\">ndarray</span><span class=\"p\">)</span> <span class=\"o\">-&gt;</span> <span class=\"n\">np</span><span class=\"o\">.</span><span class=\"n\">ndarray</span><span class=\"p\">:</span>\n<span class=\"gp\">... </span><span class=\"w\">        </span><span class=\"sd\">&quot;&quot;&quot;</span>\n<span class=\"gp\">... </span><span class=\"sd\">        Compute gradients using ML-IAP model.</span>\n<span class=\"gp\">...</span>\n<span class=\"gp\">... </span><span class=\"sd\">        Args:</span>\n<span class=\"gp\">... </span><span class=\"sd\">            state: 1D array of coordinates</span>\n<span class=\"gp\">...</span>\n<span class=\"gp\">... </span><span class=\"sd\">        Returns:</span>\n<span class=\"gp\">... </span><span class=\"sd\">            np.ndarray: Gradient array of shape (3*N,)</span>\n<span class=\"gp\">... </span><span class=\"sd\">        &quot;&quot;&quot;</span>\n<span class=\"gp\">... </span>        <span class=\"n\">coords</span> <span class=\"o\">=</span> <span class=\"n\">state</span><span class=\"o\">.</span><span class=\"n\">reshape</span><span class=\"p\">(</span><span class=\"o\">-</span><span class=\"mi\">1</span><span class=\"p\">,</span> <span class=\"mi\">3</span><span class=\"p\">)</span>\n<span class=\"gp\">... </span>        <span class=\"n\">n_atoms</span> <span class=\"o\">=</span> <span class=\"nb\">len</span><span class=\"p\">(</span><span class=\"n\">coords</span><span class=\"p\">)</span>\n<span class=\"gp\">...</span>\n<span class=\"gp\">... </span>        <span class=\"c1\"># In real implementation:</span>\n<span class=\"gp\">... </span>        <span class=\"c1\"># forces = self.model.predict_forces(coords, self.atomic_numbers)</span>\n<span class=\"gp\">... </span>        <span class=\"c1\"># return -forces.flatten()  # Convert forces to gradients</span>\n<span class=\"gp\">...</span>\n<span class=\"gp\">... </span>        <span class=\"c1\"># Placeholder: gradient of harmonic potential</span>\n<span class=\"gp\">... </span>        <span class=\"n\">gradient</span> <span class=\"o\">=</span> <span class=\"n\">np</span><span class=\"o\">.</span><span class=\"n\">zeros_like</span><span class=\"p\">(</span><span class=\"n\">state</span><span class=\"p\">)</span>\n<span class=\"gp\">... </span>        <span class=\"k\">for</span> <span class=\"n\">i</span> <span class=\"ow\">in</span> <span class=\"nb\">range</span><span class=\"p\">(</span><span class=\"n\">n_atoms</span><span class=\"p\">):</span>\n<span class=\"gp\">... </span>            <span class=\"n\">r</span> <span class=\"o\">=</span> <span class=\"n\">np</span><span class=\"o\">.</span><span class=\"n\">linalg</span><span class=\"o\">.</span><span class=\"n\">norm</span><span class=\"p\">(</span><span class=\"n\">coords</span><span class=\"p\">[</span><span class=\"n\">i</span><span class=\"p\">])</span>\n<span class=\"gp\">... </span>            <span class=\"k\">if</span> <span class=\"n\">r</span> <span class=\"o\">&gt;</span> <span class=\"mi\">0</span><span class=\"p\">:</span>\n<span class=\"gp\">... </span>                <span class=\"n\">grad_i</span> <span class=\"o\">=</span> <span class=\"n\">coords</span><span class=\"p\">[</span><span class=\"n\">i</span><span class=\"p\">]</span> <span class=\"o\">/</span> <span class=\"n\">r</span>  <span class=\"c1\"># Unit vector</span>\n<span class=\"gp\">... </span>                <span class=\"n\">gradient</span><span class=\"p\">[</span><span class=\"mi\">3</span><span class=\"o\">*</span><span class=\"n\">i</span><span class=\"p\">:</span><span class=\"mi\">3</span><span class=\"o\">*</span><span class=\"n\">i</span><span class=\"o\">+</span><span class=\"mi\">3</span><span class=\"p\">]</span> <span class=\"o\">=</span> <span class=\"n\">grad_i</span>\n<span class=\"gp\">...</span>\n<span class=\"gp\">... </span>        <span class=\"k\">return</span> <span class=\"n\">gradient</span>\n<span class=\"gp\">...</span>\n<span class=\"gp\">... </span>    <span class=\"k\">def</span><span class=\"w\"> </span><span class=\"nf\">compute_hessian</span><span class=\"p\">(</span><span class=\"bp\">self</span><span class=\"p\">,</span> <span class=\"n\">state</span><span class=\"p\">:</span> <span class=\"n\">np</span><span class=\"o\">.</span><span class=\"n\">ndarray</span><span class=\"p\">)</span> <span class=\"o\">-&gt;</span> <span class=\"n\">np</span><span class=\"o\">.</span><span class=\"n\">ndarray</span><span class=\"p\">:</span>\n<span class=\"gp\">... </span><span class=\"w\">        </span><span class=\"sd\">&quot;&quot;&quot;</span>\n<span class=\"gp\">... </span><span class=\"sd\">        Compute Hessian matrix.</span>\n<span class=\"gp\">...</span>\n<span class=\"gp\">... </span><span class=\"sd\">        For ML-IAP models, analytical Hessians may not be available.</span>\n<span class=\"gp\">... </span><span class=\"sd\">        Consider using finite differences or numerical differentiation.</span>\n<span class=\"gp\">... </span><span class=\"sd\">        &quot;&quot;&quot;</span>\n<span class=\"gp\">... </span>        <span class=\"c1\"># Many ML-IAP models don&#39;t provide analytical Hessians</span>\n<span class=\"gp\">... </span>        <span class=\"c1\"># Use finite differences as fallback</span>\n<span class=\"gp\">... </span>        <span class=\"k\">return</span> <span class=\"bp\">self</span><span class=\"o\">.</span><span class=\"n\">_finite_difference_hessian</span><span class=\"p\">(</span><span class=\"n\">state</span><span class=\"p\">)</span>\n<span class=\"gp\">...</span>\n<span class=\"gp\">... </span>    <span class=\"k\">def</span><span class=\"w\"> </span><span class=\"nf\">_finite_difference_hessian</span><span class=\"p\">(</span><span class=\"bp\">self</span><span class=\"p\">,</span> <span class=\"n\">state</span><span class=\"p\">:</span> <span class=\"n\">np</span><span class=\"o\">.</span><span class=\"n\">ndarray</span><span class=\"p\">,</span>\n<span class=\"gp\">... </span>                                  <span class=\"n\">h</span><span class=\"p\">:</span> <span class=\"nb\">float</span> <span class=\"o\">=</span> <span class=\"mf\">1e-5</span><span class=\"p\">)</span> <span class=\"o\">-&gt;</span> <span class=\"n\">np</span><span class=\"o\">.</span><span class=\"n\">ndarray</span><span class=\"p\">:</span>\n<span class=\"gp\">... </span><span class=\"w\">        </span><span class=\"sd\">&quot;&quot;&quot;</span>\n<span class=\"gp\">... </span><span class=\"sd\">        Compute Hessian using finite differences.</span>\n<span class=\"gp\">...</span>\n<span class=\"gp\">... </span><span class=\"sd\">        Args:</span>\n<span class=\"gp\">... </span><span class=\"sd\">            state: Coordinate array</span>\n<span class=\"gp\">... </span><span class=\"sd\">            h: Finite difference step size</span>\n<span class=\"gp\">...</span>\n<span class=\"gp\">... </span><span class=\"sd\">        Returns:</span>\n<span class=\"gp\">... </span><span class=\"sd\">            np.ndarray: Hessian matrix</span>\n<span class=\"gp\">... </span><span class=\"sd\">        &quot;&quot;&quot;</span>\n<span class=\"gp\">... </span>        <span class=\"n\">n</span> <span class=\"o\">=</span> <span class=\"nb\">len</span><span class=\"p\">(</span><span class=\"n\">state</span><span class=\"p\">)</span>\n<span class=\"gp\">... </span>        <span class=\"n\">hessian</span> <span class=\"o\">=</span> <span class=\"n\">np</span><span class=\"o\">.</span><span class=\"n\">zeros</span><span class=\"p\">((</span><span class=\"n\">n</span><span class=\"p\">,</span> <span class=\"n\">n</span><span class=\"p\">))</span>\n<span class=\"gp\">... </span>        <span class=\"n\">grad_0</span> <span class=\"o\">=</span> <span class=\"bp\">self</span><span class=\"o\">.</span><span class=\"n\">compute_gradient</span><span class=\"p\">(</span><span class=\"n\">state</span><span class=\"p\">)</span>\n<span class=\"gp\">...</span>\n<span class=\"gp\">... </span>        <span class=\"k\">for</span> <span class=\"n\">i</span> <span class=\"ow\">in</span> <span class=\"nb\">range</span><span class=\"p\">(</span><span class=\"n\">n</span><span class=\"p\">):</span>\n<span class=\"gp\">... </span>            <span class=\"n\">state_plus</span> <span class=\"o\">=</span> <span class=\"n\">state</span><span class=\"o\">.</span><span class=\"n\">copy</span><span class=\"p\">()</span>\n<span class=\"gp\">... </span>            <span class=\"n\">state_plus</span><span class=\"p\">[</span><span class=\"n\">i</span><span class=\"p\">]</span> <span class=\"o\">+=</span> <span class=\"n\">h</span>\n<span class=\"gp\">... </span>            <span class=\"n\">grad_plus</span> <span class=\"o\">=</span> <span class=\"bp\">self</span><span class=\"o\">.</span><span class=\"n\">compute_gradient</span><span class=\"p\">(</span><span class=\"n\">state_plus</span><span class=\"p\">)</span>\n<span class=\"gp\">... </span>            <span class=\"n\">hessian</span><span class=\"p\">[</span><span class=\"n\">i</span><span class=\"p\">]</span> <span class=\"o\">=</span> <span class=\"p\">(</span><span class=\"n\">grad_plus</span> <span class=\"o\">-</span> <span class=\"n\">grad_0</span><span class=\"p\">)</span> <span class=\"o\">/</span> <span class=\"n\">h</span>\n<span class=\"gp\">...</span>\n<span class=\"gp\">... </span>        <span class=\"c1\"># Make symmetric</span>\n<span class=\"gp\">... </span>        <span class=\"n\">hessian</span> <span class=\"o\">=</span> <span class=\"p\">(</span><span class=\"n\">hessian</span> <span class=\"o\">+</span> <span class=\"n\">hessian</span><span class=\"o\">.</span><span class=\"n\">T</span><span class=\"p\">)</span> <span class=\"o\">/</span> <span class=\"mi\">2</span>\n<span class=\"gp\">... </span>        <span class=\"k\">return</span> <span class=\"n\">hessian</span>\n<span class=\"gp\">...</span>\n<span class=\"gp\">... </span>    <span class=\"k\">def</span><span class=\"w\"> </span><span class=\"nf\">get_xyz</span><span class=\"p\">(</span><span class=\"bp\">self</span><span class=\"p\">,</span> <span class=\"n\">state</span><span class=\"p\">:</span> <span class=\"n\">np</span><span class=\"o\">.</span><span class=\"n\">ndarray</span><span class=\"p\">)</span> <span class=\"o\">-&gt;</span> <span class=\"nb\">str</span><span class=\"p\">:</span>\n<span class=\"gp\">... </span><span class=\"w\">        </span><span class=\"sd\">&quot;&quot;&quot;</span>\n<span class=\"gp\">... </span><span class=\"sd\">        Generate XYZ format string.</span>\n<span class=\"gp\">... </span><span class=\"sd\">        &quot;&quot;&quot;</span>\n<span class=\"gp\">... </span>        <span class=\"n\">coords</span> <span class=\"o\">=</span> <span class=\"n\">state</span><span class=\"o\">.</span><span class=\"n\">reshape</span><span class=\"p\">(</span><span class=\"o\">-</span><span class=\"mi\">1</span><span class=\"p\">,</span> <span class=\"mi\">3</span><span class=\"p\">)</span>\n<span class=\"gp\">... </span>        <span class=\"n\">n_atoms</span> <span class=\"o\">=</span> <span class=\"nb\">len</span><span class=\"p\">(</span><span class=\"n\">coords</span><span class=\"p\">)</span>\n<span class=\"gp\">...</span>\n<span class=\"gp\">... </span>        <span class=\"n\">lines</span> <span class=\"o\">=</span> <span class=\"p\">[</span><span class=\"nb\">str</span><span class=\"p\">(</span><span class=\"n\">n_atoms</span><span class=\"p\">),</span> <span class=\"s2\">&quot;ML-IAP Generated&quot;</span><span class=\"p\">]</span>\n<span class=\"gp\">... </span>        <span class=\"k\">for</span> <span class=\"n\">i</span> <span class=\"ow\">in</span> <span class=\"nb\">range</span><span class=\"p\">(</span><span class=\"n\">n_atoms</span><span class=\"p\">):</span>\n<span class=\"gp\">... </span>            <span class=\"n\">atomic_num</span> <span class=\"o\">=</span> <span class=\"bp\">self</span><span class=\"o\">.</span><span class=\"n\">atomic_numbers</span><span class=\"p\">[</span><span class=\"n\">i</span><span class=\"p\">]</span>\n<span class=\"gp\">... </span>            <span class=\"c1\"># Simple atomic number to symbol mapping</span>\n<span class=\"gp\">... </span>            <span class=\"n\">symbol</span> <span class=\"o\">=</span> <span class=\"p\">{</span><span class=\"mi\">1</span><span class=\"p\">:</span> <span class=\"s2\">&quot;H&quot;</span><span class=\"p\">,</span> <span class=\"mi\">6</span><span class=\"p\">:</span> <span class=\"s2\">&quot;C&quot;</span><span class=\"p\">,</span> <span class=\"mi\">7</span><span class=\"p\">:</span> <span class=\"s2\">&quot;N&quot;</span><span class=\"p\">,</span> <span class=\"mi\">8</span><span class=\"p\">:</span> <span class=\"s2\">&quot;O&quot;</span><span class=\"p\">}</span><span class=\"o\">.</span><span class=\"n\">get</span><span class=\"p\">(</span><span class=\"n\">atomic_num</span><span class=\"p\">,</span> <span class=\"s2\">&quot;X&quot;</span><span class=\"p\">)</span>\n<span class=\"gp\">... </span>            <span class=\"n\">x</span><span class=\"p\">,</span> <span class=\"n\">y</span><span class=\"p\">,</span> <span class=\"n\">z</span> <span class=\"o\">=</span> <span class=\"n\">coords</span><span class=\"p\">[</span><span class=\"n\">i</span><span class=\"p\">]</span>\n<span class=\"gp\">... </span>            <span class=\"n\">lines</span><span class=\"o\">.</span><span class=\"n\">append</span><span class=\"p\">(</span><span class=\"s2\">&quot;12.6f&quot;</span><span class=\"p\">)</span>\n<span class=\"gp\">...</span>\n<span class=\"gp\">... </span>        <span class=\"k\">return</span> <span class=\"s2\">&quot;</span><span class=\"se\">\\n</span><span class=\"s2\">&quot;</span><span class=\"o\">.</span><span class=\"n\">join</span><span class=\"p\">(</span><span class=\"n\">lines</span><span class=\"p\">)</span>\n</code></pre>\n</div>\n\n<h6 id=\"using-the-custom-backend\">Using the Custom Backend:</h6>\n\n<blockquote>\n  <div class=\"pdoc-code codehilite\">\n<pre><span></span><code><span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Register and create the ML-IAP backend</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">ml_backend</span> <span class=\"o\">=</span> <span class=\"n\">BackendRegistry</span><span class=\"o\">.</span><span class=\"n\">create</span><span class=\"p\">(</span><span class=\"s2\">&quot;ml_iap&quot;</span><span class=\"p\">,</span>\n<span class=\"gp\">... </span>    <span class=\"n\">model_path</span><span class=\"o\">=</span><span class=\"s2\">&quot;path/to/model.pth&quot;</span><span class=\"p\">,</span>\n<span class=\"gp\">... </span>    <span class=\"n\">atomic_numbers</span><span class=\"o\">=</span><span class=\"p\">[</span><span class=\"mi\">8</span><span class=\"p\">,</span> <span class=\"mi\">1</span><span class=\"p\">,</span> <span class=\"mi\">1</span><span class=\"p\">],</span>  <span class=\"c1\"># Water molecule</span>\n<span class=\"gp\">... </span>    <span class=\"n\">device</span><span class=\"o\">=</span><span class=\"s2\">&quot;cpu&quot;</span>\n<span class=\"gp\">... </span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Use in DFTScape calculations</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">coords</span> <span class=\"o\">=</span> <span class=\"n\">np</span><span class=\"o\">.</span><span class=\"n\">array</span><span class=\"p\">([</span><span class=\"mf\">0.0</span><span class=\"p\">,</span> <span class=\"mf\">0.0</span><span class=\"p\">,</span> <span class=\"mf\">0.0</span><span class=\"p\">,</span> <span class=\"mf\">0.757</span><span class=\"p\">,</span> <span class=\"mf\">0.586</span><span class=\"p\">,</span> <span class=\"mf\">0.0</span><span class=\"p\">,</span> <span class=\"o\">-</span><span class=\"mf\">0.757</span><span class=\"p\">,</span> <span class=\"mf\">0.586</span><span class=\"p\">,</span> <span class=\"mf\">0.0</span><span class=\"p\">])</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">energy</span> <span class=\"o\">=</span> <span class=\"n\">ml_backend</span><span class=\"o\">.</span><span class=\"n\">compute_energy</span><span class=\"p\">(</span><span class=\"n\">coords</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">gradient</span> <span class=\"o\">=</span> <span class=\"n\">ml_backend</span><span class=\"o\">.</span><span class=\"n\">compute_gradient</span><span class=\"p\">(</span><span class=\"n\">coords</span><span class=\"p\">)</span>\n</code></pre>\n  </div>\n</blockquote>\n\n<h1 id=\"best-practices-for-custom-backends\">Best Practices for Custom Backends</h1>\n\n<ol>\n<li><p>Error Handling:</p>\n\n<ul>\n<li>Validate input dimensions and coordinate formats</li>\n<li>Handle model loading failures gracefully</li>\n<li>Provide informative error messages</li>\n</ul></li>\n<li><p>Performance Optimization:</p>\n\n<ul>\n<li>Cache expensive computations when possible</li>\n<li>Use appropriate data types (float32 vs float64)</li>\n<li>Consider batched operations for multiple evaluations</li>\n</ul></li>\n<li><p>Coordinate Systems:</p>\n\n<ul>\n<li>Always work with flattened 1D arrays internally</li>\n<li>Convert to 3D arrays (N, 3) for calculations</li>\n<li>Maintain consistent units (Angstroms for coordinates)</li>\n</ul></li>\n<li><p>Memory Management:</p>\n\n<ul>\n<li>Clean up large data structures when done</li>\n<li>Use memory-efficient data structures</li>\n<li>Consider streaming for large systems</li>\n</ul></li>\n<li><p>Testing and Validation:</p>\n\n<ul>\n<li>Test against known analytical systems</li>\n<li>Validate gradient/Hessian consistency</li>\n<li>Check energy conservation in dynamics</li>\n</ul></li>\n<li><p>Documentation:</p>\n\n<ul>\n<li>Document all parameters and their units</li>\n<li>Provide usage examples</li>\n<li>Explain limitations and assumptions</li>\n</ul></li>\n</ol>\n\n<h1 id=\"integration-with-dftscape-algorithms\">Integration with DFTScape Algorithms</h1>\n\n<h6 id=\"custom-backends-automatically-work-with-all-dftscape-algorithms\">Custom backends automatically work with all DFTScape algorithms:</h6>\n\n<blockquote>\n  <div class=\"pdoc-code codehilite\">\n<pre><span></span><code><span class=\"gp\">&gt;&gt;&gt; </span><span class=\"kn\">from</span><span class=\"w\"> </span><span class=\"nn\">dftscape.search</span><span class=\"w\"> </span><span class=\"kn\">import</span> <span class=\"n\">SearchOrchestrator</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Use custom backend in geometry optimization</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">search</span> <span class=\"o\">=</span> <span class=\"n\">SearchOrchestrator</span><span class=\"p\">(</span>\n<span class=\"gp\">... </span>    <span class=\"n\">backend</span><span class=\"o\">=</span><span class=\"n\">ml_backend</span><span class=\"p\">,</span>\n<span class=\"gp\">... </span>    <span class=\"o\">...</span><span class=\"p\">,</span>\n<span class=\"gp\">... </span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Run optimization</span>\n</code></pre>\n  </div>\n</blockquote>\n\n<h1 id=\"notes\">Notes</h1>\n\n<ul>\n<li>Backend registration happens at import time</li>\n<li>Unavailable backends (missing dependencies) are not registered</li>\n<li>All backends must handle coordinate arrays of shape (3*N,)</li>\n<li>Energy, gradient, and Hessian calculations should be consistent</li>\n<li>XYZ export enables visualization and analysis</li>\n<li>Custom backends enable integration of any computational method</li>\n</ul>\n\n<h1 id=\"see-also\">See Also</h1>\n\n<ul>\n<li>dftscape.core.interfaces.Backend: Backend protocol definition</li>\n<li>dftscape.backends.registry.BackendRegistry: Backend registration system</li>\n<li>dftscape.backends.impl_psi4: Psi4 quantum chemistry backend</li>\n<li>dftscape.backends.impl_test: Test backend implementation</li>\n</ul>\n"}, {"fullname": "dftscape.backends.Backend", "modulename": "dftscape.backends", "qualname": "Backend", "kind": "class", "doc": "<p>Protocol for computational backends in DFTScape.</p>\n\n<p>This protocol defines the interface that all quantum chemistry computational\nbackends must implement to be used within the DFTScape framework. It provides\na unified API for energy calculations, gradient computations, Hessian matrix\nevaluation, and molecular geometry handling.</p>\n\n<p>The Backend protocol abstracts the specific quantum chemistry package or method\nbeing used, allowing DFTScape to work with different computational engines\n(Psi4, Gaussian, ORCA, etc.) through a consistent interface.</p>\n\n<h6 id=\"key-methods\">Key Methods:</h6>\n\n<blockquote>\n  <p>compute_energy: Calculate potential energy at a molecular configuration\n  compute_gradient: Calculate first derivatives (forces) at a configuration\n  compute_hessian: Calculate second derivatives (force constants) at a configuration\n  get_xyz: Convert molecular coordinates to XYZ format string</p>\n</blockquote>\n\n<p>Implementation Requirements:</p>\n\n<ul>\n<li>All methods must accept numpy arrays for molecular coordinates</li>\n<li>Coordinate arrays should be 1D with shape (3*N,) for N atoms</li>\n<li>Energy values should be in atomic units (Hartree)</li>\n<li>Gradients should be 1D arrays with shape (3*N,) in atomic units</li>\n<li>Hessians should be 2D arrays with shape (3<em>N, 3</em>N) in atomic units</li>\n<li>XYZ strings should follow standard XYZ format with atomic symbols</li>\n</ul>\n\n<h6 id=\"example-implementation\">Example Implementation:</h6>\n\n<blockquote>\n  <div class=\"pdoc-code codehilite\">\n<pre><span></span><code><span class=\"gp\">&gt;&gt;&gt; </span><span class=\"k\">class</span><span class=\"w\"> </span><span class=\"nc\">MyBackend</span><span class=\"p\">:</span>\n<span class=\"gp\">... </span>    <span class=\"k\">def</span><span class=\"w\"> </span><span class=\"nf\">compute_energy</span><span class=\"p\">(</span><span class=\"bp\">self</span><span class=\"p\">,</span> <span class=\"n\">state</span><span class=\"p\">:</span> <span class=\"n\">np</span><span class=\"o\">.</span><span class=\"n\">ndarray</span><span class=\"p\">)</span> <span class=\"o\">-&gt;</span> <span class=\"nb\">float</span><span class=\"p\">:</span>\n<span class=\"gp\">... </span>        <span class=\"c1\"># Implementation here</span>\n<span class=\"gp\">... </span>        <span class=\"k\">return</span> <span class=\"n\">energy_value</span>\n<span class=\"gp\">...</span>\n<span class=\"gp\">... </span>    <span class=\"k\">def</span><span class=\"w\"> </span><span class=\"nf\">compute_gradient</span><span class=\"p\">(</span><span class=\"bp\">self</span><span class=\"p\">,</span> <span class=\"n\">state</span><span class=\"p\">:</span> <span class=\"n\">np</span><span class=\"o\">.</span><span class=\"n\">ndarray</span><span class=\"p\">)</span> <span class=\"o\">-&gt;</span> <span class=\"n\">np</span><span class=\"o\">.</span><span class=\"n\">ndarray</span><span class=\"p\">:</span>\n<span class=\"gp\">... </span>        <span class=\"c1\"># Implementation here</span>\n<span class=\"gp\">... </span>        <span class=\"k\">return</span> <span class=\"n\">gradient_array</span>\n<span class=\"gp\">...</span>\n<span class=\"gp\">... </span>    <span class=\"c1\"># ... other methods</span>\n</code></pre>\n  </div>\n</blockquote>\n\n<h6 id=\"notes\">Notes:</h6>\n\n<blockquote>\n  <ul>\n  <li>Implementations should handle coordinate validation and unit conversion</li>\n  <li>Error handling for invalid geometries is implementation-specific</li>\n  <li>Performance optimizations (caching, parallelization) are encouraged</li>\n  <li>Thread safety depends on the specific backend implementation</li>\n  </ul>\n</blockquote>\n", "bases": "typing.Protocol"}, {"fullname": "dftscape.backends.Backend.__init__", "modulename": "dftscape.backends", "qualname": "Backend.__init__", "kind": "function", "doc": "<p></p>\n", "signature": "<span class=\"signature pdoc-code condensed\">(<span class=\"param\"><span class=\"o\">*</span><span class=\"n\">args</span>, </span><span class=\"param\"><span class=\"o\">**</span><span class=\"n\">kwargs</span></span>)</span>"}, {"fullname": "dftscape.backends.Backend.compute_energy", "modulename": "dftscape.backends", "qualname": "Backend.compute_energy", "kind": "function", "doc": "<p>Compute the potential energy for a given molecular configuration.</p>\n\n<h6 id=\"arguments\">Arguments:</h6>\n\n<ul>\n<li><strong>state:</strong>  1D numpy array of shape (3*N,) containing atomic coordinates\nin Angstroms, where N is the number of atoms. Coordinates should\nbe ordered as [x1, y1, z1, x2, y2, z2, ..., xN, yN, zN].</li>\n</ul>\n\n<h6 id=\"returns\">Returns:</h6>\n\n<blockquote>\n  <p>float: Potential energy value in atomic units (Hartree).</p>\n</blockquote>\n\n<h6 id=\"raises\">Raises:</h6>\n\n<ul>\n<li>Implementation-specific exceptions for invalid geometries or</li>\n<li>computational failures.</li>\n</ul>\n\n<h6 id=\"example\">Example:</h6>\n\n<blockquote>\n  <div class=\"pdoc-code codehilite\">\n<pre><span></span><code><span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">coords</span> <span class=\"o\">=</span> <span class=\"n\">np</span><span class=\"o\">.</span><span class=\"n\">array</span><span class=\"p\">([</span><span class=\"mf\">0.0</span><span class=\"p\">,</span> <span class=\"mf\">0.0</span><span class=\"p\">,</span> <span class=\"mf\">0.0</span><span class=\"p\">,</span> <span class=\"mf\">1.0</span><span class=\"p\">,</span> <span class=\"mf\">0.0</span><span class=\"p\">,</span> <span class=\"mf\">0.0</span><span class=\"p\">])</span>  <span class=\"c1\"># H2 molecule</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">energy</span> <span class=\"o\">=</span> <span class=\"n\">backend</span><span class=\"o\">.</span><span class=\"n\">compute_energy</span><span class=\"p\">(</span><span class=\"n\">coords</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"sa\">f</span><span class=\"s2\">&quot;Energy: </span><span class=\"si\">{</span><span class=\"n\">energy</span><span class=\"si\">:</span><span class=\"s2\">.6f</span><span class=\"si\">}</span><span class=\"s2\"> Hartree&quot;</span><span class=\"p\">)</span>\n</code></pre>\n  </div>\n</blockquote>\n", "signature": "<span class=\"signature pdoc-code condensed\">(<span class=\"param\"><span class=\"bp\">self</span>, </span><span class=\"param\"><span class=\"n\">state</span><span class=\"p\">:</span> <span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span></span><span class=\"return-annotation\">) -> <span class=\"nb\">float</span>:</span></span>", "funcdef": "def"}, {"fullname": "dftscape.backends.Backend.compute_gradient", "modulename": "dftscape.backends", "qualname": "Backend.compute_gradient", "kind": "function", "doc": "<p>Compute the gradient (first derivatives) of the potential energy.</p>\n\n<p>The gradient represents the forces acting on each atom and points in\nthe direction of steepest descent on the potential energy surface.</p>\n\n<h6 id=\"arguments\">Arguments:</h6>\n\n<ul>\n<li><strong>state:</strong>  1D numpy array of shape (3*N,) containing atomic coordinates\nin Angstroms, ordered as [x1, y1, z1, x2, y2, z2, ..., xN, yN, zN].</li>\n</ul>\n\n<h6 id=\"returns\">Returns:</h6>\n\n<blockquote>\n  <p>np.ndarray: 1D array of shape (3*N,) containing the gradient components\n             in atomic units (Hartree/Angstrom). The ordering matches\n             the input coordinates.</p>\n</blockquote>\n\n<h6 id=\"raises\">Raises:</h6>\n\n<ul>\n<li>Implementation-specific exceptions for invalid geometries or</li>\n<li>computational failures.</li>\n</ul>\n\n<h6 id=\"example\">Example:</h6>\n\n<blockquote>\n  <div class=\"pdoc-code codehilite\">\n<pre><span></span><code><span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">coords</span> <span class=\"o\">=</span> <span class=\"n\">np</span><span class=\"o\">.</span><span class=\"n\">array</span><span class=\"p\">([</span><span class=\"mf\">0.0</span><span class=\"p\">,</span> <span class=\"mf\">0.0</span><span class=\"p\">,</span> <span class=\"mf\">0.0</span><span class=\"p\">,</span> <span class=\"mf\">1.0</span><span class=\"p\">,</span> <span class=\"mf\">0.0</span><span class=\"p\">,</span> <span class=\"mf\">0.0</span><span class=\"p\">])</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">grad</span> <span class=\"o\">=</span> <span class=\"n\">backend</span><span class=\"o\">.</span><span class=\"n\">compute_gradient</span><span class=\"p\">(</span><span class=\"n\">coords</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"sa\">f</span><span class=\"s2\">&quot;Gradient norm: </span><span class=\"si\">{</span><span class=\"n\">np</span><span class=\"o\">.</span><span class=\"n\">linalg</span><span class=\"o\">.</span><span class=\"n\">norm</span><span class=\"p\">(</span><span class=\"n\">grad</span><span class=\"p\">)</span><span class=\"si\">:</span><span class=\"s2\">.6f</span><span class=\"si\">}</span><span class=\"s2\">&quot;</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"sa\">f</span><span class=\"s2\">&quot;Force on first atom: </span><span class=\"si\">{</span><span class=\"n\">grad</span><span class=\"p\">[:</span><span class=\"mi\">3</span><span class=\"p\">]</span><span class=\"si\">}</span><span class=\"s2\">&quot;</span><span class=\"p\">)</span>\n</code></pre>\n  </div>\n</blockquote>\n", "signature": "<span class=\"signature pdoc-code condensed\">(<span class=\"param\"><span class=\"bp\">self</span>, </span><span class=\"param\"><span class=\"n\">state</span><span class=\"p\">:</span> <span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span></span><span class=\"return-annotation\">) -> <span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span>:</span></span>", "funcdef": "def"}, {"fullname": "dftscape.backends.Backend.compute_hessian", "modulename": "dftscape.backends", "qualname": "Backend.compute_hessian", "kind": "function", "doc": "<p>Compute the Hessian matrix (second derivatives) of the potential energy.</p>\n\n<p>The Hessian matrix contains information about the curvature of the potential\nenergy surface and is essential for determining the nature of critical points\n(minima, transition states) and for optimization algorithms.</p>\n\n<h6 id=\"arguments\">Arguments:</h6>\n\n<ul>\n<li><strong>state:</strong>  1D numpy array of shape (3*N,) containing atomic coordinates\nin Angstroms, ordered as [x1, y1, z1, x2, y2, z2, ..., xN, yN, zN].</li>\n</ul>\n\n<h6 id=\"returns\">Returns:</h6>\n\n<blockquote>\n  <p>np.ndarray: 2D array of shape (3<em>N, 3</em>N) containing the Hessian matrix\n             in atomic units (Hartree/Angstrom\u00b2). The matrix is symmetric\n             and ordered to match the input coordinate ordering.</p>\n</blockquote>\n\n<h6 id=\"raises\">Raises:</h6>\n\n<ul>\n<li>Implementation-specific exceptions for invalid geometries or</li>\n<li>computational failures.</li>\n</ul>\n\n<h6 id=\"example\">Example:</h6>\n\n<blockquote>\n  <div class=\"pdoc-code codehilite\">\n<pre><span></span><code><span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">coords</span> <span class=\"o\">=</span> <span class=\"n\">np</span><span class=\"o\">.</span><span class=\"n\">array</span><span class=\"p\">([</span><span class=\"mf\">0.0</span><span class=\"p\">,</span> <span class=\"mf\">0.0</span><span class=\"p\">,</span> <span class=\"mf\">0.0</span><span class=\"p\">,</span> <span class=\"mf\">1.0</span><span class=\"p\">,</span> <span class=\"mf\">0.0</span><span class=\"p\">,</span> <span class=\"mf\">0.0</span><span class=\"p\">])</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">hess</span> <span class=\"o\">=</span> <span class=\"n\">backend</span><span class=\"o\">.</span><span class=\"n\">compute_hessian</span><span class=\"p\">(</span><span class=\"n\">coords</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">eigenvals</span> <span class=\"o\">=</span> <span class=\"n\">np</span><span class=\"o\">.</span><span class=\"n\">linalg</span><span class=\"o\">.</span><span class=\"n\">eigvals</span><span class=\"p\">(</span><span class=\"n\">hess</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"sa\">f</span><span class=\"s2\">&quot;Hessian eigenvalues: </span><span class=\"si\">{</span><span class=\"n\">eigenvals</span><span class=\"si\">}</span><span class=\"s2\">&quot;</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"sa\">f</span><span class=\"s2\">&quot;Number of negative eigenvalues: </span><span class=\"si\">{</span><span class=\"n\">np</span><span class=\"o\">.</span><span class=\"n\">sum</span><span class=\"p\">(</span><span class=\"n\">eigenvals</span><span class=\"w\"> </span><span class=\"o\">&lt;</span><span class=\"w\"> </span><span class=\"mi\">0</span><span class=\"p\">)</span><span class=\"si\">}</span><span class=\"s2\">&quot;</span><span class=\"p\">)</span>\n</code></pre>\n  </div>\n</blockquote>\n", "signature": "<span class=\"signature pdoc-code condensed\">(<span class=\"param\"><span class=\"bp\">self</span>, </span><span class=\"param\"><span class=\"n\">state</span><span class=\"p\">:</span> <span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span></span><span class=\"return-annotation\">) -> <span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span>:</span></span>", "funcdef": "def"}, {"fullname": "dftscape.backends.Backend.get_xyz", "modulename": "dftscape.backends", "qualname": "Backend.get_xyz", "kind": "function", "doc": "<p>Convert molecular coordinates to XYZ format string.</p>\n\n<p>XYZ format is a standard text representation of molecular structures\nused throughout computational chemistry. It contains the number of atoms,\nan optional comment line, and atomic coordinates with element symbols.</p>\n\n<h6 id=\"arguments\">Arguments:</h6>\n\n<ul>\n<li><strong>state:</strong>  1D numpy array of shape (3*N,) containing atomic coordinates\nin Angstroms, ordered as [x1, y1, z1, x2, y2, z2, ..., xN, yN, zN].</li>\n</ul>\n\n<h6 id=\"returns\">Returns:</h6>\n\n<blockquote>\n  <p>str: XYZ format string with the following structure:\n       Line 1: Number of atoms (integer)\n       Line 2: Optional comment (often empty or energy value)\n       Lines 3+: Atomic symbol and coordinates (e.g., \"H 0.000000 0.000000 0.000000\")</p>\n</blockquote>\n\n<h6 id=\"raises\">Raises:</h6>\n\n<ul>\n<li>Implementation-specific exceptions for invalid geometries.</li>\n</ul>\n\n<h6 id=\"example\">Example:</h6>\n\n<blockquote>\n  <div class=\"pdoc-code codehilite\">\n<pre><span></span><code><span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">coords</span> <span class=\"o\">=</span> <span class=\"n\">np</span><span class=\"o\">.</span><span class=\"n\">array</span><span class=\"p\">([</span><span class=\"mf\">0.0</span><span class=\"p\">,</span> <span class=\"mf\">0.0</span><span class=\"p\">,</span> <span class=\"mf\">0.0</span><span class=\"p\">,</span> <span class=\"mf\">1.0</span><span class=\"p\">,</span> <span class=\"mf\">0.0</span><span class=\"p\">,</span> <span class=\"mf\">0.0</span><span class=\"p\">])</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">xyz_str</span> <span class=\"o\">=</span> <span class=\"n\">backend</span><span class=\"o\">.</span><span class=\"n\">get_xyz</span><span class=\"p\">(</span><span class=\"n\">coords</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"n\">xyz_str</span><span class=\"p\">)</span>\n<span class=\"go\">2</span>\n<span class=\"go\">H2 molecule</span>\n<span class=\"go\">H  0.000000  0.000000  0.000000</span>\n<span class=\"go\">H  1.000000  0.000000  0.000000</span>\n</code></pre>\n  </div>\n</blockquote>\n\n<h6 id=\"notes\">Notes:</h6>\n\n<blockquote>\n  <ul>\n  <li>Atomic symbols are typically inferred from the molecular system</li>\n  <li>Coordinate precision should be sufficient for the intended application</li>\n  <li>The comment line can include energy values or other metadata</li>\n  </ul>\n</blockquote>\n", "signature": "<span class=\"signature pdoc-code condensed\">(<span class=\"param\"><span class=\"bp\">self</span>, </span><span class=\"param\"><span class=\"n\">state</span><span class=\"p\">:</span> <span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span></span><span class=\"return-annotation\">) -> <span class=\"nb\">str</span>:</span></span>", "funcdef": "def"}, {"fullname": "dftscape.backends.BackendRegistry", "modulename": "dftscape.backends", "qualname": "BackendRegistry", "kind": "class", "doc": "<p>Registry for Backend Implementations in DFTScape.</p>\n\n<p>This class manages the registration and instantiation of backend implementations\nfor DFTScape. It extends the BaseRegistry to provide type-safe backend management\nwith specialized methods for quantum chemistry and testing backends.</p>\n\n<p>The registry supports multiple backend types:</p>\n\n<ul>\n<li>Quantum chemistry backends (Psi4, ORCA, etc.) for production calculations</li>\n<li>Testing backends for algorithm validation and benchmarking</li>\n<li>Custom backends for specialized computational methods</li>\n</ul>\n\n<p>Each backend is registered with a unique name and can be instantiated with\nbackend-specific configuration parameters. The registry provides automatic\ntype casting to ensure type safety when working with backend instances.</p>\n\n<h6 id=\"attributes\">Attributes:</h6>\n\n<ul>\n<li><strong>_registry (dict):</strong>  Class-level dictionary mapping backend names to classes.\nAutomatically created for each registry subclass.</li>\n</ul>\n\n<h6 id=\"class-attributes\">Class Attributes:</h6>\n\n<blockquote>\n  <p>Inherits all class attributes from BaseRegistry[T] where T=Backend.</p>\n</blockquote>\n\n<h6 id=\"notes\">Notes:</h6>\n\n<blockquote>\n  <ul>\n  <li>Each backend class must implement the Backend protocol</li>\n  <li>Backend registration happens at import time via decorators</li>\n  <li>Unavailable backends (missing dependencies) are not automatically registered</li>\n  <li>Registry operations are thread-safe for read access</li>\n  <li>Type casting ensures Backend protocol compliance</li>\n  </ul>\n</blockquote>\n\n<h6 id=\"examples\">Examples:</h6>\n\n<blockquote>\n  <div class=\"pdoc-code codehilite\">\n<pre><span></span><code><span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Register a new backend</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"nd\">@BackendRegistry</span><span class=\"o\">.</span><span class=\"n\">register</span><span class=\"p\">(</span><span class=\"s2\">&quot;gaussian&quot;</span><span class=\"p\">)</span>\n<span class=\"gp\">... </span><span class=\"k\">class</span><span class=\"w\"> </span><span class=\"nc\">GaussianBackend</span><span class=\"p\">(</span><span class=\"n\">Backend</span><span class=\"p\">):</span>\n<span class=\"gp\">... </span>    <span class=\"k\">def</span><span class=\"w\"> </span><span class=\"fm\">__init__</span><span class=\"p\">(</span><span class=\"bp\">self</span><span class=\"p\">,</span> <span class=\"o\">**</span><span class=\"n\">kwargs</span><span class=\"p\">):</span>\n<span class=\"gp\">... </span>        <span class=\"nb\">super</span><span class=\"p\">()</span><span class=\"o\">.</span><span class=\"fm\">__init__</span><span class=\"p\">()</span>\n<span class=\"gp\">... </span>        <span class=\"c1\"># Gaussian-specific initialization</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Create backend instance</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">backend</span> <span class=\"o\">=</span> <span class=\"n\">BackendRegistry</span><span class=\"o\">.</span><span class=\"n\">create</span><span class=\"p\">(</span><span class=\"s2\">&quot;gaussian&quot;</span><span class=\"p\">,</span> <span class=\"n\">method</span><span class=\"o\">=</span><span class=\"s2\">&quot;b3lyp&quot;</span><span class=\"p\">,</span> <span class=\"n\">basis</span><span class=\"o\">=</span><span class=\"s2\">&quot;6-31g*&quot;</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># List available backends</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">available</span> <span class=\"o\">=</span> <span class=\"n\">BackendRegistry</span><span class=\"o\">.</span><span class=\"n\">list_available</span><span class=\"p\">()</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"sa\">f</span><span class=\"s2\">&quot;Available: </span><span class=\"si\">{</span><span class=\"n\">available</span><span class=\"si\">}</span><span class=\"s2\">&quot;</span><span class=\"p\">)</span>\n</code></pre>\n  </div>\n</blockquote>\n\n<h6 id=\"see-also\">See Also:</h6>\n\n<blockquote>\n  <ul>\n  <li>Backend: Protocol defining backend interface</li>\n  <li>BaseRegistry: Base registry implementation</li>\n  <li>impl_psi4.Psi4Backend: Production quantum chemistry backend</li>\n  <li>impl_test.TestBackend: Testing backend for validation</li>\n  </ul>\n</blockquote>\n", "bases": "typing.Generic[~T]"}, {"fullname": "dftscape.backends.BackendRegistry.create", "modulename": "dftscape.backends", "qualname": "BackendRegistry.create", "kind": "function", "doc": "<p>Create an instance of a backend by name with type safety.</p>\n\n<p>This method extends the base create() method to provide type-safe\ninstantiation of backend implementations. It ensures that all created\ninstances conform to the Backend protocol through automatic type casting.</p>\n\n<p>The method supports backend-specific configuration through keyword arguments,\nallowing different backends to accept their required initialization parameters.</p>\n\n<h6 id=\"arguments\">Arguments:</h6>\n\n<ul>\n<li><strong>name:</strong>  Name of the backend to instantiate. Must be a registered backend\n(e.g., \"psi4\", \"test\", or custom registered backends).</li>\n<li><strong>*args:</strong>  Positional arguments to pass to the backend constructor.</li>\n<li><strong>**kwargs:</strong>  Keyword arguments for backend-specific configuration.\nCommon examples:\n<ul>\n<li>For Psi4: cmp_mthd, memory, num_threads, options, molecule_xyz</li>\n<li>For test: No additional arguments typically needed</li>\n</ul></li>\n</ul>\n\n<h6 id=\"returns\">Returns:</h6>\n\n<blockquote>\n  <p>Backend: A fully configured backend instance ready for calculations.\n          The instance is guaranteed to implement the Backend protocol.</p>\n</blockquote>\n\n<h6 id=\"raises\">Raises:</h6>\n\n<ul>\n<li><strong>ValueError:</strong>  If the backend name is not registered. Error message includes\nall available backend names for debugging.</li>\n<li><strong>TypeError:</strong>  If backend constructor arguments are invalid.</li>\n<li><strong>ImportError:</strong>  If backend dependencies are not available.</li>\n</ul>\n\n<h6 id=\"examples\">Examples:</h6>\n\n<blockquote>\n  <div class=\"pdoc-code codehilite\">\n<pre><span></span><code><span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Create Psi4 backend with full configuration</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">psi4_config</span> <span class=\"o\">=</span> <span class=\"p\">{</span>\n<span class=\"gp\">... </span>    <span class=\"s2\">&quot;cmp_mthd&quot;</span><span class=\"p\">:</span> <span class=\"s2\">&quot;b3lyp/6-31g*&quot;</span><span class=\"p\">,</span>\n<span class=\"gp\">... </span>    <span class=\"s2\">&quot;memory&quot;</span><span class=\"p\">:</span> <span class=\"s2\">&quot;1GB&quot;</span><span class=\"p\">,</span>\n<span class=\"gp\">... </span>    <span class=\"s2\">&quot;num_threads&quot;</span><span class=\"p\">:</span> <span class=\"mi\">4</span><span class=\"p\">,</span>\n<span class=\"gp\">... </span>    <span class=\"s2\">&quot;options&quot;</span><span class=\"p\">:</span> <span class=\"p\">{</span><span class=\"s2\">&quot;scf_type&quot;</span><span class=\"p\">:</span> <span class=\"s2\">&quot;df&quot;</span><span class=\"p\">},</span>\n<span class=\"gp\">... </span>    <span class=\"s2\">&quot;molecule_xyz&quot;</span><span class=\"p\">:</span> <span class=\"s2\">&quot;3</span><span class=\"se\">\\n\\n</span><span class=\"s2\">O 0.0 0.0 0.0</span><span class=\"se\">\\n</span><span class=\"s2\">H 0.757 0.586 0.0</span><span class=\"se\">\\n</span><span class=\"s2\">H -0.757 0.586 0.0&quot;</span><span class=\"p\">,</span>\n<span class=\"gp\">... </span>    <span class=\"s2\">&quot;molecule_directives&quot;</span><span class=\"p\">:</span> <span class=\"p\">{</span><span class=\"s2\">&quot;charge&quot;</span><span class=\"p\">:</span> <span class=\"mi\">0</span><span class=\"p\">,</span> <span class=\"s2\">&quot;multiplicity&quot;</span><span class=\"p\">:</span> <span class=\"mi\">1</span><span class=\"p\">}</span>\n<span class=\"gp\">... </span><span class=\"p\">}</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">backend</span> <span class=\"o\">=</span> <span class=\"n\">BackendRegistry</span><span class=\"o\">.</span><span class=\"n\">create</span><span class=\"p\">(</span><span class=\"s2\">&quot;psi4&quot;</span><span class=\"p\">,</span> <span class=\"o\">**</span><span class=\"n\">psi4_config</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Create test backend (no additional arguments needed)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">test_backend</span> <span class=\"o\">=</span> <span class=\"n\">BackendRegistry</span><span class=\"o\">.</span><span class=\"n\">create</span><span class=\"p\">(</span><span class=\"s2\">&quot;test&quot;</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Use the backend for calculations</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">coords</span> <span class=\"o\">=</span> <span class=\"n\">np</span><span class=\"o\">.</span><span class=\"n\">array</span><span class=\"p\">([</span><span class=\"mf\">0.0</span><span class=\"p\">,</span> <span class=\"mf\">0.0</span><span class=\"p\">,</span> <span class=\"mf\">0.0</span><span class=\"p\">,</span> <span class=\"mf\">0.757</span><span class=\"p\">,</span> <span class=\"mf\">0.586</span><span class=\"p\">,</span> <span class=\"mf\">0.0</span><span class=\"p\">,</span> <span class=\"o\">-</span><span class=\"mf\">0.757</span><span class=\"p\">,</span> <span class=\"mf\">0.586</span><span class=\"p\">,</span> <span class=\"mf\">0.0</span><span class=\"p\">])</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">energy</span> <span class=\"o\">=</span> <span class=\"n\">backend</span><span class=\"o\">.</span><span class=\"n\">compute_energy</span><span class=\"p\">(</span><span class=\"n\">coords</span><span class=\"o\">.</span><span class=\"n\">flatten</span><span class=\"p\">())</span>\n</code></pre>\n  </div>\n</blockquote>\n\n<h6 id=\"notes\">Notes:</h6>\n\n<blockquote>\n  <ul>\n  <li>Automatically casts result to Backend type for type safety</li>\n  <li>Supports arbitrary backend-specific constructor arguments</li>\n  <li>Backend availability depends on installed dependencies</li>\n  <li>Error messages include available backends for troubleshooting</li>\n  <li>Created backends are ready for immediate use in calculations</li>\n  </ul>\n</blockquote>\n", "signature": "<span class=\"signature pdoc-code condensed\">(<span class=\"param\"><span class=\"bp\">cls</span>, </span><span class=\"param\"><span class=\"n\">name</span><span class=\"p\">:</span> <span class=\"nb\">str</span>, </span><span class=\"param\"><span class=\"o\">*</span><span class=\"n\">args</span>, </span><span class=\"param\"><span class=\"o\">**</span><span class=\"n\">kwargs</span></span><span class=\"return-annotation\">) -> <span class=\"n\">dftscape</span><span class=\"o\">.</span><span class=\"n\">core</span><span class=\"o\">.</span><span class=\"n\">interfaces</span><span class=\"o\">.</span><span class=\"n\">Backend</span>:</span></span>", "funcdef": "def"}, {"fullname": "dftscape.backends.Psi4Backend", "modulename": "dftscape.backends", "qualname": "Psi4Backend", "kind": "class", "doc": "<p>Psi4 Backend for Quantum Chemistry Calculations in DFTScape.</p>\n\n<p>This backend provides a complete integration of Psi4 quantum chemistry\nsoftware with DFTScape's optimization framework. It enables accurate\nelectronic structure calculations for molecular systems, supporting\nenergy minimization, transition state finding, and potential energy\nsurface exploration.</p>\n\n<p>The backend handles all aspects of Psi4 integration including memory\nmanagement, thread control, wavefunction reuse, and temporary file\ncleanup. It provides analytical gradients and Hessians for high-accuracy\ngeometry optimizations.</p>\n\n<h6 id=\"key-features\">Key Features:</h6>\n\n<blockquote>\n  <ul>\n  <li>Full Psi4 computational method support (HF, DFT, correlated methods)</li>\n  <li>Arbitrary basis set selection</li>\n  <li>Analytical gradient and Hessian calculations</li>\n  <li>Wavefunction reuse for computational efficiency</li>\n  <li>Memory and threading control</li>\n  <li>Automatic temporary file management</li>\n  <li>XYZ format compatibility</li>\n  </ul>\n</blockquote>\n\n<h6 id=\"attributes\">Attributes:</h6>\n\n<ul>\n<li><strong>cmp_mthd (str):</strong>  Computational method and basis set (e.g., \"b3lyp/6-31g*\")</li>\n<li><strong>memory (str):</strong>  Memory allocation for Psi4 calculations</li>\n<li><strong>num_threads (int):</strong>  Number of threads for parallel computation</li>\n<li><strong>options (Dict[str, Any]):</strong>  Psi4-specific calculation options</li>\n<li><strong>molecule (psi4.core.Molecule):</strong>  Psi4 molecule object</li>\n<li><strong>molecule_directives (Dict[str, Any]):</strong>  Molecule initialization parameters</li>\n<li><strong>wfn (Optional[psi4.core.Wavefunction]):</strong>  Current wavefunction for reuse</li>\n<li><strong>temp_output_file (Optional[str]):</strong>  Path to temporary output file (None if use_temp_file=False)</li>\n</ul>\n\n<h6 id=\"notes\">Notes:</h6>\n\n<blockquote>\n  <ul>\n  <li>Requires Psi4 to be installed and properly configured</li>\n  <li>Memory and thread settings significantly affect performance</li>\n  <li>Wavefunction reuse improves efficiency for sequential calculations</li>\n  <li>Temporary files are automatically cleaned up on destruction (if used)</li>\n  <li>Supports all Psi4 computational methods and basis sets</li>\n  <li>Analytical derivatives provide high accuracy for optimization</li>\n  <li>Output can be discarded to /dev/null to prevent file accumulation</li>\n  </ul>\n</blockquote>\n\n<h6 id=\"examples\">Examples:</h6>\n\n<blockquote>\n  <div class=\"pdoc-code codehilite\">\n<pre><span></span><code><span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Configure for water molecule DFT calculation</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">config</span> <span class=\"o\">=</span> <span class=\"p\">{</span>\n<span class=\"gp\">... </span>    <span class=\"s2\">&quot;cmp_mthd&quot;</span><span class=\"p\">:</span> <span class=\"s2\">&quot;b3lyp/6-31g*&quot;</span><span class=\"p\">,</span>\n<span class=\"gp\">... </span>    <span class=\"s2\">&quot;memory&quot;</span><span class=\"p\">:</span> <span class=\"s2\">&quot;2GB&quot;</span><span class=\"p\">,</span>\n<span class=\"gp\">... </span>    <span class=\"s2\">&quot;num_threads&quot;</span><span class=\"p\">:</span> <span class=\"mi\">4</span><span class=\"p\">,</span>\n<span class=\"gp\">... </span>    <span class=\"s2\">&quot;options&quot;</span><span class=\"p\">:</span> <span class=\"p\">{</span><span class=\"s2\">&quot;scf_type&quot;</span><span class=\"p\">:</span> <span class=\"s2\">&quot;df&quot;</span><span class=\"p\">},</span>\n<span class=\"gp\">... </span>    <span class=\"s2\">&quot;molecule_xyz&quot;</span><span class=\"p\">:</span> <span class=\"s2\">&quot;3</span><span class=\"se\">\\n\\n</span><span class=\"s2\">O 0.0 0.0 0.0</span><span class=\"se\">\\n</span><span class=\"s2\">H 0.757 0.586 0.0</span><span class=\"se\">\\n</span><span class=\"s2\">H -0.757 0.586 0.0&quot;</span><span class=\"p\">,</span>\n<span class=\"gp\">... </span>    <span class=\"s2\">&quot;molecule_directives&quot;</span><span class=\"p\">:</span> <span class=\"p\">{</span><span class=\"s2\">&quot;charge&quot;</span><span class=\"p\">:</span> <span class=\"mi\">0</span><span class=\"p\">,</span> <span class=\"s2\">&quot;multiplicity&quot;</span><span class=\"p\">:</span> <span class=\"mi\">1</span><span class=\"p\">}</span>\n<span class=\"gp\">... </span><span class=\"p\">}</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">backend</span> <span class=\"o\">=</span> <span class=\"n\">Psi4Backend</span><span class=\"p\">(</span><span class=\"o\">**</span><span class=\"n\">config</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Perform calculations</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">coords</span> <span class=\"o\">=</span> <span class=\"n\">np</span><span class=\"o\">.</span><span class=\"n\">array</span><span class=\"p\">([[</span><span class=\"mf\">0.0</span><span class=\"p\">,</span> <span class=\"mf\">0.0</span><span class=\"p\">,</span> <span class=\"mf\">0.0</span><span class=\"p\">],</span> <span class=\"p\">[</span><span class=\"mf\">0.757</span><span class=\"p\">,</span> <span class=\"mf\">0.586</span><span class=\"p\">,</span> <span class=\"mf\">0.0</span><span class=\"p\">],</span> <span class=\"p\">[</span><span class=\"o\">-</span><span class=\"mf\">0.757</span><span class=\"p\">,</span> <span class=\"mf\">0.586</span><span class=\"p\">,</span> <span class=\"mf\">0.0</span><span class=\"p\">]])</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">energy</span> <span class=\"o\">=</span> <span class=\"n\">backend</span><span class=\"o\">.</span><span class=\"n\">compute_energy</span><span class=\"p\">(</span><span class=\"n\">coords</span><span class=\"o\">.</span><span class=\"n\">flatten</span><span class=\"p\">())</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">gradient</span> <span class=\"o\">=</span> <span class=\"n\">backend</span><span class=\"o\">.</span><span class=\"n\">compute_gradient</span><span class=\"p\">(</span><span class=\"n\">coords</span><span class=\"o\">.</span><span class=\"n\">flatten</span><span class=\"p\">())</span>\n</code></pre>\n  </div>\n</blockquote>\n", "bases": "dftscape.core.interfaces.Backend"}, {"fullname": "dftscape.backends.Psi4Backend.__init__", "modulename": "dftscape.backends", "qualname": "Psi4Backend.__init__", "kind": "function", "doc": "<p>Initialize Psi4 backend with computational parameters.</p>\n\n<p>Sets up a complete Psi4 environment for quantum chemistry calculations,\nincluding memory allocation, threading, computational method configuration,\nand molecule initialization. Creates temporary files for output management\nand configures Psi4 for optimal performance.</p>\n\n<h6 id=\"arguments\">Arguments:</h6>\n\n<ul>\n<li><strong>cmp_mthd:</strong>  Computational method and basis set specification.\nFormat: \"method/basis\" (e.g., \"b3lyp/6-31g*\", \"hf/sto-3g\").\nSupported methods: HF, DFT (b3lyp, pbe, etc.), correlated methods.</li>\n<li><strong>memory:</strong>  Memory allocation for Psi4 calculations.\nFormat: string with units (e.g., \"1GB\", \"512MB\", \"2.5GB\").</li>\n<li><strong>num_threads:</strong>  Number of threads for parallel computation.\nShould match available CPU cores for optimal performance.</li>\n<li><strong>options:</strong>  Dictionary of Psi4-specific calculation options.\nCommon options include:\n<ul>\n<li>\"scf_type\": SCF algorithm (\"pk\", \"df\", \"direct\")</li>\n<li>\"dft_spherical_points\": Grid points for DFT (302, 590, etc.)</li>\n<li>\"e_convergence\": Energy convergence threshold</li>\n<li>\"d_convergence\": Density convergence threshold</li>\n</ul></li>\n<li><strong>molecule_xyz:</strong>  Molecular geometry in XYZ format string.\nFormat: \"natoms\\ncomment\\natom1 x y z\\natom2 x y z\\n...\"\nCoordinates should be in Angstroms.</li>\n<li><strong>molecule_directives:</strong>  Dictionary of molecule initialization parameters.\nCommon parameters:\n<ul>\n<li>\"charge\": Molecular charge (int, default 0)</li>\n<li>\"multiplicity\": Spin multiplicity (int, default 1)</li>\n<li>\"units\": Coordinate units (\"Angstrom\" or \"Bohr\")</li>\n</ul></li>\n<li><strong>use_temp_file:</strong>  If True, use a temporary file for Psi4 output (legacy behavior).\nIf False, redirect output to /dev/null via a temporary symlink to discard all output.\nDefault is False to prevent file accumulation and crashes.</li>\n</ul>\n\n<h6 id=\"raises\">Raises:</h6>\n\n<ul>\n<li><strong>ImportError:</strong>  If Psi4 is not installed or cannot be imported.</li>\n<li><strong>RuntimeError:</strong>  If Psi4 calculation setup fails.</li>\n<li><strong>ValueError:</strong>  If molecule initialization fails.</li>\n</ul>\n\n<h6 id=\"examples\">Examples:</h6>\n\n<blockquote>\n  <div class=\"pdoc-code codehilite\">\n<pre><span></span><code><span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Water molecule DFT calculation</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">config</span> <span class=\"o\">=</span> <span class=\"p\">{</span>\n<span class=\"gp\">... </span>    <span class=\"s2\">&quot;cmp_mthd&quot;</span><span class=\"p\">:</span> <span class=\"s2\">&quot;b3lyp/6-31g*&quot;</span><span class=\"p\">,</span>\n<span class=\"gp\">... </span>    <span class=\"s2\">&quot;memory&quot;</span><span class=\"p\">:</span> <span class=\"s2\">&quot;1GB&quot;</span><span class=\"p\">,</span>\n<span class=\"gp\">... </span>    <span class=\"s2\">&quot;num_threads&quot;</span><span class=\"p\">:</span> <span class=\"mi\">4</span><span class=\"p\">,</span>\n<span class=\"gp\">... </span>    <span class=\"s2\">&quot;options&quot;</span><span class=\"p\">:</span> <span class=\"p\">{</span><span class=\"s2\">&quot;scf_type&quot;</span><span class=\"p\">:</span> <span class=\"s2\">&quot;df&quot;</span><span class=\"p\">,</span> <span class=\"s2\">&quot;dft_spherical_points&quot;</span><span class=\"p\">:</span> <span class=\"mi\">302</span><span class=\"p\">},</span>\n<span class=\"gp\">... </span>    <span class=\"s2\">&quot;molecule_xyz&quot;</span><span class=\"p\">:</span> <span class=\"s2\">&quot;3</span><span class=\"se\">\\n</span><span class=\"s2\">Water molecule</span><span class=\"se\">\\n</span><span class=\"s2\">O 0.0 0.0 0.0</span><span class=\"se\">\\n</span><span class=\"s2\">H 0.757 0.586 0.0</span><span class=\"se\">\\n</span><span class=\"s2\">H -0.757 0.586 0.0&quot;</span><span class=\"p\">,</span>\n<span class=\"gp\">... </span>    <span class=\"s2\">&quot;molecule_directives&quot;</span><span class=\"p\">:</span> <span class=\"p\">{</span><span class=\"s2\">&quot;charge&quot;</span><span class=\"p\">:</span> <span class=\"mi\">0</span><span class=\"p\">,</span> <span class=\"s2\">&quot;multiplicity&quot;</span><span class=\"p\">:</span> <span class=\"mi\">1</span><span class=\"p\">}</span>\n<span class=\"gp\">... </span><span class=\"p\">}</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">backend</span> <span class=\"o\">=</span> <span class=\"n\">Psi4Backend</span><span class=\"p\">(</span><span class=\"o\">**</span><span class=\"n\">config</span><span class=\"p\">)</span>\n</code></pre>\n  </div>\n</blockquote>\n\n<h6 id=\"notes\">Notes:</h6>\n\n<blockquote>\n  <ul>\n  <li>When use_temp_file=False, all Psi4 output is discarded via a temporary symlink to /dev/null</li>\n  <li>When use_temp_file=True, creates temporary output file (legacy behavior)</li>\n  <li>Configures Psi4 global settings (memory, threads, options)</li>\n  <li>Initializes molecule from XYZ string with specified directives</li>\n  <li>Wavefunction starts as None and is created on first calculation</li>\n  <li>Temporary files and symlinks are automatically cleaned up on backend destruction</li>\n  </ul>\n</blockquote>\n", "signature": "<span class=\"signature pdoc-code multiline\">(<span class=\"param\">\t<span class=\"n\">cmp_mthd</span><span class=\"p\">:</span> <span class=\"nb\">str</span>,</span><span class=\"param\">\t<span class=\"n\">memory</span><span class=\"p\">:</span> <span class=\"nb\">str</span>,</span><span class=\"param\">\t<span class=\"n\">num_threads</span><span class=\"p\">:</span> <span class=\"nb\">int</span>,</span><span class=\"param\">\t<span class=\"n\">options</span><span class=\"p\">:</span> <span class=\"n\">Dict</span><span class=\"p\">[</span><span class=\"nb\">str</span><span class=\"p\">,</span> <span class=\"n\">Any</span><span class=\"p\">]</span>,</span><span class=\"param\">\t<span class=\"n\">molecule_xyz</span><span class=\"p\">:</span> <span class=\"nb\">str</span>,</span><span class=\"param\">\t<span class=\"n\">molecule_directives</span><span class=\"p\">:</span> <span class=\"n\">Dict</span><span class=\"p\">[</span><span class=\"nb\">str</span><span class=\"p\">,</span> <span class=\"n\">Any</span><span class=\"p\">]</span>,</span><span class=\"param\">\t<span class=\"n\">use_temp_file</span><span class=\"p\">:</span> <span class=\"nb\">bool</span> <span class=\"o\">=</span> <span class=\"kc\">False</span></span>)</span>"}, {"fullname": "dftscape.backends.Psi4Backend.cmp_mthd", "modulename": "dftscape.backends", "qualname": "Psi4Backend.cmp_mthd", "kind": "variable", "doc": "<p></p>\n", "annotation": ": str"}, {"fullname": "dftscape.backends.Psi4Backend.memory", "modulename": "dftscape.backends", "qualname": "Psi4Backend.memory", "kind": "variable", "doc": "<p></p>\n", "annotation": ": str"}, {"fullname": "dftscape.backends.Psi4Backend.num_threads", "modulename": "dftscape.backends", "qualname": "Psi4Backend.num_threads", "kind": "variable", "doc": "<p></p>\n", "annotation": ": int"}, {"fullname": "dftscape.backends.Psi4Backend.options", "modulename": "dftscape.backends", "qualname": "Psi4Backend.options", "kind": "variable", "doc": "<p></p>\n", "annotation": ": Dict[str, Any]"}, {"fullname": "dftscape.backends.Psi4Backend.wfn", "modulename": "dftscape.backends", "qualname": "Psi4Backend.wfn", "kind": "variable", "doc": "<p></p>\n", "annotation": ": Optional[Any]"}, {"fullname": "dftscape.backends.Psi4Backend.molecule", "modulename": "dftscape.backends", "qualname": "Psi4Backend.molecule", "kind": "variable", "doc": "<p></p>\n", "annotation": ": Any"}, {"fullname": "dftscape.backends.Psi4Backend.molecule_directives", "modulename": "dftscape.backends", "qualname": "Psi4Backend.molecule_directives", "kind": "variable", "doc": "<p></p>\n", "annotation": ": Dict[str, Any]"}, {"fullname": "dftscape.backends.Psi4Backend.compute_energy", "modulename": "dftscape.backends", "qualname": "Psi4Backend.compute_energy", "kind": "function", "doc": "<p>Compute the electronic energy at the given molecular geometry.</p>\n\n<p>Performs a quantum chemistry calculation to determine the electronic\nenergy of the molecule at the specified nuclear coordinates. Uses\nthe configured computational method and basis set with wavefunction\nreuse for efficiency.</p>\n\n<p>The calculation includes self-consistent field (SCF) convergence and\ncorrelation energy evaluation depending on the chosen method. The\nwavefunction is stored for reuse in subsequent gradient calculations.</p>\n\n<h6 id=\"arguments\">Arguments:</h6>\n\n<ul>\n<li><strong>state:</strong>  1D numpy array of nuclear coordinates with shape (3*N,),\nwhere N is the number of atoms. Coordinates should be in\nAngstroms and ordered as [x1, y1, z1, x2, y2, z2, ...].</li>\n</ul>\n\n<h6 id=\"returns\">Returns:</h6>\n\n<blockquote>\n  <p>float: Electronic energy in Hartree atomic units.\n        Lower energies indicate more stable configurations.</p>\n</blockquote>\n\n<h6 id=\"raises\">Raises:</h6>\n\n<ul>\n<li><strong>RuntimeError:</strong>  If Psi4 calculation fails or SCF does not converge.</li>\n<li><strong>ValueError:</strong>  If coordinate array has incorrect dimensions.</li>\n</ul>\n\n<h6 id=\"examples\">Examples:</h6>\n\n<blockquote>\n  <div class=\"pdoc-code codehilite\">\n<pre><span></span><code><span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Water molecule at equilibrium geometry</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">coords</span> <span class=\"o\">=</span> <span class=\"n\">np</span><span class=\"o\">.</span><span class=\"n\">array</span><span class=\"p\">([</span><span class=\"mf\">0.0</span><span class=\"p\">,</span> <span class=\"mf\">0.0</span><span class=\"p\">,</span> <span class=\"mf\">0.0</span><span class=\"p\">,</span> <span class=\"mf\">0.757</span><span class=\"p\">,</span> <span class=\"mf\">0.586</span><span class=\"p\">,</span> <span class=\"mf\">0.0</span><span class=\"p\">,</span> <span class=\"o\">-</span><span class=\"mf\">0.757</span><span class=\"p\">,</span> <span class=\"mf\">0.586</span><span class=\"p\">,</span> <span class=\"mf\">0.0</span><span class=\"p\">])</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">energy</span> <span class=\"o\">=</span> <span class=\"n\">backend</span><span class=\"o\">.</span><span class=\"n\">compute_energy</span><span class=\"p\">(</span><span class=\"n\">coords</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"sa\">f</span><span class=\"s2\">&quot;Energy: </span><span class=\"si\">{</span><span class=\"n\">energy</span><span class=\"si\">:</span><span class=\"s2\">.6f</span><span class=\"si\">}</span><span class=\"s2\"> Hartree&quot;</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Stretched O-H bond</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">stretched_coords</span> <span class=\"o\">=</span> <span class=\"n\">np</span><span class=\"o\">.</span><span class=\"n\">array</span><span class=\"p\">([</span><span class=\"mf\">0.0</span><span class=\"p\">,</span> <span class=\"mf\">0.0</span><span class=\"p\">,</span> <span class=\"mf\">0.0</span><span class=\"p\">,</span> <span class=\"mf\">1.2</span><span class=\"p\">,</span> <span class=\"mf\">0.0</span><span class=\"p\">,</span> <span class=\"mf\">0.0</span><span class=\"p\">,</span> <span class=\"o\">-</span><span class=\"mf\">0.757</span><span class=\"p\">,</span> <span class=\"mf\">0.586</span><span class=\"p\">,</span> <span class=\"mf\">0.0</span><span class=\"p\">])</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">energy_stretched</span> <span class=\"o\">=</span> <span class=\"n\">backend</span><span class=\"o\">.</span><span class=\"n\">compute_energy</span><span class=\"p\">(</span><span class=\"n\">stretched_coords</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"sa\">f</span><span class=\"s2\">&quot;Energy (stretched): </span><span class=\"si\">{</span><span class=\"n\">energy_stretched</span><span class=\"si\">:</span><span class=\"s2\">.6f</span><span class=\"si\">}</span><span class=\"s2\"> Hartree&quot;</span><span class=\"p\">)</span>\n</code></pre>\n  </div>\n</blockquote>\n\n<h6 id=\"notes\">Notes:</h6>\n\n<blockquote>\n  <ul>\n  <li>Updates molecular geometry before calculation</li>\n  <li>Reuses wavefunction from previous calculations when available</li>\n  <li>SCF convergence depends on molecular geometry and method settings</li>\n  <li>Energy values are in atomic units (Hartree)</li>\n  <li>Calculation time depends on method, basis set, and system size</li>\n  </ul>\n</blockquote>\n", "signature": "<span class=\"signature pdoc-code condensed\">(<span class=\"param\"><span class=\"bp\">self</span>, </span><span class=\"param\"><span class=\"n\">state</span><span class=\"p\">:</span> <span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span></span><span class=\"return-annotation\">) -> <span class=\"nb\">float</span>:</span></span>", "funcdef": "def"}, {"fullname": "dftscape.backends.Psi4Backend.compute_gradient", "modulename": "dftscape.backends", "qualname": "Psi4Backend.compute_gradient", "kind": "function", "doc": "<p>Compute the analytical nuclear gradient at the given molecular geometry.</p>\n\n<p>Calculates the first derivatives of the electronic energy with respect\nto nuclear coordinates using analytical quantum chemistry methods.\nThe gradient provides the direction of steepest energy descent in\ncoordinate space, essential for geometry optimization algorithms.</p>\n\n<p>Uses the same wavefunction as the most recent energy calculation when\navailable, providing computational efficiency for sequential evaluations.</p>\n\n<h6 id=\"arguments\">Arguments:</h6>\n\n<ul>\n<li><strong>state:</strong>  1D numpy array of nuclear coordinates with shape (3*N,),\nwhere N is the number of atoms. Coordinates in Angstroms,\nordered as [x1, y1, z1, x2, y2, z2, ...].</li>\n</ul>\n\n<h6 id=\"returns\">Returns:</h6>\n\n<blockquote>\n  <p>np.ndarray: Nuclear gradient vector with shape (3*N,).\n             Each component is dE/dx_i in Hartree/Angstrom units.\n             Flattened to match input coordinate ordering.</p>\n</blockquote>\n\n<h6 id=\"raises\">Raises:</h6>\n\n<ul>\n<li><strong>RuntimeError:</strong>  If Psi4 gradient calculation fails.</li>\n<li><strong>ValueError:</strong>  If coordinate array has incorrect dimensions.</li>\n</ul>\n\n<h6 id=\"examples\">Examples:</h6>\n\n<blockquote>\n  <div class=\"pdoc-code codehilite\">\n<pre><span></span><code><span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Calculate gradient at equilibrium geometry</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">coords</span> <span class=\"o\">=</span> <span class=\"n\">np</span><span class=\"o\">.</span><span class=\"n\">array</span><span class=\"p\">([</span><span class=\"mf\">0.0</span><span class=\"p\">,</span> <span class=\"mf\">0.0</span><span class=\"p\">,</span> <span class=\"mf\">0.0</span><span class=\"p\">,</span> <span class=\"mf\">0.757</span><span class=\"p\">,</span> <span class=\"mf\">0.586</span><span class=\"p\">,</span> <span class=\"mf\">0.0</span><span class=\"p\">,</span> <span class=\"o\">-</span><span class=\"mf\">0.757</span><span class=\"p\">,</span> <span class=\"mf\">0.586</span><span class=\"p\">,</span> <span class=\"mf\">0.0</span><span class=\"p\">])</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">gradient</span> <span class=\"o\">=</span> <span class=\"n\">backend</span><span class=\"o\">.</span><span class=\"n\">compute_gradient</span><span class=\"p\">(</span><span class=\"n\">coords</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"sa\">f</span><span class=\"s2\">&quot;Gradient norm: </span><span class=\"si\">{</span><span class=\"n\">np</span><span class=\"o\">.</span><span class=\"n\">linalg</span><span class=\"o\">.</span><span class=\"n\">norm</span><span class=\"p\">(</span><span class=\"n\">gradient</span><span class=\"p\">)</span><span class=\"si\">:</span><span class=\"s2\">.6f</span><span class=\"si\">}</span><span class=\"s2\">&quot;</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"sa\">f</span><span class=\"s2\">&quot;Max gradient component: </span><span class=\"si\">{</span><span class=\"n\">np</span><span class=\"o\">.</span><span class=\"n\">max</span><span class=\"p\">(</span><span class=\"n\">np</span><span class=\"o\">.</span><span class=\"n\">abs</span><span class=\"p\">(</span><span class=\"n\">gradient</span><span class=\"p\">))</span><span class=\"si\">:</span><span class=\"s2\">.6f</span><span class=\"si\">}</span><span class=\"s2\">&quot;</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Check if geometry is at stationary point</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"k\">if</span> <span class=\"n\">np</span><span class=\"o\">.</span><span class=\"n\">linalg</span><span class=\"o\">.</span><span class=\"n\">norm</span><span class=\"p\">(</span><span class=\"n\">gradient</span><span class=\"p\">)</span> <span class=\"o\">&lt;</span> <span class=\"mf\">1e-4</span><span class=\"p\">:</span>\n<span class=\"gp\">... </span>    <span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"s2\">&quot;Near stationary point&quot;</span><span class=\"p\">)</span>\n<span class=\"gp\">... </span><span class=\"k\">else</span><span class=\"p\">:</span>\n<span class=\"gp\">... </span>    <span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"s2\">&quot;Geometry needs optimization&quot;</span><span class=\"p\">)</span>\n</code></pre>\n  </div>\n</blockquote>\n\n<h6 id=\"notes\">Notes:</h6>\n\n<blockquote>\n  <ul>\n  <li>Provides analytical gradients (exact derivatives)</li>\n  <li>Reuses wavefunction from previous energy calculation</li>\n  <li>Gradient components are in Hartree/Angstrom</li>\n  <li>Zero gradient indicates stationary point</li>\n  <li>Gradient norm indicates distance from stationary point</li>\n  <li>More expensive than energy calculation but essential for optimization</li>\n  </ul>\n</blockquote>\n", "signature": "<span class=\"signature pdoc-code condensed\">(<span class=\"param\"><span class=\"bp\">self</span>, </span><span class=\"param\"><span class=\"n\">state</span><span class=\"p\">:</span> <span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span></span><span class=\"return-annotation\">) -> <span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span>:</span></span>", "funcdef": "def"}, {"fullname": "dftscape.backends.Psi4Backend.compute_hessian", "modulename": "dftscape.backends", "qualname": "Psi4Backend.compute_hessian", "kind": "function", "doc": "<p>Compute the analytical nuclear Hessian matrix at the given molecular geometry.</p>\n\n<p>Calculates the second derivatives of the electronic energy with respect\nto nuclear coordinates using analytical quantum chemistry methods.\nThe Hessian matrix provides curvature information essential for\ntransition state finding and vibrational analysis.</p>\n\n<p>The Hessian eigenvalues determine the nature of stationary points:</p>\n\n<ul>\n<li>All positive: minimum (stable structure)</li>\n<li>One negative: transition state (first-order saddle)</li>\n<li>Multiple negative: higher-order saddle or unstable structure</li>\n</ul>\n\n<h6 id=\"arguments\">Arguments:</h6>\n\n<ul>\n<li><strong>state:</strong>  1D numpy array of nuclear coordinates with shape (3*N,),\nwhere N is the number of atoms. Coordinates in Angstroms,\nordered as [x1, y1, z1, x2, y2, z2, ...].</li>\n</ul>\n\n<h6 id=\"returns\">Returns:</h6>\n\n<blockquote>\n  <p>np.ndarray: Nuclear Hessian matrix with shape (3<em>N, 3</em>N).\n             Elements are d\u00b2E/dx_i dx_j in Hartree/Angstrom\u00b2 units.\n             Symmetric matrix representing energy curvature.</p>\n</blockquote>\n\n<h6 id=\"raises\">Raises:</h6>\n\n<ul>\n<li><strong>RuntimeError:</strong>  If Psi4 Hessian calculation fails.</li>\n<li><strong>ValueError:</strong>  If coordinate array has incorrect dimensions.</li>\n</ul>\n\n<h6 id=\"examples\">Examples:</h6>\n\n<blockquote>\n  <div class=\"pdoc-code codehilite\">\n<pre><span></span><code><span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Calculate Hessian at equilibrium geometry</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">coords</span> <span class=\"o\">=</span> <span class=\"n\">np</span><span class=\"o\">.</span><span class=\"n\">array</span><span class=\"p\">([</span><span class=\"mf\">0.0</span><span class=\"p\">,</span> <span class=\"mf\">0.0</span><span class=\"p\">,</span> <span class=\"mf\">0.0</span><span class=\"p\">,</span> <span class=\"mf\">0.757</span><span class=\"p\">,</span> <span class=\"mf\">0.586</span><span class=\"p\">,</span> <span class=\"mf\">0.0</span><span class=\"p\">,</span> <span class=\"o\">-</span><span class=\"mf\">0.757</span><span class=\"p\">,</span> <span class=\"mf\">0.586</span><span class=\"p\">,</span> <span class=\"mf\">0.0</span><span class=\"p\">])</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">hessian</span> <span class=\"o\">=</span> <span class=\"n\">backend</span><span class=\"o\">.</span><span class=\"n\">compute_hessian</span><span class=\"p\">(</span><span class=\"n\">coords</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Analyze stationary point character</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">eigenvals</span> <span class=\"o\">=</span> <span class=\"n\">np</span><span class=\"o\">.</span><span class=\"n\">linalg</span><span class=\"o\">.</span><span class=\"n\">eigvals</span><span class=\"p\">(</span><span class=\"n\">hessian</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">n_negative</span> <span class=\"o\">=</span> <span class=\"n\">np</span><span class=\"o\">.</span><span class=\"n\">sum</span><span class=\"p\">(</span><span class=\"n\">eigenvals</span> <span class=\"o\">&lt;</span> <span class=\"mi\">0</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"sa\">f</span><span class=\"s2\">&quot;Number of negative eigenvalues: </span><span class=\"si\">{</span><span class=\"n\">n_negative</span><span class=\"si\">}</span><span class=\"s2\">&quot;</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"k\">if</span> <span class=\"n\">n_negative</span> <span class=\"o\">==</span> <span class=\"mi\">0</span><span class=\"p\">:</span>\n<span class=\"gp\">... </span>    <span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"s2\">&quot;Minimum (stable structure)&quot;</span><span class=\"p\">)</span>\n<span class=\"gp\">... </span><span class=\"k\">elif</span> <span class=\"n\">n_negative</span> <span class=\"o\">==</span> <span class=\"mi\">1</span><span class=\"p\">:</span>\n<span class=\"gp\">... </span>    <span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"s2\">&quot;Transition state&quot;</span><span class=\"p\">)</span>\n<span class=\"gp\">... </span><span class=\"k\">else</span><span class=\"p\">:</span>\n<span class=\"gp\">... </span>    <span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"s2\">&quot;Higher-order saddle&quot;</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Calculate harmonic vibrational frequencies</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># (eigenvalues of Hessian give frequencies squared)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">frequencies</span> <span class=\"o\">=</span> <span class=\"n\">np</span><span class=\"o\">.</span><span class=\"n\">sqrt</span><span class=\"p\">(</span><span class=\"n\">np</span><span class=\"o\">.</span><span class=\"n\">abs</span><span class=\"p\">(</span><span class=\"n\">eigenvals</span><span class=\"p\">))</span> <span class=\"o\">*</span> <span class=\"mf\">5140.48</span>  <span class=\"c1\"># cm\u207b\u00b9</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"sa\">f</span><span class=\"s2\">&quot;Vibrational frequencies: </span><span class=\"si\">{</span><span class=\"n\">frequencies</span><span class=\"si\">}</span><span class=\"s2\"> cm\u207b\u00b9&quot;</span><span class=\"p\">)</span>\n</code></pre>\n  </div>\n</blockquote>\n\n<h6 id=\"notes\">Notes:</h6>\n\n<blockquote>\n  <ul>\n  <li>Provides analytical Hessian (exact second derivatives)</li>\n  <li>Most computationally expensive calculation</li>\n  <li>Hessian is always symmetric by construction</li>\n  <li>Eigenvalue analysis determines stationary point type</li>\n  <li>Essential for transition state characterization</li>\n  <li>Can be used for vibrational frequency calculations</li>\n  </ul>\n</blockquote>\n", "signature": "<span class=\"signature pdoc-code condensed\">(<span class=\"param\"><span class=\"bp\">self</span>, </span><span class=\"param\"><span class=\"n\">state</span><span class=\"p\">:</span> <span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span></span><span class=\"return-annotation\">) -> <span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span>:</span></span>", "funcdef": "def"}, {"fullname": "dftscape.backends.Psi4Backend.get_xyz", "modulename": "dftscape.backends", "qualname": "Psi4Backend.get_xyz", "kind": "function", "doc": "<p>Generate XYZ format string representation of the molecular geometry.</p>\n\n<p>Exports the current molecular geometry in the standard XYZ file format,\nwhich is widely supported by molecular visualization and analysis tools.\nThe format includes atomic symbols, coordinates, and proper formatting\nfor compatibility with external software.</p>\n\n<p>The XYZ format structure:</p>\n\n<ul>\n<li>Line 1: Number of atoms (integer)</li>\n<li>Line 2: Comment/title line (can be empty)</li>\n<li>Lines 3+: Atomic symbol and coordinates (Angstroms)\nFormat: \"Symbol  X  Y  Z\"</li>\n</ul>\n\n<h6 id=\"arguments\">Arguments:</h6>\n\n<ul>\n<li><strong>state:</strong>  1D numpy array of nuclear coordinates with shape (3*N,).\nUsed to update the molecule geometry before export.</li>\n</ul>\n\n<h6 id=\"returns\">Returns:</h6>\n\n<blockquote>\n  <p>str: Complete XYZ format string with proper formatting and newlines.\n      Ready for writing to file or use with molecular tools.</p>\n</blockquote>\n\n<h6 id=\"raises\">Raises:</h6>\n\n<ul>\n<li><strong>ValueError:</strong>  If coordinate array has incorrect dimensions.</li>\n</ul>\n\n<h6 id=\"examples\">Examples:</h6>\n\n<blockquote>\n  <div class=\"pdoc-code codehilite\">\n<pre><span></span><code><span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Export water molecule geometry</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">coords</span> <span class=\"o\">=</span> <span class=\"n\">np</span><span class=\"o\">.</span><span class=\"n\">array</span><span class=\"p\">([</span><span class=\"mf\">0.0</span><span class=\"p\">,</span> <span class=\"mf\">0.0</span><span class=\"p\">,</span> <span class=\"mf\">0.0</span><span class=\"p\">,</span> <span class=\"mf\">0.757</span><span class=\"p\">,</span> <span class=\"mf\">0.586</span><span class=\"p\">,</span> <span class=\"mf\">0.0</span><span class=\"p\">,</span> <span class=\"o\">-</span><span class=\"mf\">0.757</span><span class=\"p\">,</span> <span class=\"mf\">0.586</span><span class=\"p\">,</span> <span class=\"mf\">0.0</span><span class=\"p\">])</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">xyz_string</span> <span class=\"o\">=</span> <span class=\"n\">backend</span><span class=\"o\">.</span><span class=\"n\">get_xyz</span><span class=\"p\">(</span><span class=\"n\">coords</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"n\">xyz_string</span><span class=\"p\">)</span>\n<span class=\"go\">3</span>\n<span class=\"go\">Water molecule</span>\n<span class=\"go\">O     0.000000     0.000000     0.000000</span>\n<span class=\"go\">H     0.757000     0.586000     0.000000</span>\n<span class=\"go\">H    -0.757000     0.586000     0.000000</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Save to file</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"k\">with</span> <span class=\"nb\">open</span><span class=\"p\">(</span><span class=\"s2\">&quot;molecule.xyz&quot;</span><span class=\"p\">,</span> <span class=\"s2\">&quot;w&quot;</span><span class=\"p\">)</span> <span class=\"k\">as</span> <span class=\"n\">f</span><span class=\"p\">:</span>\n<span class=\"gp\">... </span>    <span class=\"n\">f</span><span class=\"o\">.</span><span class=\"n\">write</span><span class=\"p\">(</span><span class=\"n\">xyz_string</span><span class=\"p\">)</span>\n</code></pre>\n  </div>\n</blockquote>\n\n<h6 id=\"notes\">Notes:</h6>\n\n<blockquote>\n  <ul>\n  <li>Updates molecule geometry before export using provided coordinates</li>\n  <li>Uses Psi4's built-in XYZ export functionality</li>\n  <li>Coordinates are in Angstroms (standard for XYZ format)</li>\n  <li>Atomic symbols are taken from the molecule definition</li>\n  <li>Suitable for molecular visualization (VMD, PyMOL, etc.)</li>\n  <li>Compatible with quantum chemistry software input files</li>\n  </ul>\n</blockquote>\n", "signature": "<span class=\"signature pdoc-code condensed\">(<span class=\"param\"><span class=\"bp\">self</span>, </span><span class=\"param\"><span class=\"n\">state</span><span class=\"p\">:</span> <span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span></span><span class=\"return-annotation\">) -> <span class=\"nb\">str</span>:</span></span>", "funcdef": "def"}, {"fullname": "dftscape.backends.TestBackend", "modulename": "dftscape.backends", "qualname": "TestBackend", "kind": "class", "doc": "<p>Test Backend for Algorithm Validation and Testing.</p>\n\n<p>This backend implements a 3D separable double-well potential function\ndesigned specifically for testing and validating search algorithms in DFTScape.\nThe potential function provides a controlled environment with well-characterized\nstationary points, making it ideal for benchmarking optimization methods and\ntransition state finding algorithms.</p>\n\n<h6 id=\"mathematical-function\">Mathematical Function:</h6>\n\n<blockquote>\n  <p>f(x, y, z) = (x\u00b2-1)\u00b2 + (y\u00b2-1)\u00b2 + (z\u00b2-1)\u00b2</p>\n</blockquote>\n\n<p>The function is separable in each coordinate, allowing for easy analysis\nof the optimization landscape and critical point properties.</p>\n\n<h1 id=\"critical-points-27-total\">Critical Points (27 total):</h1>\n\n<p>Global Minima (Index 0):\n    Locations: All combinations of (\u00b11, \u00b11, \u00b11)\n    Energy: f = 0\n    Count: 8 points\n    Description: Eight equivalent global minima at the corners of the cube</p>\n\n<p>Index-1 Saddles:\n    Locations: One coordinate = 0, others = \u00b11 (all combinations)\n    Energy: f = 1\n    Count: 12 points\n    Description: Saddle points on the faces of the potential energy cube</p>\n\n<p>Index-2 Saddles:\n    Locations: Two coordinates = 0, one = \u00b11 (all combinations)\n    Energy: f = 2\n    Count: 6 points\n    Description: Saddle points along the edges of the potential energy cube</p>\n\n<p>Index-3 Saddle (Maximum):\n    Location: (0, 0, 0)\n    Energy: f = 3\n    Count: 1 point\n    Description: Global maximum at the center of the coordinate system</p>\n\n<p>All critical points are non-degenerate with Hessian eigenvalues {-4, 8},\nproviding well-conditioned test cases for optimization algorithms.</p>\n\n<h6 id=\"attributes\">Attributes:</h6>\n\n<ul>\n<li><strong>config (Dict[str, Any]):</strong>  Configuration parameters passed during initialization</li>\n<li><strong>_potential_fn (Callable):</strong>  JIT-compiled potential energy function</li>\n<li><strong>_gradient_fn (Callable):</strong>  JIT-compiled gradient function</li>\n<li><strong>_hessian_fn (Callable):</strong>  JIT-compiled Hessian function</li>\n</ul>\n\n<h6 id=\"notes\">Notes:</h6>\n\n<blockquote>\n  <ul>\n  <li>Requires JAX for automatic differentiation and JIT compilation</li>\n  <li>All derivatives computed analytically (no numerical approximations)</li>\n  <li>Functions are JIT-compiled for optimal performance</li>\n  <li>Thread-safe for evaluation (no internal state modifications)</li>\n  <li>Designed for 3D coordinate systems only</li>\n  </ul>\n</blockquote>\n\n<h6 id=\"examples\">Examples:</h6>\n\n<blockquote>\n  <div class=\"pdoc-code codehilite\">\n<pre><span></span><code><span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">backend</span> <span class=\"o\">=</span> <span class=\"n\">TestBackend</span><span class=\"p\">()</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Evaluate at a minimum</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">min_point</span> <span class=\"o\">=</span> <span class=\"n\">np</span><span class=\"o\">.</span><span class=\"n\">array</span><span class=\"p\">([</span><span class=\"mf\">1.0</span><span class=\"p\">,</span> <span class=\"mf\">1.0</span><span class=\"p\">,</span> <span class=\"mf\">1.0</span><span class=\"p\">])</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">energy</span> <span class=\"o\">=</span> <span class=\"n\">backend</span><span class=\"o\">.</span><span class=\"n\">compute_energy</span><span class=\"p\">(</span><span class=\"n\">min_point</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"sa\">f</span><span class=\"s2\">&quot;Energy at minimum: </span><span class=\"si\">{</span><span class=\"n\">energy</span><span class=\"si\">}</span><span class=\"s2\">&quot;</span><span class=\"p\">)</span>  <span class=\"c1\"># 0.0</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Evaluate at the maximum</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">max_point</span> <span class=\"o\">=</span> <span class=\"n\">np</span><span class=\"o\">.</span><span class=\"n\">array</span><span class=\"p\">([</span><span class=\"mf\">0.0</span><span class=\"p\">,</span> <span class=\"mf\">0.0</span><span class=\"p\">,</span> <span class=\"mf\">0.0</span><span class=\"p\">])</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">energy</span> <span class=\"o\">=</span> <span class=\"n\">backend</span><span class=\"o\">.</span><span class=\"n\">compute_energy</span><span class=\"p\">(</span><span class=\"n\">max_point</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"sa\">f</span><span class=\"s2\">&quot;Energy at maximum: </span><span class=\"si\">{</span><span class=\"n\">energy</span><span class=\"si\">}</span><span class=\"s2\">&quot;</span><span class=\"p\">)</span>  <span class=\"c1\"># 3.0</span>\n</code></pre>\n  </div>\n</blockquote>\n", "bases": "dftscape.core.interfaces.Backend"}, {"fullname": "dftscape.backends.TestBackend.__init__", "modulename": "dftscape.backends", "qualname": "TestBackend.__init__", "kind": "function", "doc": "<p>Initialize the JAX test backend with configuration parameters.</p>\n\n<p>Sets up the 3D separable double-well potential function with JAX\nautomatic differentiation and JIT compilation for optimal performance.\nThe backend is configured with the mathematical function:</p>\n\n<p>f(x, y, z) = (x\u00b2-1)\u00b2 + (y\u00b2-1)\u00b2 + (z\u00b2-1)\u00b2</p>\n\n<h6 id=\"arguments\">Arguments:</h6>\n\n<ul>\n<li><strong>**kwargs:</strong>  Configuration parameters (stored but not currently used).\nReserved for future extensions and customization options.</li>\n</ul>\n\n<h6 id=\"raises\">Raises:</h6>\n\n<ul>\n<li><strong>ImportError:</strong>  If JAX is not available (handled at class level).</li>\n</ul>\n\n<h6 id=\"notes\">Notes:</h6>\n\n<blockquote>\n  <ul>\n  <li>Creates JIT-compiled versions of potential, gradient, and Hessian</li>\n  <li>Functions are optimized for repeated evaluations</li>\n  <li>No internal state is modified during evaluations (thread-safe)</li>\n  <li>Configuration parameters are stored for future extensibility</li>\n  </ul>\n</blockquote>\n\n<h6 id=\"examples\">Examples:</h6>\n\n<blockquote>\n  <div class=\"pdoc-code codehilite\">\n<pre><span></span><code><span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">backend</span> <span class=\"o\">=</span> <span class=\"n\">TestBackend</span><span class=\"p\">(</span><span class=\"n\">precision</span><span class=\"o\">=</span><span class=\"s2\">&quot;high&quot;</span><span class=\"p\">,</span> <span class=\"n\">cache</span><span class=\"o\">=</span><span class=\"kc\">True</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Configuration stored but not currently used</span>\n</code></pre>\n  </div>\n</blockquote>\n", "signature": "<span class=\"signature pdoc-code condensed\">(<span class=\"param\"><span class=\"o\">**</span><span class=\"n\">kwargs</span><span class=\"p\">:</span> <span class=\"n\">Any</span></span>)</span>"}, {"fullname": "dftscape.backends.TestBackend.config", "modulename": "dftscape.backends", "qualname": "TestBackend.config", "kind": "variable", "doc": "<p></p>\n"}, {"fullname": "dftscape.backends.TestBackend.compute_energy", "modulename": "dftscape.backends", "qualname": "TestBackend.compute_energy", "kind": "function", "doc": "<p>Compute the potential energy at the given 3D state.</p>\n\n<p>Evaluates the separable double-well potential function:\nf(x, y, z) = (x\u00b2-1)\u00b2 + (y\u00b2-1)\u00b2 + (z\u00b2-1)\u00b2</p>\n\n<p>This function has known analytical properties and is designed for\ntesting optimization algorithms with well-characterized critical points.</p>\n\n<h6 id=\"arguments\">Arguments:</h6>\n\n<ul>\n<li><strong>state:</strong>  1D numpy array with shape (3,) containing [x, y, z] coordinates.\nMust be exactly 3-dimensional for this test backend.</li>\n</ul>\n\n<h6 id=\"returns\">Returns:</h6>\n\n<blockquote>\n  <p>float: Potential energy value at the given coordinates.\n        Range: [0, \u221e), with global minimum at 0 and no upper bound.</p>\n</blockquote>\n\n<h6 id=\"raises\">Raises:</h6>\n\n<ul>\n<li><strong>ValueError:</strong>  If state does not have exactly 3 dimensions.</li>\n</ul>\n\n<h6 id=\"examples\">Examples:</h6>\n\n<blockquote>\n  <div class=\"pdoc-code codehilite\">\n<pre><span></span><code><span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">backend</span> <span class=\"o\">=</span> <span class=\"n\">TestBackend</span><span class=\"p\">()</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Global minimum</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">min_state</span> <span class=\"o\">=</span> <span class=\"n\">np</span><span class=\"o\">.</span><span class=\"n\">array</span><span class=\"p\">([</span><span class=\"mf\">1.0</span><span class=\"p\">,</span> <span class=\"mf\">1.0</span><span class=\"p\">,</span> <span class=\"mf\">1.0</span><span class=\"p\">])</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">energy</span> <span class=\"o\">=</span> <span class=\"n\">backend</span><span class=\"o\">.</span><span class=\"n\">compute_energy</span><span class=\"p\">(</span><span class=\"n\">min_state</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"sa\">f</span><span class=\"s2\">&quot;Global minimum energy: </span><span class=\"si\">{</span><span class=\"n\">energy</span><span class=\"si\">}</span><span class=\"s2\">&quot;</span><span class=\"p\">)</span>  <span class=\"c1\"># 0.0</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Index-1 saddle point</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">saddle_state</span> <span class=\"o\">=</span> <span class=\"n\">np</span><span class=\"o\">.</span><span class=\"n\">array</span><span class=\"p\">([</span><span class=\"mf\">0.0</span><span class=\"p\">,</span> <span class=\"mf\">1.0</span><span class=\"p\">,</span> <span class=\"mf\">1.0</span><span class=\"p\">])</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">energy</span> <span class=\"o\">=</span> <span class=\"n\">backend</span><span class=\"o\">.</span><span class=\"n\">compute_energy</span><span class=\"p\">(</span><span class=\"n\">saddle_state</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"sa\">f</span><span class=\"s2\">&quot;Saddle energy: </span><span class=\"si\">{</span><span class=\"n\">energy</span><span class=\"si\">}</span><span class=\"s2\">&quot;</span><span class=\"p\">)</span>  <span class=\"c1\"># 1.0</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Global maximum</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">max_state</span> <span class=\"o\">=</span> <span class=\"n\">np</span><span class=\"o\">.</span><span class=\"n\">array</span><span class=\"p\">([</span><span class=\"mf\">0.0</span><span class=\"p\">,</span> <span class=\"mf\">0.0</span><span class=\"p\">,</span> <span class=\"mf\">0.0</span><span class=\"p\">])</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">energy</span> <span class=\"o\">=</span> <span class=\"n\">backend</span><span class=\"o\">.</span><span class=\"n\">compute_energy</span><span class=\"p\">(</span><span class=\"n\">max_state</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"sa\">f</span><span class=\"s2\">&quot;Global maximum energy: </span><span class=\"si\">{</span><span class=\"n\">energy</span><span class=\"si\">}</span><span class=\"s2\">&quot;</span><span class=\"p\">)</span>  <span class=\"c1\"># 3.0</span>\n</code></pre>\n  </div>\n</blockquote>\n\n<h6 id=\"notes\">Notes:</h6>\n\n<blockquote>\n  <ul>\n  <li>Uses JIT-compiled JAX function for optimal performance</li>\n  <li>Computation is deterministic and thread-safe</li>\n  <li>No side effects or internal state modifications</li>\n  <li>Energy landscape is symmetric in all three coordinates</li>\n  </ul>\n</blockquote>\n", "signature": "<span class=\"signature pdoc-code condensed\">(<span class=\"param\"><span class=\"bp\">self</span>, </span><span class=\"param\"><span class=\"n\">state</span><span class=\"p\">:</span> <span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span></span><span class=\"return-annotation\">) -> <span class=\"nb\">float</span>:</span></span>", "funcdef": "def"}, {"fullname": "dftscape.backends.TestBackend.compute_gradient", "modulename": "dftscape.backends", "qualname": "TestBackend.compute_gradient", "kind": "function", "doc": "<p>Compute the analytical gradient vector using automatic differentiation.</p>\n\n<p>Calculates the exact gradient of the separable double-well potential:\n\u2207f(x, y, z) = [2(x\u00b2-1)<em>2x, 2(y\u00b2-1)</em>2y, 2(z\u00b2-1)*2z]</p>\n\n<p>The gradient is computed using JAX's automatic differentiation,\nproviding exact analytical derivatives without numerical approximations.</p>\n\n<h6 id=\"arguments\">Arguments:</h6>\n\n<ul>\n<li><strong>state:</strong>  1D numpy array with shape (3,) containing [x, y, z] coordinates.\nMust be exactly 3-dimensional for this test backend.</li>\n</ul>\n\n<h6 id=\"returns\">Returns:</h6>\n\n<blockquote>\n  <p>np.ndarray: Gradient vector with shape (3,) containing [df/dx, df/dy, df/dz].\n             Each component is the partial derivative with respect to that coordinate.</p>\n</blockquote>\n\n<h6 id=\"raises\">Raises:</h6>\n\n<ul>\n<li><strong>ValueError:</strong>  If state does not have exactly 3 dimensions.</li>\n</ul>\n\n<h6 id=\"examples\">Examples:</h6>\n\n<blockquote>\n  <div class=\"pdoc-code codehilite\">\n<pre><span></span><code><span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">backend</span> <span class=\"o\">=</span> <span class=\"n\">TestBackend</span><span class=\"p\">()</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Gradient at global minimum (should be zero)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">min_state</span> <span class=\"o\">=</span> <span class=\"n\">np</span><span class=\"o\">.</span><span class=\"n\">array</span><span class=\"p\">([</span><span class=\"mf\">1.0</span><span class=\"p\">,</span> <span class=\"mf\">1.0</span><span class=\"p\">,</span> <span class=\"mf\">1.0</span><span class=\"p\">])</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">grad</span> <span class=\"o\">=</span> <span class=\"n\">backend</span><span class=\"o\">.</span><span class=\"n\">compute_gradient</span><span class=\"p\">(</span><span class=\"n\">min_state</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"sa\">f</span><span class=\"s2\">&quot;Gradient at minimum: </span><span class=\"si\">{</span><span class=\"n\">grad</span><span class=\"si\">}</span><span class=\"s2\">&quot;</span><span class=\"p\">)</span>  <span class=\"c1\"># [0. 0. 0.]</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Gradient at origin (global maximum)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">origin</span> <span class=\"o\">=</span> <span class=\"n\">np</span><span class=\"o\">.</span><span class=\"n\">array</span><span class=\"p\">([</span><span class=\"mf\">0.0</span><span class=\"p\">,</span> <span class=\"mf\">0.0</span><span class=\"p\">,</span> <span class=\"mf\">0.0</span><span class=\"p\">])</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">grad</span> <span class=\"o\">=</span> <span class=\"n\">backend</span><span class=\"o\">.</span><span class=\"n\">compute_gradient</span><span class=\"p\">(</span><span class=\"n\">origin</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"sa\">f</span><span class=\"s2\">&quot;Gradient at origin: </span><span class=\"si\">{</span><span class=\"n\">grad</span><span class=\"si\">}</span><span class=\"s2\">&quot;</span><span class=\"p\">)</span>  <span class=\"c1\"># [0. 0. 0.]</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Gradient at a point away from critical points</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">point</span> <span class=\"o\">=</span> <span class=\"n\">np</span><span class=\"o\">.</span><span class=\"n\">array</span><span class=\"p\">([</span><span class=\"mf\">0.5</span><span class=\"p\">,</span> <span class=\"mf\">0.5</span><span class=\"p\">,</span> <span class=\"mf\">0.5</span><span class=\"p\">])</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">grad</span> <span class=\"o\">=</span> <span class=\"n\">backend</span><span class=\"o\">.</span><span class=\"n\">compute_gradient</span><span class=\"p\">(</span><span class=\"n\">point</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"sa\">f</span><span class=\"s2\">&quot;Gradient at (0.5,0.5,0.5): </span><span class=\"si\">{</span><span class=\"n\">grad</span><span class=\"si\">}</span><span class=\"s2\">&quot;</span><span class=\"p\">)</span>\n</code></pre>\n  </div>\n</blockquote>\n\n<h6 id=\"notes\">Notes:</h6>\n\n<blockquote>\n  <ul>\n  <li>Uses JIT-compiled JAX automatic differentiation</li>\n  <li>Provides exact analytical gradients (no numerical errors)</li>\n  <li>Computation is deterministic and thread-safe</li>\n  <li>Gradient vanishes at all critical points (minima, saddles, maximum)</li>\n  <li>Due to separability, each coordinate's gradient depends only on itself</li>\n  </ul>\n</blockquote>\n", "signature": "<span class=\"signature pdoc-code condensed\">(<span class=\"param\"><span class=\"bp\">self</span>, </span><span class=\"param\"><span class=\"n\">state</span><span class=\"p\">:</span> <span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span></span><span class=\"return-annotation\">) -> <span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span>:</span></span>", "funcdef": "def"}, {"fullname": "dftscape.backends.TestBackend.compute_hessian", "modulename": "dftscape.backends", "qualname": "TestBackend.compute_hessian", "kind": "function", "doc": "<p>Compute the analytical Hessian matrix using automatic differentiation.</p>\n\n<p>Calculates the exact Hessian matrix of the separable double-well potential.\nDue to the separable nature of the function, the Hessian is diagonal:</p>\n\n<p>H(x,y,z) = diag[4(3x\u00b2-1), 4(3y\u00b2-1), 4(3z\u00b2-1)]</p>\n\n<p>The Hessian is computed using JAX's automatic differentiation of the gradient,\nproviding exact analytical second derivatives.</p>\n\n<h6 id=\"arguments\">Arguments:</h6>\n\n<ul>\n<li><strong>state:</strong>  1D numpy array with shape (3,) containing [x, y, z] coordinates.\nMust be exactly 3-dimensional for this test backend.</li>\n</ul>\n\n<h6 id=\"returns\">Returns:</h6>\n\n<blockquote>\n  <p>np.ndarray: 3x3 Hessian matrix containing second derivatives.\n             Matrix is symmetric and diagonal due to function separability.</p>\n</blockquote>\n\n<h6 id=\"raises\">Raises:</h6>\n\n<ul>\n<li><strong>ValueError:</strong>  If state does not have exactly 3 dimensions.</li>\n</ul>\n\n<h6 id=\"examples\">Examples:</h6>\n\n<blockquote>\n  <div class=\"pdoc-code codehilite\">\n<pre><span></span><code><span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">backend</span> <span class=\"o\">=</span> <span class=\"n\">TestBackend</span><span class=\"p\">()</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Hessian at global minimum</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">min_state</span> <span class=\"o\">=</span> <span class=\"n\">np</span><span class=\"o\">.</span><span class=\"n\">array</span><span class=\"p\">([</span><span class=\"mf\">1.0</span><span class=\"p\">,</span> <span class=\"mf\">1.0</span><span class=\"p\">,</span> <span class=\"mf\">1.0</span><span class=\"p\">])</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">hess</span> <span class=\"o\">=</span> <span class=\"n\">backend</span><span class=\"o\">.</span><span class=\"n\">compute_hessian</span><span class=\"p\">(</span><span class=\"n\">min_state</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"s2\">&quot;Hessian at minimum:&quot;</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"n\">hess</span><span class=\"p\">)</span>  <span class=\"c1\"># Diagonal matrix with positive eigenvalues</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Hessian at origin (global maximum)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">origin</span> <span class=\"o\">=</span> <span class=\"n\">np</span><span class=\"o\">.</span><span class=\"n\">array</span><span class=\"p\">([</span><span class=\"mf\">0.0</span><span class=\"p\">,</span> <span class=\"mf\">0.0</span><span class=\"p\">,</span> <span class=\"mf\">0.0</span><span class=\"p\">])</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">hess</span> <span class=\"o\">=</span> <span class=\"n\">backend</span><span class=\"o\">.</span><span class=\"n\">compute_hessian</span><span class=\"p\">(</span><span class=\"n\">origin</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"s2\">&quot;Hessian at origin:&quot;</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"n\">hess</span><span class=\"p\">)</span>  <span class=\"c1\"># Diagonal matrix with negative eigenvalues</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Check eigenvalues (should be [-4, -4, -4] at origin)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">eigenvals</span> <span class=\"o\">=</span> <span class=\"n\">np</span><span class=\"o\">.</span><span class=\"n\">linalg</span><span class=\"o\">.</span><span class=\"n\">eigvals</span><span class=\"p\">(</span><span class=\"n\">hess</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"sa\">f</span><span class=\"s2\">&quot;Eigenvalues at origin: </span><span class=\"si\">{</span><span class=\"n\">eigenvals</span><span class=\"si\">}</span><span class=\"s2\">&quot;</span><span class=\"p\">)</span>\n</code></pre>\n  </div>\n</blockquote>\n\n<h6 id=\"notes\">Notes:</h6>\n\n<blockquote>\n  <ul>\n  <li>Uses JIT-compiled JAX automatic differentiation</li>\n  <li>Provides exact analytical Hessian (no numerical approximations)</li>\n  <li>Hessian is always diagonal due to function separability</li>\n  <li>Eigenvalues determine Morse index of critical points:\n  <ul>\n  <li>Positive eigenvalues: minima along those directions</li>\n  <li>Negative eigenvalues: maxima along those directions</li>\n  </ul></li>\n  <li>All critical points have non-degenerate Hessians</li>\n  </ul>\n</blockquote>\n", "signature": "<span class=\"signature pdoc-code condensed\">(<span class=\"param\"><span class=\"bp\">self</span>, </span><span class=\"param\"><span class=\"n\">state</span><span class=\"p\">:</span> <span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span></span><span class=\"return-annotation\">) -> <span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span>:</span></span>", "funcdef": "def"}, {"fullname": "dftscape.backends.TestBackend.get_xyz", "modulename": "dftscape.backends", "qualname": "TestBackend.get_xyz", "kind": "function", "doc": "<p>Generate XYZ format string representation of the 3D state.</p>\n\n<p>For the test backend, the 3D coordinates are represented as a single\n\"X\" atom at the specified (x, y, z) position. This provides a minimal\nmolecular representation suitable for visualization and compatibility\nwith molecular analysis tools.</p>\n\n<p>The XYZ format is a standard text-based molecular structure format\nwith the structure:</p>\n\n<ul>\n<li>Line 1: Number of atoms (1 for test backend)</li>\n<li>Line 2: Comment/title line</li>\n<li>Line 3+: Atomic symbol and coordinates (X x y z)</li>\n</ul>\n\n<h6 id=\"arguments\">Arguments:</h6>\n\n<ul>\n<li><strong>state:</strong>  1D numpy array with shape (3,) containing [x, y, z] coordinates.\nMust be exactly 3-dimensional for this test backend.</li>\n</ul>\n\n<h6 id=\"returns\">Returns:</h6>\n\n<blockquote>\n  <p>str: XYZ format string with proper formatting and newlines.\n      Contains exactly 3 lines representing a single atom.</p>\n</blockquote>\n\n<h6 id=\"raises\">Raises:</h6>\n\n<ul>\n<li><strong>ValueError:</strong>  If state does not have exactly 3 dimensions.</li>\n</ul>\n\n<h6 id=\"examples\">Examples:</h6>\n\n<blockquote>\n  <div class=\"pdoc-code codehilite\">\n<pre><span></span><code><span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">backend</span> <span class=\"o\">=</span> <span class=\"n\">TestBackend</span><span class=\"p\">()</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Get XYZ at global minimum</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">min_state</span> <span class=\"o\">=</span> <span class=\"n\">np</span><span class=\"o\">.</span><span class=\"n\">array</span><span class=\"p\">([</span><span class=\"mf\">1.0</span><span class=\"p\">,</span> <span class=\"mf\">1.0</span><span class=\"p\">,</span> <span class=\"mf\">1.0</span><span class=\"p\">])</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">xyz</span> <span class=\"o\">=</span> <span class=\"n\">backend</span><span class=\"o\">.</span><span class=\"n\">get_xyz</span><span class=\"p\">(</span><span class=\"n\">min_state</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"n\">xyz</span><span class=\"p\">)</span>\n<span class=\"go\">1</span>\n<span class=\"go\">Test molecule</span>\n<span class=\"go\">X     1.000000     1.000000     1.000000</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Get XYZ at origin</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">origin</span> <span class=\"o\">=</span> <span class=\"n\">np</span><span class=\"o\">.</span><span class=\"n\">array</span><span class=\"p\">([</span><span class=\"mf\">0.0</span><span class=\"p\">,</span> <span class=\"mf\">0.0</span><span class=\"p\">,</span> <span class=\"mf\">0.0</span><span class=\"p\">])</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">xyz</span> <span class=\"o\">=</span> <span class=\"n\">backend</span><span class=\"o\">.</span><span class=\"n\">get_xyz</span><span class=\"p\">(</span><span class=\"n\">origin</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"n\">xyz</span><span class=\"p\">)</span>\n<span class=\"go\">1</span>\n<span class=\"go\">Test molecule</span>\n<span class=\"go\">X     0.000000     0.000000     0.000000</span>\n</code></pre>\n  </div>\n</blockquote>\n\n<h6 id=\"notes\">Notes:</h6>\n\n<blockquote>\n  <ul>\n  <li>Always represents the state as a single \"X\" atom</li>\n  <li>Coordinates are formatted with 6 decimal places</li>\n  <li>Suitable for molecular visualization tools</li>\n  <li>Compatible with standard XYZ file format specifications</li>\n  <li>Comment line identifies this as a test molecule</li>\n  </ul>\n</blockquote>\n", "signature": "<span class=\"signature pdoc-code condensed\">(<span class=\"param\"><span class=\"bp\">self</span>, </span><span class=\"param\"><span class=\"n\">state</span><span class=\"p\">:</span> <span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span></span><span class=\"return-annotation\">) -> <span class=\"nb\">str</span>:</span></span>", "funcdef": "def"}, {"fullname": "dftscape.checkpoint", "modulename": "dftscape.checkpoint", "kind": "module", "doc": "<h1 id=\"dftscape-checkpoint-subpackage\">DFTScape Checkpoint Subpackage</h1>\n\n<p>The checkpoint subpackage provides a unified, extensible framework for data\npersistence and recovery in DFTScape. It supports multiple storage formats\nthrough a pluggable architecture, enabling efficient checkpointing of\nmolecular simulation data including coordinates, energies, forces, and\nother numerical arrays.</p>\n\n<h1 id=\"key-features\">Key Features</h1>\n\n<h6 id=\"multiple-storage-formats\">Multiple Storage Formats:</h6>\n\n<blockquote>\n  <ul>\n  <li>NPZ: High-performance compressed NumPy arrays with type preservation</li>\n  <li>JSON: Human-readable text format for configuration and metadata</li>\n  <li>Extensible: Easy to add new checkpoint formats via registry pattern</li>\n  </ul>\n</blockquote>\n\n<h6 id=\"type-preservation\">Type Preservation:</h6>\n\n<blockquote>\n  <ul>\n  <li>Exact preservation of NumPy dtypes and array shapes</li>\n  <li>Scalar type restoration (int, float, bool, str)</li>\n  <li>Cross-platform compatibility with byte order normalization</li>\n  </ul>\n</blockquote>\n\n<h6 id=\"performance-optimized\">Performance Optimized:</h6>\n\n<blockquote>\n  <ul>\n  <li>Compressed storage to reduce disk usage</li>\n  <li>Efficient I/O for large numerical datasets</li>\n  <li>Memory-efficient loading with lazy evaluation support</li>\n  </ul>\n</blockquote>\n\n<p>Registry-Based Architecture:\n    - Pluggable checkpoint implementations\n    - Runtime format selection\n    - Consistent API across all formats</p>\n\n<h1 id=\"available-implementations\">Available Implementations</h1>\n\n<h6 id=\"npzcheckpointer\">NPZCheckpointer:</h6>\n\n<blockquote>\n  <p>Best for large numerical datasets, molecular coordinates, forces, and\n  Hessians. Provides exact type preservation and compression.</p>\n</blockquote>\n\n<h6 id=\"jsoncheckpointer\">JSONCheckpointer:</h6>\n\n<blockquote>\n  <p>Best for configuration data, metadata, and human-readable storage.\n  Supports complex nested structures with full type fidelity.</p>\n</blockquote>\n\n<h1 id=\"usage-examples\">Usage Examples</h1>\n\n<h6 id=\"basic-checkpointing\">Basic Checkpointing:</h6>\n\n<blockquote>\n  <div class=\"pdoc-code codehilite\">\n<pre><span></span><code><span class=\"gp\">&gt;&gt;&gt; </span><span class=\"kn\">from</span><span class=\"w\"> </span><span class=\"nn\">dftscape.checkpoint</span><span class=\"w\"> </span><span class=\"kn\">import</span> <span class=\"n\">CheckpointRegistry</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Create NPZ checkpointer for numerical data</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">ckpt</span> <span class=\"o\">=</span> <span class=\"n\">CheckpointRegistry</span><span class=\"o\">.</span><span class=\"n\">create</span><span class=\"p\">(</span><span class=\"s2\">&quot;npz&quot;</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">data</span> <span class=\"o\">=</span> <span class=\"p\">{</span><span class=\"s2\">&quot;coords&quot;</span><span class=\"p\">:</span> <span class=\"n\">np</span><span class=\"o\">.</span><span class=\"n\">array</span><span class=\"p\">([[</span><span class=\"mi\">1</span><span class=\"p\">,</span> <span class=\"mi\">2</span><span class=\"p\">,</span> <span class=\"mi\">3</span><span class=\"p\">]]),</span> <span class=\"s2\">&quot;energy&quot;</span><span class=\"p\">:</span> <span class=\"o\">-</span><span class=\"mf\">123.45</span><span class=\"p\">}</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">ckpt</span><span class=\"o\">.</span><span class=\"n\">save</span><span class=\"p\">(</span><span class=\"s2\">&quot;checkpoint.npz&quot;</span><span class=\"p\">,</span> <span class=\"n\">data</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">restored</span> <span class=\"o\">=</span> <span class=\"n\">ckpt</span><span class=\"o\">.</span><span class=\"n\">load</span><span class=\"p\">(</span><span class=\"s2\">&quot;checkpoint.npz&quot;</span><span class=\"p\">)</span>\n</code></pre>\n  </div>\n</blockquote>\n\n<h6 id=\"format-selection\">Format Selection:</h6>\n\n<blockquote>\n  <div class=\"pdoc-code codehilite\">\n<pre><span></span><code><span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Use JSON for configuration data</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">json_ckpt</span> <span class=\"o\">=</span> <span class=\"n\">CheckpointRegistry</span><span class=\"o\">.</span><span class=\"n\">create</span><span class=\"p\">(</span><span class=\"s2\">&quot;json&quot;</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">config</span> <span class=\"o\">=</span> <span class=\"p\">{</span><span class=\"s2\">&quot;method&quot;</span><span class=\"p\">:</span> <span class=\"s2\">&quot;DFT&quot;</span><span class=\"p\">,</span> <span class=\"s2\">&quot;basis&quot;</span><span class=\"p\">:</span> <span class=\"s2\">&quot;6-31G*&quot;</span><span class=\"p\">,</span> <span class=\"s2\">&quot;converged&quot;</span><span class=\"p\">:</span> <span class=\"kc\">True</span><span class=\"p\">}</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">json_ckpt</span><span class=\"o\">.</span><span class=\"n\">save</span><span class=\"p\">(</span><span class=\"s2\">&quot;config.json&quot;</span><span class=\"p\">,</span> <span class=\"n\">config</span><span class=\"p\">)</span>\n</code></pre>\n  </div>\n</blockquote>\n\n<p>Explicit Array/Scalar Separation:</p>\n\n<blockquote>\n  <blockquote>\n    <blockquote>\n      <h1 id=\"for-fine-grained-control-over-data-types\">For fine-grained control over data types</h1>\n      \n      <p>arrays = {\"forces\": np.array([[0.1, 0.2, 0.3]])}\n      scalars = {\"step\": 100, \"energy\": -123.45}\n      ckpt.save_arrays_and_scalars(\"data.npz\", arrays, scalars)\n      arrays_loaded, scalars_loaded = ckpt.load_arrays_and_scalars(\"data.npz\")</p>\n    </blockquote>\n  </blockquote>\n</blockquote>\n\n<h6 id=\"registry-operations\">Registry Operations:</h6>\n\n<blockquote>\n  <div class=\"pdoc-code codehilite\">\n<pre><span></span><code><span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># List available checkpoint formats</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">available</span> <span class=\"o\">=</span> <span class=\"n\">CheckpointRegistry</span><span class=\"o\">.</span><span class=\"n\">list_available</span><span class=\"p\">()</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"n\">available</span><span class=\"p\">)</span>  <span class=\"c1\"># [&#39;npz&#39;, &#39;json&#39;]</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Get checkpointer instance by name</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">npz_ckpt</span> <span class=\"o\">=</span> <span class=\"n\">CheckpointRegistry</span><span class=\"o\">.</span><span class=\"n\">get</span><span class=\"p\">(</span><span class=\"s2\">&quot;npz&quot;</span><span class=\"p\">)</span>\n</code></pre>\n  </div>\n</blockquote>\n\n<h1 id=\"api-overview\">API Overview</h1>\n\n<h6 id=\"checkpointregistry\">CheckpointRegistry:</h6>\n\n<blockquote>\n  <p>Central registry for checkpoint implementations</p>\n  \n  <ul>\n  <li>create(format): Create checkpointer instance</li>\n  <li>get(format): Get checkpointer class</li>\n  <li>list_available(): List registered formats</li>\n  <li>register(name): Decorator for registering new formats</li>\n  </ul>\n</blockquote>\n\n<h6 id=\"checkpointer-protocol\">Checkpointer Protocol:</h6>\n\n<blockquote>\n  <p>Common interface for all checkpoint implementations</p>\n  \n  <ul>\n  <li>save(path, data): Save unified dictionary</li>\n  <li>load(path): Load unified dictionary</li>\n  <li>save_arrays_and_scalars(path, arrays, scalars): Save with separation</li>\n  <li>load_arrays_and_scalars(path): Load with separation</li>\n  </ul>\n</blockquote>\n\n<h1 id=\"notes\">Notes</h1>\n\n<ul>\n<li>All checkpointers support automatic directory creation</li>\n<li>NPZ format provides best performance for numerical data</li>\n<li>JSON format provides best readability for configuration</li>\n<li>Registry pattern enables easy extension with new formats</li>\n<li>All implementations are thread-safe for read operations</li>\n<li>Type preservation ensures exact numerical fidelity</li>\n</ul>\n\n<h1 id=\"see-also\">See Also</h1>\n\n<ul>\n<li>dftscape.checkpoint.registry: Registry implementation and protocol</li>\n<li>dftscape.checkpoint.impl_npz: NPZ-based high-performance checkpointer</li>\n<li>dftscape.checkpoint.impl_json: JSON-based human-readable checkpointer</li>\n</ul>\n"}, {"fullname": "dftscape.checkpoint.CheckpointRegistry", "modulename": "dftscape.checkpoint", "qualname": "CheckpointRegistry", "kind": "class", "doc": "<p>Registry for checkpoint implementation classes with type-safe creation.</p>\n\n<p>This registry extends the BaseRegistry to provide specialized management\nfor checkpoint implementations. It ensures type safety by casting created\ninstances to the Checkpointer protocol, enabling seamless integration\nwith DFTScape's checkpointing infrastructure.</p>\n\n<p>The registry automatically discovers and registers available checkpoint\nimplementations at import time, making new formats immediately available\nwithout code changes.</p>\n\n<h6 id=\"registered-implementations\">Registered Implementations:</h6>\n\n<blockquote>\n  <ul>\n  <li>\"json\": JSONCheckpointer for human-readable, cross-platform storage</li>\n  <li>\"npz\": NPZCheckpointer for efficient numerical data storage</li>\n  </ul>\n</blockquote>\n\n<h6 id=\"usage\">Usage:</h6>\n\n<blockquote>\n  <div class=\"pdoc-code codehilite\">\n<pre><span></span><code><span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Create checkpointer by name</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">json_cp</span> <span class=\"o\">=</span> <span class=\"n\">CheckpointRegistry</span><span class=\"o\">.</span><span class=\"n\">create</span><span class=\"p\">(</span><span class=\"s2\">&quot;json&quot;</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">npz_cp</span> <span class=\"o\">=</span> <span class=\"n\">CheckpointRegistry</span><span class=\"o\">.</span><span class=\"n\">create</span><span class=\"p\">(</span><span class=\"s2\">&quot;npz&quot;</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># List available formats</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">formats</span> <span class=\"o\">=</span> <span class=\"n\">CheckpointRegistry</span><span class=\"o\">.</span><span class=\"n\">list_available</span><span class=\"p\">()</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"n\">formats</span><span class=\"p\">)</span>  <span class=\"c1\"># [&#39;json&#39;, &#39;npz&#39;]</span>\n</code></pre>\n  </div>\n</blockquote>\n\n<h6 id=\"notes\">Notes:</h6>\n\n<blockquote>\n  <ul>\n  <li>Extends BaseRegistry with Checkpointer type safety</li>\n  <li>Automatic registration of implementations via imports</li>\n  <li>Supports dynamic instantiation with custom parameters</li>\n  <li>Used throughout DFTScape for pluggable checkpoint formats</li>\n  <li>Maintains backward compatibility with existing checkpoints</li>\n  </ul>\n</blockquote>\n", "bases": "typing.Generic[~T]"}, {"fullname": "dftscape.checkpoint.CheckpointRegistry.create", "modulename": "dftscape.checkpoint", "qualname": "CheckpointRegistry.create", "kind": "function", "doc": "<p>Create an instance of a checkpointer by name.</p>\n", "signature": "<span class=\"signature pdoc-code multiline\">(<span class=\"param\">\t<span class=\"bp\">cls</span>,</span><span class=\"param\">\t<span class=\"n\">name</span><span class=\"p\">:</span> <span class=\"nb\">str</span>,</span><span class=\"param\">\t<span class=\"o\">*</span><span class=\"n\">args</span>,</span><span class=\"param\">\t<span class=\"o\">**</span><span class=\"n\">kwargs</span></span><span class=\"return-annotation\">) -> <span class=\"n\">dftscape</span><span class=\"o\">.</span><span class=\"n\">checkpoint</span><span class=\"o\">.</span><span class=\"n\">registry</span><span class=\"o\">.</span><span class=\"n\">Checkpointer</span>:</span></span>", "funcdef": "def"}, {"fullname": "dftscape.common", "modulename": "dftscape.common", "kind": "module", "doc": "<p>Common utilities and base classes for DFTScape molecular landscape exploration.</p>\n\n<p>This package provides the foundational components and utilities used throughout\nthe DFTScape system for molecular structure analysis and landscape exploration.\nIt contains reusable patterns, data structures, and algorithms that support\nthe core functionality of DFTScape's molecular exploration capabilities.</p>\n\n<h1 id=\"key-components\">Key Components:</h1>\n\n<p>Data Structures (<code>data_structures.py</code>):\n    SerialisableDataClass: Base class for dataclasses with automatic JSON\n                          serialization support. Provides to_config()/from_config()\n                          methods for converting complex nested objects to/from\n                          dictionaries, with special handling for numpy arrays\n                          and nested serializable objects.</p>\n\n<p>Registry Pattern (<code>registry.py</code>):\n    BaseRegistry: Generic base class implementing the registry pattern for\n                 pluggable components. Supports decorator-based registration\n                 and dynamic instantiation of components by name. Used for\n                 extensible architectures throughout DFTScape.</p>\n\n<p>Distance Functions (<code>distance.py</code>):\n    DistanceRegistry: Registry for molecular structure distance functions\n    DistanceFunction: Protocol defining the interface for distance functions\n    RMSDDistance: Root Mean Square Deviation distance with multiple methods\n    EuclideanDistance: Simple Euclidean distance between coordinate arrays\n    MaxCoordinateDistance: Maximum coordinate distance between atoms</p>\n\n<h1 id=\"usage-examples\">Usage Examples:</h1>\n\n<h6 id=\"basic-data-serialization\">Basic Data Serialization:</h6>\n\n<blockquote>\n  <div class=\"pdoc-code codehilite\">\n<pre><span></span><code><span class=\"gp\">&gt;&gt;&gt; </span><span class=\"kn\">from</span><span class=\"w\"> </span><span class=\"nn\">dftscape.common</span><span class=\"w\"> </span><span class=\"kn\">import</span> <span class=\"n\">SerialisableDataClass</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"nd\">@dataclass</span>\n<span class=\"gp\">... </span><span class=\"k\">class</span><span class=\"w\"> </span><span class=\"nc\">MyData</span><span class=\"p\">(</span><span class=\"n\">SerialisableDataClass</span><span class=\"p\">):</span>\n<span class=\"gp\">... </span>    <span class=\"n\">name</span><span class=\"p\">:</span> <span class=\"nb\">str</span>\n<span class=\"gp\">... </span>    <span class=\"n\">value</span><span class=\"p\">:</span> <span class=\"nb\">float</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">data</span> <span class=\"o\">=</span> <span class=\"n\">MyData</span><span class=\"p\">(</span><span class=\"s2\">&quot;test&quot;</span><span class=\"p\">,</span> <span class=\"mf\">3.14</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">json_str</span> <span class=\"o\">=</span> <span class=\"n\">data</span><span class=\"o\">.</span><span class=\"n\">to_json</span><span class=\"p\">()</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">restored</span> <span class=\"o\">=</span> <span class=\"n\">MyData</span><span class=\"o\">.</span><span class=\"n\">from_json</span><span class=\"p\">(</span><span class=\"n\">json_str</span><span class=\"p\">)</span>\n</code></pre>\n  </div>\n</blockquote>\n\n<h6 id=\"component-registry\">Component Registry:</h6>\n\n<blockquote>\n  <div class=\"pdoc-code codehilite\">\n<pre><span></span><code><span class=\"gp\">&gt;&gt;&gt; </span><span class=\"kn\">from</span><span class=\"w\"> </span><span class=\"nn\">dftscape.common</span><span class=\"w\"> </span><span class=\"kn\">import</span> <span class=\"n\">BaseRegistry</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"k\">class</span><span class=\"w\"> </span><span class=\"nc\">MyRegistry</span><span class=\"p\">(</span><span class=\"n\">BaseRegistry</span><span class=\"p\">[</span><span class=\"n\">MyComponent</span><span class=\"p\">]):</span>\n<span class=\"gp\">... </span>    <span class=\"k\">pass</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"nd\">@MyRegistry</span><span class=\"o\">.</span><span class=\"n\">register</span><span class=\"p\">(</span><span class=\"s2\">&quot;my_comp&quot;</span><span class=\"p\">)</span>\n<span class=\"gp\">... </span><span class=\"k\">class</span><span class=\"w\"> </span><span class=\"nc\">MyComponent</span><span class=\"p\">:</span>\n<span class=\"gp\">... </span>    <span class=\"k\">pass</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">instance</span> <span class=\"o\">=</span> <span class=\"n\">MyRegistry</span><span class=\"o\">.</span><span class=\"n\">create</span><span class=\"p\">(</span><span class=\"s2\">&quot;my_comp&quot;</span><span class=\"p\">)</span>\n</code></pre>\n  </div>\n</blockquote>\n\n<h6 id=\"distance-calculations\">Distance Calculations:</h6>\n\n<blockquote>\n  <div class=\"pdoc-code codehilite\">\n<pre><span></span><code><span class=\"gp\">&gt;&gt;&gt; </span><span class=\"kn\">from</span><span class=\"w\"> </span><span class=\"nn\">dftscape.common</span><span class=\"w\"> </span><span class=\"kn\">import</span> <span class=\"n\">DistanceRegistry</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">rmsd_func</span> <span class=\"o\">=</span> <span class=\"n\">DistanceRegistry</span><span class=\"o\">.</span><span class=\"n\">create</span><span class=\"p\">(</span><span class=\"s2\">&quot;rmsd&quot;</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">distance</span> <span class=\"o\">=</span> <span class=\"n\">rmsd_func</span><span class=\"p\">(</span><span class=\"n\">xyz1</span><span class=\"p\">,</span> <span class=\"n\">xyz2</span><span class=\"p\">,</span> <span class=\"n\">method</span><span class=\"o\">=</span><span class=\"s2\">&quot;kabsch&quot;</span><span class=\"p\">)</span>\n</code></pre>\n  </div>\n</blockquote>\n\n<h1 id=\"architecture-notes\">Architecture Notes:</h1>\n\n<p>The common package follows several design principles:</p>\n\n<ul>\n<li>Extensibility through registry patterns</li>\n<li>Type safety with generic types and protocols</li>\n<li>Serialization compatibility for distributed computing</li>\n<li>Performance optimization for molecular structure operations</li>\n<li>Clean separation of concerns between data, algorithms, and infrastructure</li>\n</ul>\n\n<p>All components are designed to be thread-safe for read operations and\nsupport the distributed computing requirements of DFTScape's molecular\nlandscape exploration workflows.</p>\n"}, {"fullname": "dftscape.common.BaseRegistry", "modulename": "dftscape.common", "qualname": "BaseRegistry", "kind": "class", "doc": "<p>Base registry class for managing component factories.</p>\n\n<p>This generic base class provides the core functionality for component\nregistries in DFTScape. Each subclass gets its own registry dictionary,\nallowing different types of components to be managed independently.</p>\n\n<p>The registry supports registration of component classes by name and\nprovides methods for instantiation, lookup, and discovery. It's designed\nto be extended by specialized registries that add domain-specific\nfunctionality.</p>\n\n<h6 id=\"key-features\">Key Features:</h6>\n\n<blockquote>\n  <ul>\n  <li>Generic type support for type-safe component management</li>\n  <li>Automatic per-subclass registry isolation</li>\n  <li>Decorator-based registration syntax</li>\n  <li>Runtime component instantiation with error handling</li>\n  <li>Component discovery and listing capabilities</li>\n  </ul>\n</blockquote>\n\n<h6 id=\"usage\">Usage:</h6>\n\n<blockquote>\n  <div class=\"pdoc-code codehilite\">\n<pre><span></span><code><span class=\"gp\">&gt;&gt;&gt; </span><span class=\"k\">class</span><span class=\"w\"> </span><span class=\"nc\">MyRegistry</span><span class=\"p\">(</span><span class=\"n\">BaseRegistry</span><span class=\"p\">[</span><span class=\"n\">MyComponent</span><span class=\"p\">]):</span>\n<span class=\"gp\">... </span>    <span class=\"nd\">@classmethod</span>\n<span class=\"gp\">... </span>    <span class=\"k\">def</span><span class=\"w\"> </span><span class=\"nf\">create_special</span><span class=\"p\">(</span><span class=\"bp\">cls</span><span class=\"p\">,</span> <span class=\"n\">name</span><span class=\"p\">:</span> <span class=\"nb\">str</span><span class=\"p\">,</span> <span class=\"o\">**</span><span class=\"n\">kwargs</span><span class=\"p\">)</span> <span class=\"o\">-&gt;</span> <span class=\"n\">MyComponent</span><span class=\"p\">:</span>\n<span class=\"gp\">... </span>        <span class=\"c1\"># Add specialized creation logic</span>\n<span class=\"gp\">... </span>        <span class=\"k\">return</span> <span class=\"nb\">super</span><span class=\"p\">()</span><span class=\"o\">.</span><span class=\"n\">create</span><span class=\"p\">(</span><span class=\"n\">name</span><span class=\"p\">,</span> <span class=\"o\">**</span><span class=\"n\">kwargs</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"nd\">@MyRegistry</span><span class=\"o\">.</span><span class=\"n\">register</span><span class=\"p\">(</span><span class=\"s2\">&quot;component_a&quot;</span><span class=\"p\">)</span>\n<span class=\"gp\">... </span><span class=\"k\">class</span><span class=\"w\"> </span><span class=\"nc\">ComponentA</span><span class=\"p\">(</span><span class=\"n\">MyComponent</span><span class=\"p\">):</span>\n<span class=\"gp\">... </span>    <span class=\"k\">pass</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">instance</span> <span class=\"o\">=</span> <span class=\"n\">MyRegistry</span><span class=\"o\">.</span><span class=\"n\">create</span><span class=\"p\">(</span><span class=\"s2\">&quot;component_a&quot;</span><span class=\"p\">)</span>\n</code></pre>\n  </div>\n</blockquote>\n\n<h6 id=\"notes\">Notes:</h6>\n\n<blockquote>\n  <ul>\n  <li>Each subclass automatically gets its own _registry dictionary</li>\n  <li>Components are registered using the @register decorator</li>\n  <li>Unknown component names raise ValueError with helpful messages</li>\n  <li>Supports arbitrary constructor arguments via **kwargs</li>\n  <li>Thread-safe for read operations (registration should be done at startup)</li>\n  </ul>\n</blockquote>\n", "bases": "typing.Generic[~T]"}, {"fullname": "dftscape.common.BaseRegistry.register", "modulename": "dftscape.common", "qualname": "BaseRegistry.register", "kind": "function", "doc": "<p>Decorator to register a component class with a name.</p>\n\n<p>This class method returns a decorator that registers a component class\nin the registry under the specified name. The decorator preserves the\noriginal class while adding it to the registry for later instantiation.</p>\n\n<h6 id=\"arguments\">Arguments:</h6>\n\n<ul>\n<li><strong>name:</strong>  The name to register the component under. This name will be\nused to create instances via the create() method.</li>\n</ul>\n\n<h6 id=\"returns\">Returns:</h6>\n\n<blockquote>\n  <p>A decorator function that registers the component class and returns\n  the original class unchanged.</p>\n</blockquote>\n\n<h6 id=\"raises\">Raises:</h6>\n\n<ul>\n<li><strong>ValueError:</strong>  If a component with the same name is already registered.</li>\n</ul>\n\n<h6 id=\"examples\">Examples:</h6>\n\n<blockquote>\n  <div class=\"pdoc-code codehilite\">\n<pre><span></span><code><span class=\"gp\">&gt;&gt;&gt; </span><span class=\"nd\">@MyRegistry</span><span class=\"o\">.</span><span class=\"n\">register</span><span class=\"p\">(</span><span class=\"s2\">&quot;my_component&quot;</span><span class=\"p\">)</span>\n<span class=\"gp\">... </span><span class=\"k\">class</span><span class=\"w\"> </span><span class=\"nc\">MyComponent</span><span class=\"p\">:</span>\n<span class=\"gp\">... </span>    <span class=\"k\">def</span><span class=\"w\"> </span><span class=\"fm\">__init__</span><span class=\"p\">(</span><span class=\"bp\">self</span><span class=\"p\">,</span> <span class=\"n\">value</span><span class=\"p\">:</span> <span class=\"nb\">int</span><span class=\"p\">):</span>\n<span class=\"gp\">... </span>        <span class=\"bp\">self</span><span class=\"o\">.</span><span class=\"n\">value</span> <span class=\"o\">=</span> <span class=\"n\">value</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Later create instances by name</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">instance</span> <span class=\"o\">=</span> <span class=\"n\">MyRegistry</span><span class=\"o\">.</span><span class=\"n\">create</span><span class=\"p\">(</span><span class=\"s2\">&quot;my_component&quot;</span><span class=\"p\">,</span> <span class=\"n\">value</span><span class=\"o\">=</span><span class=\"mi\">42</span><span class=\"p\">)</span>\n</code></pre>\n  </div>\n</blockquote>\n\n<h6 id=\"notes\">Notes:</h6>\n\n<blockquote>\n  <ul>\n  <li>Registration typically happens at import time</li>\n  <li>The decorator returns the original class unchanged</li>\n  <li>Names should be unique within each registry subclass</li>\n  <li>Registered classes can be instantiated with arbitrary arguments</li>\n  </ul>\n</blockquote>\n", "signature": "<span class=\"signature pdoc-code condensed\">(<span class=\"param\"><span class=\"bp\">cls</span>, </span><span class=\"param\"><span class=\"n\">name</span><span class=\"p\">:</span> <span class=\"nb\">str</span></span><span class=\"return-annotation\">) -> <span class=\"n\">Callable</span><span class=\"p\">[[</span><span class=\"n\">Type</span><span class=\"p\">[</span><span class=\"o\">~</span><span class=\"n\">T</span><span class=\"p\">]],</span> <span class=\"n\">Type</span><span class=\"p\">[</span><span class=\"o\">~</span><span class=\"n\">T</span><span class=\"p\">]]</span>:</span></span>", "funcdef": "def"}, {"fullname": "dftscape.common.BaseRegistry.get", "modulename": "dftscape.common", "qualname": "BaseRegistry.get", "kind": "function", "doc": "<p>Get a component class by name.</p>\n\n<p>This method retrieves a previously registered component class by its\nregistered name. It's primarily used internally by the create() method\nbut can also be used directly when you need the class rather than an instance.</p>\n\n<h6 id=\"arguments\">Arguments:</h6>\n\n<ul>\n<li><strong>name:</strong>  The name of the component to retrieve.</li>\n</ul>\n\n<h6 id=\"returns\">Returns:</h6>\n\n<blockquote>\n  <p>The component class registered under the given name.</p>\n</blockquote>\n\n<h6 id=\"raises\">Raises:</h6>\n\n<ul>\n<li><strong>ValueError:</strong>  If no component with the given name is registered.\nThe error message includes all available component names.</li>\n</ul>\n\n<h6 id=\"examples\">Examples:</h6>\n\n<blockquote>\n  <div class=\"pdoc-code codehilite\">\n<pre><span></span><code><span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Get the class directly</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">component_class</span> <span class=\"o\">=</span> <span class=\"n\">MyRegistry</span><span class=\"o\">.</span><span class=\"n\">get</span><span class=\"p\">(</span><span class=\"s2\">&quot;my_component&quot;</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">instance</span> <span class=\"o\">=</span> <span class=\"n\">component_class</span><span class=\"p\">(</span><span class=\"n\">arg1</span><span class=\"o\">=</span><span class=\"s2\">&quot;value&quot;</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Usually you&#39;ll use create() instead</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">instance</span> <span class=\"o\">=</span> <span class=\"n\">MyRegistry</span><span class=\"o\">.</span><span class=\"n\">create</span><span class=\"p\">(</span><span class=\"s2\">&quot;my_component&quot;</span><span class=\"p\">,</span> <span class=\"n\">arg1</span><span class=\"o\">=</span><span class=\"s2\">&quot;value&quot;</span><span class=\"p\">)</span>\n</code></pre>\n  </div>\n</blockquote>\n\n<h6 id=\"notes\">Notes:</h6>\n\n<blockquote>\n  <ul>\n  <li>This method returns the class, not an instance</li>\n  <li>Use create() for most use cases that need instances</li>\n  <li>Error messages include all available names for debugging</li>\n  <li>Case-sensitive name matching</li>\n  </ul>\n</blockquote>\n", "signature": "<span class=\"signature pdoc-code condensed\">(<span class=\"param\"><span class=\"bp\">cls</span>, </span><span class=\"param\"><span class=\"n\">name</span><span class=\"p\">:</span> <span class=\"nb\">str</span></span><span class=\"return-annotation\">) -> <span class=\"n\">Type</span><span class=\"p\">[</span><span class=\"o\">~</span><span class=\"n\">T</span><span class=\"p\">]</span>:</span></span>", "funcdef": "def"}, {"fullname": "dftscape.common.BaseRegistry.create", "modulename": "dftscape.common", "qualname": "BaseRegistry.create", "kind": "function", "doc": "<p>Create an instance of a component by name.</p>\n\n<p>This is the primary method for instantiating registered components.\nIt looks up the component class by name and creates an instance with\nthe provided arguments. If the instance has a _registry_key attribute,\nit will be set to the creation name for tracking purposes.</p>\n\n<h6 id=\"arguments\">Arguments:</h6>\n\n<ul>\n<li><strong>name:</strong>  The name of the component to instantiate.</li>\n<li><strong>*args:</strong>  Positional arguments to pass to the component constructor.</li>\n<li><strong>**kwargs:</strong>  Keyword arguments to pass to the component constructor.</li>\n</ul>\n\n<h6 id=\"returns\">Returns:</h6>\n\n<blockquote>\n  <p>An instance of the requested component class.</p>\n</blockquote>\n\n<h6 id=\"raises\">Raises:</h6>\n\n<ul>\n<li><strong>ValueError:</strong>  If no component with the given name is registered.</li>\n<li><strong>TypeError:</strong>  If the component constructor arguments are invalid.</li>\n</ul>\n\n<h6 id=\"examples\">Examples:</h6>\n\n<blockquote>\n  <div class=\"pdoc-code codehilite\">\n<pre><span></span><code><span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Simple instantiation</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">instance</span> <span class=\"o\">=</span> <span class=\"n\">MyRegistry</span><span class=\"o\">.</span><span class=\"n\">create</span><span class=\"p\">(</span><span class=\"s2\">&quot;my_component&quot;</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># With constructor arguments</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">instance</span> <span class=\"o\">=</span> <span class=\"n\">MyRegistry</span><span class=\"o\">.</span><span class=\"n\">create</span><span class=\"p\">(</span><span class=\"s2\">&quot;my_component&quot;</span><span class=\"p\">,</span> <span class=\"n\">value</span><span class=\"o\">=</span><span class=\"mi\">42</span><span class=\"p\">,</span> <span class=\"n\">name</span><span class=\"o\">=</span><span class=\"s2\">&quot;test&quot;</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Check registry key if supported</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"k\">if</span> <span class=\"nb\">hasattr</span><span class=\"p\">(</span><span class=\"n\">instance</span><span class=\"p\">,</span> <span class=\"s1\">&#39;_registry_key&#39;</span><span class=\"p\">):</span>\n<span class=\"gp\">... </span>    <span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"sa\">f</span><span class=\"s2\">&quot;Created from: </span><span class=\"si\">{</span><span class=\"n\">instance</span><span class=\"o\">.</span><span class=\"n\">_registry_key</span><span class=\"si\">}</span><span class=\"s2\">&quot;</span><span class=\"p\">)</span>\n</code></pre>\n  </div>\n</blockquote>\n\n<h6 id=\"notes\">Notes:</h6>\n\n<blockquote>\n  <ul>\n  <li>Automatically sets _registry_key attribute if present on instance</li>\n  <li>Supports arbitrary constructor signatures</li>\n  <li>Error messages include available component names</li>\n  <li>Most common way to instantiate registered components</li>\n  </ul>\n</blockquote>\n", "signature": "<span class=\"signature pdoc-code condensed\">(<span class=\"param\"><span class=\"bp\">cls</span>, </span><span class=\"param\"><span class=\"n\">name</span><span class=\"p\">:</span> <span class=\"nb\">str</span>, </span><span class=\"param\"><span class=\"o\">*</span><span class=\"n\">args</span>, </span><span class=\"param\"><span class=\"o\">**</span><span class=\"n\">kwargs</span></span><span class=\"return-annotation\">) -> <span class=\"o\">~</span><span class=\"n\">T</span>:</span></span>", "funcdef": "def"}, {"fullname": "dftscape.common.BaseRegistry.list_available", "modulename": "dftscape.common", "qualname": "BaseRegistry.list_available", "kind": "function", "doc": "<p>List all available component names.</p>\n\n<p>This method returns a list of all component names currently registered\nin this registry. It's useful for discovering available components at\nruntime and for providing user interfaces or configuration options.</p>\n\n<h6 id=\"returns\">Returns:</h6>\n\n<blockquote>\n  <p>A list of strings containing all registered component names,\n  sorted alphabetically.</p>\n</blockquote>\n\n<h6 id=\"examples\">Examples:</h6>\n\n<blockquote>\n  <div class=\"pdoc-code codehilite\">\n<pre><span></span><code><span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">available</span> <span class=\"o\">=</span> <span class=\"n\">MyRegistry</span><span class=\"o\">.</span><span class=\"n\">list_available</span><span class=\"p\">()</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"s2\">&quot;Available components:&quot;</span><span class=\"p\">,</span> <span class=\"n\">available</span><span class=\"p\">)</span>\n<span class=\"go\">[&#39;component_a&#39;, &#39;component_b&#39;, &#39;component_c&#39;]</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Check if a specific component exists</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"k\">if</span> <span class=\"s2\">&quot;my_component&quot;</span> <span class=\"ow\">in</span> <span class=\"n\">MyRegistry</span><span class=\"o\">.</span><span class=\"n\">list_available</span><span class=\"p\">():</span>\n<span class=\"gp\">... </span>    <span class=\"n\">instance</span> <span class=\"o\">=</span> <span class=\"n\">MyRegistry</span><span class=\"o\">.</span><span class=\"n\">create</span><span class=\"p\">(</span><span class=\"s2\">&quot;my_component&quot;</span><span class=\"p\">)</span>\n</code></pre>\n  </div>\n</blockquote>\n\n<h6 id=\"notes\">Notes:</h6>\n\n<blockquote>\n  <ul>\n  <li>Returns names in alphabetical order</li>\n  <li>Empty list if no components are registered</li>\n  <li>Useful for validation and user interface generation</li>\n  <li>Names correspond to those used with register() and create()</li>\n  </ul>\n</blockquote>\n", "signature": "<span class=\"signature pdoc-code condensed\">(<span class=\"param\"><span class=\"bp\">cls</span></span><span class=\"return-annotation\">) -> <span class=\"nb\">list</span><span class=\"p\">[</span><span class=\"nb\">str</span><span class=\"p\">]</span>:</span></span>", "funcdef": "def"}, {"fullname": "dftscape.common.SerialisableDataClass", "modulename": "dftscape.common", "qualname": "SerialisableDataClass", "kind": "class", "doc": "<p>Base class for dataclasses with automatic JSON serialization support.</p>\n\n<p>This abstract base class provides comprehensive serialization capabilities\nfor dataclasses used in DFTScape. It automatically handles conversion to/from\ndictionary representations suitable for JSON serialization, with special\nsupport for numpy arrays, nested objects, and complex data structures.</p>\n\n<p>The class uses Python's dataclass decorator and is frozen to ensure\nimmutability, which is important for maintaining data integrity in\ndistributed computing environments.</p>\n\n<p>Key Features:</p>\n\n<ul>\n<li>Automatic field serialization with type preservation</li>\n<li>Numpy array handling with dtype information</li>\n<li>Recursive serialization of nested SerialisableDataClass objects</li>\n<li>Dynamic deserialization with class reconstruction</li>\n<li>JSON string conversion methods</li>\n</ul>\n\n<h6 id=\"usage\">Usage:</h6>\n\n<blockquote>\n  <div class=\"pdoc-code codehilite\">\n<pre><span></span><code><span class=\"gp\">&gt;&gt;&gt; </span><span class=\"nd\">@dataclass</span>\n<span class=\"gp\">... </span><span class=\"k\">class</span><span class=\"w\"> </span><span class=\"nc\">MyPoint</span><span class=\"p\">(</span><span class=\"n\">SerialisableDataClass</span><span class=\"p\">):</span>\n<span class=\"gp\">... </span>    <span class=\"n\">x</span><span class=\"p\">:</span> <span class=\"nb\">float</span>\n<span class=\"gp\">... </span>    <span class=\"n\">y</span><span class=\"p\">:</span> <span class=\"nb\">float</span>\n<span class=\"gp\">... </span>    <span class=\"n\">coords</span><span class=\"p\">:</span> <span class=\"n\">np</span><span class=\"o\">.</span><span class=\"n\">ndarray</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">point</span> <span class=\"o\">=</span> <span class=\"n\">MyPoint</span><span class=\"p\">(</span><span class=\"mf\">1.0</span><span class=\"p\">,</span> <span class=\"mf\">2.0</span><span class=\"p\">,</span> <span class=\"n\">np</span><span class=\"o\">.</span><span class=\"n\">array</span><span class=\"p\">([</span><span class=\"mf\">1.0</span><span class=\"p\">,</span> <span class=\"mf\">2.0</span><span class=\"p\">]))</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">config</span> <span class=\"o\">=</span> <span class=\"n\">point</span><span class=\"o\">.</span><span class=\"n\">to_config</span><span class=\"p\">()</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">restored</span> <span class=\"o\">=</span> <span class=\"n\">MyPoint</span><span class=\"o\">.</span><span class=\"n\">from_config</span><span class=\"p\">(</span><span class=\"n\">config</span><span class=\"p\">)</span>\n</code></pre>\n  </div>\n</blockquote>\n\n<h6 id=\"notes\">Notes:</h6>\n\n<blockquote>\n  <ul>\n  <li>Subclasses must be decorated with @dataclass</li>\n  <li>Frozen=True ensures immutability for thread safety</li>\n  <li>None values are skipped during serialization</li>\n  <li>Class and module information is embedded for deserialization</li>\n  </ul>\n</blockquote>\n"}, {"fullname": "dftscape.common.SerialisableDataClass.to_config", "modulename": "dftscape.common", "qualname": "SerialisableDataClass.to_config", "kind": "function", "doc": "<p>Convert dataclass instance to dictionary representation for JSON serialization.</p>\n\n<p>This method recursively traverses all fields of the dataclass and converts\nthem to a dictionary format suitable for JSON serialization. It handles\nvarious data types including numpy arrays, nested objects, and collections.</p>\n\n<h6 id=\"returns\">Returns:</h6>\n\n<blockquote>\n  <p>Dict[str, Any]: Dictionary containing all serializable field values\n                 with special handling for complex types.</p>\n</blockquote>\n\n<h6 id=\"notes\">Notes:</h6>\n\n<blockquote>\n  <ul>\n  <li>Numpy arrays are converted to lists with dtype information preserved</li>\n  <li>Nested SerialisableDataClass objects are recursively serialized</li>\n  <li>None values are skipped to keep JSON clean</li>\n  <li>Class and module information is added for deserialization</li>\n  <li>Handles lists, tuples, and dictionaries containing serializable objects</li>\n  </ul>\n</blockquote>\n\n<h6 id=\"examples\">Examples:</h6>\n\n<blockquote>\n  <div class=\"pdoc-code codehilite\">\n<pre><span></span><code><span class=\"gp\">&gt;&gt;&gt; </span><span class=\"nd\">@dataclass</span>\n<span class=\"gp\">... </span><span class=\"k\">class</span><span class=\"w\"> </span><span class=\"nc\">Point</span><span class=\"p\">(</span><span class=\"n\">SerialisableDataClass</span><span class=\"p\">):</span>\n<span class=\"gp\">... </span>    <span class=\"n\">x</span><span class=\"p\">:</span> <span class=\"nb\">float</span>\n<span class=\"gp\">... </span>    <span class=\"n\">y</span><span class=\"p\">:</span> <span class=\"nb\">float</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">p</span> <span class=\"o\">=</span> <span class=\"n\">Point</span><span class=\"p\">(</span><span class=\"mf\">1.0</span><span class=\"p\">,</span> <span class=\"mf\">2.0</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">p</span><span class=\"o\">.</span><span class=\"n\">to_config</span><span class=\"p\">()</span>\n<span class=\"go\">{&#39;x&#39;: 1.0, &#39;y&#39;: 2.0, &#39;_class&#39;: &#39;Point&#39;, &#39;_module&#39;: &#39;...&#39;}</span>\n</code></pre>\n  </div>\n  \n  <div class=\"pdoc-code codehilite\">\n<pre><span></span><code><span class=\"gp\">&gt;&gt;&gt; </span><span class=\"nd\">@dataclass</span>\n<span class=\"gp\">... </span><span class=\"k\">class</span><span class=\"w\"> </span><span class=\"nc\">Data</span><span class=\"p\">(</span><span class=\"n\">SerialisableDataClass</span><span class=\"p\">):</span>\n<span class=\"gp\">... </span>    <span class=\"n\">array</span><span class=\"p\">:</span> <span class=\"n\">np</span><span class=\"o\">.</span><span class=\"n\">ndarray</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">d</span> <span class=\"o\">=</span> <span class=\"n\">Data</span><span class=\"p\">(</span><span class=\"n\">np</span><span class=\"o\">.</span><span class=\"n\">array</span><span class=\"p\">([</span><span class=\"mi\">1</span><span class=\"p\">,</span> <span class=\"mi\">2</span><span class=\"p\">,</span> <span class=\"mi\">3</span><span class=\"p\">]))</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">d</span><span class=\"o\">.</span><span class=\"n\">to_config</span><span class=\"p\">()</span>\n<span class=\"go\">{&#39;array&#39;: [1, 2, 3], &#39;array_dtype&#39;: &#39;&lt;i8&#39;, &#39;_class&#39;: &#39;Data&#39;, ...}</span>\n</code></pre>\n  </div>\n</blockquote>\n", "signature": "<span class=\"signature pdoc-code condensed\">(<span class=\"param\"><span class=\"bp\">self</span></span><span class=\"return-annotation\">) -> <span class=\"n\">Dict</span><span class=\"p\">[</span><span class=\"nb\">str</span><span class=\"p\">,</span> <span class=\"n\">Any</span><span class=\"p\">]</span>:</span></span>", "funcdef": "def"}, {"fullname": "dftscape.common.SerialisableDataClass.from_config", "modulename": "dftscape.common", "qualname": "SerialisableDataClass.from_config", "kind": "function", "doc": "<p>Reconstruct dataclass instance from dictionary representation.</p>\n\n<p>This class method performs the inverse operation of to_config(), reconstructing\na dataclass instance from a serialized dictionary. It handles type conversion,\nnumpy array reconstruction, and dynamic instantiation of nested objects.</p>\n\n<h6 id=\"arguments\">Arguments:</h6>\n\n<ul>\n<li><strong>config:</strong>  Dictionary containing serialized field values, typically\nproduced by to_config() method.</li>\n</ul>\n\n<h6 id=\"returns\">Returns:</h6>\n\n<blockquote>\n  <p>T: Reconstructed instance of the dataclass with all fields properly\n     typed and converted.</p>\n</blockquote>\n\n<h6 id=\"raises\">Raises:</h6>\n\n<ul>\n<li><strong>ImportError:</strong>  If referenced classes cannot be imported during reconstruction.</li>\n<li><strong>ValueError:</strong>  If configuration contains invalid data types or structures.</li>\n</ul>\n\n<h6 id=\"notes\">Notes:</h6>\n\n<blockquote>\n  <ul>\n  <li>Automatically reconstructs numpy arrays from lists and dtype info</li>\n  <li>Dynamically imports and instantiates nested SerialisableDataClass objects</li>\n  <li>Handles complex nested structures (lists, tuples, dictionaries)</li>\n  <li>Removes metadata fields (_class, _module, *_dtype) during reconstruction</li>\n  <li>Preserves original data types where possible</li>\n  </ul>\n</blockquote>\n\n<h6 id=\"examples\">Examples:</h6>\n\n<blockquote>\n  <div class=\"pdoc-code codehilite\">\n<pre><span></span><code><span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">config</span> <span class=\"o\">=</span> <span class=\"p\">{</span><span class=\"s1\">&#39;x&#39;</span><span class=\"p\">:</span> <span class=\"mf\">1.0</span><span class=\"p\">,</span> <span class=\"s1\">&#39;y&#39;</span><span class=\"p\">:</span> <span class=\"mf\">2.0</span><span class=\"p\">,</span> <span class=\"s1\">&#39;_class&#39;</span><span class=\"p\">:</span> <span class=\"s1\">&#39;Point&#39;</span><span class=\"p\">,</span> <span class=\"s1\">&#39;_module&#39;</span><span class=\"p\">:</span> <span class=\"s1\">&#39;...&#39;</span><span class=\"p\">}</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">point</span> <span class=\"o\">=</span> <span class=\"n\">Point</span><span class=\"o\">.</span><span class=\"n\">from_config</span><span class=\"p\">(</span><span class=\"n\">config</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">point</span><span class=\"o\">.</span><span class=\"n\">x</span><span class=\"p\">,</span> <span class=\"n\">point</span><span class=\"o\">.</span><span class=\"n\">y</span>\n<span class=\"go\">(1.0, 2.0)</span>\n</code></pre>\n  </div>\n</blockquote>\n", "signature": "<span class=\"signature pdoc-code condensed\">(<span class=\"param\"><span class=\"bp\">cls</span><span class=\"p\">:</span> <span class=\"n\">Type</span><span class=\"p\">[</span><span class=\"o\">~</span><span class=\"n\">T</span><span class=\"p\">]</span>, </span><span class=\"param\"><span class=\"n\">config</span><span class=\"p\">:</span> <span class=\"n\">Dict</span><span class=\"p\">[</span><span class=\"nb\">str</span><span class=\"p\">,</span> <span class=\"n\">Any</span><span class=\"p\">]</span></span><span class=\"return-annotation\">) -> <span class=\"o\">~</span><span class=\"n\">T</span>:</span></span>", "funcdef": "def"}, {"fullname": "dftscape.common.SerialisableDataClass.to_json", "modulename": "dftscape.common", "qualname": "SerialisableDataClass.to_json", "kind": "function", "doc": "<p>Convert dataclass instance to formatted JSON string.</p>\n\n<p>This method provides a convenient way to serialize the dataclass to a\nhuman-readable JSON string with proper indentation.</p>\n\n<h6 id=\"returns\">Returns:</h6>\n\n<blockquote>\n  <p>str: JSON string representation of the dataclass with 2-space indentation.</p>\n</blockquote>\n\n<h6 id=\"notes\">Notes:</h6>\n\n<blockquote>\n  <ul>\n  <li>Uses json.dumps with indent=2 for readability</li>\n  <li>Internally calls to_config() for serialization</li>\n  <li>Suitable for configuration files, debugging, or data exchange</li>\n  </ul>\n</blockquote>\n\n<h6 id=\"examples\">Examples:</h6>\n\n<blockquote>\n  <div class=\"pdoc-code codehilite\">\n<pre><span></span><code><span class=\"gp\">&gt;&gt;&gt; </span><span class=\"nd\">@dataclass</span>\n<span class=\"gp\">... </span><span class=\"k\">class</span><span class=\"w\"> </span><span class=\"nc\">Config</span><span class=\"p\">(</span><span class=\"n\">SerialisableDataClass</span><span class=\"p\">):</span>\n<span class=\"gp\">... </span>    <span class=\"n\">name</span><span class=\"p\">:</span> <span class=\"nb\">str</span>\n<span class=\"gp\">... </span>    <span class=\"n\">value</span><span class=\"p\">:</span> <span class=\"nb\">int</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">c</span> <span class=\"o\">=</span> <span class=\"n\">Config</span><span class=\"p\">(</span><span class=\"s2\">&quot;test&quot;</span><span class=\"p\">,</span> <span class=\"mi\">42</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"n\">c</span><span class=\"o\">.</span><span class=\"n\">to_json</span><span class=\"p\">())</span>\n<span class=\"go\">{</span>\n<span class=\"go\">  &quot;name&quot;: &quot;test&quot;,</span>\n<span class=\"go\">  &quot;value&quot;: 42,</span>\n<span class=\"go\">  &quot;_class&quot;: &quot;Config&quot;,</span>\n<span class=\"go\">  &quot;_module&quot;: &quot;...&quot;</span>\n<span class=\"go\">}</span>\n</code></pre>\n  </div>\n</blockquote>\n", "signature": "<span class=\"signature pdoc-code condensed\">(<span class=\"param\"><span class=\"bp\">self</span></span><span class=\"return-annotation\">) -> <span class=\"nb\">str</span>:</span></span>", "funcdef": "def"}, {"fullname": "dftscape.common.SerialisableDataClass.from_json", "modulename": "dftscape.common", "qualname": "SerialisableDataClass.from_json", "kind": "function", "doc": "<p>Load dataclass instance from JSON string.</p>\n\n<p>This class method provides a convenient way to deserialize a dataclass\nfrom a JSON string, performing the inverse operation of to_json().</p>\n\n<h6 id=\"arguments\">Arguments:</h6>\n\n<ul>\n<li><strong>json_str:</strong>  JSON string containing serialized dataclass data,\ntypically produced by to_json().</li>\n</ul>\n\n<h6 id=\"returns\">Returns:</h6>\n\n<blockquote>\n  <p>T: Reconstructed dataclass instance with all fields properly typed.</p>\n</blockquote>\n\n<h6 id=\"raises\">Raises:</h6>\n\n<ul>\n<li><strong>json.JSONDecodeError:</strong>  If the JSON string is malformed.</li>\n<li><strong>ImportError:</strong>  If referenced classes cannot be imported.</li>\n<li><strong>ValueError:</strong>  If the JSON contains invalid data structures.</li>\n</ul>\n\n<h6 id=\"notes\">Notes:</h6>\n\n<blockquote>\n  <ul>\n  <li>Uses json.loads to parse the JSON string</li>\n  <li>Internally calls from_config() for object reconstruction</li>\n  <li>Handles all the same data types as from_config()</li>\n  <li>Preserves complex nested structures and numpy arrays</li>\n  </ul>\n</blockquote>\n\n<h6 id=\"examples\">Examples:</h6>\n\n<blockquote>\n  <div class=\"pdoc-code codehilite\">\n<pre><span></span><code><span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">json_str</span> <span class=\"o\">=</span> <span class=\"s1\">&#39;{&quot;name&quot;: &quot;test&quot;, &quot;value&quot;: 42, &quot;_class&quot;: &quot;Config&quot;, ...}&#39;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">config</span> <span class=\"o\">=</span> <span class=\"n\">Config</span><span class=\"o\">.</span><span class=\"n\">from_json</span><span class=\"p\">(</span><span class=\"n\">json_str</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">config</span><span class=\"o\">.</span><span class=\"n\">name</span><span class=\"p\">,</span> <span class=\"n\">config</span><span class=\"o\">.</span><span class=\"n\">value</span>\n<span class=\"go\">(&#39;test&#39;, 42)</span>\n</code></pre>\n  </div>\n</blockquote>\n", "signature": "<span class=\"signature pdoc-code condensed\">(<span class=\"param\"><span class=\"bp\">cls</span><span class=\"p\">:</span> <span class=\"n\">Type</span><span class=\"p\">[</span><span class=\"o\">~</span><span class=\"n\">T</span><span class=\"p\">]</span>, </span><span class=\"param\"><span class=\"n\">json_str</span><span class=\"p\">:</span> <span class=\"nb\">str</span></span><span class=\"return-annotation\">) -> <span class=\"o\">~</span><span class=\"n\">T</span>:</span></span>", "funcdef": "def"}, {"fullname": "dftscape.common.DistanceRegistry", "modulename": "dftscape.common", "qualname": "DistanceRegistry", "kind": "class", "doc": "<p>Registry for distance function classes with type-safe creation.</p>\n\n<p>This registry extends the BaseRegistry to provide specialized management\nfor distance function implementations. It ensures type safety by casting\ncreated instances to the DistanceFunction protocol.</p>\n\n<p>The registry allows distance functions to be registered by name and\ninstantiated dynamically, enabling runtime configuration of distance\nmetrics in DFTScape's molecular landscape exploration algorithms.</p>\n\n<h6 id=\"registered-functions\">Registered Functions:</h6>\n\n<blockquote>\n  <ul>\n  <li>\"rmsd\": RMSD (Root Mean Square Deviation) distance</li>\n  <li>\"euclidean\": Euclidean distance between coordinate arrays</li>\n  <li>\"max_coordinate\": Maximum coordinate distance between atoms</li>\n  </ul>\n</blockquote>\n\n<h6 id=\"usage\">Usage:</h6>\n\n<blockquote>\n  <div class=\"pdoc-code codehilite\">\n<pre><span></span><code><span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Register a custom distance function</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"nd\">@DistanceRegistry</span><span class=\"o\">.</span><span class=\"n\">register</span><span class=\"p\">(</span><span class=\"s2\">&quot;custom&quot;</span><span class=\"p\">)</span>\n<span class=\"gp\">... </span><span class=\"k\">class</span><span class=\"w\"> </span><span class=\"nc\">CustomDistance</span><span class=\"p\">(</span><span class=\"n\">DistanceFunctionBase</span><span class=\"p\">):</span>\n<span class=\"gp\">... </span>    <span class=\"k\">def</span><span class=\"w\"> </span><span class=\"fm\">__call__</span><span class=\"p\">(</span><span class=\"bp\">self</span><span class=\"p\">,</span> <span class=\"n\">xyz1</span><span class=\"p\">,</span> <span class=\"n\">xyz2</span><span class=\"p\">,</span> <span class=\"o\">**</span><span class=\"n\">kwargs</span><span class=\"p\">):</span>\n<span class=\"gp\">... </span>        <span class=\"k\">return</span> <span class=\"mf\">0.0</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Create instance by name</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">dist_func</span> <span class=\"o\">=</span> <span class=\"n\">DistanceRegistry</span><span class=\"o\">.</span><span class=\"n\">create</span><span class=\"p\">(</span><span class=\"s2\">&quot;rmsd&quot;</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">distance</span> <span class=\"o\">=</span> <span class=\"n\">dist_func</span><span class=\"p\">(</span><span class=\"n\">xyz1</span><span class=\"p\">,</span> <span class=\"n\">xyz2</span><span class=\"p\">)</span>\n</code></pre>\n  </div>\n</blockquote>\n\n<h6 id=\"notes\">Notes:</h6>\n\n<blockquote>\n  <ul>\n  <li>Extends BaseRegistry with DistanceFunction type safety</li>\n  <li>Supports dynamic registration and instantiation</li>\n  <li>Used throughout DFTScape for pluggable distance metrics</li>\n  <li>Maintains list of available distance functions</li>\n  </ul>\n</blockquote>\n", "bases": "typing.Generic[~T]"}, {"fullname": "dftscape.common.DistanceRegistry.create", "modulename": "dftscape.common", "qualname": "DistanceRegistry.create", "kind": "function", "doc": "<p>Create an instance of a distance function by name.</p>\n", "signature": "<span class=\"signature pdoc-code multiline\">(<span class=\"param\">\t<span class=\"bp\">cls</span>,</span><span class=\"param\">\t<span class=\"n\">name</span><span class=\"p\">:</span> <span class=\"nb\">str</span>,</span><span class=\"param\">\t<span class=\"o\">*</span><span class=\"n\">args</span>,</span><span class=\"param\">\t<span class=\"o\">**</span><span class=\"n\">kwargs</span></span><span class=\"return-annotation\">) -> <span class=\"n\">dftscape</span><span class=\"o\">.</span><span class=\"n\">common</span><span class=\"o\">.</span><span class=\"n\">distance</span><span class=\"o\">.</span><span class=\"n\">DistanceFunction</span>:</span></span>", "funcdef": "def"}, {"fullname": "dftscape.common.DistanceFunction", "modulename": "dftscape.common", "qualname": "DistanceFunction", "kind": "class", "doc": "<p>Protocol for distance functions used to measure molecular structure similarity.</p>\n\n<p>This protocol defines the standard interface that all distance functions\nin DFTScape must implement. It ensures consistency across different distance\nmetrics and enables polymorphic usage in the molecular landscape exploration\nalgorithms.</p>\n\n<p>The protocol requires a callable that takes two XYZ format strings and\nreturns a float distance value, with support for additional keyword arguments\nfor configuration.</p>\n\n<h6 id=\"usage\">Usage:</h6>\n\n<blockquote>\n  <div class=\"pdoc-code codehilite\">\n<pre><span></span><code><span class=\"gp\">&gt;&gt;&gt; </span><span class=\"k\">def</span><span class=\"w\"> </span><span class=\"nf\">my_distance</span><span class=\"p\">(</span><span class=\"n\">xyz1</span><span class=\"p\">:</span> <span class=\"nb\">str</span><span class=\"p\">,</span> <span class=\"n\">xyz2</span><span class=\"p\">:</span> <span class=\"nb\">str</span><span class=\"p\">,</span> <span class=\"o\">**</span><span class=\"n\">kwargs</span><span class=\"p\">)</span> <span class=\"o\">-&gt;</span> <span class=\"nb\">float</span><span class=\"p\">:</span>\n<span class=\"gp\">... </span>    <span class=\"c1\"># Implementation here</span>\n<span class=\"gp\">... </span>    <span class=\"k\">return</span> <span class=\"n\">distance_value</span>\n</code></pre>\n  </div>\n</blockquote>\n\n<h6 id=\"notes\">Notes:</h6>\n\n<blockquote>\n  <ul>\n  <li>Lower distance values indicate more similar structures</li>\n  <li>Functions should handle XYZ format strings as input</li>\n  <li>Additional parameters can be passed via **kwargs</li>\n  <li>Functions should be deterministic and symmetric</li>\n  </ul>\n</blockquote>\n", "bases": "typing.Protocol"}, {"fullname": "dftscape.common.DistanceFunction.__init__", "modulename": "dftscape.common", "qualname": "DistanceFunction.__init__", "kind": "function", "doc": "<p></p>\n", "signature": "<span class=\"signature pdoc-code condensed\">(<span class=\"param\"><span class=\"o\">*</span><span class=\"n\">args</span>, </span><span class=\"param\"><span class=\"o\">**</span><span class=\"n\">kwargs</span></span>)</span>"}, {"fullname": "dftscape.core", "modulename": "dftscape.core", "kind": "module", "doc": "<p>Core DFTScape components for molecular dynamics and critical point finding.</p>\n\n<p>This module provides the fundamental building blocks for DFTScape's molecular\ndynamics simulations and critical point location algorithms. It integrates\nspecialized components for efficient navigation of potential energy surfaces.</p>\n\n<h2 id=\"core-components\">Core Components</h2>\n\n<p>Dynamics Framework:</p>\n\n<ul>\n<li>Dynamics: Abstract base class defining the interface for all dynamics simulations</li>\n<li>HiSD: High index Saddle Dynamics for finding transition states</li>\n</ul>\n\n<p>Computational Backends:</p>\n\n<ul>\n<li>Backend: Abstract interface for quantum chemistry computations</li>\n<li>Backend implementations for different quantum chemistry packages</li>\n</ul>\n\n<p>Eigensolvers:</p>\n\n<ul>\n<li>Multiple eigensolver implementations for Hessian eigenvalue computations</li>\n<li>Optimized for large-scale molecular systems</li>\n</ul>\n\n<p>Symmetry and Constraints:</p>\n\n<ul>\n<li>SymmetryHandler: Manages molecular symmetry constraints</li>\n<li>SubspaceHandler: Handles subspace projections and constraints</li>\n</ul>\n\n<p>Search and Orchestration:</p>\n\n<ul>\n<li>SearchOrchestrator: Coordinates complex search workflows</li>\n<li>JobExecutor: Manages parallel computation jobs</li>\n<li>NodeStateManager: Tracks computational node states</li>\n</ul>\n\n<h2 id=\"key-concepts\">Key Concepts</h2>\n\n<p>Critical Points: Stationary points on the potential energy surface where the gradient is zero</p>\n\n<ul>\n<li>Minima: Local energy minima (all Hessian eigenvalues positive)</li>\n<li>Saddle Points: Transition states (one negative Hessian eigenvalue)</li>\n</ul>\n\n<p>Dynamics Algorithms:</p>\n\n<ul>\n<li>Use gradient information to guide molecular motion</li>\n<li>Employ Hessian information for improved convergence</li>\n<li>Handle symmetry constraints and subspace projections</li>\n<li>Monitor convergence and detect numerical instabilities</li>\n</ul>\n\n<h2 id=\"usage-examples\">Usage Examples</h2>\n\n<h6 id=\"basic-usage-with-hisd-for-saddle-point-search\">Basic usage with HiSD for saddle point search:</h6>\n\n<blockquote>\n  <div class=\"pdoc-code codehilite\">\n<pre><span></span><code><span class=\"gp\">&gt;&gt;&gt; </span><span class=\"kn\">from</span><span class=\"w\"> </span><span class=\"nn\">dftscape.core</span><span class=\"w\"> </span><span class=\"kn\">import</span> <span class=\"n\">HiSD</span><span class=\"p\">,</span> <span class=\"n\">Backend</span><span class=\"p\">,</span> <span class=\"n\">SubspaceHandler</span><span class=\"p\">,</span> <span class=\"n\">SymmetryHandler</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"kn\">from</span><span class=\"w\"> </span><span class=\"nn\">dftscape.backends</span><span class=\"w\"> </span><span class=\"kn\">import</span> <span class=\"n\">BackendRegistry</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Initialize components</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">backend</span> <span class=\"o\">=</span> <span class=\"n\">BackendRegistry</span><span class=\"o\">.</span><span class=\"n\">create</span><span class=\"p\">(</span><span class=\"s1\">&#39;psi4&#39;</span><span class=\"p\">,</span> <span class=\"n\">method</span><span class=\"o\">=</span><span class=\"s1\">&#39;hf/sto-3g&#39;</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">subspace_handler</span> <span class=\"o\">=</span> <span class=\"n\">SubspaceHandler</span><span class=\"p\">(</span><span class=\"n\">backend</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">symmetry_handler</span> <span class=\"o\">=</span> <span class=\"n\">SymmetryHandler</span><span class=\"p\">()</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Create HiSD dynamics</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">hisd</span> <span class=\"o\">=</span> <span class=\"n\">HiSD</span><span class=\"p\">(</span><span class=\"n\">backend</span><span class=\"p\">,</span> <span class=\"n\">subspace_handler</span><span class=\"p\">,</span> <span class=\"n\">symmetry_handler</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Run simulation</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">result</span> <span class=\"o\">=</span> <span class=\"n\">hisd</span><span class=\"o\">.</span><span class=\"n\">run</span><span class=\"p\">(</span><span class=\"n\">run_condition</span><span class=\"p\">)</span>\n</code></pre>\n  </div>\n</blockquote>\n\n<h6 id=\"advanced-configuration\">Advanced configuration:</h6>\n\n<blockquote>\n  <div class=\"pdoc-code codehilite\">\n<pre><span></span><code><span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">hisd</span> <span class=\"o\">=</span> <span class=\"n\">HiSD</span><span class=\"p\">(</span>\n<span class=\"gp\">... </span>    <span class=\"n\">backend</span><span class=\"o\">=</span><span class=\"n\">backend</span><span class=\"p\">,</span>\n<span class=\"gp\">... </span>    <span class=\"n\">subspace_handler</span><span class=\"o\">=</span><span class=\"n\">subspace_handler</span><span class=\"p\">,</span>\n<span class=\"gp\">... </span>    <span class=\"n\">symmetry_handler</span><span class=\"o\">=</span><span class=\"n\">symmetry_handler</span><span class=\"p\">,</span>\n<span class=\"gp\">... </span>    <span class=\"n\">dt</span><span class=\"o\">=</span><span class=\"mf\">0.3</span><span class=\"p\">,</span>                    <span class=\"c1\"># Smaller time step</span>\n<span class=\"gp\">... </span>    <span class=\"n\">maxiter</span><span class=\"o\">=</span><span class=\"mi\">5000</span><span class=\"p\">,</span>              <span class=\"c1\"># More iterations</span>\n<span class=\"gp\">... </span>    <span class=\"n\">grad_norm_tol</span><span class=\"o\">=</span><span class=\"mf\">1e-7</span><span class=\"p\">,</span>        <span class=\"c1\"># Tighter convergence</span>\n<span class=\"gp\">... </span>    <span class=\"n\">subspace_update_interval</span><span class=\"o\">=</span><span class=\"mi\">5</span> <span class=\"c1\"># Update subspace every 5 steps</span>\n<span class=\"gp\">... </span><span class=\"p\">)</span>\n</code></pre>\n  </div>\n</blockquote>\n\n<h2 id=\"implementation-notes\">Implementation Notes</h2>\n\n<ul>\n<li>All dynamics classes inherit from the abstract Dynamics base class</li>\n<li>HiSD uses subspace projections to separate stable/unstable modes</li>\n<li>Energy explosion detection prevents numerical instabilities</li>\n<li>Configurable logging and metrics for monitoring progress</li>\n<li>Support for symmetry constraints in molecular systems</li>\n</ul>\n"}, {"fullname": "dftscape.core.Backend", "modulename": "dftscape.core", "qualname": "Backend", "kind": "class", "doc": "<p>Protocol for computational backends in DFTScape.</p>\n\n<p>This protocol defines the interface that all quantum chemistry computational\nbackends must implement to be used within the DFTScape framework. It provides\na unified API for energy calculations, gradient computations, Hessian matrix\nevaluation, and molecular geometry handling.</p>\n\n<p>The Backend protocol abstracts the specific quantum chemistry package or method\nbeing used, allowing DFTScape to work with different computational engines\n(Psi4, Gaussian, ORCA, etc.) through a consistent interface.</p>\n\n<h6 id=\"key-methods\">Key Methods:</h6>\n\n<blockquote>\n  <p>compute_energy: Calculate potential energy at a molecular configuration\n  compute_gradient: Calculate first derivatives (forces) at a configuration\n  compute_hessian: Calculate second derivatives (force constants) at a configuration\n  get_xyz: Convert molecular coordinates to XYZ format string</p>\n</blockquote>\n\n<p>Implementation Requirements:</p>\n\n<ul>\n<li>All methods must accept numpy arrays for molecular coordinates</li>\n<li>Coordinate arrays should be 1D with shape (3*N,) for N atoms</li>\n<li>Energy values should be in atomic units (Hartree)</li>\n<li>Gradients should be 1D arrays with shape (3*N,) in atomic units</li>\n<li>Hessians should be 2D arrays with shape (3<em>N, 3</em>N) in atomic units</li>\n<li>XYZ strings should follow standard XYZ format with atomic symbols</li>\n</ul>\n\n<h6 id=\"example-implementation\">Example Implementation:</h6>\n\n<blockquote>\n  <div class=\"pdoc-code codehilite\">\n<pre><span></span><code><span class=\"gp\">&gt;&gt;&gt; </span><span class=\"k\">class</span><span class=\"w\"> </span><span class=\"nc\">MyBackend</span><span class=\"p\">:</span>\n<span class=\"gp\">... </span>    <span class=\"k\">def</span><span class=\"w\"> </span><span class=\"nf\">compute_energy</span><span class=\"p\">(</span><span class=\"bp\">self</span><span class=\"p\">,</span> <span class=\"n\">state</span><span class=\"p\">:</span> <span class=\"n\">np</span><span class=\"o\">.</span><span class=\"n\">ndarray</span><span class=\"p\">)</span> <span class=\"o\">-&gt;</span> <span class=\"nb\">float</span><span class=\"p\">:</span>\n<span class=\"gp\">... </span>        <span class=\"c1\"># Implementation here</span>\n<span class=\"gp\">... </span>        <span class=\"k\">return</span> <span class=\"n\">energy_value</span>\n<span class=\"gp\">...</span>\n<span class=\"gp\">... </span>    <span class=\"k\">def</span><span class=\"w\"> </span><span class=\"nf\">compute_gradient</span><span class=\"p\">(</span><span class=\"bp\">self</span><span class=\"p\">,</span> <span class=\"n\">state</span><span class=\"p\">:</span> <span class=\"n\">np</span><span class=\"o\">.</span><span class=\"n\">ndarray</span><span class=\"p\">)</span> <span class=\"o\">-&gt;</span> <span class=\"n\">np</span><span class=\"o\">.</span><span class=\"n\">ndarray</span><span class=\"p\">:</span>\n<span class=\"gp\">... </span>        <span class=\"c1\"># Implementation here</span>\n<span class=\"gp\">... </span>        <span class=\"k\">return</span> <span class=\"n\">gradient_array</span>\n<span class=\"gp\">...</span>\n<span class=\"gp\">... </span>    <span class=\"c1\"># ... other methods</span>\n</code></pre>\n  </div>\n</blockquote>\n\n<h6 id=\"notes\">Notes:</h6>\n\n<blockquote>\n  <ul>\n  <li>Implementations should handle coordinate validation and unit conversion</li>\n  <li>Error handling for invalid geometries is implementation-specific</li>\n  <li>Performance optimizations (caching, parallelization) are encouraged</li>\n  <li>Thread safety depends on the specific backend implementation</li>\n  </ul>\n</blockquote>\n", "bases": "typing.Protocol"}, {"fullname": "dftscape.core.Backend.__init__", "modulename": "dftscape.core", "qualname": "Backend.__init__", "kind": "function", "doc": "<p></p>\n", "signature": "<span class=\"signature pdoc-code condensed\">(<span class=\"param\"><span class=\"o\">*</span><span class=\"n\">args</span>, </span><span class=\"param\"><span class=\"o\">**</span><span class=\"n\">kwargs</span></span>)</span>"}, {"fullname": "dftscape.core.Backend.compute_energy", "modulename": "dftscape.core", "qualname": "Backend.compute_energy", "kind": "function", "doc": "<p>Compute the potential energy for a given molecular configuration.</p>\n\n<h6 id=\"arguments\">Arguments:</h6>\n\n<ul>\n<li><strong>state:</strong>  1D numpy array of shape (3*N,) containing atomic coordinates\nin Angstroms, where N is the number of atoms. Coordinates should\nbe ordered as [x1, y1, z1, x2, y2, z2, ..., xN, yN, zN].</li>\n</ul>\n\n<h6 id=\"returns\">Returns:</h6>\n\n<blockquote>\n  <p>float: Potential energy value in atomic units (Hartree).</p>\n</blockquote>\n\n<h6 id=\"raises\">Raises:</h6>\n\n<ul>\n<li>Implementation-specific exceptions for invalid geometries or</li>\n<li>computational failures.</li>\n</ul>\n\n<h6 id=\"example\">Example:</h6>\n\n<blockquote>\n  <div class=\"pdoc-code codehilite\">\n<pre><span></span><code><span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">coords</span> <span class=\"o\">=</span> <span class=\"n\">np</span><span class=\"o\">.</span><span class=\"n\">array</span><span class=\"p\">([</span><span class=\"mf\">0.0</span><span class=\"p\">,</span> <span class=\"mf\">0.0</span><span class=\"p\">,</span> <span class=\"mf\">0.0</span><span class=\"p\">,</span> <span class=\"mf\">1.0</span><span class=\"p\">,</span> <span class=\"mf\">0.0</span><span class=\"p\">,</span> <span class=\"mf\">0.0</span><span class=\"p\">])</span>  <span class=\"c1\"># H2 molecule</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">energy</span> <span class=\"o\">=</span> <span class=\"n\">backend</span><span class=\"o\">.</span><span class=\"n\">compute_energy</span><span class=\"p\">(</span><span class=\"n\">coords</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"sa\">f</span><span class=\"s2\">&quot;Energy: </span><span class=\"si\">{</span><span class=\"n\">energy</span><span class=\"si\">:</span><span class=\"s2\">.6f</span><span class=\"si\">}</span><span class=\"s2\"> Hartree&quot;</span><span class=\"p\">)</span>\n</code></pre>\n  </div>\n</blockquote>\n", "signature": "<span class=\"signature pdoc-code condensed\">(<span class=\"param\"><span class=\"bp\">self</span>, </span><span class=\"param\"><span class=\"n\">state</span><span class=\"p\">:</span> <span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span></span><span class=\"return-annotation\">) -> <span class=\"nb\">float</span>:</span></span>", "funcdef": "def"}, {"fullname": "dftscape.core.Backend.compute_gradient", "modulename": "dftscape.core", "qualname": "Backend.compute_gradient", "kind": "function", "doc": "<p>Compute the gradient (first derivatives) of the potential energy.</p>\n\n<p>The gradient represents the forces acting on each atom and points in\nthe direction of steepest descent on the potential energy surface.</p>\n\n<h6 id=\"arguments\">Arguments:</h6>\n\n<ul>\n<li><strong>state:</strong>  1D numpy array of shape (3*N,) containing atomic coordinates\nin Angstroms, ordered as [x1, y1, z1, x2, y2, z2, ..., xN, yN, zN].</li>\n</ul>\n\n<h6 id=\"returns\">Returns:</h6>\n\n<blockquote>\n  <p>np.ndarray: 1D array of shape (3*N,) containing the gradient components\n             in atomic units (Hartree/Angstrom). The ordering matches\n             the input coordinates.</p>\n</blockquote>\n\n<h6 id=\"raises\">Raises:</h6>\n\n<ul>\n<li>Implementation-specific exceptions for invalid geometries or</li>\n<li>computational failures.</li>\n</ul>\n\n<h6 id=\"example\">Example:</h6>\n\n<blockquote>\n  <div class=\"pdoc-code codehilite\">\n<pre><span></span><code><span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">coords</span> <span class=\"o\">=</span> <span class=\"n\">np</span><span class=\"o\">.</span><span class=\"n\">array</span><span class=\"p\">([</span><span class=\"mf\">0.0</span><span class=\"p\">,</span> <span class=\"mf\">0.0</span><span class=\"p\">,</span> <span class=\"mf\">0.0</span><span class=\"p\">,</span> <span class=\"mf\">1.0</span><span class=\"p\">,</span> <span class=\"mf\">0.0</span><span class=\"p\">,</span> <span class=\"mf\">0.0</span><span class=\"p\">])</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">grad</span> <span class=\"o\">=</span> <span class=\"n\">backend</span><span class=\"o\">.</span><span class=\"n\">compute_gradient</span><span class=\"p\">(</span><span class=\"n\">coords</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"sa\">f</span><span class=\"s2\">&quot;Gradient norm: </span><span class=\"si\">{</span><span class=\"n\">np</span><span class=\"o\">.</span><span class=\"n\">linalg</span><span class=\"o\">.</span><span class=\"n\">norm</span><span class=\"p\">(</span><span class=\"n\">grad</span><span class=\"p\">)</span><span class=\"si\">:</span><span class=\"s2\">.6f</span><span class=\"si\">}</span><span class=\"s2\">&quot;</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"sa\">f</span><span class=\"s2\">&quot;Force on first atom: </span><span class=\"si\">{</span><span class=\"n\">grad</span><span class=\"p\">[:</span><span class=\"mi\">3</span><span class=\"p\">]</span><span class=\"si\">}</span><span class=\"s2\">&quot;</span><span class=\"p\">)</span>\n</code></pre>\n  </div>\n</blockquote>\n", "signature": "<span class=\"signature pdoc-code condensed\">(<span class=\"param\"><span class=\"bp\">self</span>, </span><span class=\"param\"><span class=\"n\">state</span><span class=\"p\">:</span> <span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span></span><span class=\"return-annotation\">) -> <span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span>:</span></span>", "funcdef": "def"}, {"fullname": "dftscape.core.Backend.compute_hessian", "modulename": "dftscape.core", "qualname": "Backend.compute_hessian", "kind": "function", "doc": "<p>Compute the Hessian matrix (second derivatives) of the potential energy.</p>\n\n<p>The Hessian matrix contains information about the curvature of the potential\nenergy surface and is essential for determining the nature of critical points\n(minima, transition states) and for optimization algorithms.</p>\n\n<h6 id=\"arguments\">Arguments:</h6>\n\n<ul>\n<li><strong>state:</strong>  1D numpy array of shape (3*N,) containing atomic coordinates\nin Angstroms, ordered as [x1, y1, z1, x2, y2, z2, ..., xN, yN, zN].</li>\n</ul>\n\n<h6 id=\"returns\">Returns:</h6>\n\n<blockquote>\n  <p>np.ndarray: 2D array of shape (3<em>N, 3</em>N) containing the Hessian matrix\n             in atomic units (Hartree/Angstrom\u00b2). The matrix is symmetric\n             and ordered to match the input coordinate ordering.</p>\n</blockquote>\n\n<h6 id=\"raises\">Raises:</h6>\n\n<ul>\n<li>Implementation-specific exceptions for invalid geometries or</li>\n<li>computational failures.</li>\n</ul>\n\n<h6 id=\"example\">Example:</h6>\n\n<blockquote>\n  <div class=\"pdoc-code codehilite\">\n<pre><span></span><code><span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">coords</span> <span class=\"o\">=</span> <span class=\"n\">np</span><span class=\"o\">.</span><span class=\"n\">array</span><span class=\"p\">([</span><span class=\"mf\">0.0</span><span class=\"p\">,</span> <span class=\"mf\">0.0</span><span class=\"p\">,</span> <span class=\"mf\">0.0</span><span class=\"p\">,</span> <span class=\"mf\">1.0</span><span class=\"p\">,</span> <span class=\"mf\">0.0</span><span class=\"p\">,</span> <span class=\"mf\">0.0</span><span class=\"p\">])</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">hess</span> <span class=\"o\">=</span> <span class=\"n\">backend</span><span class=\"o\">.</span><span class=\"n\">compute_hessian</span><span class=\"p\">(</span><span class=\"n\">coords</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">eigenvals</span> <span class=\"o\">=</span> <span class=\"n\">np</span><span class=\"o\">.</span><span class=\"n\">linalg</span><span class=\"o\">.</span><span class=\"n\">eigvals</span><span class=\"p\">(</span><span class=\"n\">hess</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"sa\">f</span><span class=\"s2\">&quot;Hessian eigenvalues: </span><span class=\"si\">{</span><span class=\"n\">eigenvals</span><span class=\"si\">}</span><span class=\"s2\">&quot;</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"sa\">f</span><span class=\"s2\">&quot;Number of negative eigenvalues: </span><span class=\"si\">{</span><span class=\"n\">np</span><span class=\"o\">.</span><span class=\"n\">sum</span><span class=\"p\">(</span><span class=\"n\">eigenvals</span><span class=\"w\"> </span><span class=\"o\">&lt;</span><span class=\"w\"> </span><span class=\"mi\">0</span><span class=\"p\">)</span><span class=\"si\">}</span><span class=\"s2\">&quot;</span><span class=\"p\">)</span>\n</code></pre>\n  </div>\n</blockquote>\n", "signature": "<span class=\"signature pdoc-code condensed\">(<span class=\"param\"><span class=\"bp\">self</span>, </span><span class=\"param\"><span class=\"n\">state</span><span class=\"p\">:</span> <span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span></span><span class=\"return-annotation\">) -> <span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span>:</span></span>", "funcdef": "def"}, {"fullname": "dftscape.core.Backend.get_xyz", "modulename": "dftscape.core", "qualname": "Backend.get_xyz", "kind": "function", "doc": "<p>Convert molecular coordinates to XYZ format string.</p>\n\n<p>XYZ format is a standard text representation of molecular structures\nused throughout computational chemistry. It contains the number of atoms,\nan optional comment line, and atomic coordinates with element symbols.</p>\n\n<h6 id=\"arguments\">Arguments:</h6>\n\n<ul>\n<li><strong>state:</strong>  1D numpy array of shape (3*N,) containing atomic coordinates\nin Angstroms, ordered as [x1, y1, z1, x2, y2, z2, ..., xN, yN, zN].</li>\n</ul>\n\n<h6 id=\"returns\">Returns:</h6>\n\n<blockquote>\n  <p>str: XYZ format string with the following structure:\n       Line 1: Number of atoms (integer)\n       Line 2: Optional comment (often empty or energy value)\n       Lines 3+: Atomic symbol and coordinates (e.g., \"H 0.000000 0.000000 0.000000\")</p>\n</blockquote>\n\n<h6 id=\"raises\">Raises:</h6>\n\n<ul>\n<li>Implementation-specific exceptions for invalid geometries.</li>\n</ul>\n\n<h6 id=\"example\">Example:</h6>\n\n<blockquote>\n  <div class=\"pdoc-code codehilite\">\n<pre><span></span><code><span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">coords</span> <span class=\"o\">=</span> <span class=\"n\">np</span><span class=\"o\">.</span><span class=\"n\">array</span><span class=\"p\">([</span><span class=\"mf\">0.0</span><span class=\"p\">,</span> <span class=\"mf\">0.0</span><span class=\"p\">,</span> <span class=\"mf\">0.0</span><span class=\"p\">,</span> <span class=\"mf\">1.0</span><span class=\"p\">,</span> <span class=\"mf\">0.0</span><span class=\"p\">,</span> <span class=\"mf\">0.0</span><span class=\"p\">])</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">xyz_str</span> <span class=\"o\">=</span> <span class=\"n\">backend</span><span class=\"o\">.</span><span class=\"n\">get_xyz</span><span class=\"p\">(</span><span class=\"n\">coords</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"n\">xyz_str</span><span class=\"p\">)</span>\n<span class=\"go\">2</span>\n<span class=\"go\">H2 molecule</span>\n<span class=\"go\">H  0.000000  0.000000  0.000000</span>\n<span class=\"go\">H  1.000000  0.000000  0.000000</span>\n</code></pre>\n  </div>\n</blockquote>\n\n<h6 id=\"notes\">Notes:</h6>\n\n<blockquote>\n  <ul>\n  <li>Atomic symbols are typically inferred from the molecular system</li>\n  <li>Coordinate precision should be sufficient for the intended application</li>\n  <li>The comment line can include energy values or other metadata</li>\n  </ul>\n</blockquote>\n", "signature": "<span class=\"signature pdoc-code condensed\">(<span class=\"param\"><span class=\"bp\">self</span>, </span><span class=\"param\"><span class=\"n\">state</span><span class=\"p\">:</span> <span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span></span><span class=\"return-annotation\">) -> <span class=\"nb\">str</span>:</span></span>", "funcdef": "def"}, {"fullname": "dftscape.core.SubspaceHandler", "modulename": "dftscape.core", "qualname": "SubspaceHandler", "kind": "class", "doc": "<p>Handler for subspace-based optimization with symmetry constraints.</p>\n\n<p>This class manages the coordination between quantum chemistry backends, symmetry\nconstraint handlers, and eigensolvers to perform efficient subspace optimization.\nIt serves as the central component for subspace-based saddle point finding and\nminimum search algorithms in DFTScape.</p>\n\n<p>The subspace handler is responsible for:</p>\n\n<ul>\n<li><strong>Subspace Renewal</strong>: Updating subspaces using eigensolvers with constraints</li>\n<li><strong>Symmetry Enforcement</strong>: Integrating symmetry constraints into optimization</li>\n<li><strong>Edge Case Handling</strong>: Managing special cases like gradient flow (k=0)</li>\n<li><strong>Error Recovery</strong>: Robust handling of numerical instabilities</li>\n<li><strong>Performance Optimization</strong>: Efficient numpy array operations</li>\n</ul>\n\n<h6 id=\"attributes\">Attributes:</h6>\n\n<ul>\n<li><strong>backend (Backend):</strong>  Quantum chemistry backend for energy and gradient computations.\nProvides the computational engine for DFTScape calculations.</li>\n<li><strong>symmetry_handler (SymmetryHandler):</strong>  Handler for symmetry constraints.\nDefines which directions should be orthogonal to search directions.</li>\n<li><strong>eigensolver (Eigensolver):</strong>  Solver for generalized eigenvalue problems.\nPerforms the core subspace optimization computations.</li>\n<li><strong>logger (logging.Logger):</strong>  Logger instance for debugging and monitoring.\nProvides detailed information about subspace operations.</li>\n</ul>\n\n<h6 id=\"methods\">Methods:</h6>\n\n<blockquote>\n  <p>renew_subspace: Update subspace using eigensolver with constraints\n  __init__: Initialize handler with required components</p>\n</blockquote>\n\n<h6 id=\"design-patterns\">Design Patterns:</h6>\n\n<blockquote>\n  <ul>\n  <li><strong>Composition Pattern</strong>: Combines backend, symmetry, and eigensolver components</li>\n  <li><strong>Strategy Pattern</strong>: Pluggable eigensolver and symmetry strategies</li>\n  <li><strong>Template Method</strong>: Standardized subspace renewal process</li>\n  </ul>\n</blockquote>\n\n<h6 id=\"thread-safety\">Thread Safety:</h6>\n\n<blockquote>\n  <ul>\n  <li>Read operations are thread-safe</li>\n  <li>Concurrent modifications may cause race conditions</li>\n  <li>Logging is thread-safe</li>\n  </ul>\n</blockquote>\n\n<h6 id=\"performance-characteristics\">Performance Characteristics:</h6>\n\n<blockquote>\n  <ul>\n  <li>Memory: O(n\u00d7k) where n is state dimension, k is subspace dimension</li>\n  <li>Time: Depends on eigensolver complexity (typically O(n\u00d7k\u00b2))</li>\n  <li>Scalability: Linear with system size for most operations</li>\n  </ul>\n</blockquote>\n\n<h6 id=\"usage-examples\">Usage Examples:</h6>\n\n<blockquote>\n  <div class=\"pdoc-code codehilite\">\n<pre><span></span><code><span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Basic usage with molecular symmetry</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">handler</span> <span class=\"o\">=</span> <span class=\"n\">SubspaceHandler</span><span class=\"p\">(</span>\n<span class=\"gp\">... </span>    <span class=\"n\">backend</span><span class=\"o\">=</span><span class=\"n\">Backend</span><span class=\"o\">.</span><span class=\"n\">create</span><span class=\"p\">(</span><span class=\"s2\">&quot;psi4&quot;</span><span class=\"p\">),</span>\n<span class=\"gp\">... </span>    <span class=\"n\">symmetry_handler</span><span class=\"o\">=</span><span class=\"n\">SymmetryHandler</span><span class=\"o\">.</span><span class=\"n\">create</span><span class=\"p\">(</span><span class=\"s2\">&quot;molecular&quot;</span><span class=\"p\">),</span>\n<span class=\"gp\">... </span>    <span class=\"n\">eigensolver</span><span class=\"o\">=</span><span class=\"n\">Eigensolver</span><span class=\"o\">.</span><span class=\"n\">create</span><span class=\"p\">(</span><span class=\"s2\">&quot;scipy&quot;</span><span class=\"p\">)</span>\n<span class=\"gp\">... </span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Subspace renewal in optimization loop</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">current_subspace</span> <span class=\"o\">=</span> <span class=\"n\">np</span><span class=\"o\">.</span><span class=\"n\">random</span><span class=\"o\">.</span><span class=\"n\">randn</span><span class=\"p\">(</span><span class=\"n\">state_dim</span><span class=\"p\">,</span> <span class=\"n\">subspace_dim</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">eigenvalues</span><span class=\"p\">,</span> <span class=\"n\">eigenvectors</span> <span class=\"o\">=</span> <span class=\"n\">handler</span><span class=\"o\">.</span><span class=\"n\">renew_subspace</span><span class=\"p\">(</span><span class=\"n\">current_subspace</span><span class=\"p\">,</span> <span class=\"n\">state</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Gradient flow (k=0) case</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">empty_subspace</span> <span class=\"o\">=</span> <span class=\"n\">np</span><span class=\"o\">.</span><span class=\"n\">array</span><span class=\"p\">([])</span><span class=\"o\">.</span><span class=\"n\">reshape</span><span class=\"p\">(</span><span class=\"n\">state_dim</span><span class=\"p\">,</span> <span class=\"mi\">0</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">eigenvals</span><span class=\"p\">,</span> <span class=\"n\">eigenvecs</span> <span class=\"o\">=</span> <span class=\"n\">handler</span><span class=\"o\">.</span><span class=\"n\">renew_subspace</span><span class=\"p\">(</span><span class=\"n\">empty_subspace</span><span class=\"p\">,</span> <span class=\"n\">state</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Returns empty arrays for gradient flow</span>\n</code></pre>\n  </div>\n</blockquote>\n\n<h6 id=\"error-handling\">Error Handling:</h6>\n\n<blockquote>\n  <ul>\n  <li>Handles None returns from eigensolvers gracefully</li>\n  <li>Validates subspace dimensions and state consistency</li>\n  <li>Logs detailed error information for debugging</li>\n  <li>Recovers from numerical instabilities</li>\n  </ul>\n</blockquote>\n\n<h6 id=\"integration-notes\">Integration Notes:</h6>\n\n<blockquote>\n  <ul>\n  <li>Used by SaddlePointOptimizer for subspace-based search</li>\n  <li>Consumes SymmetryHandler for constraint definitions</li>\n  <li>Interfaces with Eigensolver for numerical computations</li>\n  <li>Coordinates with Backend for physical property calculations</li>\n  </ul>\n</blockquote>\n\n<h6 id=\"implementation-details\">Implementation Details:</h6>\n\n<blockquote>\n  <ul>\n  <li>Uses scipy's Y parameter for constraint enforcement</li>\n  <li>Handles k=0 case explicitly for gradient flow optimization</li>\n  <li>Performs QR decomposition for constraint orthogonalization</li>\n  <li>Supports both constrained and unconstrained subspaces</li>\n  </ul>\n</blockquote>\n"}, {"fullname": "dftscape.core.SubspaceHandler.__init__", "modulename": "dftscape.core", "qualname": "SubspaceHandler.__init__", "kind": "function", "doc": "<p>Initialize the subspace handler with required components.</p>\n\n<p>This constructor sets up the subspace handler by storing references to the\nquantum chemistry backend, symmetry constraint handler, and eigensolver.\nAll components must be properly initialized before use.</p>\n\n<h6 id=\"arguments\">Arguments:</h6>\n\n<ul>\n<li><strong>backend (Backend):</strong>  Quantum chemistry backend for energy and gradient\ncomputations. Must implement the Backend interface with energy()\nand gradient() methods.</li>\n<li><strong>symmetry_handler (SymmetryHandler):</strong>  Handler for symmetry constraints.\nDefines which directions should be orthogonal to optimization search\ndirections. Can be None for unconstrained optimization.</li>\n<li><strong>eigensolver (Eigensolver):</strong>  Solver for generalized eigenvalue problems.\nMust implement the Eigensolver interface with solve() method.</li>\n</ul>\n\n<h6 id=\"raises\">Raises:</h6>\n\n<ul>\n<li><strong>TypeError:</strong>  If any component doesn't implement the required interface.</li>\n<li><strong>ValueError:</strong>  If components are not properly initialized.</li>\n</ul>\n\n<h6 id=\"examples\">Examples:</h6>\n\n<blockquote>\n  <div class=\"pdoc-code codehilite\">\n<pre><span></span><code><span class=\"gp\">&gt;&gt;&gt; </span><span class=\"kn\">from</span><span class=\"w\"> </span><span class=\"nn\">dftscape.core</span><span class=\"w\"> </span><span class=\"kn\">import</span> <span class=\"n\">Backend</span><span class=\"p\">,</span> <span class=\"n\">SymmetryHandler</span><span class=\"p\">,</span> <span class=\"n\">Eigensolver</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Initialize with molecular symmetry constraints</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">backend</span> <span class=\"o\">=</span> <span class=\"n\">Backend</span><span class=\"o\">.</span><span class=\"n\">create</span><span class=\"p\">(</span><span class=\"s2\">&quot;psi4&quot;</span><span class=\"p\">,</span> <span class=\"n\">method</span><span class=\"o\">=</span><span class=\"s2\">&quot;b3lyp&quot;</span><span class=\"p\">,</span> <span class=\"n\">basis</span><span class=\"o\">=</span><span class=\"s2\">&quot;6-31g&quot;</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">symmetry</span> <span class=\"o\">=</span> <span class=\"n\">SymmetryHandler</span><span class=\"o\">.</span><span class=\"n\">create</span><span class=\"p\">(</span><span class=\"s2\">&quot;molecular&quot;</span><span class=\"p\">,</span> <span class=\"n\">overlap_threshold</span><span class=\"o\">=</span><span class=\"mf\">0.1</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">eigensolver</span> <span class=\"o\">=</span> <span class=\"n\">Eigensolver</span><span class=\"o\">.</span><span class=\"n\">create</span><span class=\"p\">(</span><span class=\"s2\">&quot;scipy&quot;</span><span class=\"p\">,</span> <span class=\"n\">tolerance</span><span class=\"o\">=</span><span class=\"mf\">1e-8</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">handler</span> <span class=\"o\">=</span> <span class=\"n\">SubspaceHandler</span><span class=\"p\">(</span><span class=\"n\">backend</span><span class=\"p\">,</span> <span class=\"n\">symmetry</span><span class=\"p\">,</span> <span class=\"n\">eigensolver</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Initialize without symmetry constraints</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">unconstrained</span> <span class=\"o\">=</span> <span class=\"n\">SubspaceHandler</span><span class=\"p\">(</span>\n<span class=\"gp\">... </span>    <span class=\"n\">backend</span><span class=\"o\">=</span><span class=\"n\">backend</span><span class=\"p\">,</span>\n<span class=\"gp\">... </span>    <span class=\"n\">symmetry_handler</span><span class=\"o\">=</span><span class=\"n\">SymmetryHandler</span><span class=\"o\">.</span><span class=\"n\">create</span><span class=\"p\">(</span><span class=\"s2\">&quot;none&quot;</span><span class=\"p\">),</span>\n<span class=\"gp\">... </span>    <span class=\"n\">eigensolver</span><span class=\"o\">=</span><span class=\"n\">eigensolver</span>\n<span class=\"gp\">... </span><span class=\"p\">)</span>\n</code></pre>\n  </div>\n</blockquote>\n\n<h6 id=\"notes\">Notes:</h6>\n\n<blockquote>\n  <ul>\n  <li>All components are stored as instance attributes</li>\n  <li>Logger is automatically configured with module name</li>\n  <li>Components should be fully initialized before handler creation</li>\n  <li>Memory usage depends on component implementations</li>\n  </ul>\n</blockquote>\n", "signature": "<span class=\"signature pdoc-code multiline\">(<span class=\"param\">\t<span class=\"n\">backend</span><span class=\"p\">:</span> <span class=\"n\">dftscape</span><span class=\"o\">.</span><span class=\"n\">core</span><span class=\"o\">.</span><span class=\"n\">interfaces</span><span class=\"o\">.</span><span class=\"n\">Backend</span>,</span><span class=\"param\">\t<span class=\"n\">symmetry_handler</span><span class=\"p\">:</span> <span class=\"n\">dftscape</span><span class=\"o\">.</span><span class=\"n\">core</span><span class=\"o\">.</span><span class=\"n\">symmetry_handlers</span><span class=\"o\">.</span><span class=\"n\">SymmetryHandler</span>,</span><span class=\"param\">\t<span class=\"n\">eigensolver</span><span class=\"p\">:</span> <span class=\"n\">dftscape</span><span class=\"o\">.</span><span class=\"n\">core</span><span class=\"o\">.</span><span class=\"n\">eigensolvers</span><span class=\"o\">.</span><span class=\"n\">Eigensolver</span></span>)</span>"}, {"fullname": "dftscape.core.SubspaceHandler.backend", "modulename": "dftscape.core", "qualname": "SubspaceHandler.backend", "kind": "variable", "doc": "<p></p>\n"}, {"fullname": "dftscape.core.SubspaceHandler.symmetry_handler", "modulename": "dftscape.core", "qualname": "SubspaceHandler.symmetry_handler", "kind": "variable", "doc": "<p></p>\n"}, {"fullname": "dftscape.core.SubspaceHandler.eigensolver", "modulename": "dftscape.core", "qualname": "SubspaceHandler.eigensolver", "kind": "variable", "doc": "<p></p>\n"}, {"fullname": "dftscape.core.SubspaceHandler.logger", "modulename": "dftscape.core", "qualname": "SubspaceHandler.logger", "kind": "variable", "doc": "<p></p>\n"}, {"fullname": "dftscape.core.SubspaceHandler.renew_subspace", "modulename": "dftscape.core", "qualname": "SubspaceHandler.renew_subspace", "kind": "function", "doc": "<p>Renew subspace using the configured eigensolver with built-in constraint handling.</p>\n\n<p>This method performs subspace renewal by solving a generalized eigenvalue problem\nwith symmetry constraints. It handles edge cases like gradient flow (k=0) and\nintegrates constraint subspaces from the symmetry handler.</p>\n\n<p>The renewal process involves:</p>\n\n<ol>\n<li><strong>Dimension Extraction</strong>: Get subspace dimension k from input</li>\n<li><strong>Eigensolver Configuration</strong>: Update eigensolver with current k</li>\n<li><strong>Edge Case Handling</strong>: Special treatment for k=0 (gradient flow)</li>\n<li><strong>Constraint Integration</strong>: Get constraint subspace from symmetry handler</li>\n<li><strong>Eigenvalue Solution</strong>: Solve constrained eigenvalue problem</li>\n<li><strong>Result Validation</strong>: Check and return eigenvalues/eigenvectors</li>\n</ol>\n\n<h6 id=\"arguments\">Arguments:</h6>\n\n<ul>\n<li><strong>subspace (np.ndarray):</strong>  Current subspace matrix of shape (n, k) where\nn is the state dimension and k is the subspace dimension. Can be\nempty for k=0 case.</li>\n<li><strong>state (np.ndarray):</strong>  Current optimization state vector of shape (n,).\nRepresents the current molecular geometry or electronic state.</li>\n</ul>\n\n<h6 id=\"returns\">Returns:</h6>\n\n<blockquote>\n  <p>Tuple[np.ndarray, np.ndarray]: A tuple containing:\n      - eigenvalues (np.ndarray): Eigenvalues of shape (k,) or empty array for k=0\n      - eigenvectors (np.ndarray): Eigenvectors of shape (n, k) or empty array for k=0</p>\n</blockquote>\n\n<h6 id=\"raises\">Raises:</h6>\n\n<ul>\n<li><strong>ValueError:</strong>  If subspace and state dimensions are incompatible.</li>\n<li><strong>RuntimeError:</strong>  If eigensolver fails to converge or returns invalid results.</li>\n<li><strong>AttributeError:</strong>  If symmetry handler doesn't implement required methods.</li>\n</ul>\n\n<h6 id=\"examples\">Examples:</h6>\n\n<blockquote>\n  <div class=\"pdoc-code codehilite\">\n<pre><span></span><code><span class=\"gp\">&gt;&gt;&gt; </span><span class=\"kn\">import</span><span class=\"w\"> </span><span class=\"nn\">numpy</span><span class=\"w\"> </span><span class=\"k\">as</span><span class=\"w\"> </span><span class=\"nn\">np</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"kn\">from</span><span class=\"w\"> </span><span class=\"nn\">dftscape.core.subspace_handlers</span><span class=\"w\"> </span><span class=\"kn\">import</span> <span class=\"n\">SubspaceHandler</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Create handler (assuming components are initialized)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">handler</span> <span class=\"o\">=</span> <span class=\"n\">SubspaceHandler</span><span class=\"p\">(</span><span class=\"n\">backend</span><span class=\"p\">,</span> <span class=\"n\">symmetry_handler</span><span class=\"p\">,</span> <span class=\"n\">eigensolver</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Normal subspace renewal</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">n</span><span class=\"p\">,</span> <span class=\"n\">k</span> <span class=\"o\">=</span> <span class=\"mi\">100</span><span class=\"p\">,</span> <span class=\"mi\">5</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">subspace</span> <span class=\"o\">=</span> <span class=\"n\">np</span><span class=\"o\">.</span><span class=\"n\">random</span><span class=\"o\">.</span><span class=\"n\">randn</span><span class=\"p\">(</span><span class=\"n\">n</span><span class=\"p\">,</span> <span class=\"n\">k</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">state</span> <span class=\"o\">=</span> <span class=\"n\">np</span><span class=\"o\">.</span><span class=\"n\">random</span><span class=\"o\">.</span><span class=\"n\">randn</span><span class=\"p\">(</span><span class=\"n\">n</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">eigenvals</span><span class=\"p\">,</span> <span class=\"n\">eigenvecs</span> <span class=\"o\">=</span> <span class=\"n\">handler</span><span class=\"o\">.</span><span class=\"n\">renew_subspace</span><span class=\"p\">(</span><span class=\"n\">subspace</span><span class=\"p\">,</span> <span class=\"n\">state</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"sa\">f</span><span class=\"s2\">&quot;Eigenvalues shape: </span><span class=\"si\">{</span><span class=\"n\">eigenvals</span><span class=\"o\">.</span><span class=\"n\">shape</span><span class=\"si\">}</span><span class=\"s2\">&quot;</span><span class=\"p\">)</span>  <span class=\"c1\"># (5,)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"sa\">f</span><span class=\"s2\">&quot;Eigenvectors shape: </span><span class=\"si\">{</span><span class=\"n\">eigenvecs</span><span class=\"o\">.</span><span class=\"n\">shape</span><span class=\"si\">}</span><span class=\"s2\">&quot;</span><span class=\"p\">)</span>  <span class=\"c1\"># (100, 5)</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Gradient flow case (k=0)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">empty_subspace</span> <span class=\"o\">=</span> <span class=\"n\">np</span><span class=\"o\">.</span><span class=\"n\">array</span><span class=\"p\">([])</span><span class=\"o\">.</span><span class=\"n\">reshape</span><span class=\"p\">(</span><span class=\"n\">n</span><span class=\"p\">,</span> <span class=\"mi\">0</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">vals</span><span class=\"p\">,</span> <span class=\"n\">vecs</span> <span class=\"o\">=</span> <span class=\"n\">handler</span><span class=\"o\">.</span><span class=\"n\">renew_subspace</span><span class=\"p\">(</span><span class=\"n\">empty_subspace</span><span class=\"p\">,</span> <span class=\"n\">state</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"sa\">f</span><span class=\"s2\">&quot;Gradient flow eigenvalues: </span><span class=\"si\">{</span><span class=\"n\">vals</span><span class=\"si\">}</span><span class=\"s2\">&quot;</span><span class=\"p\">)</span>  <span class=\"c1\"># []</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"sa\">f</span><span class=\"s2\">&quot;Gradient flow eigenvectors shape: </span><span class=\"si\">{</span><span class=\"n\">vecs</span><span class=\"o\">.</span><span class=\"n\">shape</span><span class=\"si\">}</span><span class=\"s2\">&quot;</span><span class=\"p\">)</span>  <span class=\"c1\"># (100, 0)</span>\n</code></pre>\n  </div>\n</blockquote>\n\n<h6 id=\"performance\">Performance:</h6>\n\n<blockquote>\n  <ul>\n  <li>Time: O(n\u00d7k\u00b2) for typical eigensolvers, O(n\u00d7k) for iterative methods</li>\n  <li>Memory: O(n\u00d7k) for subspace storage, additional O(n\u00d7m) for constraints</li>\n  <li>Scalability: Linear with state dimension n, quadratic with subspace dimension k</li>\n  </ul>\n</blockquote>\n\n<h6 id=\"notes\">Notes:</h6>\n\n<blockquote>\n  <ul>\n  <li>Handles k=0 case explicitly for gradient flow optimization</li>\n  <li>Uses scipy's Y parameter for constraint matrix integration</li>\n  <li>Performs QR decomposition for constraint orthogonalization</li>\n  <li>Logs detailed information for debugging and monitoring</li>\n  <li>Returns empty arrays consistently for k=0 case</li>\n  </ul>\n</blockquote>\n", "signature": "<span class=\"signature pdoc-code multiline\">(<span class=\"param\">\t<span class=\"bp\">self</span>,</span><span class=\"param\">\t<span class=\"n\">subspace</span><span class=\"p\">:</span> <span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span>,</span><span class=\"param\">\t<span class=\"n\">state</span><span class=\"p\">:</span> <span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span></span><span class=\"return-annotation\">) -> <span class=\"n\">Tuple</span><span class=\"p\">[</span><span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span><span class=\"p\">,</span> <span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span><span class=\"p\">]</span>:</span></span>", "funcdef": "def"}, {"fullname": "dftscape.core.Dynamics", "modulename": "dftscape.core", "qualname": "Dynamics", "kind": "class", "doc": "<p>Abstract base class for dynamics simulations in DFTScape.</p>\n\n<p>This class provides the framework for running molecular dynamics simulations\nto find critical points (minima, transition states) on potential energy surfaces.\nIt handles common functionality like logging, convergence checking, and metric\ncomputation while delegating the specific dynamics algorithm to subclasses.</p>\n\n<h6 id=\"attributes\">Attributes:</h6>\n\n<ul>\n<li><strong>backend:</strong>  Computational backend for energy/gradient calculations</li>\n<li><strong>metrics:</strong>  List of metrics to compute and log during simulation</li>\n<li><strong>log_interval:</strong>  How often to log progress (steps)</li>\n<li><strong>maxiter:</strong>  Maximum number of simulation steps</li>\n<li><strong>dt:</strong>  Time step size for integration</li>\n<li><strong>grad_norm_tol:</strong>  Gradient norm tolerance for convergence</li>\n<li><strong>state:</strong>  Current molecular state (coordinates)</li>\n<li><strong>logger:</strong>  Logger instance for progress reporting</li>\n</ul>\n", "bases": "abc.ABC"}, {"fullname": "dftscape.core.Dynamics.__init__", "modulename": "dftscape.core", "qualname": "Dynamics.__init__", "kind": "function", "doc": "<p>Initialize the dynamics simulation.</p>\n\n<h6 id=\"arguments\">Arguments:</h6>\n\n<ul>\n<li><strong>backend:</strong>  Backend implementation for computing energies and gradients</li>\n<li><strong>log_interval:</strong>  Number of steps between logging progress. None disables logging.</li>\n<li><strong>maxiter:</strong>  Maximum number of simulation steps before aborting</li>\n<li><strong>dt:</strong>  Time step size for the dynamics integration</li>\n<li><strong>grad_norm_tol:</strong>  Gradient norm threshold for convergence detection</li>\n</ul>\n", "signature": "<span class=\"signature pdoc-code multiline\">(<span class=\"param\">\t<span class=\"n\">backend</span><span class=\"p\">:</span> <span class=\"n\">dftscape</span><span class=\"o\">.</span><span class=\"n\">core</span><span class=\"o\">.</span><span class=\"n\">interfaces</span><span class=\"o\">.</span><span class=\"n\">Backend</span>,</span><span class=\"param\">\t<span class=\"n\">log_interval</span><span class=\"p\">:</span> <span class=\"n\">Optional</span><span class=\"p\">[</span><span class=\"nb\">int</span><span class=\"p\">]</span> <span class=\"o\">=</span> <span class=\"mi\">1</span>,</span><span class=\"param\">\t<span class=\"n\">maxiter</span><span class=\"p\">:</span> <span class=\"nb\">int</span> <span class=\"o\">=</span> <span class=\"mi\">10000</span>,</span><span class=\"param\">\t<span class=\"n\">dt</span><span class=\"p\">:</span> <span class=\"nb\">float</span> <span class=\"o\">=</span> <span class=\"mf\">0.5</span>,</span><span class=\"param\">\t<span class=\"n\">grad_norm_tol</span><span class=\"p\">:</span> <span class=\"nb\">float</span> <span class=\"o\">=</span> <span class=\"mf\">5e-06</span></span>)</span>"}, {"fullname": "dftscape.core.Dynamics.backend", "modulename": "dftscape.core", "qualname": "Dynamics.backend", "kind": "variable", "doc": "<p></p>\n", "annotation": ": dftscape.core.interfaces.Backend"}, {"fullname": "dftscape.core.Dynamics.metrics", "modulename": "dftscape.core", "qualname": "Dynamics.metrics", "kind": "variable", "doc": "<p></p>\n", "annotation": ": List[dftscape.core.metrics.Metric]"}, {"fullname": "dftscape.core.Dynamics.log_interval", "modulename": "dftscape.core", "qualname": "Dynamics.log_interval", "kind": "variable", "doc": "<p></p>\n", "annotation": ": int"}, {"fullname": "dftscape.core.Dynamics.maxiter", "modulename": "dftscape.core", "qualname": "Dynamics.maxiter", "kind": "variable", "doc": "<p></p>\n", "annotation": ": int"}, {"fullname": "dftscape.core.Dynamics.dt", "modulename": "dftscape.core", "qualname": "Dynamics.dt", "kind": "variable", "doc": "<p></p>\n", "annotation": ": float"}, {"fullname": "dftscape.core.Dynamics.grad_norm_tol", "modulename": "dftscape.core", "qualname": "Dynamics.grad_norm_tol", "kind": "variable", "doc": "<p></p>\n", "annotation": ": float"}, {"fullname": "dftscape.core.Dynamics.state", "modulename": "dftscape.core", "qualname": "Dynamics.state", "kind": "variable", "doc": "<p></p>\n", "annotation": ": Optional[numpy.ndarray]"}, {"fullname": "dftscape.core.Dynamics.logger", "modulename": "dftscape.core", "qualname": "Dynamics.logger", "kind": "variable", "doc": "<p></p>\n", "annotation": ": logging.Logger"}, {"fullname": "dftscape.core.Dynamics.run", "modulename": "dftscape.core", "qualname": "Dynamics.run", "kind": "function", "doc": "<p>Run the dynamics simulation.</p>\n\n<h6 id=\"arguments\">Arguments:</h6>\n\n<ul>\n<li><strong>run_condition:</strong>  Initial conditions and parameters for the simulation</li>\n</ul>\n\n<h6 id=\"returns\">Returns:</h6>\n\n<blockquote>\n  <p>CriticalPoint if simulation converges to one, None if it fails or times out</p>\n</blockquote>\n", "signature": "<span class=\"signature pdoc-code multiline\">(<span class=\"param\">\t<span class=\"bp\">self</span>,</span><span class=\"param\">\t<span class=\"n\">run_condition</span><span class=\"p\">:</span> <span class=\"n\">dftscape</span><span class=\"o\">.</span><span class=\"n\">core</span><span class=\"o\">.</span><span class=\"n\">search_primitives</span><span class=\"o\">.</span><span class=\"n\">RunCondition</span></span><span class=\"return-annotation\">) -> <span class=\"n\">Optional</span><span class=\"p\">[</span><span class=\"n\">dftscape</span><span class=\"o\">.</span><span class=\"n\">core</span><span class=\"o\">.</span><span class=\"n\">point</span><span class=\"o\">.</span><span class=\"n\">CriticalPoint</span><span class=\"p\">]</span>:</span></span>", "funcdef": "def"}, {"fullname": "dftscape.core.HiSD", "modulename": "dftscape.core", "qualname": "HiSD", "kind": "class", "doc": "<p>HiSD (High index Saddle Dynamics) implementation.</p>\n\n<p>HiSD is a specialized dynamics algorithm for finding saddle points (transition states)\non potential energy surfaces. It uses Hessian information to construct a subspace\nthat guides the dynamics towards saddle points while avoiding convergence to minima.</p>\n\n<p>The algorithm works by:</p>\n\n<ol>\n<li>Computing the gradient and projecting it onto the subspace orthogonal to the\nlowest Hessian eigenvectors</li>\n<li>Taking a dynamics step in the direction that maximizes along the unstable modes\nwhile minimizing along stable modes</li>\n<li>Periodically updating the subspace based on current Hessian information</li>\n</ol>\n\n<p>This method is particularly effective for finding transition states in complex\nenergy landscapes where traditional methods struggle.</p>\n", "bases": "dftscape.core.dynamics.Dynamics"}, {"fullname": "dftscape.core.HiSD.__init__", "modulename": "dftscape.core", "qualname": "HiSD.__init__", "kind": "function", "doc": "<p>Initialize HiSD dynamics simulation.</p>\n\n<h6 id=\"arguments\">Arguments:</h6>\n\n<ul>\n<li><strong>backend:</strong>  Backend for computing energies, gradients, and Hessians</li>\n<li><strong>subspace_handler:</strong>  Handler for managing the subspace of Hessian eigenvectors</li>\n<li><strong>symmetry_handler:</strong>  Handler for enforcing molecular symmetry constraints</li>\n<li><strong>subspace_update_interval:</strong>  Steps between subspace updates from Hessian</li>\n<li><strong>log_interval:</strong>  Steps between logging progress (None disables logging)</li>\n<li><strong>check_stop_interval:</strong>  Steps between convergence checks</li>\n<li><strong>metrics:</strong>  List of metrics to compute during simulation</li>\n<li><strong>dt:</strong>  Time step size for dynamics integration</li>\n<li><strong>maxiter:</strong>  Maximum simulation steps before timeout</li>\n<li><strong>grad_norm_tol:</strong>  Gradient norm tolerance for convergence</li>\n<li><strong>energy_threshold:</strong>  Energy value above which simulation is aborted</li>\n</ul>\n", "signature": "<span class=\"signature pdoc-code multiline\">(<span class=\"param\">\t<span class=\"n\">backend</span><span class=\"p\">:</span> <span class=\"n\">dftscape</span><span class=\"o\">.</span><span class=\"n\">core</span><span class=\"o\">.</span><span class=\"n\">interfaces</span><span class=\"o\">.</span><span class=\"n\">Backend</span>,</span><span class=\"param\">\t<span class=\"n\">subspace_handler</span><span class=\"p\">:</span> <span class=\"n\">dftscape</span><span class=\"o\">.</span><span class=\"n\">core</span><span class=\"o\">.</span><span class=\"n\">subspace_handlers</span><span class=\"o\">.</span><span class=\"n\">SubspaceHandler</span>,</span><span class=\"param\">\t<span class=\"n\">symmetry_handler</span><span class=\"p\">:</span> <span class=\"n\">dftscape</span><span class=\"o\">.</span><span class=\"n\">core</span><span class=\"o\">.</span><span class=\"n\">symmetry_handlers</span><span class=\"o\">.</span><span class=\"n\">SymmetryHandler</span>,</span><span class=\"param\">\t<span class=\"n\">subspace_update_interval</span><span class=\"p\">:</span> <span class=\"nb\">int</span> <span class=\"o\">=</span> <span class=\"mi\">1</span>,</span><span class=\"param\">\t<span class=\"n\">log_interval</span><span class=\"p\">:</span> <span class=\"n\">Optional</span><span class=\"p\">[</span><span class=\"nb\">int</span><span class=\"p\">]</span> <span class=\"o\">=</span> <span class=\"mi\">1</span>,</span><span class=\"param\">\t<span class=\"n\">check_stop_interval</span><span class=\"p\">:</span> <span class=\"nb\">int</span> <span class=\"o\">=</span> <span class=\"mi\">10</span>,</span><span class=\"param\">\t<span class=\"n\">metrics</span><span class=\"p\">:</span> <span class=\"n\">Optional</span><span class=\"p\">[</span><span class=\"n\">List</span><span class=\"p\">[</span><span class=\"n\">dftscape</span><span class=\"o\">.</span><span class=\"n\">core</span><span class=\"o\">.</span><span class=\"n\">metrics</span><span class=\"o\">.</span><span class=\"n\">Metric</span><span class=\"p\">]]</span> <span class=\"o\">=</span> <span class=\"kc\">None</span>,</span><span class=\"param\">\t<span class=\"n\">dt</span><span class=\"p\">:</span> <span class=\"nb\">float</span> <span class=\"o\">=</span> <span class=\"mf\">0.5</span>,</span><span class=\"param\">\t<span class=\"n\">maxiter</span><span class=\"p\">:</span> <span class=\"nb\">int</span> <span class=\"o\">=</span> <span class=\"mi\">10000</span>,</span><span class=\"param\">\t<span class=\"n\">grad_norm_tol</span><span class=\"p\">:</span> <span class=\"nb\">float</span> <span class=\"o\">=</span> <span class=\"mf\">5e-06</span>,</span><span class=\"param\">\t<span class=\"n\">energy_threshold</span><span class=\"p\">:</span> <span class=\"nb\">float</span> <span class=\"o\">=</span> <span class=\"mf\">100.0</span></span>)</span>"}, {"fullname": "dftscape.core.HiSD.symmetry_handler", "modulename": "dftscape.core", "qualname": "HiSD.symmetry_handler", "kind": "variable", "doc": "<p></p>\n", "annotation": ": dftscape.core.symmetry_handlers.SymmetryHandler"}, {"fullname": "dftscape.core.HiSD.subspace_update_interval", "modulename": "dftscape.core", "qualname": "HiSD.subspace_update_interval", "kind": "variable", "doc": "<p></p>\n", "annotation": ": int"}, {"fullname": "dftscape.core.HiSD.check_stop_interval", "modulename": "dftscape.core", "qualname": "HiSD.check_stop_interval", "kind": "variable", "doc": "<p></p>\n"}, {"fullname": "dftscape.core.HiSD.subspace_handler", "modulename": "dftscape.core", "qualname": "HiSD.subspace_handler", "kind": "variable", "doc": "<p></p>\n", "annotation": ": dftscape.core.subspace_handlers.SubspaceHandler"}, {"fullname": "dftscape.core.HiSD.dt", "modulename": "dftscape.core", "qualname": "HiSD.dt", "kind": "variable", "doc": "<p></p>\n", "annotation": ": float"}, {"fullname": "dftscape.core.HiSD.maxiter", "modulename": "dftscape.core", "qualname": "HiSD.maxiter", "kind": "variable", "doc": "<p></p>\n", "annotation": ": int"}, {"fullname": "dftscape.core.HiSD.energy_threshold", "modulename": "dftscape.core", "qualname": "HiSD.energy_threshold", "kind": "variable", "doc": "<p></p>\n", "annotation": ": float"}, {"fullname": "dftscape.core.HiSD.hess_evals", "modulename": "dftscape.core", "qualname": "HiSD.hess_evals", "kind": "variable", "doc": "<p></p>\n", "annotation": ": Optional[numpy.ndarray]"}, {"fullname": "dftscape.core.HiSD.index", "modulename": "dftscape.core", "qualname": "HiSD.index", "kind": "variable", "doc": "<p></p>\n", "annotation": ": Optional[int]"}, {"fullname": "dftscape.core.HiSD.subspace", "modulename": "dftscape.core", "qualname": "HiSD.subspace", "kind": "variable", "doc": "<p></p>\n", "annotation": ": Optional[numpy.ndarray]"}, {"fullname": "dftscape.core.HiSD.run", "modulename": "dftscape.core", "qualname": "HiSD.run", "kind": "function", "doc": "<p>Execute the HiSD dynamics simulation to find a critical point.</p>\n\n<p>Runs the HiSD algorithm starting from the initial conditions specified\nin the run_condition. The simulation continues until convergence,\nfailure, or maximum iterations are reached.</p>\n\n<h6 id=\"arguments\">Arguments:</h6>\n\n<ul>\n<li><strong>run_condition:</strong>  Initial conditions including starting state, subspace,\nand index information</li>\n</ul>\n\n<h6 id=\"returns\">Returns:</h6>\n\n<blockquote>\n  <p>CriticalPoint if simulation successfully converges to one,\n  None if simulation fails (energy explosion) or times out</p>\n</blockquote>\n", "signature": "<span class=\"signature pdoc-code multiline\">(<span class=\"param\">\t<span class=\"bp\">self</span>,</span><span class=\"param\">\t<span class=\"n\">run_condition</span><span class=\"p\">:</span> <span class=\"n\">dftscape</span><span class=\"o\">.</span><span class=\"n\">core</span><span class=\"o\">.</span><span class=\"n\">search_primitives</span><span class=\"o\">.</span><span class=\"n\">RunCondition</span></span><span class=\"return-annotation\">) -> <span class=\"n\">Optional</span><span class=\"p\">[</span><span class=\"n\">dftscape</span><span class=\"o\">.</span><span class=\"n\">core</span><span class=\"o\">.</span><span class=\"n\">point</span><span class=\"o\">.</span><span class=\"n\">CriticalPoint</span><span class=\"p\">]</span>:</span></span>", "funcdef": "def"}, {"fullname": "dftscape.core.RunCondition", "modulename": "dftscape.core", "qualname": "RunCondition", "kind": "class", "doc": "<p>Immutable container for optimization run parameters.</p>\n\n<p>RunCondition encapsulates all the information needed to start and execute\nan optimization run in DFTScape. It defines the target optimization index,\ninitial state, perturbation parameters, and subspace constraints.</p>\n\n<p>The dataclass is frozen to ensure immutability, preventing accidental\nmodification of run parameters during job processing and scheduling.</p>\n\n<h6 id=\"attributes\">Attributes:</h6>\n\n<ul>\n<li><strong>index (int):</strong>  Target optimization index (k) for the run. Determines\nthe dimensionality of the optimization subspace.</li>\n<li><strong>state (np.ndarray):</strong>  Initial molecular state as 1D array of shape (d,)\nwhere d is the state dimension (3*n_atoms for molecular systems).</li>\n<li><strong>perturbation_idx (int):</strong>  Index of the eigenvector used for perturbation.\nMust be valid for the given critical point's eigenvalue array.</li>\n<li><strong>perturbation_strength (float):</strong>  Magnitude of the perturbation applied\nalong the perturbation direction. Can be positive or negative.</li>\n<li><strong>perturbation_direction (np.ndarray):</strong>  Normalized eigenvector of shape (d,)\ndefining the direction of perturbation from the initial state.</li>\n<li><strong>subspace (np.ndarray):</strong>  Subspace matrix of shape (d, k) defining the\noptimization subspace. Columns are orthonormal basis vectors.</li>\n</ul>\n\n<h6 id=\"methods\">Methods:</h6>\n\n<blockquote>\n  <p>get_perturbed_state: Compute the perturbed initial state\n  __str__: Provide detailed string representation for debugging</p>\n</blockquote>\n\n<h6 id=\"design-patterns\">Design Patterns:</h6>\n\n<blockquote>\n  <ul>\n  <li><strong>Value Object</strong>: Immutable data container with no behavior</li>\n  <li><strong>Data Transfer Object</strong>: Carries data between subsystems</li>\n  <li><strong>Frozen Dataclass</strong>: Prevents accidental state modification</li>\n  </ul>\n</blockquote>\n\n<h6 id=\"usage-examples\">Usage Examples:</h6>\n\n<blockquote>\n  <div class=\"pdoc-code codehilite\">\n<pre><span></span><code><span class=\"gp\">&gt;&gt;&gt; </span><span class=\"kn\">import</span><span class=\"w\"> </span><span class=\"nn\">numpy</span><span class=\"w\"> </span><span class=\"k\">as</span><span class=\"w\"> </span><span class=\"nn\">np</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"kn\">from</span><span class=\"w\"> </span><span class=\"nn\">dftscape.core.search_primitives</span><span class=\"w\"> </span><span class=\"kn\">import</span> <span class=\"n\">RunCondition</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Create run condition manually</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">state</span> <span class=\"o\">=</span> <span class=\"n\">np</span><span class=\"o\">.</span><span class=\"n\">random</span><span class=\"o\">.</span><span class=\"n\">randn</span><span class=\"p\">(</span><span class=\"mi\">9</span><span class=\"p\">)</span>  <span class=\"c1\"># 3 atoms</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">perturbation_dir</span> <span class=\"o\">=</span> <span class=\"n\">np</span><span class=\"o\">.</span><span class=\"n\">random</span><span class=\"o\">.</span><span class=\"n\">randn</span><span class=\"p\">(</span><span class=\"mi\">9</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">perturbation_dir</span> <span class=\"o\">/=</span> <span class=\"n\">np</span><span class=\"o\">.</span><span class=\"n\">linalg</span><span class=\"o\">.</span><span class=\"n\">norm</span><span class=\"p\">(</span><span class=\"n\">perturbation_dir</span><span class=\"p\">)</span>  <span class=\"c1\"># normalize</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">subspace</span> <span class=\"o\">=</span> <span class=\"n\">np</span><span class=\"o\">.</span><span class=\"n\">random</span><span class=\"o\">.</span><span class=\"n\">randn</span><span class=\"p\">(</span><span class=\"mi\">9</span><span class=\"p\">,</span> <span class=\"mi\">2</span><span class=\"p\">)</span>  <span class=\"c1\"># 2D subspace</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">rc</span> <span class=\"o\">=</span> <span class=\"n\">RunCondition</span><span class=\"p\">(</span>\n<span class=\"gp\">... </span>    <span class=\"n\">index</span><span class=\"o\">=</span><span class=\"mi\">2</span><span class=\"p\">,</span>\n<span class=\"gp\">... </span>    <span class=\"n\">state</span><span class=\"o\">=</span><span class=\"n\">state</span><span class=\"p\">,</span>\n<span class=\"gp\">... </span>    <span class=\"n\">perturbation_idx</span><span class=\"o\">=</span><span class=\"mi\">1</span><span class=\"p\">,</span>\n<span class=\"gp\">... </span>    <span class=\"n\">perturbation_strength</span><span class=\"o\">=</span><span class=\"mf\">0.1</span><span class=\"p\">,</span>\n<span class=\"gp\">... </span>    <span class=\"n\">perturbation_direction</span><span class=\"o\">=</span><span class=\"n\">perturbation_dir</span><span class=\"p\">,</span>\n<span class=\"gp\">... </span>    <span class=\"n\">subspace</span><span class=\"o\">=</span><span class=\"n\">subspace</span>\n<span class=\"gp\">... </span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Access computed properties</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">perturbed</span> <span class=\"o\">=</span> <span class=\"n\">rc</span><span class=\"o\">.</span><span class=\"n\">get_perturbed_state</span><span class=\"p\">()</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"sa\">f</span><span class=\"s2\">&quot;Original state shape: </span><span class=\"si\">{</span><span class=\"n\">rc</span><span class=\"o\">.</span><span class=\"n\">state</span><span class=\"o\">.</span><span class=\"n\">shape</span><span class=\"si\">}</span><span class=\"s2\">&quot;</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"sa\">f</span><span class=\"s2\">&quot;Perturbed state shape: </span><span class=\"si\">{</span><span class=\"n\">perturbed</span><span class=\"o\">.</span><span class=\"n\">shape</span><span class=\"si\">}</span><span class=\"s2\">&quot;</span><span class=\"p\">)</span>\n</code></pre>\n  </div>\n</blockquote>\n\n<h6 id=\"serialization\">Serialization:</h6>\n\n<blockquote>\n  <ul>\n  <li>Inherits from SerialisableDataClass for JSON/NPZ serialization</li>\n  <li>Supports checkpointing and job persistence</li>\n  <li>Handles numpy array serialization automatically</li>\n  </ul>\n</blockquote>\n\n<h6 id=\"notes\">Notes:</h6>\n\n<blockquote>\n  <ul>\n  <li>All attributes are required and immutable</li>\n  <li>perturbation_direction should be normalized</li>\n  <li>subspace columns should be orthonormal</li>\n  <li>Used by JobExecutor for optimization initialization</li>\n  </ul>\n</blockquote>\n", "bases": "dftscape.common.data_structures.SerialisableDataClass"}, {"fullname": "dftscape.core.RunCondition.__init__", "modulename": "dftscape.core", "qualname": "RunCondition.__init__", "kind": "function", "doc": "<p></p>\n", "signature": "<span class=\"signature pdoc-code multiline\">(<span class=\"param\">\t<span class=\"n\">index</span><span class=\"p\">:</span> <span class=\"nb\">int</span>,</span><span class=\"param\">\t<span class=\"n\">state</span><span class=\"p\">:</span> <span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span>,</span><span class=\"param\">\t<span class=\"n\">perturbation_idx</span><span class=\"p\">:</span> <span class=\"nb\">int</span>,</span><span class=\"param\">\t<span class=\"n\">perturbation_strength</span><span class=\"p\">:</span> <span class=\"nb\">float</span>,</span><span class=\"param\">\t<span class=\"n\">perturbation_direction</span><span class=\"p\">:</span> <span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span>,</span><span class=\"param\">\t<span class=\"n\">subspace</span><span class=\"p\">:</span> <span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span></span>)</span>"}, {"fullname": "dftscape.core.RunCondition.index", "modulename": "dftscape.core", "qualname": "RunCondition.index", "kind": "variable", "doc": "<p></p>\n", "annotation": ": int"}, {"fullname": "dftscape.core.RunCondition.state", "modulename": "dftscape.core", "qualname": "RunCondition.state", "kind": "variable", "doc": "<p></p>\n", "annotation": ": numpy.ndarray"}, {"fullname": "dftscape.core.RunCondition.perturbation_idx", "modulename": "dftscape.core", "qualname": "RunCondition.perturbation_idx", "kind": "variable", "doc": "<p></p>\n", "annotation": ": int"}, {"fullname": "dftscape.core.RunCondition.perturbation_strength", "modulename": "dftscape.core", "qualname": "RunCondition.perturbation_strength", "kind": "variable", "doc": "<p></p>\n", "annotation": ": float"}, {"fullname": "dftscape.core.RunCondition.perturbation_direction", "modulename": "dftscape.core", "qualname": "RunCondition.perturbation_direction", "kind": "variable", "doc": "<p></p>\n", "annotation": ": numpy.ndarray"}, {"fullname": "dftscape.core.RunCondition.subspace", "modulename": "dftscape.core", "qualname": "RunCondition.subspace", "kind": "variable", "doc": "<p></p>\n", "annotation": ": numpy.ndarray"}, {"fullname": "dftscape.core.RunCondition.get_perturbed_state", "modulename": "dftscape.core", "qualname": "RunCondition.get_perturbed_state", "kind": "function", "doc": "<p>Compute the perturbed initial state for optimization.</p>\n\n<p>This method calculates the actual starting point for the optimization run\nby applying the perturbation to the original state. The perturbation is\napplied along the specified perturbation direction with the given strength.</p>\n\n<p>The perturbed state is computed as:\nperturbed_state = state + perturbation_strength * perturbation_direction</p>\n\n<h6 id=\"returns\">Returns:</h6>\n\n<blockquote>\n  <p>np.ndarray: Perturbed state vector of shape (d,) where d is the\n      state dimension. This is the actual starting point for optimization.</p>\n</blockquote>\n\n<h6 id=\"examples\">Examples:</h6>\n\n<blockquote>\n  <div class=\"pdoc-code codehilite\">\n<pre><span></span><code><span class=\"gp\">&gt;&gt;&gt; </span><span class=\"kn\">import</span><span class=\"w\"> </span><span class=\"nn\">numpy</span><span class=\"w\"> </span><span class=\"k\">as</span><span class=\"w\"> </span><span class=\"nn\">np</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"kn\">from</span><span class=\"w\"> </span><span class=\"nn\">dftscape.core.search_primitives</span><span class=\"w\"> </span><span class=\"kn\">import</span> <span class=\"n\">RunCondition</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Create run condition with perturbation</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">state</span> <span class=\"o\">=</span> <span class=\"n\">np</span><span class=\"o\">.</span><span class=\"n\">array</span><span class=\"p\">([</span><span class=\"mf\">0.0</span><span class=\"p\">,</span> <span class=\"mf\">0.0</span><span class=\"p\">,</span> <span class=\"mf\">0.0</span><span class=\"p\">])</span>  <span class=\"c1\"># origin</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">direction</span> <span class=\"o\">=</span> <span class=\"n\">np</span><span class=\"o\">.</span><span class=\"n\">array</span><span class=\"p\">([</span><span class=\"mf\">1.0</span><span class=\"p\">,</span> <span class=\"mf\">0.0</span><span class=\"p\">,</span> <span class=\"mf\">0.0</span><span class=\"p\">])</span>  <span class=\"c1\"># along x-axis</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">rc</span> <span class=\"o\">=</span> <span class=\"n\">RunCondition</span><span class=\"p\">(</span>\n<span class=\"gp\">... </span>    <span class=\"n\">index</span><span class=\"o\">=</span><span class=\"mi\">1</span><span class=\"p\">,</span>\n<span class=\"gp\">... </span>    <span class=\"n\">state</span><span class=\"o\">=</span><span class=\"n\">state</span><span class=\"p\">,</span>\n<span class=\"gp\">... </span>    <span class=\"n\">perturbation_idx</span><span class=\"o\">=</span><span class=\"mi\">0</span><span class=\"p\">,</span>\n<span class=\"gp\">... </span>    <span class=\"n\">perturbation_strength</span><span class=\"o\">=</span><span class=\"mf\">0.1</span><span class=\"p\">,</span>\n<span class=\"gp\">... </span>    <span class=\"n\">perturbation_direction</span><span class=\"o\">=</span><span class=\"n\">direction</span><span class=\"p\">,</span>\n<span class=\"gp\">... </span>    <span class=\"n\">subspace</span><span class=\"o\">=</span><span class=\"n\">np</span><span class=\"o\">.</span><span class=\"n\">array</span><span class=\"p\">([[</span><span class=\"mf\">1.0</span><span class=\"p\">],</span> <span class=\"p\">[</span><span class=\"mf\">0.0</span><span class=\"p\">],</span> <span class=\"p\">[</span><span class=\"mf\">0.0</span><span class=\"p\">]])</span>\n<span class=\"gp\">... </span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">perturbed</span> <span class=\"o\">=</span> <span class=\"n\">rc</span><span class=\"o\">.</span><span class=\"n\">get_perturbed_state</span><span class=\"p\">()</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"sa\">f</span><span class=\"s2\">&quot;Original: </span><span class=\"si\">{</span><span class=\"n\">rc</span><span class=\"o\">.</span><span class=\"n\">state</span><span class=\"si\">}</span><span class=\"s2\">&quot;</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"sa\">f</span><span class=\"s2\">&quot;Perturbed: </span><span class=\"si\">{</span><span class=\"n\">perturbed</span><span class=\"si\">}</span><span class=\"s2\">&quot;</span><span class=\"p\">)</span>  <span class=\"c1\"># [0.1, 0.0, 0.0]</span>\n</code></pre>\n  </div>\n</blockquote>\n\n<h6 id=\"notes\">Notes:</h6>\n\n<blockquote>\n  <ul>\n  <li>Returns a new array, does not modify the original state</li>\n  <li>Perturbation direction should be normalized for consistent behavior</li>\n  <li>Used by JobExecutor to initialize optimization runs</li>\n  <li>Perturbation strength controls the step size from the critical point</li>\n  </ul>\n</blockquote>\n", "signature": "<span class=\"signature pdoc-code condensed\">(<span class=\"param\"><span class=\"bp\">self</span></span><span class=\"return-annotation\">) -> <span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span>:</span></span>", "funcdef": "def"}, {"fullname": "dftscape.core.RunConditionBuilder", "modulename": "dftscape.core", "qualname": "RunConditionBuilder", "kind": "class", "doc": "<p>Builder for creating validated RunCondition objects.</p>\n\n<p>This class provides factory methods for constructing RunCondition objects\nwith proper validation and subspace construction. It handles the complex\nlogic of selecting appropriate eigenvectors, constructing subspaces, and\nvalidating parameters for both upward and downward transitions.</p>\n\n<p>The builder supports:</p>\n\n<ul>\n<li><strong>Single Direction Building</strong>: Create RunCondition for specific perturbation</li>\n<li><strong>Exhaustive Building</strong>: Create all possible RunConditions for transitions</li>\n<li><strong>Validation</strong>: Comprehensive parameter validation and error handling</li>\n<li><strong>Subspace Construction</strong>: Automatic subspace building from eigenvector selection</li>\n</ul>\n\n<h6 id=\"class-methods\">Class Methods:</h6>\n\n<blockquote>\n  <p>build_up: Create RunCondition for upward transition (increasing index)\n  build_down: Create RunCondition for downward transition (decreasing index)\n  build_up_all: Create all possible upward RunCondition pairs\n  build_down_all: Create all possible downward RunCondition pairs\n  _build_run_condition: Internal method for RunCondition construction</p>\n</blockquote>\n\n<h6 id=\"design-patterns\">Design Patterns:</h6>\n\n<blockquote>\n  <ul>\n  <li><strong>Builder Pattern</strong>: Complex object construction with validation</li>\n  <li><strong>Factory Method</strong>: Centralized RunCondition creation</li>\n  <li><strong>Template Method</strong>: Common construction logic with variations</li>\n  </ul>\n</blockquote>\n\n<h6 id=\"usage-examples\">Usage Examples:</h6>\n\n<blockquote>\n  <div class=\"pdoc-code codehilite\">\n<pre><span></span><code><span class=\"gp\">&gt;&gt;&gt; </span><span class=\"kn\">from</span><span class=\"w\"> </span><span class=\"nn\">dftscape.core.search_primitives</span><span class=\"w\"> </span><span class=\"kn\">import</span> <span class=\"n\">RunConditionBuilder</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Build single upward transition</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">rc_up</span> <span class=\"o\">=</span> <span class=\"n\">RunConditionBuilder</span><span class=\"o\">.</span><span class=\"n\">build_up</span><span class=\"p\">(</span>\n<span class=\"gp\">... </span>    <span class=\"n\">critical_point</span><span class=\"p\">,</span>\n<span class=\"gp\">... </span>    <span class=\"n\">perturbation_idx</span><span class=\"o\">=</span><span class=\"mi\">2</span><span class=\"p\">,</span>\n<span class=\"gp\">... </span>    <span class=\"n\">perturbation_strength</span><span class=\"o\">=</span><span class=\"mf\">0.1</span>\n<span class=\"gp\">... </span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Build all upward transitions</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">upward_pairs</span> <span class=\"o\">=</span> <span class=\"n\">RunConditionBuilder</span><span class=\"o\">.</span><span class=\"n\">build_up_all</span><span class=\"p\">(</span><span class=\"n\">critical_point</span><span class=\"p\">,</span> <span class=\"mf\">0.1</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"sa\">f</span><span class=\"s2\">&quot;Generated </span><span class=\"si\">{</span><span class=\"nb\">len</span><span class=\"p\">(</span><span class=\"n\">upward_pairs</span><span class=\"p\">)</span><span class=\"si\">}</span><span class=\"s2\"> direction pairs&quot;</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Each pair contains [+perturbation, -perturbation] RunConditions</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"k\">for</span> <span class=\"n\">i</span><span class=\"p\">,</span> <span class=\"p\">(</span><span class=\"n\">rc_plus</span><span class=\"p\">,</span> <span class=\"n\">rc_minus</span><span class=\"p\">)</span> <span class=\"ow\">in</span> <span class=\"nb\">enumerate</span><span class=\"p\">(</span><span class=\"n\">upward_pairs</span><span class=\"p\">):</span>\n<span class=\"gp\">... </span>    <span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"sa\">f</span><span class=\"s2\">&quot;Direction </span><span class=\"si\">{</span><span class=\"n\">i</span><span class=\"si\">}</span><span class=\"s2\">: +strength=</span><span class=\"si\">{</span><span class=\"n\">rc_plus</span><span class=\"o\">.</span><span class=\"n\">perturbation_strength</span><span class=\"si\">}</span><span class=\"s2\">&quot;</span><span class=\"p\">)</span>\n</code></pre>\n  </div>\n</blockquote>\n\n<h6 id=\"validation\">Validation:</h6>\n\n<blockquote>\n  <ul>\n  <li>Checks perturbation_idx bounds relative to critical_point.index</li>\n  <li>Validates eigenvector and eigenvalue array dimensions</li>\n  <li>Ensures subspace construction is mathematically valid</li>\n  <li>Handles edge cases and provides meaningful error messages</li>\n  </ul>\n</blockquote>\n\n<h6 id=\"implementation-notes\">Implementation Notes:</h6>\n\n<blockquote>\n  <ul>\n  <li>All methods are class methods (no instance state needed)</li>\n  <li>Uses eigenvector selection for subspace construction</li>\n  <li>Handles both positive and negative perturbation strengths</li>\n  <li>Provides consistent error handling across all methods</li>\n  <li>Memory efficient by reusing eigenvector arrays</li>\n  </ul>\n</blockquote>\n\n<h6 id=\"notes\">Notes:</h6>\n\n<blockquote>\n  <ul>\n  <li>Builder methods are the recommended way to create RunCondition objects</li>\n  <li>Automatic subspace construction ensures mathematical correctness</li>\n  <li>Validation prevents common errors in perturbation setup</li>\n  <li>Supports both interactive and batch RunCondition creation</li>\n  </ul>\n</blockquote>\n"}, {"fullname": "dftscape.core.RunConditionBuilder.build_up", "modulename": "dftscape.core", "qualname": "RunConditionBuilder.build_up", "kind": "function", "doc": "<p>Create RunCondition for upward transition (increasing index).</p>\n\n<p>This method builds a RunCondition for transitioning to a higher index\n(k+1) by perturbing along the specified eigenvector direction. The upward\ntransition increases the optimization subspace dimensionality.</p>\n\n<p>The subspace is constructed by selecting eigenvectors from index 0 to\ncritical_point.index-1, plus the perturbation_idx eigenvector. This creates\na (k+1)-dimensional subspace for the upward transition.</p>\n\n<h6 id=\"arguments\">Arguments:</h6>\n\n<ul>\n<li><strong>crit_point (CriticalPoint):</strong>  The critical point from which to build\nthe upward transition. Must have valid eigenvalues and eigenvectors.</li>\n<li><strong>perturbation_idx (int):</strong>  Index of the eigenvector to use for perturbation.\nMust be &gt;= crit_point.index to enable upward transition.</li>\n<li><strong>perturbation_strength (float):</strong>  Magnitude of the perturbation. Can be\npositive or negative to explore both directions along the eigenvector.</li>\n</ul>\n\n<h6 id=\"returns\">Returns:</h6>\n\n<blockquote>\n  <p>RunCondition: A new RunCondition object configured for upward transition\n      with target index = crit_point.index + 1.</p>\n</blockquote>\n\n<h6 id=\"raises\">Raises:</h6>\n\n<ul>\n<li><strong>ValueError:</strong>  If perturbation_idx &lt; crit_point.index (invalid for upward transition).</li>\n<li><strong>IndexError:</strong>  If perturbation_idx is out of bounds for eigenvector array.</li>\n</ul>\n\n<h6 id=\"examples\">Examples:</h6>\n\n<blockquote>\n  <div class=\"pdoc-code codehilite\">\n<pre><span></span><code><span class=\"gp\">&gt;&gt;&gt; </span><span class=\"kn\">from</span><span class=\"w\"> </span><span class=\"nn\">dftscape.core.search_primitives</span><span class=\"w\"> </span><span class=\"kn\">import</span> <span class=\"n\">RunConditionBuilder</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"kn\">from</span><span class=\"w\"> </span><span class=\"nn\">dftscape.core.point</span><span class=\"w\"> </span><span class=\"kn\">import</span> <span class=\"n\">CriticalPoint</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"kn\">import</span><span class=\"w\"> </span><span class=\"nn\">numpy</span><span class=\"w\"> </span><span class=\"k\">as</span><span class=\"w\"> </span><span class=\"nn\">np</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Create critical point (index=1, meaning 1D subspace optimization)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">eigenvalues</span> <span class=\"o\">=</span> <span class=\"n\">np</span><span class=\"o\">.</span><span class=\"n\">array</span><span class=\"p\">([</span><span class=\"o\">-</span><span class=\"mf\">0.5</span><span class=\"p\">,</span> <span class=\"mf\">0.1</span><span class=\"p\">,</span> <span class=\"mf\">0.3</span><span class=\"p\">])</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">eigenvectors</span> <span class=\"o\">=</span> <span class=\"n\">np</span><span class=\"o\">.</span><span class=\"n\">random</span><span class=\"o\">.</span><span class=\"n\">randn</span><span class=\"p\">(</span><span class=\"mi\">9</span><span class=\"p\">,</span> <span class=\"mi\">3</span><span class=\"p\">)</span>  <span class=\"c1\"># 9D state, 3 eigenvectors</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">cp</span> <span class=\"o\">=</span> <span class=\"n\">CriticalPoint</span><span class=\"p\">(</span>\n<span class=\"gp\">... </span>    <span class=\"n\">state</span><span class=\"o\">=</span><span class=\"n\">np</span><span class=\"o\">.</span><span class=\"n\">random</span><span class=\"o\">.</span><span class=\"n\">randn</span><span class=\"p\">(</span><span class=\"mi\">9</span><span class=\"p\">),</span>\n<span class=\"gp\">... </span>    <span class=\"n\">eigenvalues</span><span class=\"o\">=</span><span class=\"n\">eigenvalues</span><span class=\"p\">,</span>\n<span class=\"gp\">... </span>    <span class=\"n\">eigenvectors</span><span class=\"o\">=</span><span class=\"n\">eigenvectors</span><span class=\"p\">,</span>\n<span class=\"gp\">... </span>    <span class=\"n\">index</span><span class=\"o\">=</span><span class=\"mi\">1</span>\n<span class=\"gp\">... </span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Build upward transition using eigenvector 2</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">rc</span> <span class=\"o\">=</span> <span class=\"n\">RunConditionBuilder</span><span class=\"o\">.</span><span class=\"n\">build_up</span><span class=\"p\">(</span><span class=\"n\">cp</span><span class=\"p\">,</span> <span class=\"n\">perturbation_idx</span><span class=\"o\">=</span><span class=\"mi\">2</span><span class=\"p\">,</span> <span class=\"n\">perturbation_strength</span><span class=\"o\">=</span><span class=\"mf\">0.1</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"sa\">f</span><span class=\"s2\">&quot;Target index: </span><span class=\"si\">{</span><span class=\"n\">rc</span><span class=\"o\">.</span><span class=\"n\">index</span><span class=\"si\">}</span><span class=\"s2\">&quot;</span><span class=\"p\">)</span>  <span class=\"c1\"># 2 (increased from 1)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"sa\">f</span><span class=\"s2\">&quot;Subspace shape: </span><span class=\"si\">{</span><span class=\"n\">rc</span><span class=\"o\">.</span><span class=\"n\">subspace</span><span class=\"o\">.</span><span class=\"n\">shape</span><span class=\"si\">}</span><span class=\"s2\">&quot;</span><span class=\"p\">)</span>  <span class=\"c1\"># (9, 2) - 2D subspace</span>\n</code></pre>\n  </div>\n</blockquote>\n\n<h6 id=\"algorithm\">Algorithm:</h6>\n\n<blockquote>\n  <ol>\n  <li>Validate perturbation_idx &gt;= crit_point.index</li>\n  <li>Set target index = crit_point.index + 1</li>\n  <li>Select direction indices: [0, 1, ..., index-1, perturbation_idx]</li>\n  <li>Call _build_run_condition with computed parameters</li>\n  </ol>\n</blockquote>\n\n<h6 id=\"notes\">Notes:</h6>\n\n<blockquote>\n  <ul>\n  <li>Upward transitions increase subspace dimensionality</li>\n  <li>perturbation_idx must be &gt;= current index for validity</li>\n  <li>Subspace includes all lower eigenvectors plus perturbation eigenvector</li>\n  <li>Used for finding saddle points from minima</li>\n  </ul>\n</blockquote>\n", "signature": "<span class=\"signature pdoc-code multiline\">(<span class=\"param\">\t<span class=\"bp\">cls</span>,</span><span class=\"param\">\t<span class=\"n\">crit_point</span><span class=\"p\">:</span> <span class=\"n\">dftscape</span><span class=\"o\">.</span><span class=\"n\">core</span><span class=\"o\">.</span><span class=\"n\">point</span><span class=\"o\">.</span><span class=\"n\">CriticalPoint</span>,</span><span class=\"param\">\t<span class=\"n\">perturbation_idx</span><span class=\"p\">:</span> <span class=\"nb\">int</span>,</span><span class=\"param\">\t<span class=\"n\">perturbation_strength</span><span class=\"p\">:</span> <span class=\"nb\">float</span></span><span class=\"return-annotation\">) -> <span class=\"n\">dftscape</span><span class=\"o\">.</span><span class=\"n\">core</span><span class=\"o\">.</span><span class=\"n\">search_primitives</span><span class=\"o\">.</span><span class=\"n\">RunCondition</span>:</span></span>", "funcdef": "def"}, {"fullname": "dftscape.core.RunConditionBuilder.build_down", "modulename": "dftscape.core", "qualname": "RunConditionBuilder.build_down", "kind": "function", "doc": "<p>Create RunCondition for downward transition (decreasing index).</p>\n\n<p>This method builds a RunCondition for transitioning to a lower index\n(k-1) by removing the specified eigenvector from the subspace. The downward\ntransition decreases the optimization subspace dimensionality.</p>\n\n<p>The subspace is constructed by selecting all eigenvectors except the\nperturbation_idx, creating a (k-1)-dimensional subspace for the downward\ntransition.</p>\n\n<h6 id=\"arguments\">Arguments:</h6>\n\n<ul>\n<li><strong>crit_point (CriticalPoint):</strong>  The critical point from which to build\nthe downward transition. Must have valid eigenvalues and eigenvectors.</li>\n<li><strong>perturbation_idx (int):</strong>  Index of the eigenvector to remove from subspace.\nMust be &lt; crit_point.index to enable downward transition.</li>\n<li><strong>perturbation_strength (float):</strong>  Magnitude of the perturbation. Can be\npositive or negative to explore both directions along the eigenvector.</li>\n</ul>\n\n<h6 id=\"returns\">Returns:</h6>\n\n<blockquote>\n  <p>RunCondition: A new RunCondition object configured for downward transition\n      with target index = crit_point.index - 1.</p>\n</blockquote>\n\n<h6 id=\"raises\">Raises:</h6>\n\n<ul>\n<li><strong>ValueError:</strong>  If perturbation_idx &gt;= crit_point.index (invalid for downward transition).</li>\n<li><strong>IndexError:</strong>  If perturbation_idx is out of bounds for eigenvector array.</li>\n</ul>\n\n<h6 id=\"examples\">Examples:</h6>\n\n<blockquote>\n  <div class=\"pdoc-code codehilite\">\n<pre><span></span><code><span class=\"gp\">&gt;&gt;&gt; </span><span class=\"kn\">from</span><span class=\"w\"> </span><span class=\"nn\">dftscape.core.search_primitives</span><span class=\"w\"> </span><span class=\"kn\">import</span> <span class=\"n\">RunConditionBuilder</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Create critical point (index=2, meaning 2D subspace optimization)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">eigenvalues</span> <span class=\"o\">=</span> <span class=\"n\">np</span><span class=\"o\">.</span><span class=\"n\">array</span><span class=\"p\">([</span><span class=\"o\">-</span><span class=\"mf\">0.5</span><span class=\"p\">,</span> <span class=\"mf\">0.1</span><span class=\"p\">,</span> <span class=\"mf\">0.3</span><span class=\"p\">,</span> <span class=\"mf\">0.8</span><span class=\"p\">])</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">eigenvectors</span> <span class=\"o\">=</span> <span class=\"n\">np</span><span class=\"o\">.</span><span class=\"n\">random</span><span class=\"o\">.</span><span class=\"n\">randn</span><span class=\"p\">(</span><span class=\"mi\">9</span><span class=\"p\">,</span> <span class=\"mi\">4</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">cp</span> <span class=\"o\">=</span> <span class=\"n\">CriticalPoint</span><span class=\"p\">(</span>\n<span class=\"gp\">... </span>    <span class=\"n\">state</span><span class=\"o\">=</span><span class=\"n\">np</span><span class=\"o\">.</span><span class=\"n\">random</span><span class=\"o\">.</span><span class=\"n\">randn</span><span class=\"p\">(</span><span class=\"mi\">9</span><span class=\"p\">),</span>\n<span class=\"gp\">... </span>    <span class=\"n\">eigenvalues</span><span class=\"o\">=</span><span class=\"n\">eigenvalues</span><span class=\"p\">,</span>\n<span class=\"gp\">... </span>    <span class=\"n\">eigenvectors</span><span class=\"o\">=</span><span class=\"n\">eigenvectors</span><span class=\"p\">,</span>\n<span class=\"gp\">... </span>    <span class=\"n\">index</span><span class=\"o\">=</span><span class=\"mi\">2</span>\n<span class=\"gp\">... </span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Build downward transition by removing eigenvector 1</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">rc</span> <span class=\"o\">=</span> <span class=\"n\">RunConditionBuilder</span><span class=\"o\">.</span><span class=\"n\">build_down</span><span class=\"p\">(</span><span class=\"n\">cp</span><span class=\"p\">,</span> <span class=\"n\">perturbation_idx</span><span class=\"o\">=</span><span class=\"mi\">1</span><span class=\"p\">,</span> <span class=\"n\">perturbation_strength</span><span class=\"o\">=</span><span class=\"mf\">0.1</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"sa\">f</span><span class=\"s2\">&quot;Target index: </span><span class=\"si\">{</span><span class=\"n\">rc</span><span class=\"o\">.</span><span class=\"n\">index</span><span class=\"si\">}</span><span class=\"s2\">&quot;</span><span class=\"p\">)</span>  <span class=\"c1\"># 1 (decreased from 2)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"sa\">f</span><span class=\"s2\">&quot;Subspace shape: </span><span class=\"si\">{</span><span class=\"n\">rc</span><span class=\"o\">.</span><span class=\"n\">subspace</span><span class=\"o\">.</span><span class=\"n\">shape</span><span class=\"si\">}</span><span class=\"s2\">&quot;</span><span class=\"p\">)</span>  <span class=\"c1\"># (9, 1) - 1D subspace</span>\n</code></pre>\n  </div>\n</blockquote>\n\n<h6 id=\"algorithm\">Algorithm:</h6>\n\n<blockquote>\n  <ol>\n  <li>Validate perturbation_idx &lt; crit_point.index</li>\n  <li>Set target index = crit_point.index - 1</li>\n  <li>Select direction indices: [0, 1, ..., index-1] excluding perturbation_idx</li>\n  <li>Call _build_run_condition with computed parameters</li>\n  </ol>\n</blockquote>\n\n<h6 id=\"notes\">Notes:</h6>\n\n<blockquote>\n  <ul>\n  <li>Downward transitions decrease subspace dimensionality</li>\n  <li>perturbation_idx must be &lt; current index for validity</li>\n  <li>Subspace excludes the perturbation eigenvector</li>\n  <li>Used for finding minima from saddle points</li>\n  </ul>\n</blockquote>\n", "signature": "<span class=\"signature pdoc-code multiline\">(<span class=\"param\">\t<span class=\"bp\">cls</span>,</span><span class=\"param\">\t<span class=\"n\">crit_point</span><span class=\"p\">:</span> <span class=\"n\">dftscape</span><span class=\"o\">.</span><span class=\"n\">core</span><span class=\"o\">.</span><span class=\"n\">point</span><span class=\"o\">.</span><span class=\"n\">CriticalPoint</span>,</span><span class=\"param\">\t<span class=\"n\">perturbation_idx</span><span class=\"p\">:</span> <span class=\"nb\">int</span>,</span><span class=\"param\">\t<span class=\"n\">perturbation_strength</span><span class=\"p\">:</span> <span class=\"nb\">float</span></span><span class=\"return-annotation\">) -> <span class=\"n\">dftscape</span><span class=\"o\">.</span><span class=\"n\">core</span><span class=\"o\">.</span><span class=\"n\">search_primitives</span><span class=\"o\">.</span><span class=\"n\">RunCondition</span>:</span></span>", "funcdef": "def"}, {"fullname": "dftscape.core.RunConditionBuilder.build_up_all", "modulename": "dftscape.core", "qualname": "RunConditionBuilder.build_up_all", "kind": "function", "doc": "<p>Create all possible upward RunCondition pairs.</p>\n\n<p>This method generates RunCondition objects for all possible upward transitions\nfrom the given critical point. For each valid perturbation direction, it creates\nboth positive and negative perturbations, returning pairs of RunConditions.</p>\n\n<p>The method explores all eigenvector indices from crit_point.index to the end\nof the eigenvalue array, creating comprehensive coverage of upward search space.</p>\n\n<h6 id=\"arguments\">Arguments:</h6>\n\n<ul>\n<li><strong>crit_point (CriticalPoint):</strong>  The critical point from which to generate\nall upward transitions. Must have eigenvalues and eigenvectors arrays.</li>\n<li><strong>perturbation_mag (float):</strong>  Magnitude of perturbations for all directions.\nBoth +perturbation_mag and -perturbation_mag are used for each direction.</li>\n</ul>\n\n<h6 id=\"returns\">Returns:</h6>\n\n<blockquote>\n  <p>List[List[RunCondition]]: List of RunCondition pairs, where each inner\n      list contains [rc_plus, rc_minus] for one perturbation direction.\n      Length equals the number of valid upward directions.</p>\n</blockquote>\n\n<h6 id=\"raises\">Raises:</h6>\n\n<ul>\n<li><strong>ValueError:</strong>  If critical point has invalid eigenvalue/eigenvector dimensions.</li>\n<li><strong>IndexError:</strong>  If eigenvector access fails (should not occur with validation).</li>\n</ul>\n\n<h6 id=\"examples\">Examples:</h6>\n\n<blockquote>\n  <div class=\"pdoc-code codehilite\">\n<pre><span></span><code><span class=\"gp\">&gt;&gt;&gt; </span><span class=\"kn\">from</span><span class=\"w\"> </span><span class=\"nn\">dftscape.core.search_primitives</span><span class=\"w\"> </span><span class=\"kn\">import</span> <span class=\"n\">RunConditionBuilder</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Critical point with 4 eigenvalues, index=1</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Valid upward directions: indices 1, 2, 3</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">upward_pairs</span> <span class=\"o\">=</span> <span class=\"n\">RunConditionBuilder</span><span class=\"o\">.</span><span class=\"n\">build_up_all</span><span class=\"p\">(</span><span class=\"n\">cp</span><span class=\"p\">,</span> <span class=\"mf\">0.1</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"sa\">f</span><span class=\"s2\">&quot;Number of direction pairs: </span><span class=\"si\">{</span><span class=\"nb\">len</span><span class=\"p\">(</span><span class=\"n\">upward_pairs</span><span class=\"p\">)</span><span class=\"si\">}</span><span class=\"s2\">&quot;</span><span class=\"p\">)</span>  <span class=\"c1\"># 3</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Each pair contains positive and negative perturbations</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"k\">for</span> <span class=\"n\">i</span><span class=\"p\">,</span> <span class=\"p\">(</span><span class=\"n\">rc_plus</span><span class=\"p\">,</span> <span class=\"n\">rc_minus</span><span class=\"p\">)</span> <span class=\"ow\">in</span> <span class=\"nb\">enumerate</span><span class=\"p\">(</span><span class=\"n\">upward_pairs</span><span class=\"p\">):</span>\n<span class=\"gp\">... </span>    <span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"sa\">f</span><span class=\"s2\">&quot;Direction </span><span class=\"si\">{</span><span class=\"n\">i</span><span class=\"si\">}</span><span class=\"s2\">:&quot;</span><span class=\"p\">)</span>\n<span class=\"gp\">... </span>    <span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"sa\">f</span><span class=\"s2\">&quot;  +perturbation strength: </span><span class=\"si\">{</span><span class=\"n\">rc_plus</span><span class=\"o\">.</span><span class=\"n\">perturbation_strength</span><span class=\"si\">}</span><span class=\"s2\">&quot;</span><span class=\"p\">)</span>\n<span class=\"gp\">... </span>    <span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"sa\">f</span><span class=\"s2\">&quot;  -perturbation strength: </span><span class=\"si\">{</span><span class=\"n\">rc_minus</span><span class=\"o\">.</span><span class=\"n\">perturbation_strength</span><span class=\"si\">}</span><span class=\"s2\">&quot;</span><span class=\"p\">)</span>\n</code></pre>\n  </div>\n</blockquote>\n\n<h6 id=\"algorithm\">Algorithm:</h6>\n\n<blockquote>\n  <ol>\n  <li>Iterate over all valid upward directions (crit_point.index to end)</li>\n  <li>For each direction, create +perturbation_mag RunCondition</li>\n  <li>For each direction, create -perturbation_mag RunCondition</li>\n  <li>Return list of [rc_plus, rc_minus] pairs</li>\n  </ol>\n</blockquote>\n\n<h6 id=\"performance\">Performance:</h6>\n\n<blockquote>\n  <ul>\n  <li>Time: O(n) where n is number of upward directions</li>\n  <li>Memory: O(n) for storing RunCondition objects</li>\n  <li>Scales with eigenvalue array size</li>\n  </ul>\n</blockquote>\n\n<h6 id=\"notes\">Notes:</h6>\n\n<blockquote>\n  <ul>\n  <li>Returns pairs for comprehensive directional exploration</li>\n  <li>Used by ExhaustiveUpwardSearchStrategy</li>\n  <li>Each direction gets both positive and negative perturbations</li>\n  <li>Empty list returned if no valid upward directions exist</li>\n  </ul>\n</blockquote>\n", "signature": "<span class=\"signature pdoc-code multiline\">(<span class=\"param\">\t<span class=\"bp\">cls</span>,</span><span class=\"param\">\t<span class=\"n\">crit_point</span><span class=\"p\">:</span> <span class=\"n\">dftscape</span><span class=\"o\">.</span><span class=\"n\">core</span><span class=\"o\">.</span><span class=\"n\">point</span><span class=\"o\">.</span><span class=\"n\">CriticalPoint</span>,</span><span class=\"param\">\t<span class=\"n\">perturbation_mag</span><span class=\"p\">:</span> <span class=\"nb\">float</span></span><span class=\"return-annotation\">) -> <span class=\"n\">List</span><span class=\"p\">[</span><span class=\"n\">List</span><span class=\"p\">[</span><span class=\"n\">dftscape</span><span class=\"o\">.</span><span class=\"n\">core</span><span class=\"o\">.</span><span class=\"n\">search_primitives</span><span class=\"o\">.</span><span class=\"n\">RunCondition</span><span class=\"p\">]]</span>:</span></span>", "funcdef": "def"}, {"fullname": "dftscape.core.RunConditionBuilder.build_down_all", "modulename": "dftscape.core", "qualname": "RunConditionBuilder.build_down_all", "kind": "function", "doc": "<p>Create all possible downward RunCondition pairs.</p>\n\n<p>This method generates RunCondition objects for all possible downward transitions\nfrom the given critical point. For each valid subspace direction, it creates\nboth positive and negative perturbations, returning pairs of RunConditions.</p>\n\n<p>The method explores all eigenvector indices from 0 to crit_point.index-1,\ncreating comprehensive coverage of downward search space by removing each\ndirection from the subspace.</p>\n\n<h6 id=\"arguments\">Arguments:</h6>\n\n<ul>\n<li><strong>crit_point (CriticalPoint):</strong>  The critical point from which to generate\nall downward transitions. Must have eigenvalues and eigenvectors arrays.</li>\n<li><strong>perturbation_mag (float):</strong>  Magnitude of perturbations for all directions.\nBoth +perturbation_mag and -perturbation_mag are used for each direction.</li>\n</ul>\n\n<h6 id=\"returns\">Returns:</h6>\n\n<blockquote>\n  <p>List[List[RunCondition]]: List of RunCondition pairs, where each inner\n      list contains [rc_plus, rc_minus] for one subspace direction removal.\n      Length equals crit_point.index (number of possible downward directions).</p>\n</blockquote>\n\n<h6 id=\"raises\">Raises:</h6>\n\n<ul>\n<li><strong>ValueError:</strong>  If critical point has invalid eigenvalue/eigenvector dimensions.</li>\n<li><strong>IndexError:</strong>  If eigenvector access fails (should not occur with validation).</li>\n</ul>\n\n<h6 id=\"examples\">Examples:</h6>\n\n<blockquote>\n  <div class=\"pdoc-code codehilite\">\n<pre><span></span><code><span class=\"gp\">&gt;&gt;&gt; </span><span class=\"kn\">from</span><span class=\"w\"> </span><span class=\"nn\">dftscape.core.search_primitives</span><span class=\"w\"> </span><span class=\"kn\">import</span> <span class=\"n\">RunConditionBuilder</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Critical point with index=2 (2D subspace)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Valid downward directions: indices 0, 1 (remove each to get 1D subspace)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">downward_pairs</span> <span class=\"o\">=</span> <span class=\"n\">RunConditionBuilder</span><span class=\"o\">.</span><span class=\"n\">build_down_all</span><span class=\"p\">(</span><span class=\"n\">cp</span><span class=\"p\">,</span> <span class=\"mf\">0.1</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"sa\">f</span><span class=\"s2\">&quot;Number of direction pairs: </span><span class=\"si\">{</span><span class=\"nb\">len</span><span class=\"p\">(</span><span class=\"n\">downward_pairs</span><span class=\"p\">)</span><span class=\"si\">}</span><span class=\"s2\">&quot;</span><span class=\"p\">)</span>  <span class=\"c1\"># 2</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Each pair removes one direction from subspace</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"k\">for</span> <span class=\"n\">i</span><span class=\"p\">,</span> <span class=\"p\">(</span><span class=\"n\">rc_plus</span><span class=\"p\">,</span> <span class=\"n\">rc_minus</span><span class=\"p\">)</span> <span class=\"ow\">in</span> <span class=\"nb\">enumerate</span><span class=\"p\">(</span><span class=\"n\">downward_pairs</span><span class=\"p\">):</span>\n<span class=\"gp\">... </span>    <span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"sa\">f</span><span class=\"s2\">&quot;Removing direction </span><span class=\"si\">{</span><span class=\"n\">i</span><span class=\"si\">}</span><span class=\"s2\">:&quot;</span><span class=\"p\">)</span>\n<span class=\"gp\">... </span>    <span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"sa\">f</span><span class=\"s2\">&quot;  Target subspace dim: </span><span class=\"si\">{</span><span class=\"n\">rc_plus</span><span class=\"o\">.</span><span class=\"n\">index</span><span class=\"si\">}</span><span class=\"s2\">&quot;</span><span class=\"p\">)</span>  <span class=\"c1\"># 1</span>\n<span class=\"gp\">... </span>    <span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"sa\">f</span><span class=\"s2\">&quot;  Removed eigenvector: </span><span class=\"si\">{</span><span class=\"n\">rc_plus</span><span class=\"o\">.</span><span class=\"n\">perturbation_idx</span><span class=\"si\">}</span><span class=\"s2\">&quot;</span><span class=\"p\">)</span>\n</code></pre>\n  </div>\n</blockquote>\n\n<h6 id=\"algorithm\">Algorithm:</h6>\n\n<blockquote>\n  <ol>\n  <li>Iterate over all valid subspace directions (0 to crit_point.index-1)</li>\n  <li>For each direction, create +perturbation_mag RunCondition</li>\n  <li>For each direction, create -perturbation_mag RunCondition</li>\n  <li>Return list of [rc_plus, rc_minus] pairs</li>\n  </ol>\n</blockquote>\n\n<h6 id=\"performance\">Performance:</h6>\n\n<blockquote>\n  <ul>\n  <li>Time: O(n) where n is crit_point.index</li>\n  <li>Memory: O(n) for storing RunCondition objects</li>\n  <li>Scales with current subspace dimensionality</li>\n  </ul>\n</blockquote>\n\n<h6 id=\"notes\">Notes:</h6>\n\n<blockquote>\n  <ul>\n  <li>Returns pairs for comprehensive directional exploration</li>\n  <li>Used by ExhaustiveDownwardSearchStrategy</li>\n  <li>Each direction removal creates a new subspace</li>\n  <li>Empty list returned if crit_point.index == 0 (no downward directions)</li>\n  </ul>\n</blockquote>\n", "signature": "<span class=\"signature pdoc-code multiline\">(<span class=\"param\">\t<span class=\"bp\">cls</span>,</span><span class=\"param\">\t<span class=\"n\">crit_point</span><span class=\"p\">:</span> <span class=\"n\">dftscape</span><span class=\"o\">.</span><span class=\"n\">core</span><span class=\"o\">.</span><span class=\"n\">point</span><span class=\"o\">.</span><span class=\"n\">CriticalPoint</span>,</span><span class=\"param\">\t<span class=\"n\">perturbation_mag</span><span class=\"p\">:</span> <span class=\"nb\">float</span></span><span class=\"return-annotation\">) -> <span class=\"n\">List</span><span class=\"p\">[</span><span class=\"n\">List</span><span class=\"p\">[</span><span class=\"n\">dftscape</span><span class=\"o\">.</span><span class=\"n\">core</span><span class=\"o\">.</span><span class=\"n\">search_primitives</span><span class=\"o\">.</span><span class=\"n\">RunCondition</span><span class=\"p\">]]</span>:</span></span>", "funcdef": "def"}, {"fullname": "dftscape.core.SymmetryHandler", "modulename": "dftscape.core", "qualname": "SymmetryHandler", "kind": "class", "doc": "<p>Protocol for symmetry constraint handlers in DFTScape.</p>\n\n<p>This protocol defines the interface that all symmetry handlers must implement.\nSymmetry handlers are responsible for defining and enforcing symmetry constraints\nduring molecular optimization, ensuring that the optimizer doesn't explore\nphysically meaningless directions.</p>\n\n<p>The protocol provides three key methods:</p>\n\n<ul>\n<li><strong>get_constraint_subspace</strong>: Define constraint directions</li>\n<li><strong>validate_subspace</strong>: Verify constraint satisfaction</li>\n<li><strong>get_name</strong>: Provide human-readable identification</li>\n</ul>\n\n<h6 id=\"key-concepts\">Key Concepts:</h6>\n\n<blockquote>\n  <ul>\n  <li><strong>Constraint Subspace</strong>: Directions that should be orthogonal to optimization</li>\n  <li><strong>Trivial Modes</strong>: Translations and rotations that don't change molecular energy</li>\n  <li><strong>Overlap Threshold</strong>: Maximum allowed projection onto constraint directions</li>\n  <li><strong>Validation</strong>: Ensuring subspaces maintain required symmetries</li>\n  </ul>\n</blockquote>\n\n<h6 id=\"implementation-requirements\">Implementation Requirements:</h6>\n\n<blockquote>\n  <ul>\n  <li>Methods must handle numpy arrays of molecular coordinates</li>\n  <li>Constraint subspaces should be orthogonalized</li>\n  <li>Validation should use appropriate numerical thresholds</li>\n  <li>Names should be descriptive and unique</li>\n  </ul>\n</blockquote>\n\n<h6 id=\"design-patterns\">Design Patterns:</h6>\n\n<blockquote>\n  <ul>\n  <li><strong>Protocol Pattern</strong>: Defines interface without implementation</li>\n  <li><strong>Strategy Pattern</strong>: Pluggable symmetry constraint strategies</li>\n  <li><strong>Template Method</strong>: Standardized constraint handling process</li>\n  </ul>\n</blockquote>\n\n<h6 id=\"usage-examples\">Usage Examples:</h6>\n\n<blockquote>\n  <div class=\"pdoc-code codehilite\">\n<pre><span></span><code><span class=\"gp\">&gt;&gt;&gt; </span><span class=\"kn\">from</span><span class=\"w\"> </span><span class=\"nn\">dftscape.core.symmetry_handlers</span><span class=\"w\"> </span><span class=\"kn\">import</span> <span class=\"n\">SymmetryHandler</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Type hint for symmetry handler implementations</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"k\">def</span><span class=\"w\"> </span><span class=\"nf\">optimize_with_symmetry</span><span class=\"p\">(</span><span class=\"n\">handler</span><span class=\"p\">:</span> <span class=\"n\">SymmetryHandler</span><span class=\"p\">,</span> <span class=\"n\">state</span><span class=\"p\">:</span> <span class=\"n\">np</span><span class=\"o\">.</span><span class=\"n\">ndarray</span><span class=\"p\">):</span>\n<span class=\"gp\">... </span>    <span class=\"n\">constraints</span> <span class=\"o\">=</span> <span class=\"n\">handler</span><span class=\"o\">.</span><span class=\"n\">get_constraint_subspace</span><span class=\"p\">(</span><span class=\"n\">state</span><span class=\"p\">)</span>\n<span class=\"gp\">... </span>    <span class=\"c1\"># Use constraints in optimization...</span>\n<span class=\"gp\">... </span>    <span class=\"k\">return</span> <span class=\"n\">optimized_state</span>\n</code></pre>\n  </div>\n</blockquote>\n\n<h6 id=\"notes\">Notes:</h6>\n\n<blockquote>\n  <ul>\n  <li>All implementations must be registered with SymmetryRegistry</li>\n  <li>Constraint subspaces define forbidden optimization directions</li>\n  <li>Validation ensures numerical stability of constrained optimization</li>\n  <li>Protocol allows for custom symmetry implementations</li>\n  </ul>\n</blockquote>\n", "bases": "typing.Protocol"}, {"fullname": "dftscape.core.SymmetryHandler.__init__", "modulename": "dftscape.core", "qualname": "SymmetryHandler.__init__", "kind": "function", "doc": "<p></p>\n", "signature": "<span class=\"signature pdoc-code condensed\">(<span class=\"param\"><span class=\"o\">*</span><span class=\"n\">args</span>, </span><span class=\"param\"><span class=\"o\">**</span><span class=\"n\">kwargs</span></span>)</span>"}, {"fullname": "dftscape.core.SymmetryHandler.get_constraint_subspace", "modulename": "dftscape.core", "qualname": "SymmetryHandler.get_constraint_subspace", "kind": "function", "doc": "<p>Return the subspace that should be orthogonal to the search directions.</p>\n\n<p>This method defines the constraint subspace - the directions in which the\noptimization should not search. These typically include translational and\nrotational degrees of freedom that don't affect the molecular energy.</p>\n\n<p>The constraint subspace is used by eigensolvers to ensure that optimization\ndirections remain orthogonal to these trivial modes, maintaining molecular\nsymmetry and preventing numerical instabilities.</p>\n\n<h6 id=\"arguments\">Arguments:</h6>\n\n<ul>\n<li><strong>state (np.ndarray):</strong>  Current molecular state as a 1D array of atomic\ncoordinates. Shape should be (3*n_atoms,) where coordinates are\nordered as [x1, y1, z1, x2, y2, z2, ...].</li>\n</ul>\n\n<h6 id=\"returns\">Returns:</h6>\n\n<blockquote>\n  <p>np.ndarray | None: Constraint subspace matrix of shape (n, k) where\n      n is the state dimension and k is the constraint dimension, or\n      None if no constraints should be applied. The columns should be\n      orthonormal vectors defining the constraint directions.</p>\n</blockquote>\n\n<h6 id=\"raises\">Raises:</h6>\n\n<ul>\n<li><strong>ValueError:</strong>  If state array has invalid shape or dimensions.</li>\n<li><strong>RuntimeError:</strong>  If constraint computation fails numerically.</li>\n</ul>\n\n<h6 id=\"examples\">Examples:</h6>\n\n<blockquote>\n  <div class=\"pdoc-code codehilite\">\n<pre><span></span><code><span class=\"gp\">&gt;&gt;&gt; </span><span class=\"kn\">import</span><span class=\"w\"> </span><span class=\"nn\">numpy</span><span class=\"w\"> </span><span class=\"k\">as</span><span class=\"w\"> </span><span class=\"nn\">np</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"kn\">from</span><span class=\"w\"> </span><span class=\"nn\">dftscape.core.symmetry_handlers</span><span class=\"w\"> </span><span class=\"kn\">import</span> <span class=\"n\">SymmetryRegistry</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Create molecular symmetry handler</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">handler</span> <span class=\"o\">=</span> <span class=\"n\">SymmetryRegistry</span><span class=\"o\">.</span><span class=\"n\">create</span><span class=\"p\">(</span><span class=\"s2\">&quot;molecular&quot;</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Define simple linear molecule (2 atoms)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">state</span> <span class=\"o\">=</span> <span class=\"n\">np</span><span class=\"o\">.</span><span class=\"n\">array</span><span class=\"p\">([</span><span class=\"mf\">0.0</span><span class=\"p\">,</span> <span class=\"mf\">0.0</span><span class=\"p\">,</span> <span class=\"mf\">0.0</span><span class=\"p\">,</span>  <span class=\"c1\"># atom 1 at origin</span>\n<span class=\"gp\">... </span>                  <span class=\"mf\">0.0</span><span class=\"p\">,</span> <span class=\"mf\">0.0</span><span class=\"p\">,</span> <span class=\"mf\">2.0</span><span class=\"p\">])</span>  <span class=\"c1\"># atom 2 along z-axis</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">constraints</span> <span class=\"o\">=</span> <span class=\"n\">handler</span><span class=\"o\">.</span><span class=\"n\">get_constraint_subspace</span><span class=\"p\">(</span><span class=\"n\">state</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"sa\">f</span><span class=\"s2\">&quot;Constraint shape: </span><span class=\"si\">{</span><span class=\"n\">constraints</span><span class=\"o\">.</span><span class=\"n\">shape</span><span class=\"si\">}</span><span class=\"s2\">&quot;</span><span class=\"p\">)</span>  <span class=\"c1\"># (6, 5) for linear</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># No symmetry case</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">no_sym</span> <span class=\"o\">=</span> <span class=\"n\">SymmetryRegistry</span><span class=\"o\">.</span><span class=\"n\">create</span><span class=\"p\">(</span><span class=\"s2\">&quot;none&quot;</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">constraints</span> <span class=\"o\">=</span> <span class=\"n\">no_sym</span><span class=\"o\">.</span><span class=\"n\">get_constraint_subspace</span><span class=\"p\">(</span><span class=\"n\">state</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"sa\">f</span><span class=\"s2\">&quot;No constraints: </span><span class=\"si\">{</span><span class=\"n\">constraints</span><span class=\"si\">}</span><span class=\"s2\">&quot;</span><span class=\"p\">)</span>  <span class=\"c1\"># None</span>\n</code></pre>\n  </div>\n</blockquote>\n\n<h6 id=\"implementation-notes\">Implementation Notes:</h6>\n\n<blockquote>\n  <ul>\n  <li>Should return orthonormal constraint vectors</li>\n  <li>For molecular systems: typically 6D (3 translation + 3 rotation)</li>\n  <li>Linear molecules: 5D constraints (no rotation around molecular axis)</li>\n  <li>Memory efficient: reuse computations when possible</li>\n  <li>Thread-safe: no side effects on input state</li>\n  </ul>\n</blockquote>\n\n<h6 id=\"notes\">Notes:</h6>\n\n<blockquote>\n  <ul>\n  <li>Constraint vectors define forbidden optimization directions</li>\n  <li>Used by eigensolvers as Y parameter in scipy.sparse.linalg.eigsh</li>\n  <li>None return value indicates unconstrained optimization</li>\n  <li>Orthonormality ensures numerical stability</li>\n  </ul>\n</blockquote>\n", "signature": "<span class=\"signature pdoc-code condensed\">(<span class=\"param\"><span class=\"bp\">self</span>, </span><span class=\"param\"><span class=\"n\">state</span><span class=\"p\">:</span> <span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span></span><span class=\"return-annotation\">) -> <span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span> <span class=\"o\">|</span> <span class=\"kc\">None</span>:</span></span>", "funcdef": "def"}, {"fullname": "dftscape.core.SymmetryHandler.validate_subspace", "modulename": "dftscape.core", "qualname": "SymmetryHandler.validate_subspace", "kind": "function", "doc": "<p>Validate that subspace satisfies symmetry constraints.</p>\n\n<p>This method checks whether the given subspace maintains the required\northogonality to the constraint directions. It's used to verify that\noptimization subspaces don't overlap significantly with trivial modes.</p>\n\n<p>The validation computes the maximum overlap between the subspace and\nconstraint directions, comparing it against a threshold to determine\nif the subspace satisfies symmetry requirements.</p>\n\n<h6 id=\"arguments\">Arguments:</h6>\n\n<ul>\n<li><strong>subspace (np.ndarray):</strong>  Subspace to validate of shape (n, k) where\nn is state dimension and k is subspace dimension.</li>\n<li><strong>state (np.ndarray):</strong>  Current molecular state of shape (n,) used to\ncompute constraint directions.</li>\n</ul>\n\n<h6 id=\"returns\">Returns:</h6>\n\n<blockquote>\n  <p>bool: True if subspace satisfies symmetry constraints, False otherwise.\n      Returns True if no constraints are defined (None case).</p>\n</blockquote>\n\n<h6 id=\"raises\">Raises:</h6>\n\n<ul>\n<li><strong>ValueError:</strong>  If subspace or state arrays have invalid shapes.</li>\n<li><strong>RuntimeError:</strong>  If constraint computation fails.</li>\n</ul>\n\n<h6 id=\"examples\">Examples:</h6>\n\n<blockquote>\n  <div class=\"pdoc-code codehilite\">\n<pre><span></span><code><span class=\"gp\">&gt;&gt;&gt; </span><span class=\"kn\">import</span><span class=\"w\"> </span><span class=\"nn\">numpy</span><span class=\"w\"> </span><span class=\"k\">as</span><span class=\"w\"> </span><span class=\"nn\">np</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"kn\">from</span><span class=\"w\"> </span><span class=\"nn\">dftscape.core.symmetry_handlers</span><span class=\"w\"> </span><span class=\"kn\">import</span> <span class=\"n\">SymmetryRegistry</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">handler</span> <span class=\"o\">=</span> <span class=\"n\">SymmetryRegistry</span><span class=\"o\">.</span><span class=\"n\">create</span><span class=\"p\">(</span><span class=\"s2\">&quot;molecular&quot;</span><span class=\"p\">,</span> <span class=\"n\">overlap_threshold</span><span class=\"o\">=</span><span class=\"mf\">0.1</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">state</span> <span class=\"o\">=</span> <span class=\"n\">np</span><span class=\"o\">.</span><span class=\"n\">random</span><span class=\"o\">.</span><span class=\"n\">randn</span><span class=\"p\">(</span><span class=\"mi\">9</span><span class=\"p\">)</span>  <span class=\"c1\"># 3 atoms</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Valid subspace (orthogonal to constraints)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">valid_subspace</span> <span class=\"o\">=</span> <span class=\"n\">np</span><span class=\"o\">.</span><span class=\"n\">random</span><span class=\"o\">.</span><span class=\"n\">randn</span><span class=\"p\">(</span><span class=\"mi\">9</span><span class=\"p\">,</span> <span class=\"mi\">3</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">is_valid</span> <span class=\"o\">=</span> <span class=\"n\">handler</span><span class=\"o\">.</span><span class=\"n\">validate_subspace</span><span class=\"p\">(</span><span class=\"n\">valid_subspace</span><span class=\"p\">,</span> <span class=\"n\">state</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"sa\">f</span><span class=\"s2\">&quot;Valid subspace: </span><span class=\"si\">{</span><span class=\"n\">is_valid</span><span class=\"si\">}</span><span class=\"s2\">&quot;</span><span class=\"p\">)</span>  <span class=\"c1\"># True</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Invalid subspace (overlaps with constraints)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">constraints</span> <span class=\"o\">=</span> <span class=\"n\">handler</span><span class=\"o\">.</span><span class=\"n\">get_constraint_subspace</span><span class=\"p\">(</span><span class=\"n\">state</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">invalid_subspace</span> <span class=\"o\">=</span> <span class=\"n\">constraints</span><span class=\"p\">[:,</span> <span class=\"p\">:</span><span class=\"mi\">3</span><span class=\"p\">]</span>  <span class=\"c1\"># Direct constraint directions</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">is_valid</span> <span class=\"o\">=</span> <span class=\"n\">handler</span><span class=\"o\">.</span><span class=\"n\">validate_subspace</span><span class=\"p\">(</span><span class=\"n\">invalid_subspace</span><span class=\"p\">,</span> <span class=\"n\">state</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"sa\">f</span><span class=\"s2\">&quot;Invalid subspace: </span><span class=\"si\">{</span><span class=\"n\">is_valid</span><span class=\"si\">}</span><span class=\"s2\">&quot;</span><span class=\"p\">)</span>  <span class=\"c1\"># False</span>\n</code></pre>\n  </div>\n</blockquote>\n\n<h6 id=\"performance\">Performance:</h6>\n\n<blockquote>\n  <ul>\n  <li>Time: O(n\u00d7k\u00d7m) where m is constraint dimension</li>\n  <li>Memory: O(n\u00d7k) for temporary computations</li>\n  <li>Efficient for typical molecular systems</li>\n  </ul>\n</blockquote>\n\n<h6 id=\"notes\">Notes:</h6>\n\n<blockquote>\n  <ul>\n  <li>Uses maximum norm of constraint-subspace overlap</li>\n  <li>Threshold comparison prevents numerical instabilities</li>\n  <li>Returns True for unconstrained cases (no validation needed)</li>\n  <li>Useful for debugging symmetry constraint issues</li>\n  </ul>\n</blockquote>\n", "signature": "<span class=\"signature pdoc-code condensed\">(<span class=\"param\"><span class=\"bp\">self</span>, </span><span class=\"param\"><span class=\"n\">subspace</span><span class=\"p\">:</span> <span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span>, </span><span class=\"param\"><span class=\"n\">state</span><span class=\"p\">:</span> <span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span></span><span class=\"return-annotation\">) -> <span class=\"nb\">bool</span>:</span></span>", "funcdef": "def"}, {"fullname": "dftscape.core.SymmetryHandler.get_name", "modulename": "dftscape.core", "qualname": "SymmetryHandler.get_name", "kind": "function", "doc": "<p>Return human-readable name of this symmetry handler.</p>\n\n<p>This method provides a descriptive name for the symmetry handler,\nuseful for logging, debugging, and user interface display.</p>\n\n<h6 id=\"returns\">Returns:</h6>\n\n<blockquote>\n  <p>str: Human-readable name describing the symmetry constraints.\n      Should be concise but descriptive (e.g., \"Molecular (Translation + Rotation)\").</p>\n</blockquote>\n\n<h6 id=\"examples\">Examples:</h6>\n\n<blockquote>\n  <div class=\"pdoc-code codehilite\">\n<pre><span></span><code><span class=\"gp\">&gt;&gt;&gt; </span><span class=\"kn\">from</span><span class=\"w\"> </span><span class=\"nn\">dftscape.core.symmetry_handlers</span><span class=\"w\"> </span><span class=\"kn\">import</span> <span class=\"n\">SymmetryRegistry</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">molecular</span> <span class=\"o\">=</span> <span class=\"n\">SymmetryRegistry</span><span class=\"o\">.</span><span class=\"n\">create</span><span class=\"p\">(</span><span class=\"s2\">&quot;molecular&quot;</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"n\">molecular</span><span class=\"o\">.</span><span class=\"n\">get_name</span><span class=\"p\">())</span>  <span class=\"c1\"># &quot;Molecular (Translation + Rotation)&quot;</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">none_sym</span> <span class=\"o\">=</span> <span class=\"n\">SymmetryRegistry</span><span class=\"o\">.</span><span class=\"n\">create</span><span class=\"p\">(</span><span class=\"s2\">&quot;none&quot;</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"n\">none_sym</span><span class=\"o\">.</span><span class=\"n\">get_name</span><span class=\"p\">())</span>  <span class=\"c1\"># &quot;No Symmetry&quot;</span>\n</code></pre>\n  </div>\n</blockquote>\n\n<h6 id=\"notes\">Notes:</h6>\n\n<blockquote>\n  <ul>\n  <li>Used for logging and debugging output</li>\n  <li>Should be unique across different handler types</li>\n  <li>Keep names concise but descriptive</li>\n  <li>Used in error messages and status reporting</li>\n  </ul>\n</blockquote>\n", "signature": "<span class=\"signature pdoc-code condensed\">(<span class=\"param\"><span class=\"bp\">self</span></span><span class=\"return-annotation\">) -> <span class=\"nb\">str</span>:</span></span>", "funcdef": "def"}, {"fullname": "dftscape.core.NoSymmetryHandler", "modulename": "dftscape.core", "qualname": "NoSymmetryHandler", "kind": "class", "doc": "<p>No symmetry constraints - for systems without translational/rotational invariance.</p>\n\n<p>This handler implements unconstrained optimization by returning no constraint\nsubspace. It's useful for systems where symmetry constraints are not applicable\nor should be explicitly disabled.</p>\n\n<h6 id=\"use-cases\">Use Cases:</h6>\n\n<blockquote>\n  <ul>\n  <li><strong>Surface Optimization</strong>: When optimizing on potential energy surfaces</li>\n  <li><strong>Custom Constraints</strong>: When other constraint mechanisms are used</li>\n  <li><strong>Testing</strong>: For validation of constraint-free optimization algorithms</li>\n  <li><strong>Special Systems</strong>: Systems without standard molecular symmetry</li>\n  </ul>\n</blockquote>\n\n<h6 id=\"attributes\">Attributes:</h6>\n\n<ul>\n<li>None - stateless implementation</li>\n</ul>\n\n<h6 id=\"methods\">Methods:</h6>\n\n<blockquote>\n  <p>get_constraint_subspace: Returns None (no constraints)\n  validate_subspace: Always returns True (no validation needed)\n  get_name: Returns \"No Symmetry\"</p>\n</blockquote>\n\n<h6 id=\"usage-examples\">Usage Examples:</h6>\n\n<blockquote>\n  <div class=\"pdoc-code codehilite\">\n<pre><span></span><code><span class=\"gp\">&gt;&gt;&gt; </span><span class=\"kn\">from</span><span class=\"w\"> </span><span class=\"nn\">dftscape.core.symmetry_handlers</span><span class=\"w\"> </span><span class=\"kn\">import</span> <span class=\"n\">SymmetryRegistry</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Create unconstrained handler</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">handler</span> <span class=\"o\">=</span> <span class=\"n\">SymmetryRegistry</span><span class=\"o\">.</span><span class=\"n\">create</span><span class=\"p\">(</span><span class=\"s2\">&quot;none&quot;</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># No constraints returned</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">state</span> <span class=\"o\">=</span> <span class=\"n\">np</span><span class=\"o\">.</span><span class=\"n\">random</span><span class=\"o\">.</span><span class=\"n\">randn</span><span class=\"p\">(</span><span class=\"mi\">9</span><span class=\"p\">)</span>  <span class=\"c1\"># 3 atoms</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">constraints</span> <span class=\"o\">=</span> <span class=\"n\">handler</span><span class=\"o\">.</span><span class=\"n\">get_constraint_subspace</span><span class=\"p\">(</span><span class=\"n\">state</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"sa\">f</span><span class=\"s2\">&quot;Constraints: </span><span class=\"si\">{</span><span class=\"n\">constraints</span><span class=\"si\">}</span><span class=\"s2\">&quot;</span><span class=\"p\">)</span>  <span class=\"c1\"># None</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># All subspaces are valid</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">subspace</span> <span class=\"o\">=</span> <span class=\"n\">np</span><span class=\"o\">.</span><span class=\"n\">random</span><span class=\"o\">.</span><span class=\"n\">randn</span><span class=\"p\">(</span><span class=\"mi\">9</span><span class=\"p\">,</span> <span class=\"mi\">5</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">is_valid</span> <span class=\"o\">=</span> <span class=\"n\">handler</span><span class=\"o\">.</span><span class=\"n\">validate_subspace</span><span class=\"p\">(</span><span class=\"n\">subspace</span><span class=\"p\">,</span> <span class=\"n\">state</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"sa\">f</span><span class=\"s2\">&quot;Valid: </span><span class=\"si\">{</span><span class=\"n\">is_valid</span><span class=\"si\">}</span><span class=\"s2\">&quot;</span><span class=\"p\">)</span>  <span class=\"c1\"># True</span>\n</code></pre>\n  </div>\n</blockquote>\n\n<h6 id=\"performance\">Performance:</h6>\n\n<blockquote>\n  <ul>\n  <li>Time: O(1) - no computations performed</li>\n  <li>Memory: O(1) - no additional memory allocation</li>\n  <li>Most efficient symmetry handler implementation</li>\n  </ul>\n</blockquote>\n\n<h6 id=\"notes\">Notes:</h6>\n\n<blockquote>\n  <ul>\n  <li>Always returns None for constraint subspace</li>\n  <li>Validation always passes (no constraints to violate)</li>\n  <li>Useful for debugging and testing unconstrained algorithms</li>\n  <li>Minimal overhead implementation</li>\n  </ul>\n</blockquote>\n", "bases": "dftscape.core.symmetry_handlers.SymmetryHandler"}, {"fullname": "dftscape.core.NoSymmetryHandler.get_constraint_subspace", "modulename": "dftscape.core", "qualname": "NoSymmetryHandler.get_constraint_subspace", "kind": "function", "doc": "<p>Return empty constraint subspace.</p>\n\n<p>This implementation returns None to indicate that no symmetry constraints\nshould be applied during optimization.</p>\n\n<h6 id=\"arguments\">Arguments:</h6>\n\n<ul>\n<li><strong>state (np.ndarray):</strong>  Current molecular state (unused in this implementation).</li>\n</ul>\n\n<h6 id=\"returns\">Returns:</h6>\n\n<blockquote>\n  <p>np.ndarray | None: Always returns None to indicate no constraints.</p>\n</blockquote>\n\n<h6 id=\"examples\">Examples:</h6>\n\n<blockquote>\n  <div class=\"pdoc-code codehilite\">\n<pre><span></span><code><span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">handler</span> <span class=\"o\">=</span> <span class=\"n\">SymmetryRegistry</span><span class=\"o\">.</span><span class=\"n\">create</span><span class=\"p\">(</span><span class=\"s2\">&quot;none&quot;</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">state</span> <span class=\"o\">=</span> <span class=\"n\">np</span><span class=\"o\">.</span><span class=\"n\">random</span><span class=\"o\">.</span><span class=\"n\">randn</span><span class=\"p\">(</span><span class=\"mi\">9</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">constraints</span> <span class=\"o\">=</span> <span class=\"n\">handler</span><span class=\"o\">.</span><span class=\"n\">get_constraint_subspace</span><span class=\"p\">(</span><span class=\"n\">state</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"n\">constraints</span><span class=\"p\">)</span>  <span class=\"c1\"># None</span>\n</code></pre>\n  </div>\n</blockquote>\n", "signature": "<span class=\"signature pdoc-code condensed\">(<span class=\"param\"><span class=\"bp\">self</span>, </span><span class=\"param\"><span class=\"n\">state</span><span class=\"p\">:</span> <span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span></span><span class=\"return-annotation\">) -> <span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span> <span class=\"o\">|</span> <span class=\"kc\">None</span>:</span></span>", "funcdef": "def"}, {"fullname": "dftscape.core.NoSymmetryHandler.validate_subspace", "modulename": "dftscape.core", "qualname": "NoSymmetryHandler.validate_subspace", "kind": "function", "doc": "<p>No validation needed for no symmetry case.</p>\n\n<p>Since no constraints are applied, all subspaces are considered valid.</p>\n\n<h6 id=\"arguments\">Arguments:</h6>\n\n<ul>\n<li><strong>subspace (np.ndarray):</strong>  Subspace to validate (unused in this implementation).</li>\n<li><strong>state (np.ndarray):</strong>  Current molecular state (unused in this implementation).</li>\n</ul>\n\n<h6 id=\"returns\">Returns:</h6>\n\n<blockquote>\n  <p>bool: Always returns True since no constraints exist to violate.</p>\n</blockquote>\n\n<h6 id=\"examples\">Examples:</h6>\n\n<blockquote>\n  <div class=\"pdoc-code codehilite\">\n<pre><span></span><code><span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">handler</span> <span class=\"o\">=</span> <span class=\"n\">SymmetryRegistry</span><span class=\"o\">.</span><span class=\"n\">create</span><span class=\"p\">(</span><span class=\"s2\">&quot;none&quot;</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">subspace</span> <span class=\"o\">=</span> <span class=\"n\">np</span><span class=\"o\">.</span><span class=\"n\">random</span><span class=\"o\">.</span><span class=\"n\">randn</span><span class=\"p\">(</span><span class=\"mi\">9</span><span class=\"p\">,</span> <span class=\"mi\">5</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">state</span> <span class=\"o\">=</span> <span class=\"n\">np</span><span class=\"o\">.</span><span class=\"n\">random</span><span class=\"o\">.</span><span class=\"n\">randn</span><span class=\"p\">(</span><span class=\"mi\">9</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">is_valid</span> <span class=\"o\">=</span> <span class=\"n\">handler</span><span class=\"o\">.</span><span class=\"n\">validate_subspace</span><span class=\"p\">(</span><span class=\"n\">subspace</span><span class=\"p\">,</span> <span class=\"n\">state</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"n\">is_valid</span><span class=\"p\">)</span>  <span class=\"c1\"># True</span>\n</code></pre>\n  </div>\n</blockquote>\n", "signature": "<span class=\"signature pdoc-code condensed\">(<span class=\"param\"><span class=\"bp\">self</span>, </span><span class=\"param\"><span class=\"n\">subspace</span><span class=\"p\">:</span> <span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span>, </span><span class=\"param\"><span class=\"n\">state</span><span class=\"p\">:</span> <span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span></span><span class=\"return-annotation\">) -> <span class=\"nb\">bool</span>:</span></span>", "funcdef": "def"}, {"fullname": "dftscape.core.NoSymmetryHandler.get_name", "modulename": "dftscape.core", "qualname": "NoSymmetryHandler.get_name", "kind": "function", "doc": "<p>Return handler name.</p>\n\n<h6 id=\"returns\">Returns:</h6>\n\n<blockquote>\n  <p>str: \"No Symmetry\" to identify this unconstrained handler.</p>\n</blockquote>\n", "signature": "<span class=\"signature pdoc-code condensed\">(<span class=\"param\"><span class=\"bp\">self</span></span><span class=\"return-annotation\">) -> <span class=\"nb\">str</span>:</span></span>", "funcdef": "def"}, {"fullname": "dftscape.core.MolecularSymmetryHandler", "modulename": "dftscape.core", "qualname": "MolecularSymmetryHandler", "kind": "class", "doc": "<p>Standard molecular symmetry: translations + rotations.</p>\n\n<p>This handler implements standard molecular symmetry constraints by computing\nthe 6-dimensional trivial subspace consisting of 3 translational and 3 rotational\ndegrees of freedom. It automatically detects linear molecules and adjusts the\nconstraint dimensionality accordingly.</p>\n\n<h6 id=\"the-trivial-modes-are\">The trivial modes are:</h6>\n\n<blockquote>\n  <ul>\n  <li><strong>Translations</strong>: Movement of the entire molecule in x, y, z directions</li>\n  <li><strong>Rotations</strong>: Rotation around x, y, z axes through the center of mass</li>\n  <li><strong>Linear Correction</strong>: For linear molecules, removes rotation around molecular axis</li>\n  </ul>\n</blockquote>\n\n<h6 id=\"attributes\">Attributes:</h6>\n\n<ul>\n<li><strong>overlap_threshold (float):</strong>  Maximum allowed overlap between subspace and\ntrivial modes. Default is 0.2. Lower values are more restrictive.</li>\n</ul>\n\n<h6 id=\"methods\">Methods:</h6>\n\n<blockquote>\n  <p>get_constraint_subspace: Compute 6D trivial subspace (or 5D for linear molecules)\n  validate_subspace: Check orthogonality to trivial modes\n  get_name: Return descriptive handler name\n  _compute_trivial_subspace: Internal computation of trivial eigenvectors</p>\n</blockquote>\n\n<h6 id=\"usage-examples\">Usage Examples:</h6>\n\n<blockquote>\n  <div class=\"pdoc-code codehilite\">\n<pre><span></span><code><span class=\"gp\">&gt;&gt;&gt; </span><span class=\"kn\">from</span><span class=\"w\"> </span><span class=\"nn\">dftscape.core.symmetry_handlers</span><span class=\"w\"> </span><span class=\"kn\">import</span> <span class=\"n\">SymmetryRegistry</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Create with default threshold</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">handler</span> <span class=\"o\">=</span> <span class=\"n\">SymmetryRegistry</span><span class=\"o\">.</span><span class=\"n\">create</span><span class=\"p\">(</span><span class=\"s2\">&quot;molecular&quot;</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Create with custom threshold</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">strict_handler</span> <span class=\"o\">=</span> <span class=\"n\">SymmetryRegistry</span><span class=\"o\">.</span><span class=\"n\">create</span><span class=\"p\">(</span><span class=\"s2\">&quot;molecular&quot;</span><span class=\"p\">,</span> <span class=\"n\">overlap_threshold</span><span class=\"o\">=</span><span class=\"mf\">0.1</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Use with molecular coordinates</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Linear molecule (H2)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">h2_coords</span> <span class=\"o\">=</span> <span class=\"n\">np</span><span class=\"o\">.</span><span class=\"n\">array</span><span class=\"p\">([</span><span class=\"mf\">0.0</span><span class=\"p\">,</span> <span class=\"mf\">0.0</span><span class=\"p\">,</span> <span class=\"mf\">0.0</span><span class=\"p\">,</span>  <span class=\"c1\"># H at origin</span>\n<span class=\"gp\">... </span>                      <span class=\"mf\">0.0</span><span class=\"p\">,</span> <span class=\"mf\">0.0</span><span class=\"p\">,</span> <span class=\"mf\">0.74</span><span class=\"p\">])</span> <span class=\"c1\"># H along z-axis</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">constraints</span> <span class=\"o\">=</span> <span class=\"n\">handler</span><span class=\"o\">.</span><span class=\"n\">get_constraint_subspace</span><span class=\"p\">(</span><span class=\"n\">h2_coords</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"sa\">f</span><span class=\"s2\">&quot;Linear molecule constraints: </span><span class=\"si\">{</span><span class=\"n\">constraints</span><span class=\"o\">.</span><span class=\"n\">shape</span><span class=\"si\">}</span><span class=\"s2\">&quot;</span><span class=\"p\">)</span>  <span class=\"c1\"># (6, 5)</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Non-linear molecule (H2O)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">h2o_coords</span> <span class=\"o\">=</span> <span class=\"n\">np</span><span class=\"o\">.</span><span class=\"n\">array</span><span class=\"p\">([</span><span class=\"mf\">0.0</span><span class=\"p\">,</span> <span class=\"mf\">0.0</span><span class=\"p\">,</span> <span class=\"mf\">0.0</span><span class=\"p\">,</span>   <span class=\"c1\"># O at origin</span>\n<span class=\"gp\">... </span>                       <span class=\"mf\">0.0</span><span class=\"p\">,</span> <span class=\"mf\">0.757</span><span class=\"p\">,</span> <span class=\"mf\">0.586</span><span class=\"p\">,</span>  <span class=\"c1\"># H</span>\n<span class=\"gp\">... </span>                       <span class=\"mf\">0.0</span><span class=\"p\">,</span> <span class=\"o\">-</span><span class=\"mf\">0.757</span><span class=\"p\">,</span> <span class=\"mf\">0.586</span><span class=\"p\">])</span> <span class=\"c1\"># H</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">constraints</span> <span class=\"o\">=</span> <span class=\"n\">handler</span><span class=\"o\">.</span><span class=\"n\">get_constraint_subspace</span><span class=\"p\">(</span><span class=\"n\">h2o_coords</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"sa\">f</span><span class=\"s2\">&quot;Non-linear constraints: </span><span class=\"si\">{</span><span class=\"n\">constraints</span><span class=\"o\">.</span><span class=\"n\">shape</span><span class=\"si\">}</span><span class=\"s2\">&quot;</span><span class=\"p\">)</span>  <span class=\"c1\"># (6, 6)</span>\n</code></pre>\n  </div>\n</blockquote>\n\n<h6 id=\"performance\">Performance:</h6>\n\n<blockquote>\n  <ul>\n  <li>Time: O(n) where n is number of atoms</li>\n  <li>Memory: O(n) for coordinate processing</li>\n  <li>Efficient for molecular systems up to thousands of atoms</li>\n  </ul>\n</blockquote>\n\n<h6 id=\"implementation-notes\">Implementation Notes:</h6>\n\n<blockquote>\n  <ul>\n  <li>Uses QR decomposition for orthogonalization</li>\n  <li>Automatically detects molecular linearity</li>\n  <li>Handles rank-deficient constraint matrices</li>\n  <li>Center of mass computation for accurate rotations</li>\n  <li>Orthonormal constraint vectors for numerical stability</li>\n  </ul>\n</blockquote>\n\n<h6 id=\"notes\">Notes:</h6>\n\n<blockquote>\n  <ul>\n  <li>Constraint subspace defines directions orthogonal to optimization</li>\n  <li>Linear molecules have 5 constraints (no rotation around molecular axis)</li>\n  <li>Overlap threshold prevents numerical instabilities</li>\n  <li>Used by eigensolvers as constraint matrix Y parameter</li>\n  </ul>\n</blockquote>\n", "bases": "dftscape.core.symmetry_handlers.SymmetryHandler"}, {"fullname": "dftscape.core.MolecularSymmetryHandler.__init__", "modulename": "dftscape.core", "qualname": "MolecularSymmetryHandler.__init__", "kind": "function", "doc": "<p>Initialize molecular symmetry handler.</p>\n\n<h6 id=\"arguments\">Arguments:</h6>\n\n<ul>\n<li><strong>overlap_threshold:</strong>  Maximum allowed overlap between subspace and trivial modes.\nDefault is 0.2. Lower values provide stricter orthogonality\nrequirements but may cause numerical difficulties.</li>\n</ul>\n", "signature": "<span class=\"signature pdoc-code condensed\">(<span class=\"param\"><span class=\"n\">overlap_threshold</span><span class=\"p\">:</span> <span class=\"nb\">float</span> <span class=\"o\">=</span> <span class=\"mf\">0.2</span></span>)</span>"}, {"fullname": "dftscape.core.MolecularSymmetryHandler.overlap_threshold", "modulename": "dftscape.core", "qualname": "MolecularSymmetryHandler.overlap_threshold", "kind": "variable", "doc": "<p></p>\n"}, {"fullname": "dftscape.core.MolecularSymmetryHandler.get_constraint_subspace", "modulename": "dftscape.core", "qualname": "MolecularSymmetryHandler.get_constraint_subspace", "kind": "function", "doc": "<p>Return 6D trivial subspace (3 translations + 3 rotations).</p>\n\n<p>Computes the trivial eigenvectors corresponding to translational and rotational\ndegrees of freedom. For linear molecules, returns only 5 constraints by\nremoving the rotation around the molecular axis.</p>\n\n<h6 id=\"arguments\">Arguments:</h6>\n\n<ul>\n<li><strong>state (np.ndarray):</strong>  Molecular coordinates as 1D array of shape (3*n_atoms,).</li>\n</ul>\n\n<h6 id=\"returns\">Returns:</h6>\n\n<blockquote>\n  <p>np.ndarray: Orthonormal constraint subspace of shape (3*n_atoms, k) where\n      k=6 for non-linear molecules or k=5 for linear molecules.</p>\n</blockquote>\n\n<h6 id=\"examples\">Examples:</h6>\n\n<blockquote>\n  <div class=\"pdoc-code codehilite\">\n<pre><span></span><code><span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">handler</span> <span class=\"o\">=</span> <span class=\"n\">SymmetryRegistry</span><span class=\"o\">.</span><span class=\"n\">create</span><span class=\"p\">(</span><span class=\"s2\">&quot;molecular&quot;</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Linear molecule (H2)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">linear_coords</span> <span class=\"o\">=</span> <span class=\"n\">np</span><span class=\"o\">.</span><span class=\"n\">array</span><span class=\"p\">([</span><span class=\"mi\">0</span><span class=\"p\">,</span> <span class=\"mi\">0</span><span class=\"p\">,</span> <span class=\"mi\">0</span><span class=\"p\">,</span> <span class=\"mi\">0</span><span class=\"p\">,</span> <span class=\"mi\">0</span><span class=\"p\">,</span> <span class=\"mf\">0.74</span><span class=\"p\">])</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">constraints</span> <span class=\"o\">=</span> <span class=\"n\">handler</span><span class=\"o\">.</span><span class=\"n\">get_constraint_subspace</span><span class=\"p\">(</span><span class=\"n\">linear_coords</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"sa\">f</span><span class=\"s2\">&quot;Linear constraints shape: </span><span class=\"si\">{</span><span class=\"n\">constraints</span><span class=\"o\">.</span><span class=\"n\">shape</span><span class=\"si\">}</span><span class=\"s2\">&quot;</span><span class=\"p\">)</span>  <span class=\"c1\"># (6, 5)</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Non-linear molecule (H2O)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">nonlinear_coords</span> <span class=\"o\">=</span> <span class=\"n\">np</span><span class=\"o\">.</span><span class=\"n\">array</span><span class=\"p\">([</span><span class=\"mi\">0</span><span class=\"p\">,</span> <span class=\"mi\">0</span><span class=\"p\">,</span> <span class=\"mi\">0</span><span class=\"p\">,</span> <span class=\"mi\">0</span><span class=\"p\">,</span> <span class=\"mf\">0.757</span><span class=\"p\">,</span> <span class=\"mf\">0.586</span><span class=\"p\">,</span> <span class=\"mi\">0</span><span class=\"p\">,</span> <span class=\"o\">-</span><span class=\"mf\">0.757</span><span class=\"p\">,</span> <span class=\"mf\">0.586</span><span class=\"p\">])</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">constraints</span> <span class=\"o\">=</span> <span class=\"n\">handler</span><span class=\"o\">.</span><span class=\"n\">get_constraint_subspace</span><span class=\"p\">(</span><span class=\"n\">nonlinear_coords</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"sa\">f</span><span class=\"s2\">&quot;Non-linear constraints shape: </span><span class=\"si\">{</span><span class=\"n\">constraints</span><span class=\"o\">.</span><span class=\"n\">shape</span><span class=\"si\">}</span><span class=\"s2\">&quot;</span><span class=\"p\">)</span>  <span class=\"c1\"># (6, 6)</span>\n</code></pre>\n  </div>\n</blockquote>\n", "signature": "<span class=\"signature pdoc-code condensed\">(<span class=\"param\"><span class=\"bp\">self</span>, </span><span class=\"param\"><span class=\"n\">state</span><span class=\"p\">:</span> <span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span></span><span class=\"return-annotation\">) -> <span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span>:</span></span>", "funcdef": "def"}, {"fullname": "dftscape.core.MolecularSymmetryHandler.validate_subspace", "modulename": "dftscape.core", "qualname": "MolecularSymmetryHandler.validate_subspace", "kind": "function", "doc": "<p>Check that subspace doesn't overlap with trivial modes.</p>\n\n<p>Validates that the optimization subspace maintains sufficient orthogonality\nto the molecular symmetry directions (translations and rotations).</p>\n\n<h6 id=\"arguments\">Arguments:</h6>\n\n<ul>\n<li><strong>subspace (np.ndarray):</strong>  Subspace to validate of shape (n, k).</li>\n<li><strong>state (np.ndarray):</strong>  Current molecular coordinates of shape (n,).</li>\n</ul>\n\n<h6 id=\"returns\">Returns:</h6>\n\n<blockquote>\n  <p>bool: True if subspace satisfies orthogonality constraints,\n        False if overlap exceeds threshold.</p>\n</blockquote>\n\n<h6 id=\"examples\">Examples:</h6>\n\n<blockquote>\n  <div class=\"pdoc-code codehilite\">\n<pre><span></span><code><span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">handler</span> <span class=\"o\">=</span> <span class=\"n\">SymmetryRegistry</span><span class=\"o\">.</span><span class=\"n\">create</span><span class=\"p\">(</span><span class=\"s2\">&quot;molecular&quot;</span><span class=\"p\">,</span> <span class=\"n\">overlap_threshold</span><span class=\"o\">=</span><span class=\"mf\">0.1</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">state</span> <span class=\"o\">=</span> <span class=\"n\">np</span><span class=\"o\">.</span><span class=\"n\">random</span><span class=\"o\">.</span><span class=\"n\">randn</span><span class=\"p\">(</span><span class=\"mi\">9</span><span class=\"p\">)</span>  <span class=\"c1\"># 3 atoms</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Valid subspace (orthogonal to trivial modes)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">valid_subspace</span> <span class=\"o\">=</span> <span class=\"n\">np</span><span class=\"o\">.</span><span class=\"n\">random</span><span class=\"o\">.</span><span class=\"n\">randn</span><span class=\"p\">(</span><span class=\"mi\">9</span><span class=\"p\">,</span> <span class=\"mi\">3</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">is_valid</span> <span class=\"o\">=</span> <span class=\"n\">handler</span><span class=\"o\">.</span><span class=\"n\">validate_subspace</span><span class=\"p\">(</span><span class=\"n\">valid_subspace</span><span class=\"p\">,</span> <span class=\"n\">state</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"sa\">f</span><span class=\"s2\">&quot;Valid: </span><span class=\"si\">{</span><span class=\"n\">is_valid</span><span class=\"si\">}</span><span class=\"s2\">&quot;</span><span class=\"p\">)</span>  <span class=\"c1\"># Likely True</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Invalid subspace (overlaps with trivial modes)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">trivial_modes</span> <span class=\"o\">=</span> <span class=\"n\">handler</span><span class=\"o\">.</span><span class=\"n\">get_constraint_subspace</span><span class=\"p\">(</span><span class=\"n\">state</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">invalid_subspace</span> <span class=\"o\">=</span> <span class=\"n\">trivial_modes</span><span class=\"p\">[:,</span> <span class=\"p\">:</span><span class=\"mi\">3</span><span class=\"p\">]</span>  <span class=\"c1\"># Direct trivial directions</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">is_valid</span> <span class=\"o\">=</span> <span class=\"n\">handler</span><span class=\"o\">.</span><span class=\"n\">validate_subspace</span><span class=\"p\">(</span><span class=\"n\">invalid_subspace</span><span class=\"p\">,</span> <span class=\"n\">state</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"sa\">f</span><span class=\"s2\">&quot;Invalid: </span><span class=\"si\">{</span><span class=\"n\">is_valid</span><span class=\"si\">}</span><span class=\"s2\">&quot;</span><span class=\"p\">)</span>  <span class=\"c1\"># False</span>\n</code></pre>\n  </div>\n</blockquote>\n", "signature": "<span class=\"signature pdoc-code condensed\">(<span class=\"param\"><span class=\"bp\">self</span>, </span><span class=\"param\"><span class=\"n\">subspace</span><span class=\"p\">:</span> <span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span>, </span><span class=\"param\"><span class=\"n\">state</span><span class=\"p\">:</span> <span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span></span><span class=\"return-annotation\">) -> <span class=\"nb\">bool</span>:</span></span>", "funcdef": "def"}, {"fullname": "dftscape.core.MolecularSymmetryHandler.get_name", "modulename": "dftscape.core", "qualname": "MolecularSymmetryHandler.get_name", "kind": "function", "doc": "<p>Return descriptive handler name.</p>\n\n<h6 id=\"returns\">Returns:</h6>\n\n<blockquote>\n  <p>str: \"Molecular (Translation + Rotation)\" to identify this handler.</p>\n</blockquote>\n", "signature": "<span class=\"signature pdoc-code condensed\">(<span class=\"param\"><span class=\"bp\">self</span></span><span class=\"return-annotation\">) -> <span class=\"nb\">str</span>:</span></span>", "funcdef": "def"}, {"fullname": "dftscape.core.SymmetryRegistry", "modulename": "dftscape.core", "qualname": "SymmetryRegistry", "kind": "class", "doc": "<p>Registry for symmetry handler classes.</p>\n\n<p>This registry extends BaseRegistry to provide type-safe creation of symmetry\nhandlers. It manages the registration and instantiation of different symmetry\nconstraint implementations, allowing DFTScape to support various molecular\nsymmetry requirements.</p>\n\n<p>The registry provides:</p>\n\n<ul>\n<li><strong>Type Safety</strong>: Generic type support for SymmetryHandler protocol</li>\n<li><strong>Factory Methods</strong>: Convenient creation with automatic type casting</li>\n<li><strong>Plugin Support</strong>: Easy registration of custom symmetry handlers</li>\n<li><strong>Discovery</strong>: List available symmetry constraint options</li>\n</ul>\n\n<h6 id=\"registered-handlers\">Registered Handlers:</h6>\n\n<blockquote>\n  <ul>\n  <li>\"none\": NoSymmetryHandler - unconstrained optimization</li>\n  <li>\"molecular\": MolecularSymmetryHandler - standard molecular symmetry</li>\n  </ul>\n</blockquote>\n\n<h6 id=\"class-methods\">Class Methods:</h6>\n\n<blockquote>\n  <p>create: Type-safe factory method for symmetry handler instantiation\n  register: Decorator for registering new symmetry handler classes\n  get: Retrieve symmetry handler class by name\n  list_available: Get list of available symmetry handler names</p>\n</blockquote>\n\n<h6 id=\"usage-examples\">Usage Examples:</h6>\n\n<blockquote>\n  <div class=\"pdoc-code codehilite\">\n<pre><span></span><code><span class=\"gp\">&gt;&gt;&gt; </span><span class=\"kn\">from</span><span class=\"w\"> </span><span class=\"nn\">dftscape.core.symmetry_handlers</span><span class=\"w\"> </span><span class=\"kn\">import</span> <span class=\"n\">SymmetryRegistry</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Create molecular symmetry handler</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">molecular</span> <span class=\"o\">=</span> <span class=\"n\">SymmetryRegistry</span><span class=\"o\">.</span><span class=\"n\">create</span><span class=\"p\">(</span><span class=\"s2\">&quot;molecular&quot;</span><span class=\"p\">,</span> <span class=\"n\">overlap_threshold</span><span class=\"o\">=</span><span class=\"mf\">0.1</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"sa\">f</span><span class=\"s2\">&quot;Handler: </span><span class=\"si\">{</span><span class=\"n\">molecular</span><span class=\"o\">.</span><span class=\"n\">get_name</span><span class=\"p\">()</span><span class=\"si\">}</span><span class=\"s2\">&quot;</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Create unconstrained handler</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">unconstrained</span> <span class=\"o\">=</span> <span class=\"n\">SymmetryRegistry</span><span class=\"o\">.</span><span class=\"n\">create</span><span class=\"p\">(</span><span class=\"s2\">&quot;none&quot;</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># List available handlers</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">available</span> <span class=\"o\">=</span> <span class=\"n\">SymmetryRegistry</span><span class=\"o\">.</span><span class=\"n\">list_available</span><span class=\"p\">()</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"sa\">f</span><span class=\"s2\">&quot;Available: </span><span class=\"si\">{</span><span class=\"n\">available</span><span class=\"si\">}</span><span class=\"s2\">&quot;</span><span class=\"p\">)</span>\n</code></pre>\n  </div>\n</blockquote>\n\n<h6 id=\"integration-notes\">Integration Notes:</h6>\n\n<blockquote>\n  <ul>\n  <li>Used by SubspaceHandler for constraint integration</li>\n  <li>Supports SaddlePointOptimizer symmetry requirements</li>\n  <li>Enables plugin architecture for custom constraints</li>\n  <li>Provides type-safe interface to symmetry implementations</li>\n  </ul>\n</blockquote>\n\n<h6 id=\"implementation-details\">Implementation Details:</h6>\n\n<blockquote>\n  <ul>\n  <li>Extends BaseRegistry with SymmetryHandler type parameter</li>\n  <li>Uses cast() for type-safe instantiation</li>\n  <li>Maintains per-subclass registry isolation</li>\n  <li>Thread-safe registration and lookup operations</li>\n  </ul>\n</blockquote>\n", "bases": "typing.Generic[~T]"}, {"fullname": "dftscape.core.SymmetryRegistry.create", "modulename": "dftscape.core", "qualname": "SymmetryRegistry.create", "kind": "function", "doc": "<p>Create an instance of a symmetry handler by name.</p>\n\n<p>This factory method provides type-safe creation of symmetry handlers,\nautomatically casting the result to the SymmetryHandler protocol type.\nIt's the recommended way to instantiate symmetry handlers in DFTScape.</p>\n\n<h6 id=\"arguments\">Arguments:</h6>\n\n<ul>\n<li><strong>name (str):</strong>  Name of the symmetry handler to create. Must be registered\nin the registry (e.g., \"molecular\", \"none\").</li>\n<li><strong>*args:</strong>  Positional arguments to pass to the handler constructor.</li>\n<li><strong>**kwargs:</strong>  Keyword arguments to pass to the handler constructor.</li>\n</ul>\n\n<h6 id=\"returns\">Returns:</h6>\n\n<blockquote>\n  <p>SymmetryHandler: A new instance of the requested symmetry handler,\n      properly typed as a SymmetryHandler protocol implementation.</p>\n</blockquote>\n\n<h6 id=\"raises\">Raises:</h6>\n\n<ul>\n<li><strong>ValueError:</strong>  If the handler name is not found in the registry.\nThe error message includes all available handler names.</li>\n<li><strong>TypeError:</strong>  If the handler constructor arguments are invalid.</li>\n</ul>\n\n<h6 id=\"examples\">Examples:</h6>\n\n<blockquote>\n  <div class=\"pdoc-code codehilite\">\n<pre><span></span><code><span class=\"gp\">&gt;&gt;&gt; </span><span class=\"kn\">from</span><span class=\"w\"> </span><span class=\"nn\">dftscape.core.symmetry_handlers</span><span class=\"w\"> </span><span class=\"kn\">import</span> <span class=\"n\">SymmetryRegistry</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Create molecular symmetry with custom threshold</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">molecular</span> <span class=\"o\">=</span> <span class=\"n\">SymmetryRegistry</span><span class=\"o\">.</span><span class=\"n\">create</span><span class=\"p\">(</span>\n<span class=\"gp\">... </span>    <span class=\"s2\">&quot;molecular&quot;</span><span class=\"p\">,</span>\n<span class=\"gp\">... </span>    <span class=\"n\">overlap_threshold</span><span class=\"o\">=</span><span class=\"mf\">0.05</span>\n<span class=\"gp\">... </span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Create unconstrained handler</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">unconstrained</span> <span class=\"o\">=</span> <span class=\"n\">SymmetryRegistry</span><span class=\"o\">.</span><span class=\"n\">create</span><span class=\"p\">(</span><span class=\"s2\">&quot;none&quot;</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Error handling</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"k\">try</span><span class=\"p\">:</span>\n<span class=\"gp\">... </span>    <span class=\"n\">unknown</span> <span class=\"o\">=</span> <span class=\"n\">SymmetryRegistry</span><span class=\"o\">.</span><span class=\"n\">create</span><span class=\"p\">(</span><span class=\"s2\">&quot;custom&quot;</span><span class=\"p\">)</span>\n<span class=\"gp\">... </span><span class=\"k\">except</span> <span class=\"ne\">ValueError</span> <span class=\"k\">as</span> <span class=\"n\">e</span><span class=\"p\">:</span>\n<span class=\"gp\">... </span>    <span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"sa\">f</span><span class=\"s2\">&quot;Error: </span><span class=\"si\">{</span><span class=\"n\">e</span><span class=\"si\">}</span><span class=\"s2\">&quot;</span><span class=\"p\">)</span>\n<span class=\"gp\">... </span>    <span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"sa\">f</span><span class=\"s2\">&quot;Available: </span><span class=\"si\">{</span><span class=\"n\">SymmetryRegistry</span><span class=\"o\">.</span><span class=\"n\">list_available</span><span class=\"p\">()</span><span class=\"si\">}</span><span class=\"s2\">&quot;</span><span class=\"p\">)</span>\n</code></pre>\n  </div>\n</blockquote>\n\n<h6 id=\"notes\">Notes:</h6>\n\n<blockquote>\n  <ul>\n  <li>Uses cast() for type safety with Protocol types</li>\n  <li>Arguments are passed directly to handler constructors</li>\n  <li>Recommended over direct class instantiation</li>\n  <li>Enables dependency injection patterns</li>\n  </ul>\n</blockquote>\n", "signature": "<span class=\"signature pdoc-code multiline\">(<span class=\"param\">\t<span class=\"bp\">cls</span>,</span><span class=\"param\">\t<span class=\"n\">name</span><span class=\"p\">:</span> <span class=\"nb\">str</span>,</span><span class=\"param\">\t<span class=\"o\">*</span><span class=\"n\">args</span>,</span><span class=\"param\">\t<span class=\"o\">**</span><span class=\"n\">kwargs</span></span><span class=\"return-annotation\">) -> <span class=\"n\">dftscape</span><span class=\"o\">.</span><span class=\"n\">core</span><span class=\"o\">.</span><span class=\"n\">symmetry_handlers</span><span class=\"o\">.</span><span class=\"n\">SymmetryHandler</span>:</span></span>", "funcdef": "def"}, {"fullname": "dftscape.core.ScipyLOBPCGEigensolver", "modulename": "dftscape.core", "qualname": "ScipyLOBPCGEigensolver", "kind": "class", "doc": "<p>LOBPCG eigensolver using scipy's implementation with finite-difference HVPs.</p>\n\n<p>This eigensolver uses the Locally Optimal Block Preconditioned Conjugate\nGradient algorithm implemented in scipy.sparse.linalg.lobpcg. It computes\nHessian eigenpairs using finite-difference approximations of Hessian-vector\nproducts, making it suitable for large systems where storing the full\nHessian matrix is impractical.</p>\n\n<h2 id=\"key-features\">Key Features</h2>\n\n<ul>\n<li><strong>Memory Efficient</strong>: Uses finite-difference HVPs instead of full Hessian</li>\n<li><strong>Iterative</strong>: Converges iteratively with configurable tolerance and max iterations</li>\n<li><strong>Warm Starts</strong>: Supports initial subspace for faster convergence</li>\n<li><strong>Constraint Handling</strong>: Can orthogonalize against constraint subspaces</li>\n<li><strong>Robust</strong>: Handles constraint matrix limitations gracefully</li>\n</ul>\n\n<h2 id=\"algorithm-details\">Algorithm Details</h2>\n\n<p>The LOBPCG algorithm minimizes the Rayleigh quotient iteratively:</p>\n\n<ul>\n<li>Uses block conjugate gradient method</li>\n<li>Employs preconditioning for faster convergence</li>\n<li>Supports multiple eigenvector computation simultaneously</li>\n<li>Uses finite-difference Hessian-vector products</li>\n</ul>\n\n<h2 id=\"usage-examples\">Usage Examples</h2>\n\n<div class=\"pdoc-code codehilite\">\n<pre><span></span><code><span class=\"n\">solver</span> <span class=\"o\">=</span> <span class=\"n\">ScipyLOBPCGEigensolver</span><span class=\"p\">(</span>\n    <span class=\"n\">backend</span><span class=\"o\">=</span><span class=\"n\">backend</span><span class=\"p\">,</span>\n    <span class=\"n\">k</span><span class=\"o\">=</span><span class=\"mi\">5</span><span class=\"p\">,</span>\n    <span class=\"n\">tol</span><span class=\"o\">=</span><span class=\"mf\">1e-6</span><span class=\"p\">,</span>\n    <span class=\"n\">maxiter</span><span class=\"o\">=</span><span class=\"mi\">100</span><span class=\"p\">,</span>\n    <span class=\"n\">fd_eps</span><span class=\"o\">=</span><span class=\"mf\">1e-4</span>\n<span class=\"p\">)</span>\n<span class=\"n\">eigenvalues</span><span class=\"p\">,</span> <span class=\"n\">eigenvectors</span> <span class=\"o\">=</span> <span class=\"n\">solver</span><span class=\"o\">.</span><span class=\"n\">solve</span><span class=\"p\">(</span><span class=\"n\">state</span><span class=\"p\">,</span> <span class=\"n\">X0</span><span class=\"o\">=</span><span class=\"n\">initial_guess</span><span class=\"p\">)</span>\n</code></pre>\n</div>\n\n<h2 id=\"when-to-use\">When to Use</h2>\n\n<ul>\n<li>Large systems (n &gt; 1000 dimensions)</li>\n<li>When memory constraints prevent storing full Hessian</li>\n<li>When you need iterative solving with warm-starts</li>\n<li>For systems where finite-difference HVPs are acceptable</li>\n</ul>\n\n<h2 id=\"performance-notes\">Performance Notes</h2>\n\n<ul>\n<li>For small systems, consider EigshEigensolver for better performance</li>\n<li>Finite-difference step size (fd_eps) affects accuracy vs. stability tradeoff</li>\n<li>Warm starts significantly improve convergence speed</li>\n</ul>\n", "bases": "dftscape.core.eigensolvers.Eigensolver"}, {"fullname": "dftscape.core.ScipyLOBPCGEigensolver.__init__", "modulename": "dftscape.core", "qualname": "ScipyLOBPCGEigensolver.__init__", "kind": "function", "doc": "<p></p>\n", "signature": "<span class=\"signature pdoc-code multiline\">(<span class=\"param\">\t<span class=\"n\">backend</span><span class=\"p\">:</span> <span class=\"n\">dftscape</span><span class=\"o\">.</span><span class=\"n\">core</span><span class=\"o\">.</span><span class=\"n\">interfaces</span><span class=\"o\">.</span><span class=\"n\">Backend</span>,</span><span class=\"param\">\t<span class=\"n\">k</span><span class=\"p\">:</span> <span class=\"nb\">int</span>,</span><span class=\"param\">\t<span class=\"n\">tol</span><span class=\"p\">:</span> <span class=\"nb\">float</span> <span class=\"o\">=</span> <span class=\"mf\">0.001</span>,</span><span class=\"param\">\t<span class=\"n\">maxiter</span><span class=\"p\">:</span> <span class=\"nb\">int</span> <span class=\"o\">=</span> <span class=\"mi\">10</span>,</span><span class=\"param\">\t<span class=\"n\">largest</span><span class=\"p\">:</span> <span class=\"nb\">bool</span> <span class=\"o\">=</span> <span class=\"kc\">False</span>,</span><span class=\"param\">\t<span class=\"n\">fd_eps</span><span class=\"p\">:</span> <span class=\"nb\">float</span> <span class=\"o\">=</span> <span class=\"mf\">0.0001</span>,</span><span class=\"param\">\t<span class=\"n\">random_state</span><span class=\"p\">:</span> <span class=\"n\">Optional</span><span class=\"p\">[</span><span class=\"nb\">int</span><span class=\"p\">]</span> <span class=\"o\">=</span> <span class=\"mi\">42</span></span>)</span>"}, {"fullname": "dftscape.core.ScipyLOBPCGEigensolver.fd_eps", "modulename": "dftscape.core", "qualname": "ScipyLOBPCGEigensolver.fd_eps", "kind": "variable", "doc": "<p></p>\n", "annotation": ": float", "default_value": "0.0001"}, {"fullname": "dftscape.core.ScipyLOBPCGEigensolver.random_state", "modulename": "dftscape.core", "qualname": "ScipyLOBPCGEigensolver.random_state", "kind": "variable", "doc": "<p></p>\n", "annotation": ": Optional[int]", "default_value": "42"}, {"fullname": "dftscape.core.ScipyLOBPCGEigensolver.solve", "modulename": "dftscape.core", "qualname": "ScipyLOBPCGEigensolver.solve", "kind": "function", "doc": "<p>Compute k eigenpairs using scipy's LOBPCG with finite-difference HVPs.</p>\n\n<p>Uses the Locally Optimal Block Preconditioned Conjugate Gradient algorithm\nto find the k smallest or largest eigenpairs of the Hessian matrix.\nHessian-vector products are computed using centered finite differences.</p>\n\n<h6 id=\"arguments\">Arguments:</h6>\n\n<ul>\n<li><strong>state:</strong>  Current molecular state, shape (n,)</li>\n<li><strong>X0:</strong>  Optional initial subspace for warm start, shape (n, k).\nIf None, uses cached eigenvectors or random initialization</li>\n<li><strong>Y:</strong>  Optional constraint matrix, shape (n, m). Eigenvectors will be\northogonal to the columns of Y</li>\n</ul>\n\n<h6 id=\"returns\">Returns:</h6>\n\n<blockquote>\n  <p>Tuple of (eigenvalues, eigenvectors):</p>\n  \n  <ul>\n  <li>eigenvalues: Array of k eigenvalues</li>\n  <li>eigenvectors: Array of shape (n, k) with orthonormal columns</li>\n  </ul>\n</blockquote>\n\n<h6 id=\"raises\">Raises:</h6>\n\n<ul>\n<li><strong>ValueError:</strong>  If input dimensions are incompatible</li>\n<li><strong>RuntimeError:</strong>  If LOBPCG fails to converge within maxiter</li>\n</ul>\n\n<h6 id=\"note\">Note:</h6>\n\n<blockquote>\n  <p>If scipy's LOBPCG doesn't support constraints, falls back to manual\n  orthogonalization against the constraint subspace.</p>\n</blockquote>\n", "signature": "<span class=\"signature pdoc-code multiline\">(<span class=\"param\">\t<span class=\"bp\">self</span>,</span><span class=\"param\">\t<span class=\"n\">state</span><span class=\"p\">:</span> <span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span>,</span><span class=\"param\">\t<span class=\"n\">X0</span><span class=\"p\">:</span> <span class=\"n\">Optional</span><span class=\"p\">[</span><span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span><span class=\"p\">]</span> <span class=\"o\">=</span> <span class=\"kc\">None</span>,</span><span class=\"param\">\t<span class=\"n\">Y</span><span class=\"p\">:</span> <span class=\"n\">Optional</span><span class=\"p\">[</span><span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span><span class=\"p\">]</span> <span class=\"o\">=</span> <span class=\"kc\">None</span></span><span class=\"return-annotation\">) -> <span class=\"n\">Tuple</span><span class=\"p\">[</span><span class=\"n\">Optional</span><span class=\"p\">[</span><span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span><span class=\"p\">],</span> <span class=\"n\">Optional</span><span class=\"p\">[</span><span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span><span class=\"p\">]]</span>:</span></span>", "funcdef": "def"}, {"fullname": "dftscape.core.EigshEigensolver", "modulename": "dftscape.core", "qualname": "EigshEigensolver", "kind": "class", "doc": "<p>Eigensolver optimized for medium systems using scipy.sparse.linalg.eigsh.</p>\n\n<p>This eigensolver uses the sparse eigensolver eigsh from scipy to compute\neigenpairs of the full Hessian matrix obtained from backend.compute_hessian().\nIt provides better accuracy and stability than finite-difference methods\nfor systems where computing the full Hessian is feasible.</p>\n\n<h2 id=\"key-features\">Key Features</h2>\n\n<ul>\n<li><strong>Direct Method</strong>: Uses full Hessian matrix for maximum accuracy</li>\n<li><strong>Sparse Optimized</strong>: Designed for sparse or medium-sized dense matrices</li>\n<li><strong>Robust Fallback</strong>: Falls back to dense eigendecomposition if eigsh fails</li>\n<li><strong>Constraint Handling</strong>: Projects Hessian onto constraint orthogonal complement</li>\n</ul>\n\n<h2 id=\"algorithm-details\">Algorithm Details</h2>\n\n<p>The eigsh algorithm:</p>\n\n<ul>\n<li>Uses Arnoldi/Lanczos iteration method</li>\n<li>Supports shift-invert mode for better convergence</li>\n<li>Can find eigenvalues from both ends of spectrum</li>\n<li>Handles both sparse and dense matrices</li>\n</ul>\n\n<h2 id=\"usage-examples\">Usage Examples</h2>\n\n<div class=\"pdoc-code codehilite\">\n<pre><span></span><code><span class=\"n\">solver</span> <span class=\"o\">=</span> <span class=\"n\">EigshEigensolver</span><span class=\"p\">(</span><span class=\"n\">backend</span><span class=\"o\">=</span><span class=\"n\">backend</span><span class=\"p\">,</span> <span class=\"n\">k</span><span class=\"o\">=</span><span class=\"mi\">5</span><span class=\"p\">,</span> <span class=\"n\">tol</span><span class=\"o\">=</span><span class=\"mf\">1e-8</span><span class=\"p\">)</span>\n<span class=\"n\">eigenvalues</span><span class=\"p\">,</span> <span class=\"n\">eigenvectors</span> <span class=\"o\">=</span> <span class=\"n\">solver</span><span class=\"o\">.</span><span class=\"n\">solve</span><span class=\"p\">(</span><span class=\"n\">state</span><span class=\"p\">)</span>\n</code></pre>\n</div>\n\n<h2 id=\"when-to-use\">When to Use</h2>\n\n<ul>\n<li>Medium systems (100 &lt; n &lt; 1000 dimensions)</li>\n<li>When you need high accuracy eigenvalues</li>\n<li>When backend.compute_hessian() is available and accurate</li>\n<li>When you want faster convergence than LOBPCG</li>\n</ul>\n\n<h2 id=\"performance-characteristics\">Performance Characteristics</h2>\n\n<ul>\n<li>More accurate than finite-difference methods</li>\n<li>Faster convergence than iterative methods for medium systems</li>\n<li>Memory usage scales with O(n\u00b2) for dense Hessian</li>\n<li>Best performance when Hessian has exploitable structure</li>\n</ul>\n\n<h2 id=\"comparison-with-other-solvers\">Comparison with Other Solvers</h2>\n\n<ul>\n<li><strong>vs LOBPCG</strong>: More accurate but uses more memory</li>\n<li><strong>vs Eigh</strong>: Handles larger systems but may be less accurate</li>\n<li><strong>vs Manual LOBPCG</strong>: More robust but potentially slower</li>\n</ul>\n", "bases": "dftscape.core.eigensolvers.Eigensolver"}, {"fullname": "dftscape.core.EigshEigensolver.__init__", "modulename": "dftscape.core", "qualname": "EigshEigensolver.__init__", "kind": "function", "doc": "<p></p>\n", "signature": "<span class=\"signature pdoc-code multiline\">(<span class=\"param\">\t<span class=\"n\">backend</span><span class=\"p\">:</span> <span class=\"n\">dftscape</span><span class=\"o\">.</span><span class=\"n\">core</span><span class=\"o\">.</span><span class=\"n\">interfaces</span><span class=\"o\">.</span><span class=\"n\">Backend</span>,</span><span class=\"param\">\t<span class=\"n\">k</span><span class=\"p\">:</span> <span class=\"nb\">int</span>,</span><span class=\"param\">\t<span class=\"n\">tol</span><span class=\"p\">:</span> <span class=\"nb\">float</span> <span class=\"o\">=</span> <span class=\"mf\">0.001</span>,</span><span class=\"param\">\t<span class=\"n\">maxiter</span><span class=\"p\">:</span> <span class=\"nb\">int</span> <span class=\"o\">=</span> <span class=\"mi\">10</span>,</span><span class=\"param\">\t<span class=\"n\">largest</span><span class=\"p\">:</span> <span class=\"nb\">bool</span> <span class=\"o\">=</span> <span class=\"kc\">False</span></span>)</span>"}, {"fullname": "dftscape.core.EigshEigensolver.solve", "modulename": "dftscape.core", "qualname": "EigshEigensolver.solve", "kind": "function", "doc": "<p>Compute k eigenpairs using eigsh on the full Hessian matrix.</p>\n\n<p>Uses scipy.sparse.linalg.eigsh to find the k smallest or largest\neigenpairs of the Hessian matrix computed directly from the backend.</p>\n\n<h6 id=\"arguments\">Arguments:</h6>\n\n<ul>\n<li><strong>state:</strong>  Current molecular state, shape (n,)</li>\n<li><strong>X0:</strong>  Ignored by this implementation (not used by eigsh)</li>\n<li><strong>Y:</strong>  Optional constraint matrix, shape (n, m). If provided,\nthe Hessian is projected onto the orthogonal complement of Y</li>\n</ul>\n\n<h6 id=\"returns\">Returns:</h6>\n\n<blockquote>\n  <p>Tuple of (eigenvalues, eigenvectors):</p>\n  \n  <ul>\n  <li>eigenvalues: Array of k eigenvalues</li>\n  <li>eigenvectors: Array of shape (n, k) with orthonormal columns</li>\n  </ul>\n</blockquote>\n\n<h6 id=\"raises\">Raises:</h6>\n\n<ul>\n<li><strong>ValueError:</strong>  If input dimensions are incompatible</li>\n<li><strong>RuntimeError:</strong>  If eigsh fails and dense fallback also fails</li>\n</ul>\n\n<h6 id=\"note\">Note:</h6>\n\n<blockquote>\n  <p>Constraints are handled by projecting the Hessian matrix onto\n  the orthogonal complement, ensuring exact constraint satisfaction.</p>\n</blockquote>\n", "signature": "<span class=\"signature pdoc-code multiline\">(<span class=\"param\">\t<span class=\"bp\">self</span>,</span><span class=\"param\">\t<span class=\"n\">state</span><span class=\"p\">:</span> <span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span>,</span><span class=\"param\">\t<span class=\"n\">X0</span><span class=\"p\">:</span> <span class=\"n\">Optional</span><span class=\"p\">[</span><span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span><span class=\"p\">]</span> <span class=\"o\">=</span> <span class=\"kc\">None</span>,</span><span class=\"param\">\t<span class=\"n\">Y</span><span class=\"p\">:</span> <span class=\"n\">Optional</span><span class=\"p\">[</span><span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span><span class=\"p\">]</span> <span class=\"o\">=</span> <span class=\"kc\">None</span></span><span class=\"return-annotation\">) -> <span class=\"n\">Tuple</span><span class=\"p\">[</span><span class=\"n\">Optional</span><span class=\"p\">[</span><span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span><span class=\"p\">],</span> <span class=\"n\">Optional</span><span class=\"p\">[</span><span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span><span class=\"p\">]]</span>:</span></span>", "funcdef": "def"}, {"fullname": "dftscape.core.EighEigensolver", "modulename": "dftscape.core", "qualname": "EighEigensolver", "kind": "class", "doc": "<p>Eigensolver optimized for small systems using numpy.linalg.eigh.</p>\n\n<p>This eigensolver uses numpy's dense Hermitian eigensolver to compute all\neigenpairs of the Hessian matrix with maximum accuracy. It computes the\nfull eigenvalue decomposition, making it ideal for small systems where\nnumerical precision is critical.</p>\n\n<h2 id=\"key-features\">Key Features</h2>\n\n<ul>\n<li><strong>Maximum Accuracy</strong>: Uses exact dense eigensolver for perfect accuracy</li>\n<li><strong>All Eigenpairs</strong>: Computes all eigenvalues/vectors, then selects k</li>\n<li><strong>Hermitian Optimized</strong>: Specialized for symmetric/Hermitian matrices</li>\n<li><strong>Robust</strong>: No iterative approximations or convergence issues</li>\n</ul>\n\n<h2 id=\"algorithm-details\">Algorithm Details</h2>\n\n<p>Uses numpy.linalg.eigh which:</p>\n\n<ul>\n<li>Employs LAPACK's DSYEV/DZHEV routines</li>\n<li>Guarantees accuracy up to machine precision</li>\n<li>Handles both real symmetric and complex Hermitian matrices</li>\n<li>Returns eigenvalues in ascending order</li>\n</ul>\n\n<h2 id=\"usage-examples\">Usage Examples</h2>\n\n<div class=\"pdoc-code codehilite\">\n<pre><span></span><code><span class=\"n\">solver</span> <span class=\"o\">=</span> <span class=\"n\">EighEigensolver</span><span class=\"p\">(</span><span class=\"n\">backend</span><span class=\"o\">=</span><span class=\"n\">backend</span><span class=\"p\">,</span> <span class=\"n\">k</span><span class=\"o\">=</span><span class=\"mi\">3</span><span class=\"p\">,</span> <span class=\"n\">largest</span><span class=\"o\">=</span><span class=\"kc\">False</span><span class=\"p\">)</span>\n<span class=\"n\">eigenvalues</span><span class=\"p\">,</span> <span class=\"n\">eigenvectors</span> <span class=\"o\">=</span> <span class=\"n\">solver</span><span class=\"o\">.</span><span class=\"n\">solve</span><span class=\"p\">(</span><span class=\"n\">state</span><span class=\"p\">)</span>\n</code></pre>\n</div>\n\n<h2 id=\"when-to-use\">When to Use</h2>\n\n<ul>\n<li>Very small systems (n &lt; 100 dimensions)</li>\n<li>When you need maximum accuracy and precision</li>\n<li>When backend.compute_hessian() is available and accurate</li>\n<li>When you want exact eigenvalues (not iterative approximations)</li>\n</ul>\n\n<h2 id=\"performance-characteristics\">Performance Characteristics</h2>\n\n<ul>\n<li>Most accurate but slowest for larger systems</li>\n<li>Memory usage scales with O(n\u00b2)</li>\n<li>Computation time scales with O(n\u00b3)</li>\n<li>Best for n &lt; 100, becomes impractical for larger systems</li>\n</ul>\n\n<h2 id=\"comparison-with-other-solvers\">Comparison with Other Solvers</h2>\n\n<ul>\n<li><strong>vs Eigsh</strong>: More accurate but slower and uses more memory</li>\n<li><strong>vs LOBPCG</strong>: Exact vs. iterative, better for small systems</li>\n<li><strong>vs Manual LOBPCG</strong>: Deterministic vs. potentially unstable</li>\n</ul>\n", "bases": "dftscape.core.eigensolvers.Eigensolver"}, {"fullname": "dftscape.core.EighEigensolver.__init__", "modulename": "dftscape.core", "qualname": "EighEigensolver.__init__", "kind": "function", "doc": "<p></p>\n", "signature": "<span class=\"signature pdoc-code multiline\">(<span class=\"param\">\t<span class=\"n\">backend</span><span class=\"p\">:</span> <span class=\"n\">dftscape</span><span class=\"o\">.</span><span class=\"n\">core</span><span class=\"o\">.</span><span class=\"n\">interfaces</span><span class=\"o\">.</span><span class=\"n\">Backend</span>,</span><span class=\"param\">\t<span class=\"n\">k</span><span class=\"p\">:</span> <span class=\"nb\">int</span>,</span><span class=\"param\">\t<span class=\"n\">tol</span><span class=\"p\">:</span> <span class=\"nb\">float</span> <span class=\"o\">=</span> <span class=\"mf\">0.001</span>,</span><span class=\"param\">\t<span class=\"n\">maxiter</span><span class=\"p\">:</span> <span class=\"nb\">int</span> <span class=\"o\">=</span> <span class=\"mi\">10</span>,</span><span class=\"param\">\t<span class=\"n\">largest</span><span class=\"p\">:</span> <span class=\"nb\">bool</span> <span class=\"o\">=</span> <span class=\"kc\">False</span></span>)</span>"}, {"fullname": "dftscape.core.EighEigensolver.solve", "modulename": "dftscape.core", "qualname": "EighEigensolver.solve", "kind": "function", "doc": "<p>Compute k eigenpairs using numpy.linalg.eigh on the full Hessian matrix.</p>\n\n<p>Uses the exact dense eigensolver to find all eigenpairs of the Hessian,\nthen selects and returns the k smallest or largest eigenpairs requested.</p>\n\n<h6 id=\"arguments\">Arguments:</h6>\n\n<ul>\n<li><strong>state:</strong>  Current molecular state, shape (n,)</li>\n<li><strong>X0:</strong>  Ignored by this implementation (not used by eigh)</li>\n<li><strong>Y:</strong>  Optional constraint matrix, shape (n, m). If provided,\nthe Hessian is projected onto the orthogonal complement of Y</li>\n</ul>\n\n<h6 id=\"returns\">Returns:</h6>\n\n<blockquote>\n  <p>Tuple of (eigenvalues, eigenvectors):</p>\n  \n  <ul>\n  <li>eigenvalues: Array of k eigenvalues in requested order</li>\n  <li>eigenvectors: Array of shape (n, k) with orthonormal columns</li>\n  </ul>\n</blockquote>\n\n<h6 id=\"raises\">Raises:</h6>\n\n<ul>\n<li><strong>ValueError:</strong>  If input dimensions are incompatible</li>\n<li><strong>RuntimeError:</strong>  If eigh fails (rare for valid symmetric matrices)</li>\n</ul>\n\n<h6 id=\"note\">Note:</h6>\n\n<blockquote>\n  <p>This method computes ALL eigenvalues, so it's only practical for\n  small systems. For larger systems, use iterative methods instead.</p>\n</blockquote>\n", "signature": "<span class=\"signature pdoc-code multiline\">(<span class=\"param\">\t<span class=\"bp\">self</span>,</span><span class=\"param\">\t<span class=\"n\">state</span><span class=\"p\">:</span> <span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span>,</span><span class=\"param\">\t<span class=\"n\">X0</span><span class=\"p\">:</span> <span class=\"n\">Optional</span><span class=\"p\">[</span><span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span><span class=\"p\">]</span> <span class=\"o\">=</span> <span class=\"kc\">None</span>,</span><span class=\"param\">\t<span class=\"n\">Y</span><span class=\"p\">:</span> <span class=\"n\">Optional</span><span class=\"p\">[</span><span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span><span class=\"p\">]</span> <span class=\"o\">=</span> <span class=\"kc\">None</span></span><span class=\"return-annotation\">) -> <span class=\"n\">Tuple</span><span class=\"p\">[</span><span class=\"n\">Optional</span><span class=\"p\">[</span><span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span><span class=\"p\">],</span> <span class=\"n\">Optional</span><span class=\"p\">[</span><span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span><span class=\"p\">]]</span>:</span></span>", "funcdef": "def"}, {"fullname": "dftscape.core.Eigensolver", "modulename": "dftscape.core", "qualname": "Eigensolver", "kind": "class", "doc": "<p>Abstract base class for Hessian eigensolver implementations.</p>\n\n<p>This class defines the common interface and shared functionality for all\neigensolver implementations in DFTScape. It provides a unified API for\ncomputing eigenpairs of the Hessian matrix at a given molecular state.</p>\n\n<h2 id=\"key-features\">Key Features</h2>\n\n<ul>\n<li><strong>Unified Interface</strong>: All concrete eigensolvers implement the <code>solve</code> method</li>\n<li><strong>Warm Starts</strong>: Automatic caching of previous eigenvectors for faster convergence</li>\n<li><strong>Constraint Handling</strong>: Support for orthogonalization against constraint subspaces</li>\n<li><strong>Flexible Configuration</strong>: Configurable tolerance, max iterations, and algorithm parameters</li>\n<li><strong>Numerical Stability</strong>: Robust handling of rank-deficient subspaces and numerical issues</li>\n</ul>\n\n<h2 id=\"parameters\">Parameters</h2>\n\n<ul>\n<li><code>backend</code>: Computational backend for energy/gradient/Hessian calculations</li>\n<li><code>k</code>: Number of eigenpairs to compute (0 for gradient flow mode)</li>\n<li><code>tol</code>: Convergence tolerance for iterative methods</li>\n<li><code>maxiter</code>: Maximum iterations for iterative solvers</li>\n<li><code>largest</code>: Whether to find largest (True) or smallest (False) eigenvalues</li>\n<li><code>logger</code>: Optional logger for debugging and monitoring</li>\n</ul>\n\n<h2 id=\"usage-pattern\">Usage Pattern</h2>\n\n<div class=\"pdoc-code codehilite\">\n<pre><span></span><code><span class=\"c1\"># Subclass implementation</span>\n<span class=\"k\">class</span><span class=\"w\"> </span><span class=\"nc\">MyEigensolver</span><span class=\"p\">(</span><span class=\"n\">Eigensolver</span><span class=\"p\">):</span>\n    <span class=\"k\">def</span><span class=\"w\"> </span><span class=\"nf\">solve</span><span class=\"p\">(</span><span class=\"bp\">self</span><span class=\"p\">,</span> <span class=\"n\">state</span><span class=\"p\">,</span> <span class=\"n\">X0</span><span class=\"o\">=</span><span class=\"kc\">None</span><span class=\"p\">,</span> <span class=\"n\">Y</span><span class=\"o\">=</span><span class=\"kc\">None</span><span class=\"p\">):</span>\n        <span class=\"c1\"># Implementation here</span>\n        <span class=\"k\">pass</span>\n\n<span class=\"c1\"># Usage</span>\n<span class=\"n\">solver</span> <span class=\"o\">=</span> <span class=\"n\">MyEigensolver</span><span class=\"p\">(</span><span class=\"n\">backend</span><span class=\"o\">=</span><span class=\"n\">backend</span><span class=\"p\">,</span> <span class=\"n\">k</span><span class=\"o\">=</span><span class=\"mi\">5</span><span class=\"p\">)</span>\n<span class=\"n\">eigenvalues</span><span class=\"p\">,</span> <span class=\"n\">eigenvectors</span> <span class=\"o\">=</span> <span class=\"n\">solver</span><span class=\"o\">.</span><span class=\"n\">solve</span><span class=\"p\">(</span><span class=\"n\">state</span><span class=\"p\">)</span>\n</code></pre>\n</div>\n\n<h2 id=\"implementation-notes\">Implementation Notes</h2>\n\n<ul>\n<li>Subclasses must implement the abstract <code>solve</code> method</li>\n<li>Finite-difference HVP computation uses centered differences for accuracy</li>\n<li>QR decomposition ensures orthonormal subspaces</li>\n<li>Constraint handling uses projection onto orthogonal complement</li>\n</ul>\n", "bases": "abc.ABC"}, {"fullname": "dftscape.core.Eigensolver.backend", "modulename": "dftscape.core", "qualname": "Eigensolver.backend", "kind": "variable", "doc": "<p></p>\n", "annotation": ": dftscape.core.interfaces.Backend"}, {"fullname": "dftscape.core.Eigensolver.k", "modulename": "dftscape.core", "qualname": "Eigensolver.k", "kind": "variable", "doc": "<p></p>\n", "annotation": ": int"}, {"fullname": "dftscape.core.Eigensolver.tol", "modulename": "dftscape.core", "qualname": "Eigensolver.tol", "kind": "variable", "doc": "<p></p>\n", "annotation": ": float", "default_value": "0.001"}, {"fullname": "dftscape.core.Eigensolver.maxiter", "modulename": "dftscape.core", "qualname": "Eigensolver.maxiter", "kind": "variable", "doc": "<p></p>\n", "annotation": ": int", "default_value": "10"}, {"fullname": "dftscape.core.Eigensolver.largest", "modulename": "dftscape.core", "qualname": "Eigensolver.largest", "kind": "variable", "doc": "<p></p>\n", "annotation": ": bool", "default_value": "False"}, {"fullname": "dftscape.core.Eigensolver.logger", "modulename": "dftscape.core", "qualname": "Eigensolver.logger", "kind": "variable", "doc": "<p></p>\n", "annotation": ": Optional[logging.Logger]", "default_value": "None"}, {"fullname": "dftscape.core.Eigensolver.solve", "modulename": "dftscape.core", "qualname": "Eigensolver.solve", "kind": "function", "doc": "<p>Compute k eigenpairs of the Hessian matrix at the given state.</p>\n\n<p>This is the main method that all eigensolver implementations must provide.\nIt computes the k smallest or largest eigenpairs of the Hessian matrix\nevaluated at the specified molecular state.</p>\n\n<h6 id=\"arguments\">Arguments:</h6>\n\n<ul>\n<li><strong>state:</strong>  Current molecular state as a 1D array of shape (n,)\nwhere n is the number of degrees of freedom</li>\n<li><strong>X0:</strong>  Optional initial subspace for warm starts, shape (n, k).\nIf None, uses cached previous eigenvectors or random initialization</li>\n<li><strong>Y:</strong>  Optional constraint matrix, shape (n, m) where eigenvectors\nwill be orthogonal to the columns of Y</li>\n</ul>\n\n<h6 id=\"returns\">Returns:</h6>\n\n<blockquote>\n  <p>Tuple of (eigenvalues, eigenvectors):</p>\n  \n  <ul>\n  <li>eigenvalues: 1D array of k eigenvalues, or None if k=0</li>\n  <li>eigenvectors: 2D array of shape (n, k) with orthonormal columns,\n  or None if k=0</li>\n  </ul>\n</blockquote>\n\n<h6 id=\"raises\">Raises:</h6>\n\n<ul>\n<li><strong>NotImplementedError:</strong>  Must be implemented by subclasses</li>\n<li><strong>ValueError:</strong>  If input dimensions are incompatible</li>\n<li><strong>RuntimeError:</strong>  If the eigensolver fails to converge</li>\n</ul>\n\n<h6 id=\"note\">Note:</h6>\n\n<blockquote>\n  <p>When k=0, returns (None, None) indicating gradient flow mode\n  where only the gradient direction is needed.</p>\n</blockquote>\n", "signature": "<span class=\"signature pdoc-code multiline\">(<span class=\"param\">\t<span class=\"bp\">self</span>,</span><span class=\"param\">\t<span class=\"n\">state</span><span class=\"p\">:</span> <span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span>,</span><span class=\"param\">\t<span class=\"n\">X0</span><span class=\"p\">:</span> <span class=\"n\">Optional</span><span class=\"p\">[</span><span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span><span class=\"p\">]</span> <span class=\"o\">=</span> <span class=\"kc\">None</span>,</span><span class=\"param\">\t<span class=\"n\">Y</span><span class=\"p\">:</span> <span class=\"n\">Optional</span><span class=\"p\">[</span><span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span><span class=\"p\">]</span> <span class=\"o\">=</span> <span class=\"kc\">None</span></span><span class=\"return-annotation\">) -> <span class=\"n\">Tuple</span><span class=\"p\">[</span><span class=\"n\">Optional</span><span class=\"p\">[</span><span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span><span class=\"p\">],</span> <span class=\"n\">Optional</span><span class=\"p\">[</span><span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span><span class=\"p\">]]</span>:</span></span>", "funcdef": "def"}, {"fullname": "dftscape.core.LOBPCGManualEigensolver", "modulename": "dftscape.core", "qualname": "LOBPCGManualEigensolver", "kind": "class", "doc": "<p>Manual implementation of the Locally Optimal Block Preconditioned Conjugate Gradient (LOBPCG) method.</p>\n\n<p>This eigensolver provides a custom implementation of the LOBPCG algorithm,\noffering fine-grained control over the iterative process and convergence\ncriteria. It's designed for systems where the standard scipy implementation\nmay not be optimal or when custom preconditioning strategies are needed.</p>\n\n<h2 id=\"key-features\">Key Features</h2>\n\n<ul>\n<li><strong>Custom Implementation</strong>: Full control over algorithm details</li>\n<li><strong>Flexible Preconditioning</strong>: Support for custom preconditioners</li>\n<li><strong>Adaptive Convergence</strong>: Configurable tolerance and iteration limits</li>\n<li><strong>Memory Efficient</strong>: Matrix-free operations using Hessian-vector products</li>\n<li><strong>Backup Vector Management</strong>: Enhanced stability through backup vectors</li>\n</ul>\n\n<h2 id=\"algorithm-details\">Algorithm Details</h2>\n\n<p>The LOBPCG algorithm iteratively solves for eigenpairs by:</p>\n\n<ol>\n<li>Maintaining a block of trial vectors (X, P, R)</li>\n<li>Computing Rayleigh-Ritz projection onto subspace</li>\n<li>Applying preconditioner to residual vectors</li>\n<li>Orthogonalizing against constraints and previous vectors</li>\n<li>Updating search directions using conjugate gradient approach</li>\n</ol>\n\n<h2 id=\"usage-examples\">Usage Examples</h2>\n\n<div class=\"pdoc-code codehilite\">\n<pre><span></span><code><span class=\"n\">solver</span> <span class=\"o\">=</span> <span class=\"n\">LOBPCGManualEigensolver</span><span class=\"p\">(</span>\n    <span class=\"n\">backend</span><span class=\"o\">=</span><span class=\"n\">backend</span><span class=\"p\">,</span>\n    <span class=\"n\">k</span><span class=\"o\">=</span><span class=\"mi\">3</span><span class=\"p\">,</span>\n    <span class=\"n\">largest</span><span class=\"o\">=</span><span class=\"kc\">False</span><span class=\"p\">,</span>\n    <span class=\"n\">max_iter</span><span class=\"o\">=</span><span class=\"mi\">100</span><span class=\"p\">,</span>\n    <span class=\"n\">tol</span><span class=\"o\">=</span><span class=\"mf\">1e-8</span>\n<span class=\"p\">)</span>\n<span class=\"n\">eigenvalues</span><span class=\"p\">,</span> <span class=\"n\">eigenvectors</span> <span class=\"o\">=</span> <span class=\"n\">solver</span><span class=\"o\">.</span><span class=\"n\">solve</span><span class=\"p\">(</span><span class=\"n\">state</span><span class=\"p\">)</span>\n</code></pre>\n</div>\n\n<h2 id=\"when-to-use\">When to Use</h2>\n\n<ul>\n<li>When you need custom preconditioning strategies</li>\n<li>When scipy's LOBPCG implementation has convergence issues</li>\n<li>When you want to experiment with algorithm variations</li>\n<li>When you need detailed control over convergence criteria</li>\n</ul>\n\n<h2 id=\"performance-characteristics\">Performance Characteristics</h2>\n\n<ul>\n<li>Memory usage: O(n * block_size)</li>\n<li>Computation: O(iterations * n * block_size\u00b2) per iteration</li>\n<li>Convergence: Typically faster than power methods, slower than scipy's optimized LOBPCG</li>\n<li>Stability: More robust to preconditioner quality than simple iterative methods</li>\n</ul>\n\n<h2 id=\"comparison-with-other-solvers\">Comparison with Other Solvers</h2>\n\n<ul>\n<li><strong>vs ScipyLOBPCG</strong>: More flexible but potentially slower</li>\n<li><strong>vs Eigsh</strong>: Better for multiple eigenpairs, similar performance</li>\n<li><strong>vs Eigh</strong>: Iterative vs exact, better for larger systems</li>\n</ul>\n", "bases": "dftscape.core.eigensolvers.Eigensolver"}, {"fullname": "dftscape.core.LOBPCGManualEigensolver.__init__", "modulename": "dftscape.core", "qualname": "LOBPCGManualEigensolver.__init__", "kind": "function", "doc": "<p></p>\n", "signature": "<span class=\"signature pdoc-code multiline\">(<span class=\"param\">\t<span class=\"n\">backend</span><span class=\"p\">:</span> <span class=\"n\">dftscape</span><span class=\"o\">.</span><span class=\"n\">core</span><span class=\"o\">.</span><span class=\"n\">interfaces</span><span class=\"o\">.</span><span class=\"n\">Backend</span>,</span><span class=\"param\">\t<span class=\"n\">k</span><span class=\"p\">:</span> <span class=\"nb\">int</span>,</span><span class=\"param\">\t<span class=\"n\">tol</span><span class=\"p\">:</span> <span class=\"nb\">float</span> <span class=\"o\">=</span> <span class=\"mf\">0.001</span>,</span><span class=\"param\">\t<span class=\"n\">maxiter</span><span class=\"p\">:</span> <span class=\"nb\">int</span> <span class=\"o\">=</span> <span class=\"mi\">10</span>,</span><span class=\"param\">\t<span class=\"n\">largest</span><span class=\"p\">:</span> <span class=\"nb\">bool</span> <span class=\"o\">=</span> <span class=\"kc\">False</span>,</span><span class=\"param\">\t<span class=\"n\">fd_eps</span><span class=\"p\">:</span> <span class=\"nb\">float</span> <span class=\"o\">=</span> <span class=\"mf\">0.0001</span>,</span><span class=\"param\">\t<span class=\"n\">random_state</span><span class=\"p\">:</span> <span class=\"n\">Optional</span><span class=\"p\">[</span><span class=\"nb\">int</span><span class=\"p\">]</span> <span class=\"o\">=</span> <span class=\"mi\">42</span>,</span><span class=\"param\">\t<span class=\"n\">_reset_interval</span><span class=\"p\">:</span> <span class=\"nb\">int</span> <span class=\"o\">=</span> <span class=\"mi\">10</span></span>)</span>"}, {"fullname": "dftscape.core.LOBPCGManualEigensolver.fd_eps", "modulename": "dftscape.core", "qualname": "LOBPCGManualEigensolver.fd_eps", "kind": "variable", "doc": "<p></p>\n", "annotation": ": float", "default_value": "0.0001"}, {"fullname": "dftscape.core.LOBPCGManualEigensolver.random_state", "modulename": "dftscape.core", "qualname": "LOBPCGManualEigensolver.random_state", "kind": "variable", "doc": "<p></p>\n", "annotation": ": Optional[int]", "default_value": "42"}, {"fullname": "dftscape.core.LOBPCGManualEigensolver.solve", "modulename": "dftscape.core", "qualname": "LOBPCGManualEigensolver.solve", "kind": "function", "doc": "<p>Solve for k eigenpairs using manual LOBPCG implementation.</p>\n\n<p>Implements the Locally Optimal Block Preconditioned Conjugate Gradient\nalgorithm with custom convergence criteria and preconditioning support.</p>\n\n<h6 id=\"arguments\">Arguments:</h6>\n\n<ul>\n<li><strong>state:</strong>  Current molecular state, shape (n,)</li>\n<li><strong>X0:</strong>  Optional initial subspace for warm start, shape (n, k).\nIf None, uses cached previous subspace or random initialization.</li>\n<li><strong>Y:</strong>  Optional constraint matrix, shape (n, m). Eigenvectors will\nbe orthogonal to the columns of Y.</li>\n</ul>\n\n<h6 id=\"returns\">Returns:</h6>\n\n<blockquote>\n  <p>Tuple of (eigenvalues, eigenvectors):</p>\n  \n  <ul>\n  <li>eigenvalues: Array of k eigenvalues in requested order</li>\n  <li>eigenvectors: Array of shape (n, k) with orthonormal columns</li>\n  </ul>\n</blockquote>\n\n<h6 id=\"raises\">Raises:</h6>\n\n<ul>\n<li><strong>ValueError:</strong>  If input dimensions are incompatible</li>\n<li><strong>RuntimeError:</strong>  If LOBPCG fails to converge within maxiter</li>\n</ul>\n\n<h6 id=\"note\">Note:</h6>\n\n<blockquote>\n  <p>This implementation uses a three-term recurrence (X, P, R) and\n  Rayleigh-Ritz projection for optimal convergence properties.\n  Backup vectors are maintained for enhanced numerical stability.</p>\n</blockquote>\n", "signature": "<span class=\"signature pdoc-code multiline\">(<span class=\"param\">\t<span class=\"bp\">self</span>,</span><span class=\"param\">\t<span class=\"n\">state</span><span class=\"p\">:</span> <span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span>,</span><span class=\"param\">\t<span class=\"n\">X0</span><span class=\"p\">:</span> <span class=\"n\">Optional</span><span class=\"p\">[</span><span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span><span class=\"p\">]</span> <span class=\"o\">=</span> <span class=\"kc\">None</span>,</span><span class=\"param\">\t<span class=\"n\">Y</span><span class=\"p\">:</span> <span class=\"n\">Optional</span><span class=\"p\">[</span><span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span><span class=\"p\">]</span> <span class=\"o\">=</span> <span class=\"kc\">None</span></span><span class=\"return-annotation\">) -> <span class=\"n\">Tuple</span><span class=\"p\">[</span><span class=\"n\">Optional</span><span class=\"p\">[</span><span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span><span class=\"p\">],</span> <span class=\"n\">Optional</span><span class=\"p\">[</span><span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span><span class=\"p\">]]</span>:</span></span>", "funcdef": "def"}, {"fullname": "dftscape.core.LOBPCGSimplifiedEigensolver", "modulename": "dftscape.core", "qualname": "LOBPCGSimplifiedEigensolver", "kind": "class", "doc": "<p>Simplified LOBPCG implementation for reproducing notebook results.</p>\n\n<p>This eigensolver implements a single LOBPCG iteration with simplified\northogonalization and preconditioning, designed to match the behavior\nof notebook implementations for consistency and comparison.</p>\n\n<h2 id=\"key-features\">Key Features</h2>\n\n<ul>\n<li><strong>Single Iteration</strong>: Performs one LOBPCG iteration (not iterative convergence)</li>\n<li><strong>Simplified Orthogonalization</strong>: Uses Gram-Schmidt instead of QR decomposition</li>\n<li><strong>Simple Preconditioning</strong>: Basic residual preconditioning</li>\n<li><strong>Notebook Compatibility</strong>: Matches notebook implementation behavior</li>\n<li><strong>Backup Vector Handling</strong>: Random backup vectors for numerical stability</li>\n</ul>\n\n<h2 id=\"algorithm-details\">Algorithm Details</h2>\n\n<p>The simplified LOBPCG algorithm:</p>\n\n<ol>\n<li>Initializes subspace V (warm start or random)</li>\n<li>Computes Hessian-vector products GV for current subspace</li>\n<li>Applies simple preconditioning: W = GV - V * (V^T @ GV)</li>\n<li>Orthogonalizes residual subspace W against constraints and V</li>\n<li>Performs single Rayleigh-Ritz projection on extended subspace [V, W]</li>\n<li>Returns k eigenpairs from the reduced problem</li>\n</ol>\n\n<h2 id=\"usage-examples\">Usage Examples</h2>\n\n<div class=\"pdoc-code codehilite\">\n<pre><span></span><code><span class=\"n\">solver</span> <span class=\"o\">=</span> <span class=\"n\">LOBPCGSimplifiedEigensolver</span><span class=\"p\">(</span>\n    <span class=\"n\">backend</span><span class=\"o\">=</span><span class=\"n\">backend</span><span class=\"p\">,</span>\n    <span class=\"n\">k</span><span class=\"o\">=</span><span class=\"mi\">3</span><span class=\"p\">,</span>\n    <span class=\"n\">largest</span><span class=\"o\">=</span><span class=\"kc\">False</span><span class=\"p\">,</span>\n    <span class=\"n\">tol</span><span class=\"o\">=</span><span class=\"mf\">1e-6</span>\n<span class=\"p\">)</span>\n<span class=\"n\">eigenvalues</span><span class=\"p\">,</span> <span class=\"n\">eigenvectors</span> <span class=\"o\">=</span> <span class=\"n\">solver</span><span class=\"o\">.</span><span class=\"n\">solve</span><span class=\"p\">(</span><span class=\"n\">state</span><span class=\"p\">,</span> <span class=\"n\">X0</span><span class=\"o\">=</span><span class=\"n\">initial_guess</span><span class=\"p\">)</span>\n</code></pre>\n</div>\n\n<h2 id=\"when-to-use\">When to Use</h2>\n\n<ul>\n<li>For reproducing results from notebook implementations</li>\n<li>When you want exact notebook behavior for comparison</li>\n<li>For systems where single-iteration LOBPCG is sufficient</li>\n<li>When computational simplicity is preferred over convergence guarantees</li>\n</ul>\n\n<h2 id=\"performance-characteristics\">Performance Characteristics</h2>\n\n<ul>\n<li>Memory usage: O(n * k) for subspace storage</li>\n<li>Computation: Single iteration of O(n * k\u00b2) complexity</li>\n<li>Convergence: No guaranteed convergence, single iteration only</li>\n<li>Stability: Basic orthogonalization may be less robust than QR-based methods</li>\n</ul>\n\n<h2 id=\"comparison-with-other-solvers\">Comparison with Other Solvers</h2>\n\n<ul>\n<li><strong>vs ScipyLOBPCG</strong>: Simpler but less robust and no convergence guarantees</li>\n<li><strong>vs Manual LOBPCG</strong>: Single iteration vs full iterative convergence</li>\n<li><strong>vs Eigsh</strong>: Simpler preconditioning, potentially less accurate</li>\n</ul>\n", "bases": "dftscape.core.eigensolvers.Eigensolver"}, {"fullname": "dftscape.core.LOBPCGSimplifiedEigensolver.__init__", "modulename": "dftscape.core", "qualname": "LOBPCGSimplifiedEigensolver.__init__", "kind": "function", "doc": "<p></p>\n", "signature": "<span class=\"signature pdoc-code multiline\">(<span class=\"param\">\t<span class=\"n\">backend</span><span class=\"p\">:</span> <span class=\"n\">dftscape</span><span class=\"o\">.</span><span class=\"n\">core</span><span class=\"o\">.</span><span class=\"n\">interfaces</span><span class=\"o\">.</span><span class=\"n\">Backend</span>,</span><span class=\"param\">\t<span class=\"n\">k</span><span class=\"p\">:</span> <span class=\"nb\">int</span>,</span><span class=\"param\">\t<span class=\"n\">tol</span><span class=\"p\">:</span> <span class=\"nb\">float</span> <span class=\"o\">=</span> <span class=\"mf\">0.001</span>,</span><span class=\"param\">\t<span class=\"n\">maxiter</span><span class=\"p\">:</span> <span class=\"nb\">int</span> <span class=\"o\">=</span> <span class=\"mi\">10</span>,</span><span class=\"param\">\t<span class=\"n\">largest</span><span class=\"p\">:</span> <span class=\"nb\">bool</span> <span class=\"o\">=</span> <span class=\"kc\">False</span>,</span><span class=\"param\">\t<span class=\"n\">fd_eps</span><span class=\"p\">:</span> <span class=\"nb\">float</span> <span class=\"o\">=</span> <span class=\"mf\">0.0001</span>,</span><span class=\"param\">\t<span class=\"n\">random_state</span><span class=\"p\">:</span> <span class=\"n\">Optional</span><span class=\"p\">[</span><span class=\"nb\">int</span><span class=\"p\">]</span> <span class=\"o\">=</span> <span class=\"mi\">42</span></span>)</span>"}, {"fullname": "dftscape.core.LOBPCGSimplifiedEigensolver.fd_eps", "modulename": "dftscape.core", "qualname": "LOBPCGSimplifiedEigensolver.fd_eps", "kind": "variable", "doc": "<p></p>\n", "annotation": ": float", "default_value": "0.0001"}, {"fullname": "dftscape.core.LOBPCGSimplifiedEigensolver.random_state", "modulename": "dftscape.core", "qualname": "LOBPCGSimplifiedEigensolver.random_state", "kind": "variable", "doc": "<p></p>\n", "annotation": ": Optional[int]", "default_value": "42"}, {"fullname": "dftscape.core.LOBPCGSimplifiedEigensolver.solve", "modulename": "dftscape.core", "qualname": "LOBPCGSimplifiedEigensolver.solve", "kind": "function", "doc": "<p>Compute k eigenpairs using simplified single-iteration LOBPCG.</p>\n\n<p>Performs a single LOBPCG iteration with simplified orthogonalization\nand preconditioning, designed to match notebook implementation behavior.</p>\n\n<h6 id=\"arguments\">Arguments:</h6>\n\n<ul>\n<li><strong>state:</strong>  Current molecular state, shape (n,)</li>\n<li><strong>X0:</strong>  Optional initial subspace for warm start, shape (n, k).\nIf None, uses cached previous subspace or random initialization.</li>\n<li><strong>Y:</strong>  Optional constraint matrix, shape (n, m). Eigenvectors will\nbe orthogonal to the columns of Y.</li>\n</ul>\n\n<h6 id=\"returns\">Returns:</h6>\n\n<blockquote>\n  <p>Tuple of (eigenvalues, eigenvectors):</p>\n  \n  <ul>\n  <li>eigenvalues: Array of k eigenvalues from single Rayleigh-Ritz step</li>\n  <li>eigenvectors: Array of shape (n, k) with approximately orthonormal columns</li>\n  </ul>\n</blockquote>\n\n<h6 id=\"raises\">Raises:</h6>\n\n<ul>\n<li><strong>ValueError:</strong>  If input dimensions are incompatible</li>\n<li><strong>RuntimeError:</strong>  If orthogonalization fails catastrophically</li>\n</ul>\n\n<h6 id=\"note\">Note:</h6>\n\n<blockquote>\n  <p>This implementation performs only a single LOBPCG iteration and\n  does not guarantee convergence. Use for notebook compatibility\n  or when single-iteration results are sufficient.</p>\n</blockquote>\n", "signature": "<span class=\"signature pdoc-code multiline\">(<span class=\"param\">\t<span class=\"bp\">self</span>,</span><span class=\"param\">\t<span class=\"n\">state</span><span class=\"p\">:</span> <span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span>,</span><span class=\"param\">\t<span class=\"n\">X0</span><span class=\"p\">:</span> <span class=\"n\">Optional</span><span class=\"p\">[</span><span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span><span class=\"p\">]</span> <span class=\"o\">=</span> <span class=\"kc\">None</span>,</span><span class=\"param\">\t<span class=\"n\">Y</span><span class=\"p\">:</span> <span class=\"n\">Optional</span><span class=\"p\">[</span><span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span><span class=\"p\">]</span> <span class=\"o\">=</span> <span class=\"kc\">None</span></span><span class=\"return-annotation\">) -> <span class=\"n\">Tuple</span><span class=\"p\">[</span><span class=\"n\">Optional</span><span class=\"p\">[</span><span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span><span class=\"p\">],</span> <span class=\"n\">Optional</span><span class=\"p\">[</span><span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span><span class=\"p\">]]</span>:</span></span>", "funcdef": "def"}, {"fullname": "dftscape.core.Metric", "modulename": "dftscape.core", "qualname": "Metric", "kind": "class", "doc": "<p>Abstract base class for all metrics used in dynamics simulations.</p>\n\n<p>A metric represents a computable observable that can be monitored during\nmolecular dynamics simulations. Metrics provide real-time feedback about\nsimulation progress, convergence status, and molecular properties.</p>\n\n<h2 id=\"key-features\">Key Features</h2>\n\n<ul>\n<li><strong>Abstract Interface</strong>: Subclasses must implement the <code>compute()</code> method</li>\n<li><strong>Configuration Support</strong>: Automatic serialization/deserialization</li>\n<li><strong>Registry Integration</strong>: Dynamic instantiation from configuration</li>\n<li><strong>Formatting</strong>: Configurable output formatting for logging</li>\n</ul>\n\n<h2 id=\"attributes\">Attributes</h2>\n\n<ul>\n<li><code>name</code>: Human-readable name for the metric (used in logging)</li>\n<li><code>format_str</code>: Python format string for displaying metric values</li>\n<li><code>_registry_key</code>: Internal key used by the registry system</li>\n</ul>\n\n<h2 id=\"usage\">Usage</h2>\n\n<div class=\"pdoc-code codehilite\">\n<pre><span></span><code><span class=\"k\">class</span><span class=\"w\"> </span><span class=\"nc\">CustomMetric</span><span class=\"p\">(</span><span class=\"n\">Metric</span><span class=\"p\">):</span>\n    <span class=\"k\">def</span><span class=\"w\"> </span><span class=\"fm\">__init__</span><span class=\"p\">(</span><span class=\"bp\">self</span><span class=\"p\">):</span>\n        <span class=\"nb\">super</span><span class=\"p\">()</span><span class=\"o\">.</span><span class=\"fm\">__init__</span><span class=\"p\">(</span><span class=\"s2\">&quot;Custom&quot;</span><span class=\"p\">,</span> <span class=\"s2\">&quot;:8.4f&quot;</span><span class=\"p\">)</span>\n\n    <span class=\"k\">def</span><span class=\"w\"> </span><span class=\"nf\">compute</span><span class=\"p\">(</span><span class=\"bp\">self</span><span class=\"p\">,</span> <span class=\"n\">dynamics</span><span class=\"p\">,</span> <span class=\"n\">step</span><span class=\"p\">:</span> <span class=\"nb\">int</span><span class=\"p\">,</span> <span class=\"n\">dt</span><span class=\"p\">:</span> <span class=\"nb\">float</span><span class=\"p\">)</span> <span class=\"o\">-&gt;</span> <span class=\"nb\">float</span><span class=\"p\">:</span>\n        <span class=\"k\">return</span> <span class=\"n\">some_computation</span><span class=\"p\">(</span><span class=\"n\">dynamics</span><span class=\"o\">.</span><span class=\"n\">state</span><span class=\"p\">)</span>\n</code></pre>\n</div>\n\n<h2 id=\"configuration\">Configuration</h2>\n\n<p>Metrics can be configured via dictionaries for serialization:</p>\n\n<div class=\"pdoc-code codehilite\">\n<pre><span></span><code><span class=\"n\">config</span> <span class=\"o\">=</span> <span class=\"n\">metric</span><span class=\"o\">.</span><span class=\"n\">to_config</span><span class=\"p\">()</span>  <span class=\"c1\"># Serialize</span>\n<span class=\"n\">restored</span> <span class=\"o\">=</span> <span class=\"n\">Metric</span><span class=\"o\">.</span><span class=\"n\">from_config</span><span class=\"p\">(</span><span class=\"n\">config</span><span class=\"p\">)</span>  <span class=\"c1\"># Deserialize</span>\n</code></pre>\n</div>\n", "bases": "abc.ABC"}, {"fullname": "dftscape.core.Metric.__init__", "modulename": "dftscape.core", "qualname": "Metric.__init__", "kind": "function", "doc": "<p>Initialize a metric with name and formatting.</p>\n\n<h6 id=\"arguments\">Arguments:</h6>\n\n<ul>\n<li><strong>name:</strong>  Human-readable name for the metric</li>\n<li><strong>format_str:</strong>  Python format string (default: \":12.6f\")</li>\n</ul>\n", "signature": "<span class=\"signature pdoc-code condensed\">(<span class=\"param\"><span class=\"n\">name</span><span class=\"p\">:</span> <span class=\"nb\">str</span>, </span><span class=\"param\"><span class=\"n\">format_str</span><span class=\"p\">:</span> <span class=\"nb\">str</span> <span class=\"o\">=</span> <span class=\"s1\">&#39;:12.6f&#39;</span></span>)</span>"}, {"fullname": "dftscape.core.Metric.name", "modulename": "dftscape.core", "qualname": "Metric.name", "kind": "variable", "doc": "<p></p>\n"}, {"fullname": "dftscape.core.Metric.format_str", "modulename": "dftscape.core", "qualname": "Metric.format_str", "kind": "variable", "doc": "<p></p>\n"}, {"fullname": "dftscape.core.Metric.compute", "modulename": "dftscape.core", "qualname": "Metric.compute", "kind": "function", "doc": "<p>Compute the metric value for the current simulation state.</p>\n\n<h6 id=\"arguments\">Arguments:</h6>\n\n<ul>\n<li><strong>dynamics:</strong>  Dynamics simulation object containing state and backend</li>\n<li><strong>step:</strong>  Current simulation step number</li>\n<li><strong>dt:</strong>  Time step size (for time-dependent metrics)</li>\n</ul>\n\n<h6 id=\"returns\">Returns:</h6>\n\n<blockquote>\n  <p>Computed metric value as a float</p>\n</blockquote>\n", "signature": "<span class=\"signature pdoc-code condensed\">(<span class=\"param\"><span class=\"bp\">self</span>, </span><span class=\"param\"><span class=\"n\">dynamics</span><span class=\"p\">:</span> <span class=\"n\">Any</span>, </span><span class=\"param\"><span class=\"n\">step</span><span class=\"p\">:</span> <span class=\"nb\">int</span>, </span><span class=\"param\"><span class=\"n\">dt</span><span class=\"p\">:</span> <span class=\"nb\">float</span></span><span class=\"return-annotation\">) -> <span class=\"nb\">float</span>:</span></span>", "funcdef": "def"}, {"fullname": "dftscape.core.Metric.to_config", "modulename": "dftscape.core", "qualname": "Metric.to_config", "kind": "function", "doc": "<p>Convert metric to configuration dictionary for serialization.</p>\n\n<h6 id=\"returns\">Returns:</h6>\n\n<blockquote>\n  <p>Dictionary containing metric configuration</p>\n</blockquote>\n", "signature": "<span class=\"signature pdoc-code condensed\">(<span class=\"param\"><span class=\"bp\">self</span></span><span class=\"return-annotation\">) -> <span class=\"nb\">dict</span>:</span></span>", "funcdef": "def"}, {"fullname": "dftscape.core.Metric.from_config", "modulename": "dftscape.core", "qualname": "Metric.from_config", "kind": "function", "doc": "<p>Create metric instance from configuration dictionary.</p>\n\n<h6 id=\"arguments\">Arguments:</h6>\n\n<ul>\n<li><strong>config:</strong>  Configuration dictionary</li>\n</ul>\n\n<h6 id=\"returns\">Returns:</h6>\n\n<blockquote>\n  <p>Metric instance</p>\n</blockquote>\n", "signature": "<span class=\"signature pdoc-code condensed\">(<span class=\"param\"><span class=\"bp\">cls</span>, </span><span class=\"param\"><span class=\"n\">config</span><span class=\"p\">:</span> <span class=\"nb\">dict</span></span><span class=\"return-annotation\">):</span></span>", "funcdef": "def"}, {"fullname": "dftscape.core.Metric.get_metric_type", "modulename": "dftscape.core", "qualname": "Metric.get_metric_type", "kind": "function", "doc": "<p>Get the metric type identifier for registry.</p>\n\n<h6 id=\"returns\">Returns:</h6>\n\n<blockquote>\n  <p>Class name as string identifier</p>\n</blockquote>\n", "signature": "<span class=\"signature pdoc-code condensed\">(<span class=\"param\"><span class=\"bp\">cls</span></span><span class=\"return-annotation\">) -> <span class=\"nb\">str</span>:</span></span>", "funcdef": "def"}, {"fullname": "dftscape.core.EnergyMetric", "modulename": "dftscape.core", "qualname": "EnergyMetric", "kind": "class", "doc": "<p>Metric for computing the potential energy of the molecular system.</p>\n\n<p>This metric computes the potential energy of the current molecular state\nusing the backend's energy computation method. It's one of the most\nfundamental metrics for monitoring simulation progress and convergence.</p>\n\n<h2 id=\"key-features\">Key Features</h2>\n\n<ul>\n<li><strong>Potential Energy</strong>: Computes E = E(x) for current coordinates x</li>\n<li><strong>Convergence Monitoring</strong>: Energy changes indicate progress toward minima</li>\n<li><strong>Units</strong>: Energy values in backend-specific units (typically Hartree or kcal/mol)</li>\n<li><strong>Backend Integration</strong>: Uses backend.compute_energy() method</li>\n</ul>\n\n<h2 id=\"usage\">Usage</h2>\n\n<p>The energy metric is automatically included in most dynamics simulations\nand provides essential feedback about the quality of the current molecular\nconfiguration and the progress of optimization or dynamics.</p>\n", "bases": "dftscape.core.metrics.Metric"}, {"fullname": "dftscape.core.EnergyMetric.__init__", "modulename": "dftscape.core", "qualname": "EnergyMetric.__init__", "kind": "function", "doc": "<p>Initialize energy metric with default formatting.</p>\n", "signature": "<span class=\"signature pdoc-code condensed\">()</span>"}, {"fullname": "dftscape.core.EnergyMetric.compute", "modulename": "dftscape.core", "qualname": "EnergyMetric.compute", "kind": "function", "doc": "<p>Compute the potential energy of the current molecular state.</p>\n\n<h6 id=\"arguments\">Arguments:</h6>\n\n<ul>\n<li><strong>dynamics:</strong>  Dynamics simulation object with backend and state</li>\n<li><strong>step:</strong>  Current simulation step (unused for energy computation)</li>\n<li><strong>dt:</strong>  Time step (unused for energy computation)</li>\n</ul>\n\n<h6 id=\"returns\">Returns:</h6>\n\n<blockquote>\n  <p>Potential energy value in backend units</p>\n</blockquote>\n", "signature": "<span class=\"signature pdoc-code condensed\">(<span class=\"param\"><span class=\"bp\">self</span>, </span><span class=\"param\"><span class=\"n\">dynamics</span>, </span><span class=\"param\"><span class=\"n\">step</span><span class=\"p\">:</span> <span class=\"nb\">int</span>, </span><span class=\"param\"><span class=\"n\">dt</span><span class=\"p\">:</span> <span class=\"nb\">float</span></span><span class=\"return-annotation\">) -> <span class=\"nb\">float</span>:</span></span>", "funcdef": "def"}, {"fullname": "dftscape.core.GradNormMetric", "modulename": "dftscape.core", "qualname": "GradNormMetric", "kind": "class", "doc": "<p>Metric for computing the Euclidean norm of the gradient vector.</p>\n\n<p>This metric computes ||\u2207E|| (the L2 norm of the gradient) which is a key\nindicator of convergence in optimization and dynamics simulations. When\nthe gradient norm becomes small, the system is close to a critical point.</p>\n\n<h2 id=\"key-features\">Key Features</h2>\n\n<ul>\n<li><strong>Convergence Indicator</strong>: ||\u2207E|| \u2248 0 indicates critical points</li>\n<li><strong>Magnitude Information</strong>: Absolute scale for gradient magnitude</li>\n<li><strong>Units</strong>: Gradient norm in energy/coordinates units</li>\n<li><strong>Numerical Stability</strong>: Handles zero gradients gracefully</li>\n</ul>\n\n<h2 id=\"usage\">Usage</h2>\n\n<div class=\"pdoc-code codehilite\">\n<pre><span></span><code><span class=\"n\">grad_metric</span> <span class=\"o\">=</span> <span class=\"n\">GradNormMetric</span><span class=\"p\">()</span>\n<span class=\"n\">grad_norm</span> <span class=\"o\">=</span> <span class=\"n\">grad_metric</span><span class=\"o\">.</span><span class=\"n\">compute</span><span class=\"p\">(</span><span class=\"n\">dynamics</span><span class=\"p\">,</span> <span class=\"n\">step</span><span class=\"p\">,</span> <span class=\"n\">dt</span><span class=\"p\">)</span>\n<span class=\"k\">if</span> <span class=\"n\">grad_norm</span> <span class=\"o\">&lt;</span> <span class=\"mf\">1e-6</span><span class=\"p\">:</span>\n    <span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"s2\">&quot;Converged to critical point!&quot;</span><span class=\"p\">)</span>\n</code></pre>\n</div>\n\n<h2 id=\"notes\">Notes</h2>\n\n<ul>\n<li>Gradient norm is computed as sqrt(sum(\u2207E_i\u00b2))</li>\n<li>Small values indicate proximity to critical points</li>\n<li>Used in convergence criteria for geometry optimization</li>\n</ul>\n", "bases": "dftscape.core.metrics.Metric"}, {"fullname": "dftscape.core.GradNormMetric.__init__", "modulename": "dftscape.core", "qualname": "GradNormMetric.__init__", "kind": "function", "doc": "<p>Initialize gradient norm metric with scientific notation formatting.</p>\n", "signature": "<span class=\"signature pdoc-code condensed\">()</span>"}, {"fullname": "dftscape.core.GradNormMetric.compute", "modulename": "dftscape.core", "qualname": "GradNormMetric.compute", "kind": "function", "doc": "<p>Compute the Euclidean norm of the gradient vector.</p>\n\n<h6 id=\"arguments\">Arguments:</h6>\n\n<ul>\n<li><strong>dynamics:</strong>  Dynamics simulation object with backend and state</li>\n<li><strong>step:</strong>  Current simulation step (unused for gradient computation)</li>\n<li><strong>dt:</strong>  Time step (unused for gradient computation)</li>\n</ul>\n\n<h6 id=\"returns\">Returns:</h6>\n\n<blockquote>\n  <p>Euclidean norm of the gradient vector</p>\n</blockquote>\n", "signature": "<span class=\"signature pdoc-code condensed\">(<span class=\"param\"><span class=\"bp\">self</span>, </span><span class=\"param\"><span class=\"n\">dynamics</span>, </span><span class=\"param\"><span class=\"n\">step</span><span class=\"p\">:</span> <span class=\"nb\">int</span>, </span><span class=\"param\"><span class=\"n\">dt</span><span class=\"p\">:</span> <span class=\"nb\">float</span></span><span class=\"return-annotation\">) -> <span class=\"nb\">float</span>:</span></span>", "funcdef": "def"}, {"fullname": "dftscape.core.CriticalPoint", "modulename": "dftscape.core", "qualname": "CriticalPoint", "kind": "class", "doc": "<p>Immutable representation of a critical point in the molecular potential energy landscape.</p>\n\n<p>CriticalPoint encapsulates all geometric and energetic information about a stationary\npoint (minimum, transition state, or maximum) in the molecular potential energy surface.\nThis includes coordinates, energies, derivatives, and derived properties that characterize\nthe stability and nature of the critical point.</p>\n\n<p>The dataclass is frozen to ensure immutability, guaranteeing that critical point data\nremains consistent throughout the DFTScape workflow. This prevents accidental modification\nand enables safe sharing across different components.</p>\n\n<h6 id=\"attributes\">Attributes:</h6>\n\n<ul>\n<li><strong>index (int):</strong>  Morse index of the critical point (number of negative Hessian\neigenvalues). 0 for minima, 1 for transition states, &gt;1 for maxima.</li>\n<li><strong>energy (float):</strong>  Potential energy at this critical point in atomic units (Hartree).</li>\n<li><strong>xyz (str):</strong>  Molecular geometry in XYZ format string for visualization and export.</li>\n<li><strong>state (np.ndarray):</strong>  Molecular coordinates as flat array with shape (3*N,)\nwhere N is the number of atoms.</li>\n<li><strong>gradient (np.ndarray):</strong>  First derivatives of energy with respect to coordinates,\nshape (3*N,). Should be near zero at convergence.</li>\n<li><strong>hessian (np.ndarray):</strong>  Second derivatives (force constants) matrix with shape (3<em>N, 3</em>N).</li>\n<li><strong>eigenvalues (np.ndarray):</strong>  Eigenvalues of the Hessian matrix, shape (3*N,).\nUsed to determine Morse index and vibrational frequencies.</li>\n<li><strong>eigenvectors (np.ndarray):</strong>  Eigenvectors of the Hessian matrix, shape (3<em>N, 3</em>N).\nUsed for normal mode analysis and reaction path following.</li>\n<li><strong>comment (str):</strong>  Optional descriptive comment or metadata about this critical point.</li>\n</ul>\n\n<h6 id=\"key-properties\">Key Properties:</h6>\n\n<blockquote>\n  <ul>\n  <li><strong>Morse Index</strong>: Determines the nature (minimum/TS/maximum) of the critical point</li>\n  <li><strong>Stability</strong>: Based on Hessian eigenvalues (all positive = minimum)</li>\n  <li><strong>Geometry</strong>: Complete molecular structure information</li>\n  <li><strong>Derivatives</strong>: Gradient and Hessian for optimization and analysis</li>\n  <li><strong>Serialization</strong>: Can be saved/loaded for workflow persistence</li>\n  </ul>\n</blockquote>\n\n<h6 id=\"example\">Example:</h6>\n\n<blockquote>\n  <div class=\"pdoc-code codehilite\">\n<pre><span></span><code><span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Create a critical point (typically done via from_state)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">point</span> <span class=\"o\">=</span> <span class=\"n\">CriticalPoint</span><span class=\"p\">(</span>\n<span class=\"gp\">... </span>    <span class=\"n\">index</span><span class=\"o\">=</span><span class=\"mi\">0</span><span class=\"p\">,</span>  <span class=\"c1\"># Minimum</span>\n<span class=\"gp\">... </span>    <span class=\"n\">energy</span><span class=\"o\">=-</span><span class=\"mf\">1.234567</span><span class=\"p\">,</span>\n<span class=\"gp\">... </span>    <span class=\"n\">xyz</span><span class=\"o\">=</span><span class=\"s2\">&quot;2</span><span class=\"se\">\\n\\n</span><span class=\"s2\">H 0.0 0.0 0.0</span><span class=\"se\">\\n</span><span class=\"s2\">H 0.0 0.0 0.74&quot;</span><span class=\"p\">,</span>\n<span class=\"gp\">... </span>    <span class=\"n\">state</span><span class=\"o\">=</span><span class=\"n\">np</span><span class=\"o\">.</span><span class=\"n\">array</span><span class=\"p\">([</span><span class=\"mf\">0.0</span><span class=\"p\">,</span> <span class=\"mf\">0.0</span><span class=\"p\">,</span> <span class=\"mf\">0.0</span><span class=\"p\">,</span> <span class=\"mf\">0.0</span><span class=\"p\">,</span> <span class=\"mf\">0.0</span><span class=\"p\">,</span> <span class=\"mf\">0.74</span><span class=\"p\">]),</span>\n<span class=\"gp\">... </span>    <span class=\"n\">gradient</span><span class=\"o\">=</span><span class=\"n\">np</span><span class=\"o\">.</span><span class=\"n\">zeros</span><span class=\"p\">(</span><span class=\"mi\">6</span><span class=\"p\">),</span>  <span class=\"c1\"># Converged</span>\n<span class=\"gp\">... </span>    <span class=\"n\">hessian</span><span class=\"o\">=</span><span class=\"n\">np</span><span class=\"o\">.</span><span class=\"n\">eye</span><span class=\"p\">(</span><span class=\"mi\">6</span><span class=\"p\">)</span> <span class=\"o\">*</span> <span class=\"mf\">0.5</span><span class=\"p\">,</span>  <span class=\"c1\"># Positive definite</span>\n<span class=\"gp\">... </span>    <span class=\"n\">eigenvalues</span><span class=\"o\">=</span><span class=\"n\">np</span><span class=\"o\">.</span><span class=\"n\">array</span><span class=\"p\">([</span><span class=\"mf\">0.5</span><span class=\"p\">,</span> <span class=\"mf\">0.5</span><span class=\"p\">,</span> <span class=\"mf\">0.5</span><span class=\"p\">,</span> <span class=\"mf\">0.5</span><span class=\"p\">,</span> <span class=\"mf\">0.5</span><span class=\"p\">,</span> <span class=\"mf\">0.5</span><span class=\"p\">]),</span>\n<span class=\"gp\">... </span>    <span class=\"n\">eigenvectors</span><span class=\"o\">=</span><span class=\"n\">np</span><span class=\"o\">.</span><span class=\"n\">eye</span><span class=\"p\">(</span><span class=\"mi\">6</span><span class=\"p\">),</span>\n<span class=\"gp\">... </span>    <span class=\"n\">comment</span><span class=\"o\">=</span><span class=\"s2\">&quot;H2 equilibrium geometry&quot;</span>\n<span class=\"gp\">... </span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Check stability</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">is_minimum</span> <span class=\"o\">=</span> <span class=\"n\">point</span><span class=\"o\">.</span><span class=\"n\">index</span> <span class=\"o\">==</span> <span class=\"mi\">0</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">is_stable</span> <span class=\"o\">=</span> <span class=\"n\">np</span><span class=\"o\">.</span><span class=\"n\">all</span><span class=\"p\">(</span><span class=\"n\">point</span><span class=\"o\">.</span><span class=\"n\">eigenvalues</span> <span class=\"o\">&gt;</span> <span class=\"mi\">0</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"sa\">f</span><span class=\"s2\">&quot;Minimum: </span><span class=\"si\">{</span><span class=\"n\">is_minimum</span><span class=\"si\">}</span><span class=\"s2\">, Stable: </span><span class=\"si\">{</span><span class=\"n\">is_stable</span><span class=\"si\">}</span><span class=\"s2\">&quot;</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Access molecular information</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"sa\">f</span><span class=\"s2\">&quot;Energy: </span><span class=\"si\">{</span><span class=\"n\">point</span><span class=\"o\">.</span><span class=\"n\">energy</span><span class=\"si\">:</span><span class=\"s2\">.6f</span><span class=\"si\">}</span><span class=\"s2\"> Hartree&quot;</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"sa\">f</span><span class=\"s2\">&quot;Gradient norm: </span><span class=\"si\">{</span><span class=\"n\">np</span><span class=\"o\">.</span><span class=\"n\">linalg</span><span class=\"o\">.</span><span class=\"n\">norm</span><span class=\"p\">(</span><span class=\"n\">point</span><span class=\"o\">.</span><span class=\"n\">gradient</span><span class=\"p\">)</span><span class=\"si\">:</span><span class=\"s2\">.2e</span><span class=\"si\">}</span><span class=\"s2\">&quot;</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"s2\">&quot;Structure:&quot;</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"n\">point</span><span class=\"o\">.</span><span class=\"n\">xyz</span><span class=\"p\">)</span>\n</code></pre>\n  </div>\n</blockquote>\n\n<h6 id=\"notes\">Notes:</h6>\n\n<blockquote>\n  <ul>\n  <li>Instances are immutable after creation (frozen=True)</li>\n  <li>Morse index is automatically computed from negative eigenvalues</li>\n  <li>Gradient should be near zero for converged optimizations</li>\n  <li>Hessian eigenvalues determine vibrational frequencies (scaled by reduced mass)</li>\n  <li>XYZ format is suitable for molecular visualization tools</li>\n  <li>Memory usage scales with system size O(N) for coordinates, O(N\u00b2) for Hessian</li>\n  </ul>\n</blockquote>\n", "bases": "dftscape.common.data_structures.SerialisableDataClass"}, {"fullname": "dftscape.core.CriticalPoint.__init__", "modulename": "dftscape.core", "qualname": "CriticalPoint.__init__", "kind": "function", "doc": "<p></p>\n", "signature": "<span class=\"signature pdoc-code multiline\">(<span class=\"param\">\t<span class=\"n\">index</span><span class=\"p\">:</span> <span class=\"nb\">int</span>,</span><span class=\"param\">\t<span class=\"n\">energy</span><span class=\"p\">:</span> <span class=\"nb\">float</span>,</span><span class=\"param\">\t<span class=\"n\">xyz</span><span class=\"p\">:</span> <span class=\"nb\">str</span>,</span><span class=\"param\">\t<span class=\"n\">state</span><span class=\"p\">:</span> <span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span>,</span><span class=\"param\">\t<span class=\"n\">gradient</span><span class=\"p\">:</span> <span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span>,</span><span class=\"param\">\t<span class=\"n\">hessian</span><span class=\"p\">:</span> <span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span>,</span><span class=\"param\">\t<span class=\"n\">eigenvalues</span><span class=\"p\">:</span> <span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span>,</span><span class=\"param\">\t<span class=\"n\">eigenvectors</span><span class=\"p\">:</span> <span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span>,</span><span class=\"param\">\t<span class=\"n\">comment</span><span class=\"p\">:</span> <span class=\"nb\">str</span> <span class=\"o\">=</span> <span class=\"s1\">&#39;&#39;</span></span>)</span>"}, {"fullname": "dftscape.core.CriticalPoint.index", "modulename": "dftscape.core", "qualname": "CriticalPoint.index", "kind": "variable", "doc": "<p></p>\n", "annotation": ": int"}, {"fullname": "dftscape.core.CriticalPoint.energy", "modulename": "dftscape.core", "qualname": "CriticalPoint.energy", "kind": "variable", "doc": "<p></p>\n", "annotation": ": float"}, {"fullname": "dftscape.core.CriticalPoint.xyz", "modulename": "dftscape.core", "qualname": "CriticalPoint.xyz", "kind": "variable", "doc": "<p></p>\n", "annotation": ": str"}, {"fullname": "dftscape.core.CriticalPoint.state", "modulename": "dftscape.core", "qualname": "CriticalPoint.state", "kind": "variable", "doc": "<p></p>\n", "annotation": ": numpy.ndarray"}, {"fullname": "dftscape.core.CriticalPoint.gradient", "modulename": "dftscape.core", "qualname": "CriticalPoint.gradient", "kind": "variable", "doc": "<p></p>\n", "annotation": ": numpy.ndarray"}, {"fullname": "dftscape.core.CriticalPoint.hessian", "modulename": "dftscape.core", "qualname": "CriticalPoint.hessian", "kind": "variable", "doc": "<p></p>\n", "annotation": ": numpy.ndarray"}, {"fullname": "dftscape.core.CriticalPoint.eigenvalues", "modulename": "dftscape.core", "qualname": "CriticalPoint.eigenvalues", "kind": "variable", "doc": "<p></p>\n", "annotation": ": numpy.ndarray"}, {"fullname": "dftscape.core.CriticalPoint.eigenvectors", "modulename": "dftscape.core", "qualname": "CriticalPoint.eigenvectors", "kind": "variable", "doc": "<p></p>\n", "annotation": ": numpy.ndarray"}, {"fullname": "dftscape.core.CriticalPoint.comment", "modulename": "dftscape.core", "qualname": "CriticalPoint.comment", "kind": "variable", "doc": "<p></p>\n", "annotation": ": str", "default_value": "&#x27;&#x27;"}, {"fullname": "dftscape.core.CriticalPoint.from_state", "modulename": "dftscape.core", "qualname": "CriticalPoint.from_state", "kind": "function", "doc": "<p>Create a CriticalPoint instance by computing properties at a molecular state.</p>\n\n<p>This factory method computes all necessary quantum chemical properties\n(energy, gradient, Hessian) at the specified molecular geometry and\nconstructs a CriticalPoint instance with the results. The Morse index\nis automatically computed from the Hessian eigenvalues unless explicitly\nprovided.</p>\n\n<p>The method performs the following computations:</p>\n\n<ol>\n<li>Energy evaluation at the given state</li>\n<li>Gradient computation for convergence checking</li>\n<li>Hessian computation for stability analysis</li>\n<li>Eigenvalue decomposition of the Hessian</li>\n<li>Automatic Morse index determination (if not provided)</li>\n<li>XYZ coordinate string generation</li>\n</ol>\n\n<h6 id=\"arguments\">Arguments:</h6>\n\n<ul>\n<li><strong>state:</strong>  Molecular coordinates as flat array with shape (3*N,)\nwhere N is the number of atoms.</li>\n<li><strong>backend:</strong>  Backend instance providing quantum chemical computations.\nMust support energy, gradient, and Hessian calculations.</li>\n<li><strong>index:</strong>  Optional Morse index override. If None, will be computed\nautomatically as the number of negative Hessian eigenvalues.</li>\n</ul>\n\n<h6 id=\"returns\">Returns:</h6>\n\n<blockquote>\n  <p>A new CriticalPoint instance with all computed properties.</p>\n</blockquote>\n\n<h6 id=\"raises\">Raises:</h6>\n\n<ul>\n<li>May raise exceptions from backend computations (e.g., SCF convergence</li>\n<li>failures, numerical instabilities).</li>\n</ul>\n\n<h6 id=\"example\">Example:</h6>\n\n<blockquote>\n  <div class=\"pdoc-code codehilite\">\n<pre><span></span><code><span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Create from optimized geometry</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">optimized_state</span> <span class=\"o\">=</span> <span class=\"n\">np</span><span class=\"o\">.</span><span class=\"n\">array</span><span class=\"p\">([</span><span class=\"mf\">0.0</span><span class=\"p\">,</span> <span class=\"mf\">0.0</span><span class=\"p\">,</span> <span class=\"mf\">0.0</span><span class=\"p\">,</span> <span class=\"mf\">0.0</span><span class=\"p\">,</span> <span class=\"mf\">0.0</span><span class=\"p\">,</span> <span class=\"mf\">0.74</span><span class=\"p\">])</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">point</span> <span class=\"o\">=</span> <span class=\"n\">CriticalPoint</span><span class=\"o\">.</span><span class=\"n\">from_state</span><span class=\"p\">(</span><span class=\"n\">optimized_state</span><span class=\"p\">,</span> <span class=\"n\">psi4_backend</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Override Morse index (useful for known transition states)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">ts_point</span> <span class=\"o\">=</span> <span class=\"n\">CriticalPoint</span><span class=\"o\">.</span><span class=\"n\">from_state</span><span class=\"p\">(</span><span class=\"n\">ts_state</span><span class=\"p\">,</span> <span class=\"n\">backend</span><span class=\"p\">,</span> <span class=\"n\">index</span><span class=\"o\">=</span><span class=\"mi\">1</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Check if computation succeeded</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"k\">if</span> <span class=\"n\">point</span><span class=\"o\">.</span><span class=\"n\">index</span> <span class=\"o\">==</span> <span class=\"mi\">0</span><span class=\"p\">:</span>\n<span class=\"gp\">... </span>    <span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"sa\">f</span><span class=\"s2\">&quot;Found minimum with energy </span><span class=\"si\">{</span><span class=\"n\">point</span><span class=\"o\">.</span><span class=\"n\">energy</span><span class=\"si\">:</span><span class=\"s2\">.6f</span><span class=\"si\">}</span><span class=\"s2\">&quot;</span><span class=\"p\">)</span>\n<span class=\"gp\">... </span><span class=\"k\">else</span><span class=\"p\">:</span>\n<span class=\"gp\">... </span>    <span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"sa\">f</span><span class=\"s2\">&quot;Found saddle point (index </span><span class=\"si\">{</span><span class=\"n\">point</span><span class=\"o\">.</span><span class=\"n\">index</span><span class=\"si\">}</span><span class=\"s2\">)&quot;</span><span class=\"p\">)</span>\n</code></pre>\n  </div>\n</blockquote>\n\n<h6 id=\"notes\">Notes:</h6>\n\n<blockquote>\n  <ul>\n  <li>Computation can be expensive for large molecules</li>\n  <li>Backend must be properly configured and initialized</li>\n  <li>Hessian computation is most expensive step</li>\n  <li>Eigenvalue analysis uses threshold of -1e-6 for negative detection</li>\n  <li>XYZ string format is suitable for molecular visualization</li>\n  </ul>\n</blockquote>\n", "signature": "<span class=\"signature pdoc-code multiline\">(<span class=\"param\">\t<span class=\"bp\">cls</span>,</span><span class=\"param\">\t<span class=\"n\">state</span><span class=\"p\">:</span> <span class=\"n\">numpy</span><span class=\"o\">.</span><span class=\"n\">ndarray</span>,</span><span class=\"param\">\t<span class=\"n\">backend</span><span class=\"p\">:</span> <span class=\"n\">dftscape</span><span class=\"o\">.</span><span class=\"n\">core</span><span class=\"o\">.</span><span class=\"n\">interfaces</span><span class=\"o\">.</span><span class=\"n\">Backend</span>,</span><span class=\"param\">\t<span class=\"n\">index</span><span class=\"p\">:</span> <span class=\"n\">Optional</span><span class=\"p\">[</span><span class=\"nb\">int</span><span class=\"p\">]</span> <span class=\"o\">=</span> <span class=\"kc\">None</span></span><span class=\"return-annotation\">) -> <span class=\"n\">dftscape</span><span class=\"o\">.</span><span class=\"n\">core</span><span class=\"o\">.</span><span class=\"n\">point</span><span class=\"o\">.</span><span class=\"n\">CriticalPoint</span>:</span></span>", "funcdef": "def"}, {"fullname": "dftscape.core.CriticalPointGraph", "modulename": "dftscape.core", "qualname": "CriticalPointGraph", "kind": "class", "doc": "<p>Graph data structure for managing critical points in molecular optimization landscapes.</p>\n\n<p>This class provides an efficient way to store and manage critical points (minima,\ntransition states) discovered during molecular dynamics simulations. It automatically\ndetects and prevents duplicate structures based on distance-based similarity metrics,\nensuring that only unique molecular configurations are stored.</p>\n\n<p>The graph uses NetworkX DiGraph as the underlying data structure, where each node\nrepresents a critical point and edges can represent relationships between points\n(e.g., transition paths, energy relationships).</p>\n\n<p>Key Features:</p>\n\n<ul>\n<li>Automatic duplicate detection using configurable distance functions (RMSD, Euclidean)</li>\n<li>Efficient storage and retrieval of molecular structures</li>\n<li>Serialization support for saving/loading graph state</li>\n<li>Comprehensive reporting and analysis capabilities</li>\n<li>Support for custom distance functions and thresholds</li>\n</ul>\n\n<h6 id=\"attributes\">Attributes:</h6>\n\n<ul>\n<li><strong>threshold (float):</strong>  Distance threshold below which structures are considered duplicates</li>\n<li><strong>distance_function (DistanceFunction):</strong>  Function used to compute structural similarity</li>\n<li><strong>distance_function_name (str):</strong>  Name of the distance function for logging/serialization</li>\n<li><strong>distance_kwargs (dict):</strong>  Additional keyword arguments passed to distance function</li>\n<li><strong>graph (nx.DiGraph):</strong>  Underlying NetworkX directed graph containing the critical points</li>\n</ul>\n\n<h6 id=\"example\">Example:</h6>\n\n<blockquote>\n  <div class=\"pdoc-code codehilite\">\n<pre><span></span><code><span class=\"gp\">&gt;&gt;&gt; </span><span class=\"kn\">from</span><span class=\"w\"> </span><span class=\"nn\">dftscape.core.graph</span><span class=\"w\"> </span><span class=\"kn\">import</span> <span class=\"n\">CriticalPointGraph</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"kn\">from</span><span class=\"w\"> </span><span class=\"nn\">dftscape.core.point</span><span class=\"w\"> </span><span class=\"kn\">import</span> <span class=\"n\">CriticalPoint</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"kn\">import</span><span class=\"w\"> </span><span class=\"nn\">numpy</span><span class=\"w\"> </span><span class=\"k\">as</span><span class=\"w\"> </span><span class=\"nn\">np</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Create graph with RMSD distance function</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">graph</span> <span class=\"o\">=</span> <span class=\"n\">CriticalPointGraph</span><span class=\"p\">(</span><span class=\"n\">threshold</span><span class=\"o\">=</span><span class=\"mf\">0.1</span><span class=\"p\">,</span> <span class=\"n\">distance_function</span><span class=\"o\">=</span><span class=\"s2\">&quot;rmsd&quot;</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Create and add critical points</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">point1</span> <span class=\"o\">=</span> <span class=\"n\">CriticalPoint</span><span class=\"p\">(</span>\n<span class=\"gp\">... </span>    <span class=\"n\">index</span><span class=\"o\">=</span><span class=\"mi\">0</span><span class=\"p\">,</span> <span class=\"n\">energy</span><span class=\"o\">=-</span><span class=\"mf\">10.5</span><span class=\"p\">,</span> <span class=\"n\">xyz</span><span class=\"o\">=</span><span class=\"s2\">&quot;H 0.0 0.0 0.0&quot;</span><span class=\"p\">,</span>\n<span class=\"gp\">... </span>    <span class=\"n\">state</span><span class=\"o\">=</span><span class=\"n\">np</span><span class=\"o\">.</span><span class=\"n\">array</span><span class=\"p\">([</span><span class=\"mf\">0.0</span><span class=\"p\">,</span> <span class=\"mf\">0.0</span><span class=\"p\">,</span> <span class=\"mf\">0.0</span><span class=\"p\">]),</span>\n<span class=\"gp\">... </span>    <span class=\"n\">gradient</span><span class=\"o\">=</span><span class=\"n\">np</span><span class=\"o\">.</span><span class=\"n\">array</span><span class=\"p\">([</span><span class=\"mf\">0.0</span><span class=\"p\">,</span> <span class=\"mf\">0.0</span><span class=\"p\">,</span> <span class=\"mf\">0.0</span><span class=\"p\">]),</span>\n<span class=\"gp\">... </span>    <span class=\"n\">hessian</span><span class=\"o\">=</span><span class=\"n\">np</span><span class=\"o\">.</span><span class=\"n\">array</span><span class=\"p\">([[</span><span class=\"mf\">1.0</span><span class=\"p\">,</span> <span class=\"mf\">0.0</span><span class=\"p\">,</span> <span class=\"mf\">0.0</span><span class=\"p\">],</span> <span class=\"p\">[</span><span class=\"mf\">0.0</span><span class=\"p\">,</span> <span class=\"mf\">1.0</span><span class=\"p\">,</span> <span class=\"mf\">0.0</span><span class=\"p\">],</span> <span class=\"p\">[</span><span class=\"mf\">0.0</span><span class=\"p\">,</span> <span class=\"mf\">0.0</span><span class=\"p\">,</span> <span class=\"mf\">1.0</span><span class=\"p\">]]),</span>\n<span class=\"gp\">... </span>    <span class=\"n\">eigenvalues</span><span class=\"o\">=</span><span class=\"n\">np</span><span class=\"o\">.</span><span class=\"n\">array</span><span class=\"p\">([</span><span class=\"mf\">1.0</span><span class=\"p\">,</span> <span class=\"mf\">1.0</span><span class=\"p\">,</span> <span class=\"mf\">1.0</span><span class=\"p\">]),</span>\n<span class=\"gp\">... </span>    <span class=\"n\">eigenvectors</span><span class=\"o\">=</span><span class=\"n\">np</span><span class=\"o\">.</span><span class=\"n\">array</span><span class=\"p\">([[</span><span class=\"mf\">1.0</span><span class=\"p\">,</span> <span class=\"mf\">0.0</span><span class=\"p\">,</span> <span class=\"mf\">0.0</span><span class=\"p\">],</span> <span class=\"p\">[</span><span class=\"mf\">0.0</span><span class=\"p\">,</span> <span class=\"mf\">1.0</span><span class=\"p\">,</span> <span class=\"mf\">0.0</span><span class=\"p\">],</span> <span class=\"p\">[</span><span class=\"mf\">0.0</span><span class=\"p\">,</span> <span class=\"mf\">0.0</span><span class=\"p\">,</span> <span class=\"mf\">1.0</span><span class=\"p\">]])</span>\n<span class=\"gp\">... </span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">graph</span><span class=\"o\">.</span><span class=\"n\">add</span><span class=\"p\">(</span><span class=\"n\">point1</span><span class=\"p\">)</span>  <span class=\"c1\"># Returns True (new point added)</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Check for similar structures</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">similar_points</span> <span class=\"o\">=</span> <span class=\"n\">graph</span><span class=\"o\">.</span><span class=\"n\">find_similar</span><span class=\"p\">(</span><span class=\"n\">point1</span><span class=\"p\">,</span> <span class=\"n\">threshold</span><span class=\"o\">=</span><span class=\"mf\">0.2</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"sa\">f</span><span class=\"s2\">&quot;Found </span><span class=\"si\">{</span><span class=\"nb\">len</span><span class=\"p\">(</span><span class=\"n\">similar_points</span><span class=\"p\">)</span><span class=\"si\">}</span><span class=\"s2\"> similar structures&quot;</span><span class=\"p\">)</span>\n</code></pre>\n  </div>\n</blockquote>\n"}, {"fullname": "dftscape.core.CriticalPointGraph.__init__", "modulename": "dftscape.core", "qualname": "CriticalPointGraph.__init__", "kind": "function", "doc": "<p>Initialize the CriticalPointGraph.</p>\n\n<p>Parameters:\nthreshold: Distance threshold for uniqueness checking (default: 0.1)\ndistance_function: Distance function to use ('rmsd', 'euclidean', 'max_coordinate')\n                  or a custom DistanceFunction callable\n**distance_kwargs: Additional arguments passed to the distance function</p>\n", "signature": "<span class=\"signature pdoc-code multiline\">(<span class=\"param\">\t<span class=\"n\">threshold</span><span class=\"p\">:</span> <span class=\"nb\">float</span> <span class=\"o\">=</span> <span class=\"mf\">0.1</span>,</span><span class=\"param\">\t<span class=\"n\">distance_function</span><span class=\"p\">:</span> <span class=\"nb\">str</span> <span class=\"o\">|</span> <span class=\"n\">dftscape</span><span class=\"o\">.</span><span class=\"n\">common</span><span class=\"o\">.</span><span class=\"n\">distance</span><span class=\"o\">.</span><span class=\"n\">DistanceFunction</span> <span class=\"o\">=</span> <span class=\"s1\">&#39;rmsd&#39;</span>,</span><span class=\"param\">\t<span class=\"o\">**</span><span class=\"n\">distance_kwargs</span><span class=\"p\">:</span> <span class=\"n\">Any</span></span>)</span>"}, {"fullname": "dftscape.core.CriticalPointGraph.threshold", "modulename": "dftscape.core", "qualname": "CriticalPointGraph.threshold", "kind": "variable", "doc": "<p></p>\n"}, {"fullname": "dftscape.core.CriticalPointGraph.distance_kwargs", "modulename": "dftscape.core", "qualname": "CriticalPointGraph.distance_kwargs", "kind": "variable", "doc": "<p></p>\n"}, {"fullname": "dftscape.core.CriticalPointGraph.graph", "modulename": "dftscape.core", "qualname": "CriticalPointGraph.graph", "kind": "variable", "doc": "<p>Access the underlying NetworkX graph.</p>\n", "annotation": ": networkx.classes.digraph.DiGraph"}, {"fullname": "dftscape.core.CriticalPointGraph.add", "modulename": "dftscape.core", "qualname": "CriticalPointGraph.add", "kind": "function", "doc": "<p>Add a critical point to the graph only if it's not similar to existing nodes.</p>\n\n<p>Parameters:\ncritical_point: CriticalPoint object to add</p>\n\n<p>Returns:\nbool: True if added, False if similar to existing node</p>\n", "signature": "<span class=\"signature pdoc-code condensed\">(<span class=\"param\"><span class=\"bp\">self</span>, </span><span class=\"param\"><span class=\"n\">critical_point</span><span class=\"p\">:</span> <span class=\"n\">dftscape</span><span class=\"o\">.</span><span class=\"n\">core</span><span class=\"o\">.</span><span class=\"n\">point</span><span class=\"o\">.</span><span class=\"n\">CriticalPoint</span></span><span class=\"return-annotation\">) -> <span class=\"nb\">bool</span>:</span></span>", "funcdef": "def"}, {"fullname": "dftscape.core.CriticalPointGraph.find_similar", "modulename": "dftscape.core", "qualname": "CriticalPointGraph.find_similar", "kind": "function", "doc": "<p>Find all points in the graph similar to the target point.</p>\n\n<p>Parameters:\ntarget_point: CriticalPoint to compare against\nthreshold: Distance threshold (uses instance threshold if None)</p>\n\n<p>Returns:\nlist: List of (xyz_key, distance_value, critical_point) tuples for similar structures</p>\n", "signature": "<span class=\"signature pdoc-code multiline\">(<span class=\"param\">\t<span class=\"bp\">self</span>,</span><span class=\"param\">\t<span class=\"n\">target_point</span><span class=\"p\">:</span> <span class=\"n\">dftscape</span><span class=\"o\">.</span><span class=\"n\">core</span><span class=\"o\">.</span><span class=\"n\">point</span><span class=\"o\">.</span><span class=\"n\">CriticalPoint</span>,</span><span class=\"param\">\t<span class=\"n\">threshold</span><span class=\"p\">:</span> <span class=\"nb\">float</span> <span class=\"o\">=</span> <span class=\"kc\">None</span></span><span class=\"return-annotation\">) -> <span class=\"n\">List</span><span class=\"p\">[</span><span class=\"n\">Tuple</span><span class=\"p\">[</span><span class=\"nb\">str</span><span class=\"p\">,</span> <span class=\"nb\">float</span><span class=\"p\">,</span> <span class=\"n\">dftscape</span><span class=\"o\">.</span><span class=\"n\">core</span><span class=\"o\">.</span><span class=\"n\">point</span><span class=\"o\">.</span><span class=\"n\">CriticalPoint</span><span class=\"p\">]]</span>:</span></span>", "funcdef": "def"}, {"fullname": "dftscape.core.CriticalPointGraph.get_critical_points_by_index", "modulename": "dftscape.core", "qualname": "CriticalPointGraph.get_critical_points_by_index", "kind": "function", "doc": "<p>Get all critical points grouped by their Morse index.</p>\n\n<h6 id=\"returns\">Returns:</h6>\n\n<blockquote>\n  <p>dict: Dictionary mapping Morse index to list of CriticalPoint objects.\n       Each list is sorted by energy (lowest first).</p>\n</blockquote>\n", "signature": "<span class=\"signature pdoc-code condensed\">(<span class=\"param\"><span class=\"bp\">self</span></span><span class=\"return-annotation\">) -> <span class=\"n\">Dict</span><span class=\"p\">[</span><span class=\"nb\">int</span><span class=\"p\">,</span> <span class=\"n\">List</span><span class=\"p\">[</span><span class=\"n\">dftscape</span><span class=\"o\">.</span><span class=\"n\">core</span><span class=\"o\">.</span><span class=\"n\">point</span><span class=\"o\">.</span><span class=\"n\">CriticalPoint</span><span class=\"p\">]]</span>:</span></span>", "funcdef": "def"}, {"fullname": "dftscape.core.CriticalPointGraph.check_uniqueness", "modulename": "dftscape.core", "qualname": "CriticalPointGraph.check_uniqueness", "kind": "function", "doc": "<p>Check the graph for similar structures and report duplicates.</p>\n\n<p>Parameters:\nthreshold: Distance threshold for similarity (uses instance threshold if None)</p>\n\n<p>Returns:\ndict: Dictionary with duplicate information</p>\n", "signature": "<span class=\"signature pdoc-code condensed\">(<span class=\"param\"><span class=\"bp\">self</span>, </span><span class=\"param\"><span class=\"n\">threshold</span><span class=\"p\">:</span> <span class=\"nb\">float</span> <span class=\"o\">=</span> <span class=\"kc\">None</span></span><span class=\"return-annotation\">) -> <span class=\"n\">Dict</span><span class=\"p\">[</span><span class=\"nb\">str</span><span class=\"p\">,</span> <span class=\"n\">Any</span><span class=\"p\">]</span>:</span></span>", "funcdef": "def"}, {"fullname": "dftscape.core.CriticalPointGraph.save", "modulename": "dftscape.core", "qualname": "CriticalPointGraph.save", "kind": "function", "doc": "<p>Save the graph to a JSON file.</p>\n", "signature": "<span class=\"signature pdoc-code condensed\">(<span class=\"param\"><span class=\"bp\">self</span>, </span><span class=\"param\"><span class=\"n\">filepath</span><span class=\"p\">:</span> <span class=\"nb\">str</span></span><span class=\"return-annotation\">) -> <span class=\"kc\">None</span>:</span></span>", "funcdef": "def"}, {"fullname": "dftscape.core.CriticalPointGraph.to_config", "modulename": "dftscape.core", "qualname": "CriticalPointGraph.to_config", "kind": "function", "doc": "<p>Serialize the graph to a configuration dictionary.</p>\n", "signature": "<span class=\"signature pdoc-code condensed\">(<span class=\"param\"><span class=\"bp\">self</span></span><span class=\"return-annotation\">) -> <span class=\"n\">Dict</span><span class=\"p\">[</span><span class=\"nb\">str</span><span class=\"p\">,</span> <span class=\"n\">Any</span><span class=\"p\">]</span>:</span></span>", "funcdef": "def"}, {"fullname": "dftscape.core.CriticalPointGraph.from_config", "modulename": "dftscape.core", "qualname": "CriticalPointGraph.from_config", "kind": "function", "doc": "<p>Create CriticalPointGraph from configuration dictionary.</p>\n", "signature": "<span class=\"signature pdoc-code multiline\">(<span class=\"param\">\t<span class=\"bp\">cls</span>,</span><span class=\"param\">\t<span class=\"n\">graph_data</span><span class=\"p\">:</span> <span class=\"n\">Dict</span><span class=\"p\">[</span><span class=\"nb\">str</span><span class=\"p\">,</span> <span class=\"n\">Any</span><span class=\"p\">]</span></span><span class=\"return-annotation\">) -> <span class=\"n\">dftscape</span><span class=\"o\">.</span><span class=\"n\">core</span><span class=\"o\">.</span><span class=\"n\">graph</span><span class=\"o\">.</span><span class=\"n\">CriticalPointGraph</span>:</span></span>", "funcdef": "def"}, {"fullname": "dftscape.core.CriticalPointGraph.report", "modulename": "dftscape.core", "qualname": "CriticalPointGraph.report", "kind": "function", "doc": "<p>Generate a comprehensive summary report of the graph status.</p>\n\n<h6 id=\"returns\">Returns:</h6>\n\n<blockquote>\n  <p>str: Formatted report string with graph statistics</p>\n</blockquote>\n", "signature": "<span class=\"signature pdoc-code condensed\">(<span class=\"param\"><span class=\"bp\">self</span></span><span class=\"return-annotation\">) -> <span class=\"nb\">str</span>:</span></span>", "funcdef": "def"}, {"fullname": "dftscape.core.SearchableCriticalPointGraph", "modulename": "dftscape.core", "qualname": "SearchableCriticalPointGraph", "kind": "class", "doc": "<p>Extended critical point graph with multi-procedure search state tracking.</p>\n\n<p>This class extends CriticalPointGraph to support tracking the processing state\nof nodes across multiple concurrent or sequential search procedures. This is\nparticularly useful in complex optimization workflows where different search\nalgorithms (e.g., upward saddle searches, downward minimization) need to\ncoordinate and avoid redundant computations.</p>\n\n<p>The class maintains separate state dictionaries for each search procedure,\nallowing different procedures to have independent views of which nodes have\nbeen processed, explored, or require further investigation.</p>\n\n<p>Key Features:</p>\n\n<ul>\n<li>Inherits all CriticalPointGraph functionality for duplicate detection and storage</li>\n<li>Multi-procedure state tracking to prevent redundant computations</li>\n<li>Independent processing states for different search algorithms</li>\n<li>Efficient state management for large-scale optimization workflows</li>\n<li>Support for resumable and parallel search procedures</li>\n</ul>\n\n<h6 id=\"attributes\">Attributes:</h6>\n\n<ul>\n<li><strong>threshold (float):</strong>  Distance threshold for uniqueness checking (inherited)</li>\n<li><strong>distance_function (DistanceFunction):</strong>  Distance function for similarity (inherited)</li>\n<li><strong>distance_function_name (str):</strong>  Name of distance function (inherited)</li>\n<li><strong>distance_kwargs (dict):</strong>  Additional distance function arguments (inherited)</li>\n<li><strong>graph (nx.DiGraph):</strong>  Underlying NetworkX graph (inherited)</li>\n<li><strong>_search_states (dict):</strong>  Dictionary mapping search procedure names to their states</li>\n</ul>\n\n<h6 id=\"example\">Example:</h6>\n\n<blockquote>\n  <div class=\"pdoc-code codehilite\">\n<pre><span></span><code><span class=\"gp\">&gt;&gt;&gt; </span><span class=\"kn\">from</span><span class=\"w\"> </span><span class=\"nn\">dftscape.core.graph</span><span class=\"w\"> </span><span class=\"kn\">import</span> <span class=\"n\">SearchableCriticalPointGraph</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"kn\">from</span><span class=\"w\"> </span><span class=\"nn\">dftscape.core.point</span><span class=\"w\"> </span><span class=\"kn\">import</span> <span class=\"n\">CriticalPoint</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"kn\">import</span><span class=\"w\"> </span><span class=\"nn\">numpy</span><span class=\"w\"> </span><span class=\"k\">as</span><span class=\"w\"> </span><span class=\"nn\">np</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Create searchable graph</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">graph</span> <span class=\"o\">=</span> <span class=\"n\">SearchableCriticalPointGraph</span><span class=\"p\">(</span><span class=\"n\">threshold</span><span class=\"o\">=</span><span class=\"mf\">0.1</span><span class=\"p\">,</span> <span class=\"n\">distance_function</span><span class=\"o\">=</span><span class=\"s2\">&quot;rmsd&quot;</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Add critical points</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">point1</span> <span class=\"o\">=</span> <span class=\"n\">CriticalPoint</span><span class=\"p\">(</span><span class=\"o\">...</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">graph</span><span class=\"o\">.</span><span class=\"n\">add</span><span class=\"p\">(</span><span class=\"n\">point1</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Track processing state for different search procedures</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">graph</span><span class=\"o\">.</span><span class=\"n\">mark_processed</span><span class=\"p\">(</span><span class=\"s2\">&quot;H 0.0 0.0 0.0&quot;</span><span class=\"p\">,</span> <span class=\"s2\">&quot;upward_search&quot;</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">graph</span><span class=\"o\">.</span><span class=\"n\">mark_processed</span><span class=\"p\">(</span><span class=\"s2\">&quot;H 1.0 0.0 0.0&quot;</span><span class=\"p\">,</span> <span class=\"s2\">&quot;downward_search&quot;</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Check if nodes have been processed by specific procedures</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">is_processed</span> <span class=\"o\">=</span> <span class=\"n\">graph</span><span class=\"o\">.</span><span class=\"n\">is_processed</span><span class=\"p\">(</span><span class=\"s2\">&quot;H 0.0 0.0 0.0&quot;</span><span class=\"p\">,</span> <span class=\"s2\">&quot;upward_search&quot;</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"sa\">f</span><span class=\"s2\">&quot;Node processed by upward_search: </span><span class=\"si\">{</span><span class=\"n\">is_processed</span><span class=\"si\">}</span><span class=\"s2\">&quot;</span><span class=\"p\">)</span>\n</code></pre>\n  </div>\n</blockquote>\n", "bases": "dftscape.core.graph.CriticalPointGraph"}, {"fullname": "dftscape.core.SearchableCriticalPointGraph.__init__", "modulename": "dftscape.core", "qualname": "SearchableCriticalPointGraph.__init__", "kind": "function", "doc": "<p>Initialize with multi-procedure search state tracking.</p>\n", "signature": "<span class=\"signature pdoc-code multiline\">(<span class=\"param\">\t<span class=\"n\">threshold</span><span class=\"p\">:</span> <span class=\"nb\">float</span> <span class=\"o\">=</span> <span class=\"mf\">0.1</span>,</span><span class=\"param\">\t<span class=\"n\">distance_function</span><span class=\"p\">:</span> <span class=\"nb\">str</span> <span class=\"o\">|</span> <span class=\"n\">dftscape</span><span class=\"o\">.</span><span class=\"n\">common</span><span class=\"o\">.</span><span class=\"n\">distance</span><span class=\"o\">.</span><span class=\"n\">DistanceFunction</span> <span class=\"o\">=</span> <span class=\"s1\">&#39;rmsd&#39;</span>,</span><span class=\"param\">\t<span class=\"o\">**</span><span class=\"n\">distance_kwargs</span><span class=\"p\">:</span> <span class=\"n\">Any</span></span>)</span>"}, {"fullname": "dftscape.core.SearchableCriticalPointGraph.mark_processed", "modulename": "dftscape.core", "qualname": "SearchableCriticalPointGraph.mark_processed", "kind": "function", "doc": "<p>Mark a node as processed by a specific search procedure.</p>\n\n<p>Parameters:\nnode_id: Node identifier (XYZ string)\nsearch_procedure: Name of the search procedure (e.g., 'upward', 'downward')</p>\n", "signature": "<span class=\"signature pdoc-code condensed\">(<span class=\"param\"><span class=\"bp\">self</span>, </span><span class=\"param\"><span class=\"n\">node_id</span><span class=\"p\">:</span> <span class=\"nb\">str</span>, </span><span class=\"param\"><span class=\"n\">search_procedure</span><span class=\"p\">:</span> <span class=\"nb\">str</span></span><span class=\"return-annotation\">) -> <span class=\"kc\">None</span>:</span></span>", "funcdef": "def"}, {"fullname": "dftscape.core.SearchableCriticalPointGraph.mark_processing", "modulename": "dftscape.core", "qualname": "SearchableCriticalPointGraph.mark_processing", "kind": "function", "doc": "<p>Mark a node as currently being processed by a specific search procedure.</p>\n\n<p>Parameters:\nnode_id: Node identifier (XYZ string)\nsearch_procedure: Name of the search procedure (e.g., 'upward', 'downward')</p>\n", "signature": "<span class=\"signature pdoc-code condensed\">(<span class=\"param\"><span class=\"bp\">self</span>, </span><span class=\"param\"><span class=\"n\">node_id</span><span class=\"p\">:</span> <span class=\"nb\">str</span>, </span><span class=\"param\"><span class=\"n\">search_procedure</span><span class=\"p\">:</span> <span class=\"nb\">str</span></span><span class=\"return-annotation\">) -> <span class=\"kc\">None</span>:</span></span>", "funcdef": "def"}, {"fullname": "dftscape.core.SearchableCriticalPointGraph.is_processed", "modulename": "dftscape.core", "qualname": "SearchableCriticalPointGraph.is_processed", "kind": "function", "doc": "<p>Check if a node has been processed by a specific search procedure.</p>\n\n<p>Parameters:\nnode_id: Node identifier (XYZ string)\nsearch_procedure: Name of the search procedure</p>\n\n<p>Returns:\nbool: True if processed by this procedure</p>\n", "signature": "<span class=\"signature pdoc-code condensed\">(<span class=\"param\"><span class=\"bp\">self</span>, </span><span class=\"param\"><span class=\"n\">node_id</span><span class=\"p\">:</span> <span class=\"nb\">str</span>, </span><span class=\"param\"><span class=\"n\">search_procedure</span><span class=\"p\">:</span> <span class=\"nb\">str</span></span><span class=\"return-annotation\">) -> <span class=\"nb\">bool</span>:</span></span>", "funcdef": "def"}, {"fullname": "dftscape.core.SearchableCriticalPointGraph.is_processing", "modulename": "dftscape.core", "qualname": "SearchableCriticalPointGraph.is_processing", "kind": "function", "doc": "<p>Check if a node is currently being processed by a specific search procedure.</p>\n\n<p>Parameters:\nnode_id: Node identifier (XYZ string)\nsearch_procedure: Name of the search procedure</p>\n\n<p>Returns:\nbool: True if currently being processed by this procedure</p>\n", "signature": "<span class=\"signature pdoc-code condensed\">(<span class=\"param\"><span class=\"bp\">self</span>, </span><span class=\"param\"><span class=\"n\">node_id</span><span class=\"p\">:</span> <span class=\"nb\">str</span>, </span><span class=\"param\"><span class=\"n\">search_procedure</span><span class=\"p\">:</span> <span class=\"nb\">str</span></span><span class=\"return-annotation\">) -> <span class=\"nb\">bool</span>:</span></span>", "funcdef": "def"}, {"fullname": "dftscape.core.SearchableCriticalPointGraph.get_unprocessed_nodes", "modulename": "dftscape.core", "qualname": "SearchableCriticalPointGraph.get_unprocessed_nodes", "kind": "function", "doc": "<p>Get all nodes that haven't been processed by a specific search procedure.</p>\n\n<p>Parameters:\nsearch_procedure: Name of the search procedure</p>\n\n<p>Returns:\nSet of node IDs that are unprocessed by this procedure</p>\n", "signature": "<span class=\"signature pdoc-code condensed\">(<span class=\"param\"><span class=\"bp\">self</span>, </span><span class=\"param\"><span class=\"n\">search_procedure</span><span class=\"p\">:</span> <span class=\"nb\">str</span></span><span class=\"return-annotation\">) -> <span class=\"n\">Set</span><span class=\"p\">[</span><span class=\"nb\">str</span><span class=\"p\">]</span>:</span></span>", "funcdef": "def"}, {"fullname": "dftscape.core.SearchableCriticalPointGraph.get_processing_nodes", "modulename": "dftscape.core", "qualname": "SearchableCriticalPointGraph.get_processing_nodes", "kind": "function", "doc": "<p>Get all nodes that are currently being processed by a specific search procedure.</p>\n\n<p>Parameters:\nsearch_procedure: Name of the search procedure</p>\n\n<p>Returns:\nSet of node IDs that are currently being processed by this procedure</p>\n", "signature": "<span class=\"signature pdoc-code condensed\">(<span class=\"param\"><span class=\"bp\">self</span>, </span><span class=\"param\"><span class=\"n\">search_procedure</span><span class=\"p\">:</span> <span class=\"nb\">str</span></span><span class=\"return-annotation\">) -> <span class=\"n\">Set</span><span class=\"p\">[</span><span class=\"nb\">str</span><span class=\"p\">]</span>:</span></span>", "funcdef": "def"}, {"fullname": "dftscape.core.SearchableCriticalPointGraph.get_next_to_process", "modulename": "dftscape.core", "qualname": "SearchableCriticalPointGraph.get_next_to_process", "kind": "function", "doc": "<p></p>\n", "signature": "<span class=\"signature pdoc-code condensed\">(<span class=\"param\"><span class=\"bp\">self</span>, </span><span class=\"param\"><span class=\"n\">search_procedure</span><span class=\"p\">:</span> <span class=\"nb\">str</span></span><span class=\"return-annotation\">) -> <span class=\"nb\">str</span>:</span></span>", "funcdef": "def"}, {"fullname": "dftscape.core.SearchableCriticalPointGraph.get_search_procedures", "modulename": "dftscape.core", "qualname": "SearchableCriticalPointGraph.get_search_procedures", "kind": "function", "doc": "<p>Get list of all registered search procedures.</p>\n", "signature": "<span class=\"signature pdoc-code condensed\">(<span class=\"param\"><span class=\"bp\">self</span></span><span class=\"return-annotation\">) -> <span class=\"n\">List</span><span class=\"p\">[</span><span class=\"nb\">str</span><span class=\"p\">]</span>:</span></span>", "funcdef": "def"}, {"fullname": "dftscape.core.SearchableCriticalPointGraph.get_processing_stats", "modulename": "dftscape.core", "qualname": "SearchableCriticalPointGraph.get_processing_stats", "kind": "function", "doc": "<p>Get processing statistics for a search procedure.</p>\n\n<p>Parameters:\nsearch_procedure: Name of the search procedure</p>\n\n<p>Returns:\nDict with counts: total_nodes, processed, processing, unprocessed</p>\n", "signature": "<span class=\"signature pdoc-code condensed\">(<span class=\"param\"><span class=\"bp\">self</span>, </span><span class=\"param\"><span class=\"n\">search_procedure</span><span class=\"p\">:</span> <span class=\"nb\">str</span></span><span class=\"return-annotation\">) -> <span class=\"n\">Dict</span><span class=\"p\">[</span><span class=\"nb\">str</span><span class=\"p\">,</span> <span class=\"nb\">int</span><span class=\"p\">]</span>:</span></span>", "funcdef": "def"}, {"fullname": "dftscape.core.SearchableCriticalPointGraph.to_config", "modulename": "dftscape.core", "qualname": "SearchableCriticalPointGraph.to_config", "kind": "function", "doc": "<p>Serialize the graph to a configuration dictionary.</p>\n", "signature": "<span class=\"signature pdoc-code condensed\">(<span class=\"param\"><span class=\"bp\">self</span></span><span class=\"return-annotation\">) -> <span class=\"n\">Dict</span><span class=\"p\">[</span><span class=\"nb\">str</span><span class=\"p\">,</span> <span class=\"n\">Any</span><span class=\"p\">]</span>:</span></span>", "funcdef": "def"}, {"fullname": "dftscape.core.SearchableCriticalPointGraph.from_config", "modulename": "dftscape.core", "qualname": "SearchableCriticalPointGraph.from_config", "kind": "function", "doc": "<p>Create CriticalPointGraph from configuration dictionary.</p>\n", "signature": "<span class=\"signature pdoc-code condensed\">(<span class=\"param\"><span class=\"bp\">cls</span>, </span><span class=\"param\"><span class=\"n\">graph_data</span></span><span class=\"return-annotation\">) -> <span class=\"n\">dftscape</span><span class=\"o\">.</span><span class=\"n\">core</span><span class=\"o\">.</span><span class=\"n\">graph</span><span class=\"o\">.</span><span class=\"n\">SearchableCriticalPointGraph</span>:</span></span>", "funcdef": "def"}, {"fullname": "dftscape.core.SearchableCriticalPointGraph.report", "modulename": "dftscape.core", "qualname": "SearchableCriticalPointGraph.report", "kind": "function", "doc": "<p>Generate a comprehensive summary report of the searchable graph status.</p>\n\n<p>This extends the base CriticalPointGraph report with search procedure information.</p>\n\n<h6 id=\"returns\">Returns:</h6>\n\n<blockquote>\n  <p>str: Formatted report string with graph statistics and search status</p>\n</blockquote>\n", "signature": "<span class=\"signature pdoc-code condensed\">(<span class=\"param\"><span class=\"bp\">self</span>, </span><span class=\"param\"><span class=\"n\">show_search_status</span><span class=\"p\">:</span> <span class=\"nb\">bool</span> <span class=\"o\">=</span> <span class=\"kc\">False</span></span><span class=\"return-annotation\">) -> <span class=\"nb\">str</span>:</span></span>", "funcdef": "def"}, {"fullname": "dftscape.core.SearchOrchestrator", "modulename": "dftscape.core", "qualname": "SearchOrchestrator", "kind": "class", "doc": "<p>Main orchestrator for DFTScape search algorithms.</p>\n\n<p>This class serves as the central coordinator for high-dimensional search operations\nin DFTScape, managing the complete lifecycle of molecular landscape exploration.\nIt orchestrates the interaction between search strategies, job execution, graph\nmanagement, and monitoring systems to provide robust and efficient search capabilities.</p>\n\n<p>Key Features:</p>\n\n<ul>\n<li><strong>Dual Search Modes</strong>: Separate upward and downward search algorithms</li>\n<li><strong>Strategy Pattern</strong>: Pluggable search strategies for different algorithms</li>\n<li><strong>Job Lifecycle Management</strong>: Complete job creation, execution, and tracking</li>\n<li><strong>Graph Coordination</strong>: Integration with SearchableCriticalPointGraph</li>\n<li><strong>State Management</strong>: Comprehensive node processing state tracking</li>\n<li><strong>Progress Monitoring</strong>: Real-time monitoring with detailed statistics</li>\n<li><strong>Checkpoint Support</strong>: Full state persistence and restoration</li>\n<li><strong>Callback Integration</strong>: Extensible callback system for custom logic</li>\n<li><strong>Error Resilience</strong>: Robust error handling and recovery mechanisms</li>\n</ul>\n\n<p>The orchestrator coordinates these core components:</p>\n\n<ul>\n<li><strong>Search Strategies</strong>: FirstNontrivialUpwardSearchStrategy and ExhaustiveDownwardSearchStrategy</li>\n<li><strong>Job Management</strong>: JobQueues for scheduling, JobTracker for lifecycle tracking</li>\n<li><strong>Execution</strong>: JobExecutor for running HiSD calculations</li>\n<li><strong>State Tracking</strong>: NodeStateManager for processing coordination</li>\n<li><strong>Monitoring</strong>: SearchMonitor for performance analytics</li>\n<li><strong>Persistence</strong>: CheckpointRegistry for state management</li>\n</ul>\n\n<h6 id=\"attributes\">Attributes:</h6>\n\n<ul>\n<li><strong>graph (SearchableCriticalPointGraph):</strong>  The searchable graph containing critical points</li>\n<li><strong>job_queues (JobQueues):</strong>  Manager for pending job queues</li>\n<li><strong>d_max (Optional[int]):</strong>  Maximum search order for upward search (None = unlimited)</li>\n<li><strong>job_tracker (JobTracker):</strong>  Tracker for job lifecycle and dependencies</li>\n<li><strong>node_states (NodeStateManager):</strong>  Manager for node processing states</li>\n<li><strong>executor (JobExecutor):</strong>  Executor for running HiSD jobs</li>\n<li><strong>perturbation_magnitude (float):</strong>  Default perturbation magnitude for job spawning</li>\n<li><strong>upward_strategy (FirstNontrivialUpwardSearchStrategy):</strong>  Strategy for upward search</li>\n<li><strong>downward_strategy (ExhaustiveDownwardSearchStrategy):</strong>  Strategy for downward search</li>\n<li><strong>callbacks (Optional[List[OrchestratorCallback]]):</strong>  Callbacks for state change events</li>\n<li><strong>monitor (SearchMonitor):</strong>  Monitor for search performance and statistics</li>\n</ul>\n\n<h6 id=\"usage-examples\">Usage Examples:</h6>\n\n<blockquote>\n  <div class=\"pdoc-code codehilite\">\n<pre><span></span><code><span class=\"gp\">&gt;&gt;&gt; </span><span class=\"kn\">from</span><span class=\"w\"> </span><span class=\"nn\">dftscape.core.search_orchestrator</span><span class=\"w\"> </span><span class=\"kn\">import</span> <span class=\"n\">SearchOrchestrator</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"kn\">from</span><span class=\"w\"> </span><span class=\"nn\">dftscape.core.graph</span><span class=\"w\"> </span><span class=\"kn\">import</span> <span class=\"n\">SearchableCriticalPointGraph</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"kn\">from</span><span class=\"w\"> </span><span class=\"nn\">dftscape.core.job_queues</span><span class=\"w\"> </span><span class=\"kn\">import</span> <span class=\"n\">JobQueues</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Initialize components</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">graph</span> <span class=\"o\">=</span> <span class=\"n\">SearchableCriticalPointGraph</span><span class=\"p\">(</span><span class=\"n\">threshold</span><span class=\"o\">=</span><span class=\"mf\">0.1</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">job_queues</span> <span class=\"o\">=</span> <span class=\"n\">JobQueues</span><span class=\"p\">()</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">hisd_runner</span> <span class=\"o\">=</span> <span class=\"n\">HiSDRunner</span><span class=\"p\">(</span><span class=\"o\">...</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Create orchestrator with custom parameters</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">orchestrator</span> <span class=\"o\">=</span> <span class=\"n\">SearchOrchestrator</span><span class=\"p\">(</span>\n<span class=\"gp\">... </span>    <span class=\"n\">graph</span><span class=\"o\">=</span><span class=\"n\">graph</span><span class=\"p\">,</span>\n<span class=\"gp\">... </span>    <span class=\"n\">job_queues</span><span class=\"o\">=</span><span class=\"n\">job_queues</span><span class=\"p\">,</span>\n<span class=\"gp\">... </span>    <span class=\"n\">hisd_runner</span><span class=\"o\">=</span><span class=\"n\">hisd_runner</span><span class=\"p\">,</span>\n<span class=\"gp\">... </span>    <span class=\"n\">d_max</span><span class=\"o\">=</span><span class=\"mi\">3</span><span class=\"p\">,</span>  <span class=\"c1\"># Limit search depth</span>\n<span class=\"gp\">... </span>    <span class=\"n\">perturbation_magnitude</span><span class=\"o\">=</span><span class=\"mf\">0.05</span>  <span class=\"c1\"># Smaller perturbations</span>\n<span class=\"gp\">... </span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Run upward search</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">orchestrator</span><span class=\"o\">.</span><span class=\"n\">run_upward_search</span><span class=\"p\">()</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Check progress</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"k\">if</span> <span class=\"n\">orchestrator</span><span class=\"o\">.</span><span class=\"n\">is_upward_search_complete</span><span class=\"p\">():</span>\n<span class=\"gp\">... </span>    <span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"s2\">&quot;Upward search finished!&quot;</span><span class=\"p\">)</span>\n<span class=\"gp\">... </span>    <span class=\"n\">orchestrator</span><span class=\"o\">.</span><span class=\"n\">run_downward_search</span><span class=\"p\">()</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Run complete search</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">orchestrator</span><span class=\"o\">.</span><span class=\"n\">run_full_search</span><span class=\"p\">()</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Get comprehensive report</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">report</span> <span class=\"o\">=</span> <span class=\"n\">orchestrator</span><span class=\"o\">.</span><span class=\"n\">report</span><span class=\"p\">()</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"n\">report</span><span class=\"p\">)</span>\n</code></pre>\n  </div>\n</blockquote>\n\n<h6 id=\"advanced-configuration\">Advanced Configuration:</h6>\n\n<blockquote>\n  <div class=\"pdoc-code codehilite\">\n<pre><span></span><code><span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># With custom callbacks</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"kn\">from</span><span class=\"w\"> </span><span class=\"nn\">dftscape.core.callbacks</span><span class=\"w\"> </span><span class=\"kn\">import</span> <span class=\"n\">OrchestratorCallback</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"k\">class</span><span class=\"w\"> </span><span class=\"nc\">ProgressCallback</span><span class=\"p\">(</span><span class=\"n\">OrchestratorCallback</span><span class=\"p\">):</span>\n<span class=\"gp\">... </span>    <span class=\"k\">def</span><span class=\"w\"> </span><span class=\"nf\">on_state_change</span><span class=\"p\">(</span><span class=\"bp\">self</span><span class=\"p\">,</span> <span class=\"n\">orchestrator</span><span class=\"p\">):</span>\n<span class=\"gp\">... </span>        <span class=\"n\">stats</span> <span class=\"o\">=</span> <span class=\"n\">orchestrator</span><span class=\"o\">.</span><span class=\"n\">monitor</span><span class=\"o\">.</span><span class=\"n\">get_search_statistics</span><span class=\"p\">(</span><span class=\"s2\">&quot;upward&quot;</span><span class=\"p\">)</span>\n<span class=\"gp\">... </span>        <span class=\"k\">if</span> <span class=\"n\">stats</span><span class=\"p\">:</span>\n<span class=\"gp\">... </span>            <span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"sa\">f</span><span class=\"s2\">&quot;Progress: </span><span class=\"si\">{</span><span class=\"n\">stats</span><span class=\"o\">.</span><span class=\"n\">completed_jobs</span><span class=\"si\">}</span><span class=\"s2\">/</span><span class=\"si\">{</span><span class=\"n\">stats</span><span class=\"o\">.</span><span class=\"n\">total_jobs</span><span class=\"si\">}</span><span class=\"s2\"> jobs&quot;</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">orchestrator</span> <span class=\"o\">=</span> <span class=\"n\">SearchOrchestrator</span><span class=\"p\">(</span>\n<span class=\"gp\">... </span>    <span class=\"n\">graph</span><span class=\"o\">=</span><span class=\"n\">graph</span><span class=\"p\">,</span>\n<span class=\"gp\">... </span>    <span class=\"n\">job_queues</span><span class=\"o\">=</span><span class=\"n\">job_queues</span><span class=\"p\">,</span>\n<span class=\"gp\">... </span>    <span class=\"n\">hisd_runner</span><span class=\"o\">=</span><span class=\"n\">hisd_runner</span><span class=\"p\">,</span>\n<span class=\"gp\">... </span>    <span class=\"n\">callbacks</span><span class=\"o\">=</span><span class=\"p\">[</span><span class=\"n\">ProgressCallback</span><span class=\"p\">()]</span>\n<span class=\"gp\">... </span><span class=\"p\">)</span>\n</code></pre>\n  </div>\n</blockquote>\n\n<h6 id=\"integration-notes\">Integration Notes:</h6>\n\n<blockquote>\n  <ul>\n  <li>The orchestrator automatically manages job dependencies and execution order</li>\n  <li>Node states are tracked separately for upward and downward searches</li>\n  <li>The d_max parameter prevents exponential growth in upward search</li>\n  <li>Callbacks are triggered after significant events (state changes, graph changes)</li>\n  <li>The monitor provides detailed statistics and progress tracking</li>\n  <li>Checkpoint functionality enables resuming long-running searches</li>\n  </ul>\n</blockquote>\n\n<h6 id=\"performance-considerations\">Performance Considerations:</h6>\n\n<blockquote>\n  <ul>\n  <li>Large graphs benefit from periodic checkpointing</li>\n  <li>The perturbation_magnitude affects search thoroughness vs. efficiency</li>\n  <li>Job batching reduces overhead in high-throughput scenarios</li>\n  <li>Parallel execution (when available) significantly improves performance</li>\n  <li>Memory usage scales with graph size and job queue depth</li>\n  </ul>\n</blockquote>\n"}, {"fullname": "dftscape.core.SearchOrchestrator.__init__", "modulename": "dftscape.core", "qualname": "SearchOrchestrator.__init__", "kind": "function", "doc": "<p>Initialize the search orchestrator.</p>\n\n<p>Creates a fully configured orchestrator instance with all necessary components\nfor running high-dimensional search algorithms. The orchestrator sets up\nsearch strategies, job management systems, and monitoring infrastructure.</p>\n\n<h6 id=\"arguments\">Arguments:</h6>\n\n<ul>\n<li><strong>graph:</strong>  The searchable graph to work with. This contains the critical\npoints and provides methods for adding nodes, edges, and distance\ncalculations. The graph serves as the central data structure\nfor the search process.</li>\n<li><strong>job_queues:</strong>  The job queues manager for handling pending jobs. This\ncomponent manages job scheduling, prioritization, and\nexecution order for both upward and downward searches.</li>\n<li><strong>hisd_runner:</strong>  The HiSD runner for executing quantum chemistry calculations.\nThis interface abstracts the computational backend and\nprovides methods for running HiSD calculations and\nextracting critical points.</li>\n<li><strong>d_max:</strong>  Maximum search order (Morse index) for upward search. When\nspecified, nodes with index &gt;= d_max will not spawn new jobs,\npreventing exponential growth. If None, no limit is applied.\nTypical values: 2-5 depending on system size and computational\nresources.</li>\n<li><strong>perturbation_magnitude:</strong>  Default magnitude for coordinate perturbations\nwhen spawning search jobs. This affects the\nexploration radius around each critical point.\nSmaller values (0.01-0.05) provide more precise\nbut slower searches; larger values (0.1-0.2)\nenable broader exploration but may miss details.</li>\n<li><strong>callbacks:</strong>  Optional list of callback instances to be notified after\njob batch execution. Callbacks receive the orchestrator\ninstance and can implement custom logic for monitoring,\nlogging, or integration with external systems.</li>\n</ul>\n\n<h6 id=\"raises\">Raises:</h6>\n\n<ul>\n<li><strong>TypeError:</strong>  If required parameters are missing or have incorrect types</li>\n<li><strong>ValueError:</strong>  If parameter values are invalid (e.g., negative d_max)</li>\n</ul>\n\n<h6 id=\"example\">Example:</h6>\n\n<blockquote>\n  <div class=\"pdoc-code codehilite\">\n<pre><span></span><code><span class=\"gp\">&gt;&gt;&gt; </span><span class=\"kn\">from</span><span class=\"w\"> </span><span class=\"nn\">dftscape.core.search_orchestrator</span><span class=\"w\"> </span><span class=\"kn\">import</span> <span class=\"n\">SearchOrchestrator</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"kn\">from</span><span class=\"w\"> </span><span class=\"nn\">dftscape.core.graph</span><span class=\"w\"> </span><span class=\"kn\">import</span> <span class=\"n\">SearchableCriticalPointGraph</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"kn\">from</span><span class=\"w\"> </span><span class=\"nn\">dftscape.core.job_queues</span><span class=\"w\"> </span><span class=\"kn\">import</span> <span class=\"n\">JobQueues</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Basic initialization</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">orchestrator</span> <span class=\"o\">=</span> <span class=\"n\">SearchOrchestrator</span><span class=\"p\">(</span>\n<span class=\"gp\">... </span>    <span class=\"n\">graph</span><span class=\"o\">=</span><span class=\"n\">SearchableCriticalPointGraph</span><span class=\"p\">(</span><span class=\"n\">threshold</span><span class=\"o\">=</span><span class=\"mf\">0.1</span><span class=\"p\">),</span>\n<span class=\"gp\">... </span>    <span class=\"n\">job_queues</span><span class=\"o\">=</span><span class=\"n\">JobQueues</span><span class=\"p\">(),</span>\n<span class=\"gp\">... </span>    <span class=\"n\">hisd_runner</span><span class=\"o\">=</span><span class=\"n\">my_hisd_runner</span>\n<span class=\"gp\">... </span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Advanced configuration</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">orchestrator</span> <span class=\"o\">=</span> <span class=\"n\">SearchOrchestrator</span><span class=\"p\">(</span>\n<span class=\"gp\">... </span>    <span class=\"n\">graph</span><span class=\"o\">=</span><span class=\"n\">my_graph</span><span class=\"p\">,</span>\n<span class=\"gp\">... </span>    <span class=\"n\">job_queues</span><span class=\"o\">=</span><span class=\"n\">my_queues</span><span class=\"p\">,</span>\n<span class=\"gp\">... </span>    <span class=\"n\">hisd_runner</span><span class=\"o\">=</span><span class=\"n\">my_hisd_runner</span><span class=\"p\">,</span>\n<span class=\"gp\">... </span>    <span class=\"n\">d_max</span><span class=\"o\">=</span><span class=\"mi\">3</span><span class=\"p\">,</span>  <span class=\"c1\"># Limit to Morse index 3</span>\n<span class=\"gp\">... </span>    <span class=\"n\">perturbation_magnitude</span><span class=\"o\">=</span><span class=\"mf\">0.05</span><span class=\"p\">,</span>  <span class=\"c1\"># Precise search</span>\n<span class=\"gp\">... </span>    <span class=\"n\">callbacks</span><span class=\"o\">=</span><span class=\"p\">[</span><span class=\"n\">my_progress_callback</span><span class=\"p\">]</span>\n<span class=\"gp\">... </span><span class=\"p\">)</span>\n</code></pre>\n  </div>\n</blockquote>\n\n<h6 id=\"notes\">Notes:</h6>\n\n<blockquote>\n  <ul>\n  <li>The orchestrator starts with serial execution (max_concurrent=1)</li>\n  <li>Search strategies are initialized with the provided perturbation_magnitude</li>\n  <li>The monitor is automatically enabled for tracking search performance</li>\n  <li>Callbacks are called after significant events like state changes</li>\n  <li>The d_max parameter only affects upward search; downward search is unlimited</li>\n  </ul>\n</blockquote>\n", "signature": "<span class=\"signature pdoc-code multiline\">(<span class=\"param\">\t<span class=\"n\">graph</span><span class=\"p\">:</span> <span class=\"n\">dftscape</span><span class=\"o\">.</span><span class=\"n\">core</span><span class=\"o\">.</span><span class=\"n\">graph</span><span class=\"o\">.</span><span class=\"n\">SearchableCriticalPointGraph</span>,</span><span class=\"param\">\t<span class=\"n\">job_queues</span><span class=\"p\">:</span> <span class=\"n\">dftscape</span><span class=\"o\">.</span><span class=\"n\">core</span><span class=\"o\">.</span><span class=\"n\">job_queues</span><span class=\"o\">.</span><span class=\"n\">JobQueues</span>,</span><span class=\"param\">\t<span class=\"n\">hisd_runner</span><span class=\"p\">:</span> <span class=\"n\">dftscape</span><span class=\"o\">.</span><span class=\"n\">core</span><span class=\"o\">.</span><span class=\"n\">interfaces</span><span class=\"o\">.</span><span class=\"n\">HiSDRunner</span>,</span><span class=\"param\">\t<span class=\"n\">d_max</span><span class=\"p\">:</span> <span class=\"n\">Optional</span><span class=\"p\">[</span><span class=\"nb\">int</span><span class=\"p\">]</span> <span class=\"o\">=</span> <span class=\"kc\">None</span>,</span><span class=\"param\">\t<span class=\"n\">perturbation_magnitude</span><span class=\"p\">:</span> <span class=\"nb\">float</span> <span class=\"o\">=</span> <span class=\"mf\">0.1</span>,</span><span class=\"param\">\t<span class=\"n\">callbacks</span><span class=\"p\">:</span> <span class=\"n\">Optional</span><span class=\"p\">[</span><span class=\"n\">List</span><span class=\"p\">[</span><span class=\"n\">dftscape</span><span class=\"o\">.</span><span class=\"n\">core</span><span class=\"o\">.</span><span class=\"n\">callbacks</span><span class=\"o\">.</span><span class=\"n\">OrchestratorCallback</span><span class=\"p\">]]</span> <span class=\"o\">=</span> <span class=\"kc\">None</span></span>)</span>"}, {"fullname": "dftscape.core.SearchOrchestrator.graph", "modulename": "dftscape.core", "qualname": "SearchOrchestrator.graph", "kind": "variable", "doc": "<p></p>\n"}, {"fullname": "dftscape.core.SearchOrchestrator.job_queues", "modulename": "dftscape.core", "qualname": "SearchOrchestrator.job_queues", "kind": "variable", "doc": "<p></p>\n"}, {"fullname": "dftscape.core.SearchOrchestrator.d_max", "modulename": "dftscape.core", "qualname": "SearchOrchestrator.d_max", "kind": "variable", "doc": "<p></p>\n"}, {"fullname": "dftscape.core.SearchOrchestrator.job_tracker", "modulename": "dftscape.core", "qualname": "SearchOrchestrator.job_tracker", "kind": "variable", "doc": "<p></p>\n"}, {"fullname": "dftscape.core.SearchOrchestrator.node_states", "modulename": "dftscape.core", "qualname": "SearchOrchestrator.node_states", "kind": "variable", "doc": "<p></p>\n"}, {"fullname": "dftscape.core.SearchOrchestrator.executor", "modulename": "dftscape.core", "qualname": "SearchOrchestrator.executor", "kind": "variable", "doc": "<p></p>\n"}, {"fullname": "dftscape.core.SearchOrchestrator.perturbation_magnitude", "modulename": "dftscape.core", "qualname": "SearchOrchestrator.perturbation_magnitude", "kind": "variable", "doc": "<p></p>\n"}, {"fullname": "dftscape.core.SearchOrchestrator.upward_strategy", "modulename": "dftscape.core", "qualname": "SearchOrchestrator.upward_strategy", "kind": "variable", "doc": "<p></p>\n"}, {"fullname": "dftscape.core.SearchOrchestrator.downward_strategy", "modulename": "dftscape.core", "qualname": "SearchOrchestrator.downward_strategy", "kind": "variable", "doc": "<p></p>\n"}, {"fullname": "dftscape.core.SearchOrchestrator.callbacks", "modulename": "dftscape.core", "qualname": "SearchOrchestrator.callbacks", "kind": "variable", "doc": "<p></p>\n"}, {"fullname": "dftscape.core.SearchOrchestrator.monitor", "modulename": "dftscape.core", "qualname": "SearchOrchestrator.monitor", "kind": "variable", "doc": "<p></p>\n", "annotation": ": dftscape.core.search_monitor.SearchMonitor"}, {"fullname": "dftscape.core.SearchOrchestrator.run_upward_search", "modulename": "dftscape.core", "qualname": "SearchOrchestrator.run_upward_search", "kind": "function", "doc": "<p>Run the upward search algorithm using the configured upward strategy.</p>\n\n<p>This method executes the upward search phase, which explores the molecular\nlandscape by finding critical points of increasing Morse index. The search\nuses the FirstNontrivialUpwardSearchStrategy with the perturbation magnitude\nspecified during initialization.</p>\n\n<p>The upward search process:</p>\n\n<ol>\n<li>Starts from existing critical points in the graph</li>\n<li>Spawns jobs to find higher-index critical points via perturbations</li>\n<li>Adds newly discovered points to the graph</li>\n<li>Continues until no new jobs can be spawned or d_max is reached</li>\n<li>Respects the d_max limit to prevent exponential growth</li>\n</ol>\n\n<p>The search completes when:</p>\n\n<ul>\n<li>All nodes have been processed for upward search</li>\n<li>The job queue is empty</li>\n<li>No new jobs can be generated (due to d_max or strategy constraints)</li>\n</ul>\n\n<h6 id=\"example\">Example:</h6>\n\n<blockquote>\n  <div class=\"pdoc-code codehilite\">\n<pre><span></span><code><span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">orchestrator</span> <span class=\"o\">=</span> <span class=\"n\">SearchOrchestrator</span><span class=\"p\">(</span><span class=\"o\">...</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">orchestrator</span><span class=\"o\">.</span><span class=\"n\">run_upward_search</span><span class=\"p\">()</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"k\">if</span> <span class=\"n\">orchestrator</span><span class=\"o\">.</span><span class=\"n\">is_upward_search_complete</span><span class=\"p\">():</span>\n<span class=\"gp\">... </span>    <span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"s2\">&quot;Upward search completed successfully&quot;</span><span class=\"p\">)</span>\n</code></pre>\n  </div>\n</blockquote>\n\n<h6 id=\"notes\">Notes:</h6>\n\n<blockquote>\n  <ul>\n  <li>This method blocks until the search completes</li>\n  <li>Progress can be monitored via the monitor attribute</li>\n  <li>The search respects the d_max parameter set during initialization</li>\n  <li>Callbacks are triggered after each job batch completion</li>\n  <li>Statistics are automatically collected and available via get_statistics()</li>\n  </ul>\n</blockquote>\n", "signature": "<span class=\"signature pdoc-code condensed\">(<span class=\"param\"><span class=\"bp\">self</span></span><span class=\"return-annotation\">) -> <span class=\"kc\">None</span>:</span></span>", "funcdef": "def"}, {"fullname": "dftscape.core.SearchOrchestrator.run_search", "modulename": "dftscape.core", "qualname": "SearchOrchestrator.run_search", "kind": "function", "doc": "<p>Run a search using the given strategy and procedure type.</p>\n\n<p>This is the core search execution method that implements the main search\nalgorithm loop. It coordinates job spawning, execution, and result processing\naccording to the specified search strategy and procedure type.</p>\n\n<p>The search algorithm follows this pattern:</p>\n\n<ol>\n<li>Initialize search state and monitoring</li>\n<li>While search is not finished:\na. Get unprocessed nodes for this procedure\nb. For each node, spawn jobs using the strategy\nc. Add spawned jobs to the execution queue\nd. Execute pending jobs and process results\ne. Log progress and trigger callbacks</li>\n<li>Finalize search and generate completion statistics</li>\n</ol>\n\n<h6 id=\"arguments\">Arguments:</h6>\n\n<ul>\n<li><strong>strategy:</strong>  The search strategy to use for job spawning. This determines\nhow jobs are generated from each critical point and what\nperturbations are applied.</li>\n<li><strong>procedure:</strong>  The search procedure type (\"upward\" or \"downward\").\nThis affects node state tracking and job spawning logic.</li>\n</ul>\n\n<h6 id=\"raises\">Raises:</h6>\n\n<ul>\n<li><strong>ValueError:</strong>  If procedure is not \"upward\" or \"downward\"</li>\n<li><strong>RuntimeError:</strong>  If strategy execution fails critically</li>\n</ul>\n\n<h6 id=\"example\">Example:</h6>\n\n<blockquote>\n  <div class=\"pdoc-code codehilite\">\n<pre><span></span><code><span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Run upward search</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">orchestrator</span><span class=\"o\">.</span><span class=\"n\">run_search</span><span class=\"p\">(</span><span class=\"n\">orchestrator</span><span class=\"o\">.</span><span class=\"n\">upward_strategy</span><span class=\"p\">,</span> <span class=\"s2\">&quot;upward&quot;</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Run downward search</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">orchestrator</span><span class=\"o\">.</span><span class=\"n\">run_search</span><span class=\"p\">(</span><span class=\"n\">orchestrator</span><span class=\"o\">.</span><span class=\"n\">downward_strategy</span><span class=\"p\">,</span> <span class=\"s2\">&quot;downward&quot;</span><span class=\"p\">)</span>\n</code></pre>\n  </div>\n</blockquote>\n\n<h6 id=\"notes\">Notes:</h6>\n\n<blockquote>\n  <ul>\n  <li>This method blocks until the search completes</li>\n  <li>Job execution is batched for efficiency</li>\n  <li>Failed jobs are logged but don't stop the search</li>\n  <li>Progress is logged at regular intervals</li>\n  <li>The monitor tracks detailed statistics throughout</li>\n  </ul>\n</blockquote>\n", "signature": "<span class=\"signature pdoc-code multiline\">(<span class=\"param\">\t<span class=\"bp\">self</span>,</span><span class=\"param\">\t<span class=\"n\">strategy</span><span class=\"p\">:</span> <span class=\"n\">dftscape</span><span class=\"o\">.</span><span class=\"n\">core</span><span class=\"o\">.</span><span class=\"n\">search_strategies</span><span class=\"o\">.</span><span class=\"n\">SearchStrategy</span>,</span><span class=\"param\">\t<span class=\"n\">procedure</span><span class=\"p\">:</span> <span class=\"nb\">str</span></span><span class=\"return-annotation\">) -> <span class=\"kc\">None</span>:</span></span>", "funcdef": "def"}, {"fullname": "dftscape.core.SearchOrchestrator.run_downward_search", "modulename": "dftscape.core", "qualname": "SearchOrchestrator.run_downward_search", "kind": "function", "doc": "<p>Run the downward search algorithm using the configured downward strategy.</p>\n\n<p>This method executes the downward search phase, which explores connections\nbetween critical points by finding transition paths and lower-index saddles.\nThe search uses the ExhaustiveDownwardSearchStrategy with the perturbation\nmagnitude specified during initialization.</p>\n\n<p>The downward search process:</p>\n\n<ol>\n<li>Requires upward search to be complete first</li>\n<li>Starts from all critical points in the graph</li>\n<li>Spawns jobs to find transition paths to lower-index points</li>\n<li>Adds transition edges between connected critical points</li>\n<li>Continues until all possible transitions are explored</li>\n</ol>\n\n<p>Prerequisites:</p>\n\n<ul>\n<li>Upward search must be completed first</li>\n<li>Graph must contain critical points from upward search</li>\n<li>No d_max limit (downward search explores all connections)</li>\n</ul>\n\n<h6 id=\"raises\">Raises:</h6>\n\n<ul>\n<li><strong>RuntimeError:</strong>  If upward search is not complete</li>\n</ul>\n\n<h6 id=\"example\">Example:</h6>\n\n<blockquote>\n  <div class=\"pdoc-code codehilite\">\n<pre><span></span><code><span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">orchestrator</span> <span class=\"o\">=</span> <span class=\"n\">SearchOrchestrator</span><span class=\"p\">(</span><span class=\"o\">...</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">orchestrator</span><span class=\"o\">.</span><span class=\"n\">run_upward_search</span><span class=\"p\">()</span>  <span class=\"c1\"># Must complete first</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">orchestrator</span><span class=\"o\">.</span><span class=\"n\">run_downward_search</span><span class=\"p\">()</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"k\">if</span> <span class=\"n\">orchestrator</span><span class=\"o\">.</span><span class=\"n\">is_downward_search_complete</span><span class=\"p\">():</span>\n<span class=\"gp\">... </span>    <span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"s2\">&quot;Full landscape exploration completed&quot;</span><span class=\"p\">)</span>\n</code></pre>\n  </div>\n</blockquote>\n\n<h6 id=\"notes\">Notes:</h6>\n\n<blockquote>\n  <ul>\n  <li>This method blocks until the search completes</li>\n  <li>Downward search adds edges to the graph representing transitions</li>\n  <li>The search explores all possible connections between critical points</li>\n  <li>Progress monitoring is available via the monitor attribute</li>\n  <li>Callbacks are triggered for graph changes and state changes</li>\n  </ul>\n</blockquote>\n", "signature": "<span class=\"signature pdoc-code condensed\">(<span class=\"param\"><span class=\"bp\">self</span></span><span class=\"return-annotation\">) -> <span class=\"kc\">None</span>:</span></span>", "funcdef": "def"}, {"fullname": "dftscape.core.SearchOrchestrator.run_full_search", "modulename": "dftscape.core", "qualname": "SearchOrchestrator.run_full_search", "kind": "function", "doc": "<p>Run the complete search algorithm: upward search followed by downward search.</p>\n\n<p>This method provides a convenient way to execute the full landscape exploration\nprocess, automatically sequencing the upward and downward search phases. It\nuses the strategies' configured perturbation magnitudes and respects all\ninitialization parameters.</p>\n\n<p>The full search process:</p>\n\n<ol>\n<li>Execute upward search to find all critical points</li>\n<li>Verify upward search completion</li>\n<li>Execute downward search to find all transition connections</li>\n<li>Generate final completion statistics</li>\n</ol>\n\n<p>This is equivalent to calling:</p>\n\n<div class=\"pdoc-code codehilite\">\n<pre><span></span><code><span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">orchestrator</span><span class=\"o\">.</span><span class=\"n\">run_upward_search</span><span class=\"p\">()</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"k\">if</span> <span class=\"n\">orchestrator</span><span class=\"o\">.</span><span class=\"n\">is_upward_search_complete</span><span class=\"p\">():</span>\n<span class=\"gp\">... </span>    <span class=\"n\">orchestrator</span><span class=\"o\">.</span><span class=\"n\">run_downward_search</span><span class=\"p\">()</span>\n</code></pre>\n</div>\n\n<h6 id=\"example\">Example:</h6>\n\n<blockquote>\n  <div class=\"pdoc-code codehilite\">\n<pre><span></span><code><span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">orchestrator</span> <span class=\"o\">=</span> <span class=\"n\">SearchOrchestrator</span><span class=\"p\">(</span><span class=\"o\">...</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">orchestrator</span><span class=\"o\">.</span><span class=\"n\">run_full_search</span><span class=\"p\">()</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"s2\">&quot;Complete landscape exploration finished&quot;</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">report</span> <span class=\"o\">=</span> <span class=\"n\">orchestrator</span><span class=\"o\">.</span><span class=\"n\">report</span><span class=\"p\">()</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"n\">report</span><span class=\"p\">)</span>\n</code></pre>\n  </div>\n</blockquote>\n\n<h6 id=\"notes\">Notes:</h6>\n\n<blockquote>\n  <ul>\n  <li>This method blocks until both search phases complete</li>\n  <li>If upward search fails to complete, downward search is skipped</li>\n  <li>Progress monitoring covers both search phases</li>\n  <li>Final statistics include metrics from both upward and downward searches</li>\n  <li>The graph will contain all critical points and their connections</li>\n  </ul>\n</blockquote>\n", "signature": "<span class=\"signature pdoc-code condensed\">(<span class=\"param\"><span class=\"bp\">self</span></span><span class=\"return-annotation\">) -> <span class=\"kc\">None</span>:</span></span>", "funcdef": "def"}, {"fullname": "dftscape.core.SearchOrchestrator.is_upward_search_complete", "modulename": "dftscape.core", "qualname": "SearchOrchestrator.is_upward_search_complete", "kind": "function", "doc": "<p>Check if upward search is completely finished.</p>\n\n<p>Determines whether the upward search procedure has fully completed by\nverifying both job queue status and node processing state. This method\nis critical for coordinating the transition from upward to downward search.</p>\n\n<h6 id=\"returns\">Returns:</h6>\n\n<blockquote>\n  <p>True if upward job queue is empty AND all nodes have upward processing\n  completed, False otherwise.</p>\n</blockquote>\n\n<h6 id=\"notes\">Notes:</h6>\n\n<blockquote>\n  <ul>\n  <li>Checks job queue emptiness for pending upward jobs</li>\n  <li>Verifies all nodes have been processed for upward search</li>\n  <li>Used by run_downward_search() to ensure proper sequencing</li>\n  <li>Critical for preventing premature downward search initiation</li>\n  <li>Should be checked before starting downward search</li>\n  </ul>\n</blockquote>\n", "signature": "<span class=\"signature pdoc-code condensed\">(<span class=\"param\"><span class=\"bp\">self</span></span><span class=\"return-annotation\">) -> <span class=\"nb\">bool</span>:</span></span>", "funcdef": "def"}, {"fullname": "dftscape.core.SearchOrchestrator.is_downward_search_complete", "modulename": "dftscape.core", "qualname": "SearchOrchestrator.is_downward_search_complete", "kind": "function", "doc": "<p>Check if downward search is completely finished.</p>\n\n<p>Determines whether the downward search procedure has fully completed by\nverifying both job queue status and node processing state. This method\nindicates when the complete landscape exploration is finished.</p>\n\n<h6 id=\"returns\">Returns:</h6>\n\n<blockquote>\n  <p>True if downward job queue is empty AND all nodes have downward\n  processing completed, False otherwise.</p>\n</blockquote>\n\n<h6 id=\"notes\">Notes:</h6>\n\n<blockquote>\n  <ul>\n  <li>Checks job queue emptiness for pending downward jobs</li>\n  <li>Verifies all nodes have been processed for downward search</li>\n  <li>Indicates completion of full landscape exploration</li>\n  <li>Used for determining when search orchestration is finished</li>\n  <li>Can be used by external systems to monitor search progress</li>\n  </ul>\n</blockquote>\n", "signature": "<span class=\"signature pdoc-code condensed\">(<span class=\"param\"><span class=\"bp\">self</span></span><span class=\"return-annotation\">) -> <span class=\"nb\">bool</span>:</span></span>", "funcdef": "def"}, {"fullname": "dftscape.core.SearchOrchestrator.report", "modulename": "dftscape.core", "qualname": "SearchOrchestrator.report", "kind": "function", "doc": "<p>Generate a comprehensive summary report of the orchestrator search status.</p>\n\n<p>This method produces a detailed textual report by delegating to the\nmonitor and graph components' report methods, providing a unified view\nof the search state.</p>\n\n<h6 id=\"returns\">Returns:</h6>\n\n<blockquote>\n  <p>str: Multi-line formatted summary report combining monitor and graph status.</p>\n</blockquote>\n\n<h6 id=\"notes\">Notes:</h6>\n\n<blockquote>\n  <ul>\n  <li>Delegates to monitor.report() for search statistics and node processing</li>\n  <li>Delegates to graph.report() for graph topology and critical point analysis</li>\n  <li>Adds job queue status for pending work</li>\n  <li>Used for monitoring, debugging, and progress tracking</li>\n  </ul>\n</blockquote>\n", "signature": "<span class=\"signature pdoc-code condensed\">(<span class=\"param\"><span class=\"bp\">self</span></span><span class=\"return-annotation\">) -> <span class=\"nb\">str</span>:</span></span>", "funcdef": "def"}, {"fullname": "dftscape.core.SearchOrchestrator.load_checkpoint", "modulename": "dftscape.core", "qualname": "SearchOrchestrator.load_checkpoint", "kind": "function", "doc": "<p>Load a SearchOrchestrator instance from a checkpoint file.</p>\n\n<p>This class method reconstructs a SearchOrchestrator from a previously\nsaved checkpoint, restoring the search state including graph topology,\njob queues, and configuration parameters. It handles version compatibility\nand provides fallbacks for missing or corrupted data.</p>\n\n<h6 id=\"arguments\">Arguments:</h6>\n\n<ul>\n<li><strong>checkpoint_path:</strong>  Path to the JSON checkpoint file containing the\nserialized orchestrator state.</li>\n<li><strong>graph:</strong>  The SearchableCriticalPointGraph instance to use. If the\ncheckpoint contains graph data, it will be loaded into this graph.</li>\n<li><strong>hisd_runner:</strong>  The HiSDRunner instance to use for job execution.</li>\n<li><strong>callbacks:</strong>  Optional list of OrchestratorCallback instances to be\nnotified of job completion events.</li>\n</ul>\n\n<h6 id=\"returns\">Returns:</h6>\n\n<blockquote>\n  <p>SearchOrchestrator: A fully restored orchestrator instance ready to\n                    resume search operations from the checkpoint state.</p>\n</blockquote>\n\n<h6 id=\"raises\">Raises:</h6>\n\n<ul>\n<li><strong>FileNotFoundError:</strong>  If the checkpoint file does not exist.</li>\n<li><strong>JSONDecodeError:</strong>  If the checkpoint file contains invalid JSON.</li>\n<li><strong>Exception:</strong>  For other checkpoint loading or reconstruction errors.</li>\n</ul>\n\n<h6 id=\"notes\">Notes:</h6>\n\n<blockquote>\n  <ul>\n  <li>Uses JSON checkpointer for serialization/deserialization</li>\n  <li>Restores graph topology if present in checkpoint</li>\n  <li>Reconstructs job queues with fallback for missing data</li>\n  <li>Handles both JobQueues.from_config and manual reconstruction</li>\n  <li>Preserves search configuration (d_max, perturbation_magnitude)</li>\n  <li>Critical for resuming interrupted long-running searches</li>\n  </ul>\n</blockquote>\n", "signature": "<span class=\"signature pdoc-code multiline\">(<span class=\"param\">\t<span class=\"bp\">cls</span>,</span><span class=\"param\">\t<span class=\"n\">checkpoint_path</span><span class=\"p\">:</span> <span class=\"nb\">str</span>,</span><span class=\"param\">\t<span class=\"n\">graph</span><span class=\"p\">:</span> <span class=\"n\">dftscape</span><span class=\"o\">.</span><span class=\"n\">core</span><span class=\"o\">.</span><span class=\"n\">graph</span><span class=\"o\">.</span><span class=\"n\">SearchableCriticalPointGraph</span>,</span><span class=\"param\">\t<span class=\"n\">hisd_runner</span><span class=\"p\">:</span> <span class=\"n\">dftscape</span><span class=\"o\">.</span><span class=\"n\">core</span><span class=\"o\">.</span><span class=\"n\">interfaces</span><span class=\"o\">.</span><span class=\"n\">HiSDRunner</span>,</span><span class=\"param\">\t<span class=\"n\">callbacks</span><span class=\"p\">:</span> <span class=\"n\">Optional</span><span class=\"p\">[</span><span class=\"n\">List</span><span class=\"p\">[</span><span class=\"n\">dftscape</span><span class=\"o\">.</span><span class=\"n\">core</span><span class=\"o\">.</span><span class=\"n\">callbacks</span><span class=\"o\">.</span><span class=\"n\">OrchestratorCallback</span><span class=\"p\">]]</span> <span class=\"o\">=</span> <span class=\"kc\">None</span></span><span class=\"return-annotation\">) -> <span class=\"n\">dftscape</span><span class=\"o\">.</span><span class=\"n\">core</span><span class=\"o\">.</span><span class=\"n\">search_orchestrator</span><span class=\"o\">.</span><span class=\"n\">SearchOrchestrator</span>:</span></span>", "funcdef": "def"}, {"fullname": "dftscape.core.JobTracker", "modulename": "dftscape.core", "qualname": "JobTracker", "kind": "class", "doc": "<p>Central coordinator for tracking job completion and node dependencies.</p>\n\n<p>JobTracker maintains the complex relationships between computational nodes\nand their spawned jobs in the DFTScape optimization workflow. It provides\nthe orchestration system with the ability to determine when all jobs from\na particular node have completed, enabling proper workflow progression and\ndependency management.</p>\n\n<p>The tracker uses efficient data structures to maintain job status and\nprovides comprehensive querying capabilities for monitoring and control.\nIt handles the complexities of job ID matching, including partial IDs and\nvarious naming conventions used throughout the system.</p>\n\n<h6 id=\"attributes\">Attributes:</h6>\n\n<ul>\n<li><strong>pending_jobs (Dict[str, Set[str]]):</strong>  Maps node IDs to sets of job IDs\nthat are currently pending completion.\nJobs are removed as they complete.</li>\n<li><strong>completed_jobs (Dict[str, Set[str]]):</strong>  Maps node IDs to sets of job IDs\nthat have successfully completed.\nUsed for statistics and analysis.</li>\n<li><strong>job_results (Dict[str, JobResult]):</strong>  Maps job IDs to their complete\nresults for successful jobs. Failed\njobs may still have entries with\nerror information.</li>\n</ul>\n\n<h6 id=\"key-capabilities\">Key Capabilities:</h6>\n\n<blockquote>\n  <ul>\n  <li>Job lifecycle tracking from spawn to completion</li>\n  <li>Flexible job ID matching with fallback logic</li>\n  <li>Comprehensive status reporting and statistics</li>\n  <li>Result storage and retrieval for analysis</li>\n  <li>Node completion detection for workflow progression</li>\n  <li>Failure analysis and reporting</li>\n  </ul>\n</blockquote>\n\n<h6 id=\"example\">Example:</h6>\n\n<blockquote>\n  <div class=\"pdoc-code codehilite\">\n<pre><span></span><code><span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">tracker</span> <span class=\"o\">=</span> <span class=\"n\">JobTracker</span><span class=\"p\">()</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Track jobs for a node</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">tracker</span><span class=\"o\">.</span><span class=\"n\">add_jobs_for_node</span><span class=\"p\">(</span><span class=\"s2\">&quot;node_001&quot;</span><span class=\"p\">,</span> <span class=\"p\">[</span><span class=\"s2\">&quot;job_001&quot;</span><span class=\"p\">,</span> <span class=\"s2\">&quot;job_002&quot;</span><span class=\"p\">,</span> <span class=\"s2\">&quot;job_003&quot;</span><span class=\"p\">])</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Mark jobs as completed</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">result1</span> <span class=\"o\">=</span> <span class=\"n\">JobResult</span><span class=\"p\">(</span><span class=\"n\">job_id</span><span class=\"o\">=</span><span class=\"s2\">&quot;job_001&quot;</span><span class=\"p\">,</span> <span class=\"n\">success</span><span class=\"o\">=</span><span class=\"kc\">True</span><span class=\"p\">,</span> <span class=\"n\">execution_time</span><span class=\"o\">=</span><span class=\"mf\">10.0</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">tracker</span><span class=\"o\">.</span><span class=\"n\">mark_job_complete</span><span class=\"p\">(</span><span class=\"s2\">&quot;node_001&quot;</span><span class=\"p\">,</span> <span class=\"s2\">&quot;job_001&quot;</span><span class=\"p\">,</span> <span class=\"n\">result1</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Check status</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"sa\">f</span><span class=\"s2\">&quot;Pending: </span><span class=\"si\">{</span><span class=\"n\">tracker</span><span class=\"o\">.</span><span class=\"n\">get_pending_job_count</span><span class=\"p\">(</span><span class=\"s1\">&#39;node_001&#39;</span><span class=\"p\">)</span><span class=\"si\">}</span><span class=\"s2\">&quot;</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"sa\">f</span><span class=\"s2\">&quot;Completed: </span><span class=\"si\">{</span><span class=\"n\">tracker</span><span class=\"o\">.</span><span class=\"n\">get_completed_job_count</span><span class=\"p\">(</span><span class=\"s1\">&#39;node_001&#39;</span><span class=\"p\">)</span><span class=\"si\">}</span><span class=\"s2\">&quot;</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"sa\">f</span><span class=\"s2\">&quot;All done: </span><span class=\"si\">{</span><span class=\"n\">tracker</span><span class=\"o\">.</span><span class=\"n\">all_jobs_complete</span><span class=\"p\">(</span><span class=\"s1\">&#39;node_001&#39;</span><span class=\"p\">)</span><span class=\"si\">}</span><span class=\"s2\">&quot;</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Get results</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">result</span> <span class=\"o\">=</span> <span class=\"n\">tracker</span><span class=\"o\">.</span><span class=\"n\">get_job_result</span><span class=\"p\">(</span><span class=\"s2\">&quot;job_001&quot;</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"k\">if</span> <span class=\"n\">result</span><span class=\"p\">:</span>\n<span class=\"gp\">... </span>    <span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"sa\">f</span><span class=\"s2\">&quot;Job took </span><span class=\"si\">{</span><span class=\"n\">result</span><span class=\"o\">.</span><span class=\"n\">execution_time</span><span class=\"si\">:</span><span class=\"s2\">.2f</span><span class=\"si\">}</span><span class=\"s2\">s&quot;</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Analyze failures</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">failed</span> <span class=\"o\">=</span> <span class=\"n\">tracker</span><span class=\"o\">.</span><span class=\"n\">get_failed_jobs</span><span class=\"p\">(</span><span class=\"s2\">&quot;node_001&quot;</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"k\">if</span> <span class=\"n\">failed</span><span class=\"p\">:</span>\n<span class=\"gp\">... </span>    <span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"sa\">f</span><span class=\"s2\">&quot;Failed jobs: </span><span class=\"si\">{</span><span class=\"n\">failed</span><span class=\"si\">}</span><span class=\"s2\">&quot;</span><span class=\"p\">)</span>\n</code></pre>\n  </div>\n</blockquote>\n\n<h6 id=\"implementation-details\">Implementation Details:</h6>\n\n<blockquote>\n  <ul>\n  <li>Uses sets for O(1) membership testing and memory efficiency</li>\n  <li>Handles job ID matching with suffix-based fallback for robustness</li>\n  <li>Thread-safe for read operations (writes need external synchronization)</li>\n  <li>Memory usage scales with total tracked jobs and results</li>\n  <li>Job results are retained indefinitely (consider cleanup strategies)</li>\n  </ul>\n</blockquote>\n\n<h6 id=\"notes\">Notes:</h6>\n\n<blockquote>\n  <ul>\n  <li>Job IDs must be unique across the entire system</li>\n  <li>Node IDs should correspond to graph nodes in the landscape</li>\n  <li>Failed jobs don't prevent node completion detection</li>\n  <li>The tracker only monitors status, doesn't execute jobs</li>\n  <li>Consider periodic cleanup of old results for long-running workflows</li>\n  </ul>\n</blockquote>\n"}, {"fullname": "dftscape.core.JobTracker.pending_jobs", "modulename": "dftscape.core", "qualname": "JobTracker.pending_jobs", "kind": "variable", "doc": "<p></p>\n", "annotation": ": Dict[str, Set[str]]"}, {"fullname": "dftscape.core.JobTracker.completed_jobs", "modulename": "dftscape.core", "qualname": "JobTracker.completed_jobs", "kind": "variable", "doc": "<p></p>\n", "annotation": ": Dict[str, Set[str]]"}, {"fullname": "dftscape.core.JobTracker.job_results", "modulename": "dftscape.core", "qualname": "JobTracker.job_results", "kind": "variable", "doc": "<p></p>\n", "annotation": ": Dict[str, dftscape.core.job_result.JobResult]"}, {"fullname": "dftscape.core.JobTracker.add_jobs_for_node", "modulename": "dftscape.core", "qualname": "JobTracker.add_jobs_for_node", "kind": "function", "doc": "<p>Register jobs that were spawned from a specific computational node.</p>\n\n<p>This method establishes the relationship between a node and its jobs,\nallowing the tracker to monitor completion status and determine when\nall work from a node has finished. Jobs are initially marked as pending\nand will be moved to completed status as they finish.</p>\n\n<p>If the node already has tracked jobs, the new jobs are added to the\nexisting set. This allows for incremental job addition during complex\nworkflows where a node might spawn jobs in multiple batches.</p>\n\n<h6 id=\"arguments\">Arguments:</h6>\n\n<ul>\n<li><strong>node_id:</strong>  Unique identifier for the computational node that spawned\nthe jobs. Should correspond to a node in the search landscape.</li>\n<li><strong>job_ids:</strong>  List of unique job identifiers for the spawned jobs.\nEach ID must be unique across the entire tracking system.</li>\n</ul>\n\n<h6 id=\"raises\">Raises:</h6>\n\n<ul>\n<li>No exceptions are raised - new nodes and jobs are created automatically.</li>\n</ul>\n\n<h6 id=\"example\">Example:</h6>\n\n<blockquote>\n  <div class=\"pdoc-code codehilite\">\n<pre><span></span><code><span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">tracker</span> <span class=\"o\">=</span> <span class=\"n\">JobTracker</span><span class=\"p\">()</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">tracker</span><span class=\"o\">.</span><span class=\"n\">add_jobs_for_node</span><span class=\"p\">(</span><span class=\"s2\">&quot;minima_001&quot;</span><span class=\"p\">,</span> <span class=\"p\">[</span><span class=\"s2\">&quot;upward_001&quot;</span><span class=\"p\">,</span> <span class=\"s2\">&quot;upward_002&quot;</span><span class=\"p\">])</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">tracker</span><span class=\"o\">.</span><span class=\"n\">add_jobs_for_node</span><span class=\"p\">(</span><span class=\"s2\">&quot;minima_001&quot;</span><span class=\"p\">,</span> <span class=\"p\">[</span><span class=\"s2\">&quot;downward_001&quot;</span><span class=\"p\">])</span>  <span class=\"c1\"># Add more jobs</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"n\">tracker</span><span class=\"o\">.</span><span class=\"n\">get_pending_job_count</span><span class=\"p\">(</span><span class=\"s2\">&quot;minima_001&quot;</span><span class=\"p\">))</span>  <span class=\"c1\"># 3</span>\n</code></pre>\n  </div>\n</blockquote>\n\n<h6 id=\"notes\">Notes:</h6>\n\n<blockquote>\n  <ul>\n  <li>Job IDs should be unique across the entire system</li>\n  <li>Multiple calls for the same node accumulate jobs</li>\n  <li>Jobs start in pending state until marked complete</li>\n  <li>Node tracking is created automatically if it doesn't exist</li>\n  </ul>\n</blockquote>\n", "signature": "<span class=\"signature pdoc-code condensed\">(<span class=\"param\"><span class=\"bp\">self</span>, </span><span class=\"param\"><span class=\"n\">node_id</span><span class=\"p\">:</span> <span class=\"nb\">str</span>, </span><span class=\"param\"><span class=\"n\">job_ids</span><span class=\"p\">:</span> <span class=\"n\">List</span><span class=\"p\">[</span><span class=\"nb\">str</span><span class=\"p\">]</span></span><span class=\"return-annotation\">) -> <span class=\"kc\">None</span>:</span></span>", "funcdef": "def"}, {"fullname": "dftscape.core.JobTracker.mark_job_complete", "modulename": "dftscape.core", "qualname": "JobTracker.mark_job_complete", "kind": "function", "doc": "<p>Mark a job as completed and store its result for the specified node.</p>\n\n<p>This method updates the job's status from pending to completed and stores\nthe job result for later retrieval. It includes sophisticated job ID matching\nlogic to handle various naming conventions and partial ID specifications.</p>\n\n<p>The method performs the following steps:</p>\n\n<ol>\n<li>Checks for exact job ID match in the node's pending jobs</li>\n<li>If no exact match, attempts suffix-based matching for robustness</li>\n<li>Updates internal data structures to reflect completion</li>\n<li>Stores the job result for analysis and reporting</li>\n<li>Logs the completion event with appropriate detail</li>\n</ol>\n\n<h6 id=\"arguments\">Arguments:</h6>\n\n<ul>\n<li><strong>node_id:</strong>  The computational node that spawned the job. Used to locate\nthe job in the correct pending job set.</li>\n<li><strong>job_id:</strong>  The job identifier to mark as complete. Can be a full job ID\nor a suffix (e.g., \"001\" instead of \"node_upward_001\").</li>\n<li><strong>result:</strong>  Complete JobResult containing execution details, success status,\nand any computational results.</li>\n</ul>\n\n<h6 id=\"raises\">Raises:</h6>\n\n<ul>\n<li>No exceptions are raised - unmatched jobs are logged as warnings.</li>\n</ul>\n\n<h6 id=\"example\">Example:</h6>\n\n<blockquote>\n  <div class=\"pdoc-code codehilite\">\n<pre><span></span><code><span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">tracker</span> <span class=\"o\">=</span> <span class=\"n\">JobTracker</span><span class=\"p\">()</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">tracker</span><span class=\"o\">.</span><span class=\"n\">add_jobs_for_node</span><span class=\"p\">(</span><span class=\"s2\">&quot;node_001&quot;</span><span class=\"p\">,</span> <span class=\"p\">[</span><span class=\"s2\">&quot;job_001&quot;</span><span class=\"p\">,</span> <span class=\"s2\">&quot;job_002&quot;</span><span class=\"p\">])</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Mark with full job ID</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">result</span> <span class=\"o\">=</span> <span class=\"n\">JobResult</span><span class=\"p\">(</span><span class=\"n\">job_id</span><span class=\"o\">=</span><span class=\"s2\">&quot;job_001&quot;</span><span class=\"p\">,</span> <span class=\"n\">success</span><span class=\"o\">=</span><span class=\"kc\">True</span><span class=\"p\">,</span> <span class=\"n\">execution_time</span><span class=\"o\">=</span><span class=\"mf\">10.0</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">tracker</span><span class=\"o\">.</span><span class=\"n\">mark_job_complete</span><span class=\"p\">(</span><span class=\"s2\">&quot;node_001&quot;</span><span class=\"p\">,</span> <span class=\"s2\">&quot;job_001&quot;</span><span class=\"p\">,</span> <span class=\"n\">result</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Mark with suffix (fallback matching)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">tracker</span><span class=\"o\">.</span><span class=\"n\">mark_job_complete</span><span class=\"p\">(</span><span class=\"s2\">&quot;node_001&quot;</span><span class=\"p\">,</span> <span class=\"s2\">&quot;002&quot;</span><span class=\"p\">,</span> <span class=\"n\">result</span><span class=\"p\">)</span>  <span class=\"c1\"># matches &quot;job_002&quot;</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"n\">tracker</span><span class=\"o\">.</span><span class=\"n\">get_completed_job_count</span><span class=\"p\">(</span><span class=\"s2\">&quot;node_001&quot;</span><span class=\"p\">))</span>  <span class=\"c1\"># 2</span>\n</code></pre>\n  </div>\n</blockquote>\n\n<h6 id=\"notes\">Notes:</h6>\n\n<blockquote>\n  <ul>\n  <li>Job ID matching is case-sensitive</li>\n  <li>Suffix matching looks for jobs ending with the provided ID</li>\n  <li>Already completed jobs are skipped with debug logging</li>\n  <li>Unmatched jobs generate warning logs with diagnostic information</li>\n  <li>Job results are stored permanently (consider cleanup for long workflows)</li>\n  </ul>\n</blockquote>\n", "signature": "<span class=\"signature pdoc-code multiline\">(<span class=\"param\">\t<span class=\"bp\">self</span>,</span><span class=\"param\">\t<span class=\"n\">node_id</span><span class=\"p\">:</span> <span class=\"nb\">str</span>,</span><span class=\"param\">\t<span class=\"n\">job_id</span><span class=\"p\">:</span> <span class=\"nb\">str</span>,</span><span class=\"param\">\t<span class=\"n\">result</span><span class=\"p\">:</span> <span class=\"n\">dftscape</span><span class=\"o\">.</span><span class=\"n\">core</span><span class=\"o\">.</span><span class=\"n\">job_result</span><span class=\"o\">.</span><span class=\"n\">JobResult</span></span><span class=\"return-annotation\">) -> <span class=\"kc\">None</span>:</span></span>", "funcdef": "def"}, {"fullname": "dftscape.core.JobTracker.all_jobs_complete", "modulename": "dftscape.core", "qualname": "JobTracker.all_jobs_complete", "kind": "function", "doc": "<p>Check if all jobs spawned from a specific node have been completed.</p>\n\n<p>This method determines whether a computational node has finished all its\nwork by checking if there are any remaining pending jobs. It's the primary\nmechanism for the orchestrator to know when a node is ready for further\nprocessing or when the entire workflow can proceed.</p>\n\n<p>A node is considered complete when its pending job set is empty, regardless\nof whether the jobs succeeded or failed. This allows workflows to continue\neven with some failures, as failed jobs are still \"complete\" from a tracking\nperspective.</p>\n\n<h6 id=\"arguments\">Arguments:</h6>\n\n<ul>\n<li><strong>node_id:</strong>  The computational node to check for completion.</li>\n</ul>\n\n<h6 id=\"returns\">Returns:</h6>\n\n<blockquote>\n  <p>True if all jobs for the node have completed (no pending jobs remain).\n  False if there are still pending jobs for the node.</p>\n</blockquote>\n\n<h6 id=\"example\">Example:</h6>\n\n<blockquote>\n  <div class=\"pdoc-code codehilite\">\n<pre><span></span><code><span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">tracker</span> <span class=\"o\">=</span> <span class=\"n\">JobTracker</span><span class=\"p\">()</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">tracker</span><span class=\"o\">.</span><span class=\"n\">add_jobs_for_node</span><span class=\"p\">(</span><span class=\"s2\">&quot;node_001&quot;</span><span class=\"p\">,</span> <span class=\"p\">[</span><span class=\"s2\">&quot;job_001&quot;</span><span class=\"p\">,</span> <span class=\"s2\">&quot;job_002&quot;</span><span class=\"p\">])</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">tracker</span><span class=\"o\">.</span><span class=\"n\">all_jobs_complete</span><span class=\"p\">(</span><span class=\"s2\">&quot;node_001&quot;</span><span class=\"p\">)</span>  <span class=\"c1\"># False</span>\n<span class=\"go\">False</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Complete one job</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">result</span> <span class=\"o\">=</span> <span class=\"n\">JobResult</span><span class=\"p\">(</span><span class=\"n\">job_id</span><span class=\"o\">=</span><span class=\"s2\">&quot;job_001&quot;</span><span class=\"p\">,</span> <span class=\"n\">success</span><span class=\"o\">=</span><span class=\"kc\">True</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">tracker</span><span class=\"o\">.</span><span class=\"n\">mark_job_complete</span><span class=\"p\">(</span><span class=\"s2\">&quot;node_001&quot;</span><span class=\"p\">,</span> <span class=\"s2\">&quot;job_001&quot;</span><span class=\"p\">,</span> <span class=\"n\">result</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">tracker</span><span class=\"o\">.</span><span class=\"n\">all_jobs_complete</span><span class=\"p\">(</span><span class=\"s2\">&quot;node_001&quot;</span><span class=\"p\">)</span>  <span class=\"c1\"># False (still one pending)</span>\n<span class=\"go\">False</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Complete remaining job</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">tracker</span><span class=\"o\">.</span><span class=\"n\">mark_job_complete</span><span class=\"p\">(</span><span class=\"s2\">&quot;node_001&quot;</span><span class=\"p\">,</span> <span class=\"s2\">&quot;job_002&quot;</span><span class=\"p\">,</span> <span class=\"n\">result</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">tracker</span><span class=\"o\">.</span><span class=\"n\">all_jobs_complete</span><span class=\"p\">(</span><span class=\"s2\">&quot;node_001&quot;</span><span class=\"p\">)</span>  <span class=\"c1\"># True</span>\n<span class=\"go\">True</span>\n</code></pre>\n  </div>\n</blockquote>\n\n<h6 id=\"notes\">Notes:</h6>\n\n<blockquote>\n  <ul>\n  <li>Failed jobs are still considered \"complete\" for workflow progression</li>\n  <li>Unknown nodes return True (no pending jobs = complete)</li>\n  <li>This method is fast (O(1)) due to set-based storage</li>\n  <li>Used by orchestrator for dependency resolution and scheduling</li>\n  </ul>\n</blockquote>\n", "signature": "<span class=\"signature pdoc-code condensed\">(<span class=\"param\"><span class=\"bp\">self</span>, </span><span class=\"param\"><span class=\"n\">node_id</span><span class=\"p\">:</span> <span class=\"nb\">str</span></span><span class=\"return-annotation\">) -> <span class=\"nb\">bool</span>:</span></span>", "funcdef": "def"}, {"fullname": "dftscape.core.JobTracker.get_pending_job_count", "modulename": "dftscape.core", "qualname": "JobTracker.get_pending_job_count", "kind": "function", "doc": "<p>Get the number of jobs that are still pending completion for a node.</p>\n\n<p>Returns the count of jobs that have been spawned from the specified node\nbut have not yet been marked as completed. This is useful for monitoring\nprogress, load balancing, and determining how much work remains.</p>\n\n<h6 id=\"arguments\">Arguments:</h6>\n\n<ul>\n<li><strong>node_id:</strong>  The computational node to query for pending job count.</li>\n</ul>\n\n<h6 id=\"returns\">Returns:</h6>\n\n<blockquote>\n  <p>The number of pending jobs for the node. Returns 0 if the node\n  has no pending jobs or doesn't exist in the tracker.</p>\n</blockquote>\n\n<h6 id=\"example\">Example:</h6>\n\n<blockquote>\n  <div class=\"pdoc-code codehilite\">\n<pre><span></span><code><span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">tracker</span> <span class=\"o\">=</span> <span class=\"n\">JobTracker</span><span class=\"p\">()</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">tracker</span><span class=\"o\">.</span><span class=\"n\">add_jobs_for_node</span><span class=\"p\">(</span><span class=\"s2\">&quot;node_001&quot;</span><span class=\"p\">,</span> <span class=\"p\">[</span><span class=\"s2\">&quot;job_001&quot;</span><span class=\"p\">,</span> <span class=\"s2\">&quot;job_002&quot;</span><span class=\"p\">,</span> <span class=\"s2\">&quot;job_003&quot;</span><span class=\"p\">])</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">tracker</span><span class=\"o\">.</span><span class=\"n\">get_pending_job_count</span><span class=\"p\">(</span><span class=\"s2\">&quot;node_001&quot;</span><span class=\"p\">)</span>  <span class=\"c1\"># 3</span>\n<span class=\"go\">3</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Complete one job</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">result</span> <span class=\"o\">=</span> <span class=\"n\">JobResult</span><span class=\"p\">(</span><span class=\"n\">job_id</span><span class=\"o\">=</span><span class=\"s2\">&quot;job_001&quot;</span><span class=\"p\">,</span> <span class=\"n\">success</span><span class=\"o\">=</span><span class=\"kc\">True</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">tracker</span><span class=\"o\">.</span><span class=\"n\">mark_job_complete</span><span class=\"p\">(</span><span class=\"s2\">&quot;node_001&quot;</span><span class=\"p\">,</span> <span class=\"s2\">&quot;job_001&quot;</span><span class=\"p\">,</span> <span class=\"n\">result</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">tracker</span><span class=\"o\">.</span><span class=\"n\">get_pending_job_count</span><span class=\"p\">(</span><span class=\"s2\">&quot;node_001&quot;</span><span class=\"p\">)</span>  <span class=\"c1\"># 2</span>\n<span class=\"go\">2</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Check non-existent node</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">tracker</span><span class=\"o\">.</span><span class=\"n\">get_pending_job_count</span><span class=\"p\">(</span><span class=\"s2\">&quot;unknown_node&quot;</span><span class=\"p\">)</span>  <span class=\"c1\"># 0</span>\n<span class=\"go\">0</span>\n</code></pre>\n  </div>\n</blockquote>\n\n<h6 id=\"notes\">Notes:</h6>\n\n<blockquote>\n  <ul>\n  <li>This count decreases as jobs are marked complete</li>\n  <li>Unknown nodes return 0 (no pending jobs)</li>\n  <li>Used for progress monitoring and resource allocation</li>\n  <li>Fast operation due to set-based storage</li>\n  </ul>\n</blockquote>\n", "signature": "<span class=\"signature pdoc-code condensed\">(<span class=\"param\"><span class=\"bp\">self</span>, </span><span class=\"param\"><span class=\"n\">node_id</span><span class=\"p\">:</span> <span class=\"nb\">str</span></span><span class=\"return-annotation\">) -> <span class=\"nb\">int</span>:</span></span>", "funcdef": "def"}, {"fullname": "dftscape.core.JobTracker.get_completed_job_count", "modulename": "dftscape.core", "qualname": "JobTracker.get_completed_job_count", "kind": "function", "doc": "<p>Get the number of jobs that have been completed for a node.</p>\n\n<p>Returns the count of jobs that have been successfully marked as completed\nfor the specified node. This includes both successful and failed jobs,\nas both are considered \"complete\" from a workflow perspective.</p>\n\n<h6 id=\"arguments\">Arguments:</h6>\n\n<ul>\n<li><strong>node_id:</strong>  The computational node to query for completed job count.</li>\n</ul>\n\n<h6 id=\"returns\">Returns:</h6>\n\n<blockquote>\n  <p>The number of completed jobs for the node. Returns 0 if the node\n  has no completed jobs or doesn't exist in the tracker.</p>\n</blockquote>\n\n<h6 id=\"example\">Example:</h6>\n\n<blockquote>\n  <div class=\"pdoc-code codehilite\">\n<pre><span></span><code><span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">tracker</span> <span class=\"o\">=</span> <span class=\"n\">JobTracker</span><span class=\"p\">()</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">tracker</span><span class=\"o\">.</span><span class=\"n\">add_jobs_for_node</span><span class=\"p\">(</span><span class=\"s2\">&quot;node_001&quot;</span><span class=\"p\">,</span> <span class=\"p\">[</span><span class=\"s2\">&quot;job_001&quot;</span><span class=\"p\">,</span> <span class=\"s2\">&quot;job_002&quot;</span><span class=\"p\">])</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">tracker</span><span class=\"o\">.</span><span class=\"n\">get_completed_job_count</span><span class=\"p\">(</span><span class=\"s2\">&quot;node_001&quot;</span><span class=\"p\">)</span>  <span class=\"c1\"># 0</span>\n<span class=\"go\">0</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Complete jobs</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">result</span> <span class=\"o\">=</span> <span class=\"n\">JobResult</span><span class=\"p\">(</span><span class=\"n\">job_id</span><span class=\"o\">=</span><span class=\"s2\">&quot;job_001&quot;</span><span class=\"p\">,</span> <span class=\"n\">success</span><span class=\"o\">=</span><span class=\"kc\">True</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">tracker</span><span class=\"o\">.</span><span class=\"n\">mark_job_complete</span><span class=\"p\">(</span><span class=\"s2\">&quot;node_001&quot;</span><span class=\"p\">,</span> <span class=\"s2\">&quot;job_001&quot;</span><span class=\"p\">,</span> <span class=\"n\">result</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">tracker</span><span class=\"o\">.</span><span class=\"n\">get_completed_job_count</span><span class=\"p\">(</span><span class=\"s2\">&quot;node_001&quot;</span><span class=\"p\">)</span>  <span class=\"c1\"># 1</span>\n<span class=\"go\">1</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">tracker</span><span class=\"o\">.</span><span class=\"n\">mark_job_complete</span><span class=\"p\">(</span><span class=\"s2\">&quot;node_001&quot;</span><span class=\"p\">,</span> <span class=\"s2\">&quot;job_002&quot;</span><span class=\"p\">,</span> <span class=\"n\">result</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">tracker</span><span class=\"o\">.</span><span class=\"n\">get_completed_job_count</span><span class=\"p\">(</span><span class=\"s2\">&quot;node_001&quot;</span><span class=\"p\">)</span>  <span class=\"c1\"># 2</span>\n<span class=\"go\">2</span>\n</code></pre>\n  </div>\n</blockquote>\n\n<h6 id=\"notes\">Notes:</h6>\n\n<blockquote>\n  <ul>\n  <li>Includes both successful and failed jobs</li>\n  <li>This count increases as jobs are marked complete</li>\n  <li>Unknown nodes return 0 (no completed jobs)</li>\n  <li>Used for progress tracking and completion statistics</li>\n  </ul>\n</blockquote>\n", "signature": "<span class=\"signature pdoc-code condensed\">(<span class=\"param\"><span class=\"bp\">self</span>, </span><span class=\"param\"><span class=\"n\">node_id</span><span class=\"p\">:</span> <span class=\"nb\">str</span></span><span class=\"return-annotation\">) -> <span class=\"nb\">int</span>:</span></span>", "funcdef": "def"}, {"fullname": "dftscape.core.JobTracker.get_job_result", "modulename": "dftscape.core", "qualname": "JobTracker.get_job_result", "kind": "function", "doc": "<p>Retrieve the result of a completed job by its identifier.</p>\n\n<p>Returns the complete JobResult for a job that has been marked as completed.\nThis allows access to execution details, success status, timing information,\nand any computational results from the job.</p>\n\n<h6 id=\"arguments\">Arguments:</h6>\n\n<ul>\n<li><strong>job_id:</strong>  The unique identifier of the job to retrieve results for.</li>\n</ul>\n\n<h6 id=\"returns\">Returns:</h6>\n\n<blockquote>\n  <p>The JobResult for the completed job, or None if the job ID is not\n  found in the completed jobs or doesn't exist.</p>\n</blockquote>\n\n<h6 id=\"example\">Example:</h6>\n\n<blockquote>\n  <div class=\"pdoc-code codehilite\">\n<pre><span></span><code><span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">tracker</span> <span class=\"o\">=</span> <span class=\"n\">JobTracker</span><span class=\"p\">()</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">tracker</span><span class=\"o\">.</span><span class=\"n\">add_jobs_for_node</span><span class=\"p\">(</span><span class=\"s2\">&quot;node_001&quot;</span><span class=\"p\">,</span> <span class=\"p\">[</span><span class=\"s2\">&quot;job_001&quot;</span><span class=\"p\">])</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Complete the job</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">result</span> <span class=\"o\">=</span> <span class=\"n\">JobResult</span><span class=\"p\">(</span>\n<span class=\"gp\">... </span>    <span class=\"n\">job_id</span><span class=\"o\">=</span><span class=\"s2\">&quot;job_001&quot;</span><span class=\"p\">,</span>\n<span class=\"gp\">... </span>    <span class=\"n\">success</span><span class=\"o\">=</span><span class=\"kc\">True</span><span class=\"p\">,</span>\n<span class=\"gp\">... </span>    <span class=\"n\">execution_time</span><span class=\"o\">=</span><span class=\"mf\">15.5</span><span class=\"p\">,</span>\n<span class=\"gp\">... </span>    <span class=\"n\">critical_point</span><span class=\"o\">=</span><span class=\"n\">found_point</span>\n<span class=\"gp\">... </span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">tracker</span><span class=\"o\">.</span><span class=\"n\">mark_job_complete</span><span class=\"p\">(</span><span class=\"s2\">&quot;node_001&quot;</span><span class=\"p\">,</span> <span class=\"s2\">&quot;job_001&quot;</span><span class=\"p\">,</span> <span class=\"n\">result</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Retrieve the result</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">stored_result</span> <span class=\"o\">=</span> <span class=\"n\">tracker</span><span class=\"o\">.</span><span class=\"n\">get_job_result</span><span class=\"p\">(</span><span class=\"s2\">&quot;job_001&quot;</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"k\">if</span> <span class=\"n\">stored_result</span><span class=\"p\">:</span>\n<span class=\"gp\">... </span>    <span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"sa\">f</span><span class=\"s2\">&quot;Job took </span><span class=\"si\">{</span><span class=\"n\">stored_result</span><span class=\"o\">.</span><span class=\"n\">execution_time</span><span class=\"si\">:</span><span class=\"s2\">.2f</span><span class=\"si\">}</span><span class=\"s2\">s&quot;</span><span class=\"p\">)</span>\n<span class=\"gp\">... </span>    <span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"sa\">f</span><span class=\"s2\">&quot;Success: </span><span class=\"si\">{</span><span class=\"n\">stored_result</span><span class=\"o\">.</span><span class=\"n\">success</span><span class=\"si\">}</span><span class=\"s2\">&quot;</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Try to get non-existent job</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">tracker</span><span class=\"o\">.</span><span class=\"n\">get_job_result</span><span class=\"p\">(</span><span class=\"s2\">&quot;unknown_job&quot;</span><span class=\"p\">)</span>  <span class=\"c1\"># None</span>\n</code></pre>\n  </div>\n</blockquote>\n\n<h6 id=\"notes\">Notes:</h6>\n\n<blockquote>\n  <ul>\n  <li>Only returns results for jobs that have been marked as completed</li>\n  <li>Returns None for pending jobs or unknown job IDs</li>\n  <li>JobResult contains complete execution information</li>\n  <li>Useful for post-processing and analysis of job outcomes</li>\n  </ul>\n</blockquote>\n", "signature": "<span class=\"signature pdoc-code condensed\">(<span class=\"param\"><span class=\"bp\">self</span>, </span><span class=\"param\"><span class=\"n\">job_id</span><span class=\"p\">:</span> <span class=\"nb\">str</span></span><span class=\"return-annotation\">) -> <span class=\"n\">Optional</span><span class=\"p\">[</span><span class=\"n\">dftscape</span><span class=\"o\">.</span><span class=\"n\">core</span><span class=\"o\">.</span><span class=\"n\">job_result</span><span class=\"o\">.</span><span class=\"n\">JobResult</span><span class=\"p\">]</span>:</span></span>", "funcdef": "def"}, {"fullname": "dftscape.core.JobTracker.get_failed_jobs", "modulename": "dftscape.core", "qualname": "JobTracker.get_failed_jobs", "kind": "function", "doc": "<p>Get a list of job IDs that failed for a specific node.</p>\n\n<p>Returns the identifiers of all jobs that completed but failed (success=False)\nfor the specified computational node. This is useful for failure analysis,\ndebugging, and determining which jobs might need to be re-run.</p>\n\n<h6 id=\"arguments\">Arguments:</h6>\n\n<ul>\n<li><strong>node_id:</strong>  The computational node to query for failed jobs.</li>\n</ul>\n\n<h6 id=\"returns\">Returns:</h6>\n\n<blockquote>\n  <p>List of job IDs that failed for the node. Returns an empty list\n  if there are no failed jobs or the node doesn't exist.</p>\n</blockquote>\n\n<h6 id=\"example\">Example:</h6>\n\n<blockquote>\n  <div class=\"pdoc-code codehilite\">\n<pre><span></span><code><span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">tracker</span> <span class=\"o\">=</span> <span class=\"n\">JobTracker</span><span class=\"p\">()</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">tracker</span><span class=\"o\">.</span><span class=\"n\">add_jobs_for_node</span><span class=\"p\">(</span><span class=\"s2\">&quot;node_001&quot;</span><span class=\"p\">,</span> <span class=\"p\">[</span><span class=\"s2\">&quot;job_001&quot;</span><span class=\"p\">,</span> <span class=\"s2\">&quot;job_002&quot;</span><span class=\"p\">,</span> <span class=\"s2\">&quot;job_003&quot;</span><span class=\"p\">])</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Complete jobs with mixed results</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">success_result</span> <span class=\"o\">=</span> <span class=\"n\">JobResult</span><span class=\"p\">(</span><span class=\"n\">job_id</span><span class=\"o\">=</span><span class=\"s2\">&quot;job_001&quot;</span><span class=\"p\">,</span> <span class=\"n\">success</span><span class=\"o\">=</span><span class=\"kc\">True</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">fail_result</span> <span class=\"o\">=</span> <span class=\"n\">JobResult</span><span class=\"p\">(</span>\n<span class=\"gp\">... </span>    <span class=\"n\">job_id</span><span class=\"o\">=</span><span class=\"s2\">&quot;job_002&quot;</span><span class=\"p\">,</span>\n<span class=\"gp\">... </span>    <span class=\"n\">success</span><span class=\"o\">=</span><span class=\"kc\">False</span><span class=\"p\">,</span>\n<span class=\"gp\">... </span>    <span class=\"n\">error</span><span class=\"o\">=</span><span class=\"s2\">&quot;Convergence failure&quot;</span>\n<span class=\"gp\">... </span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">another_success</span> <span class=\"o\">=</span> <span class=\"n\">JobResult</span><span class=\"p\">(</span><span class=\"n\">job_id</span><span class=\"o\">=</span><span class=\"s2\">&quot;job_003&quot;</span><span class=\"p\">,</span> <span class=\"n\">success</span><span class=\"o\">=</span><span class=\"kc\">True</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">tracker</span><span class=\"o\">.</span><span class=\"n\">mark_job_complete</span><span class=\"p\">(</span><span class=\"s2\">&quot;node_001&quot;</span><span class=\"p\">,</span> <span class=\"s2\">&quot;job_001&quot;</span><span class=\"p\">,</span> <span class=\"n\">success_result</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">tracker</span><span class=\"o\">.</span><span class=\"n\">mark_job_complete</span><span class=\"p\">(</span><span class=\"s2\">&quot;node_001&quot;</span><span class=\"p\">,</span> <span class=\"s2\">&quot;job_002&quot;</span><span class=\"p\">,</span> <span class=\"n\">fail_result</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">tracker</span><span class=\"o\">.</span><span class=\"n\">mark_job_complete</span><span class=\"p\">(</span><span class=\"s2\">&quot;node_001&quot;</span><span class=\"p\">,</span> <span class=\"s2\">&quot;job_003&quot;</span><span class=\"p\">,</span> <span class=\"n\">another_success</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">failed</span> <span class=\"o\">=</span> <span class=\"n\">tracker</span><span class=\"o\">.</span><span class=\"n\">get_failed_jobs</span><span class=\"p\">(</span><span class=\"s2\">&quot;node_001&quot;</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"n\">failed</span><span class=\"p\">)</span>  <span class=\"c1\"># [&#39;job_002&#39;]</span>\n<span class=\"go\">[&#39;job_002&#39;]</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Check non-existent node</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">tracker</span><span class=\"o\">.</span><span class=\"n\">get_failed_jobs</span><span class=\"p\">(</span><span class=\"s2\">&quot;unknown_node&quot;</span><span class=\"p\">)</span>  <span class=\"c1\"># []</span>\n</code></pre>\n  </div>\n</blockquote>\n\n<h6 id=\"notes\">Notes:</h6>\n\n<blockquote>\n  <ul>\n  <li>Only includes jobs that have completed (not pending jobs)</li>\n  <li>Failed jobs are those with success=False in their JobResult</li>\n  <li>Useful for error analysis and workflow recovery strategies</li>\n  <li>Empty list returned for nodes with no failed jobs</li>\n  </ul>\n</blockquote>\n", "signature": "<span class=\"signature pdoc-code condensed\">(<span class=\"param\"><span class=\"bp\">self</span>, </span><span class=\"param\"><span class=\"n\">node_id</span><span class=\"p\">:</span> <span class=\"nb\">str</span></span><span class=\"return-annotation\">) -> <span class=\"n\">List</span><span class=\"p\">[</span><span class=\"nb\">str</span><span class=\"p\">]</span>:</span></span>", "funcdef": "def"}, {"fullname": "dftscape.core.JobTracker.reconstruct_from_job_queues", "modulename": "dftscape.core", "qualname": "JobTracker.reconstruct_from_job_queues", "kind": "function", "doc": "<p>Reconstruct JobTracker state from job queues during checkpoint resume.</p>\n\n<p>When resuming from a checkpoint, the JobTracker state is not saved, but\nwe can reconstruct it by parsing job IDs from the restored job queues.\nJob IDs follow the pattern: {node_id}_{procedure}_{idx}</p>\n\n<p>This method parses all job IDs in the queues and reconstructs the\nnode-to-job relationships, assuming all jobs are still pending (since\ncompleted jobs would not be in the queues).</p>\n\n<h6 id=\"arguments\">Arguments:</h6>\n\n<ul>\n<li><strong>job_queues:</strong>  The restored JobQueues instance containing pending jobs.</li>\n</ul>\n\n<h6 id=\"note\">Note:</h6>\n\n<blockquote>\n  <ul>\n  <li>Assumes all jobs in queues are pending (not completed)</li>\n  <li>Parses job IDs using the {node_id}_{procedure}_{idx} pattern</li>\n  <li>Clears existing tracker state before reconstruction</li>\n  <li>Used during checkpoint resume to restore tracking relationships</li>\n  </ul>\n</blockquote>\n", "signature": "<span class=\"signature pdoc-code condensed\">(<span class=\"param\"><span class=\"bp\">self</span>, </span><span class=\"param\"><span class=\"n\">job_queues</span><span class=\"p\">:</span> <span class=\"n\">dftscape</span><span class=\"o\">.</span><span class=\"n\">core</span><span class=\"o\">.</span><span class=\"n\">job_queues</span><span class=\"o\">.</span><span class=\"n\">JobQueues</span></span><span class=\"return-annotation\">) -> <span class=\"kc\">None</span>:</span></span>", "funcdef": "def"}, {"fullname": "dftscape.core.NodeStateManager", "modulename": "dftscape.core", "qualname": "NodeStateManager", "kind": "class", "doc": "<p>High-level interface for managing node processing states in DFTScape workflows.</p>\n\n<p>NodeStateManager provides a clean abstraction layer over the SearchableCriticalPointGraph's\nstate management functionality, specifically designed for the orchestrator's needs. It\nhandles the complexities of node state tracking while providing simple, efficient methods\nfor workflow management and progress monitoring.</p>\n\n<p>The manager maintains the processing state of each node for different search procedures,\nenabling the orchestrator to:</p>\n\n<ul>\n<li>Discover unprocessed nodes for job scheduling</li>\n<li>Track progress across different search procedures</li>\n<li>Monitor overall workflow completion</li>\n<li>Provide statistics for reporting and visualization</li>\n</ul>\n\n<h6 id=\"attributes\">Attributes:</h6>\n\n<ul>\n<li><strong>graph (SearchableCriticalPointGraph):</strong>  The underlying graph that stores\nthe actual node and state data.\nAll state management operations\nare delegated to this graph.</li>\n</ul>\n\n<h6 id=\"key-capabilities\">Key Capabilities:</h6>\n\n<blockquote>\n  <ul>\n  <li>Node processing state tracking per procedure</li>\n  <li>Efficient discovery of unprocessed nodes</li>\n  <li>Progress monitoring and statistics</li>\n  <li>State persistence through graph serialization</li>\n  <li>Integration with orchestrator workflow management</li>\n  </ul>\n</blockquote>\n\n<h6 id=\"example\">Example:</h6>\n\n<blockquote>\n  <div class=\"pdoc-code codehilite\">\n<pre><span></span><code><span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Initialize manager</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">state_manager</span> <span class=\"o\">=</span> <span class=\"n\">NodeStateManager</span><span class=\"p\">(</span><span class=\"n\">graph</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Check for work</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">upward_nodes</span> <span class=\"o\">=</span> <span class=\"n\">state_manager</span><span class=\"o\">.</span><span class=\"n\">get_unprocessed_nodes</span><span class=\"p\">(</span><span class=\"s2\">&quot;upward&quot;</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">downward_nodes</span> <span class=\"o\">=</span> <span class=\"n\">state_manager</span><span class=\"o\">.</span><span class=\"n\">get_unprocessed_nodes</span><span class=\"p\">(</span><span class=\"s2\">&quot;downward&quot;</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"sa\">f</span><span class=\"s2\">&quot;Upward work: </span><span class=\"si\">{</span><span class=\"nb\">len</span><span class=\"p\">(</span><span class=\"n\">upward_nodes</span><span class=\"p\">)</span><span class=\"si\">}</span><span class=\"s2\">, Downward work: </span><span class=\"si\">{</span><span class=\"nb\">len</span><span class=\"p\">(</span><span class=\"n\">downward_nodes</span><span class=\"p\">)</span><span class=\"si\">}</span><span class=\"s2\">&quot;</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Process nodes</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"k\">for</span> <span class=\"n\">node_id</span> <span class=\"ow\">in</span> <span class=\"n\">nodes_to_process</span><span class=\"p\">:</span>\n<span class=\"gp\">... </span>    <span class=\"c1\"># ... do processing work ...</span>\n<span class=\"gp\">... </span>    <span class=\"n\">state_manager</span><span class=\"o\">.</span><span class=\"n\">mark_processed</span><span class=\"p\">(</span><span class=\"n\">node_id</span><span class=\"p\">,</span> <span class=\"s2\">&quot;upward&quot;</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Monitor progress</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">stats</span> <span class=\"o\">=</span> <span class=\"n\">state_manager</span><span class=\"o\">.</span><span class=\"n\">get_processing_stats</span><span class=\"p\">(</span><span class=\"s2\">&quot;upward&quot;</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">completion_pct</span> <span class=\"o\">=</span> <span class=\"p\">(</span><span class=\"n\">stats</span><span class=\"p\">[</span><span class=\"s1\">&#39;processed&#39;</span><span class=\"p\">]</span> <span class=\"o\">/</span> <span class=\"n\">stats</span><span class=\"p\">[</span><span class=\"s1\">&#39;total&#39;</span><span class=\"p\">])</span> <span class=\"o\">*</span> <span class=\"mi\">100</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"sa\">f</span><span class=\"s2\">&quot;Upward search: </span><span class=\"si\">{</span><span class=\"n\">completion_pct</span><span class=\"si\">:</span><span class=\"s2\">.1f</span><span class=\"si\">}</span><span class=\"s2\">% complete&quot;</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Check completion</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"k\">if</span> <span class=\"ow\">not</span> <span class=\"n\">state_manager</span><span class=\"o\">.</span><span class=\"n\">has_unprocessed_nodes</span><span class=\"p\">(</span><span class=\"s2\">&quot;upward&quot;</span><span class=\"p\">):</span>\n<span class=\"gp\">... </span>    <span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"s2\">&quot;All upward searches completed!&quot;</span><span class=\"p\">)</span>\n<span class=\"gp\">... </span>    <span class=\"c1\"># Trigger next phase of workflow</span>\n</code></pre>\n  </div>\n</blockquote>\n\n<h6 id=\"implementation-details\">Implementation Details:</h6>\n\n<blockquote>\n  <ul>\n  <li>Thin wrapper around SearchableCriticalPointGraph state methods</li>\n  <li>Provides higher-level operations for common orchestrator patterns</li>\n  <li>Maintains consistency between different state queries</li>\n  <li>Optimized for frequent status checks during workflow execution</li>\n  <li>Thread-safe through underlying graph operations</li>\n  </ul>\n</blockquote>\n\n<h6 id=\"notes\">Notes:</h6>\n\n<blockquote>\n  <ul>\n  <li>Node IDs must exist in the underlying graph</li>\n  <li>Procedure names should be consistent across the workflow</li>\n  <li>State changes are immediately visible to all queries</li>\n  <li>Memory usage is managed by the underlying graph structure</li>\n  <li>Consider batching state updates for high-frequency operations</li>\n  </ul>\n</blockquote>\n"}, {"fullname": "dftscape.core.NodeStateManager.__init__", "modulename": "dftscape.core", "qualname": "NodeStateManager.__init__", "kind": "function", "doc": "<p></p>\n", "signature": "<span class=\"signature pdoc-code condensed\">(<span class=\"param\"><span class=\"n\">graph</span><span class=\"p\">:</span> <span class=\"n\">dftscape</span><span class=\"o\">.</span><span class=\"n\">core</span><span class=\"o\">.</span><span class=\"n\">graph</span><span class=\"o\">.</span><span class=\"n\">SearchableCriticalPointGraph</span></span>)</span>"}, {"fullname": "dftscape.core.NodeStateManager.graph", "modulename": "dftscape.core", "qualname": "NodeStateManager.graph", "kind": "variable", "doc": "<p></p>\n"}, {"fullname": "dftscape.core.NodeStateManager.get_unprocessed_nodes", "modulename": "dftscape.core", "qualname": "NodeStateManager.get_unprocessed_nodes", "kind": "function", "doc": "<p>Get all nodes that haven't been processed by a specific search procedure.</p>\n\n<p>Returns a list of node IDs that are candidates for processing by the specified\nprocedure. This is the primary method for discovering work that needs to be\ndone in the workflow. The returned nodes can be used for job scheduling and\nload balancing across available computational resources.</p>\n\n<h6 id=\"arguments\">Arguments:</h6>\n\n<ul>\n<li><strong>procedure:</strong>  The search procedure name (e.g., \"upward\", \"downward\",\nor custom procedure names) to find unprocessed nodes for.</li>\n</ul>\n\n<h6 id=\"returns\">Returns:</h6>\n\n<blockquote>\n  <p>List of node IDs that haven't been processed by the specified procedure.\n  Returns an empty list if all nodes have been processed or if the\n  procedure doesn't exist.</p>\n</blockquote>\n\n<h6 id=\"example\">Example:</h6>\n\n<blockquote>\n  <div class=\"pdoc-code codehilite\">\n<pre><span></span><code><span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Find nodes needing upward searches</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">unprocessed</span> <span class=\"o\">=</span> <span class=\"n\">state_manager</span><span class=\"o\">.</span><span class=\"n\">get_unprocessed_nodes</span><span class=\"p\">(</span><span class=\"s2\">&quot;upward&quot;</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"k\">if</span> <span class=\"n\">unprocessed</span><span class=\"p\">:</span>\n<span class=\"gp\">... </span>    <span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"sa\">f</span><span class=\"s2\">&quot;Found </span><span class=\"si\">{</span><span class=\"nb\">len</span><span class=\"p\">(</span><span class=\"n\">unprocessed</span><span class=\"p\">)</span><span class=\"si\">}</span><span class=\"s2\"> nodes for upward search&quot;</span><span class=\"p\">)</span>\n<span class=\"gp\">... </span>    <span class=\"c1\"># Schedule jobs for these nodes</span>\n<span class=\"gp\">... </span>    <span class=\"k\">for</span> <span class=\"n\">node_id</span> <span class=\"ow\">in</span> <span class=\"n\">unprocessed</span><span class=\"p\">[:</span><span class=\"mi\">5</span><span class=\"p\">]:</span>  <span class=\"c1\"># Process first 5</span>\n<span class=\"gp\">... </span>        <span class=\"n\">schedule_job</span><span class=\"p\">(</span><span class=\"n\">node_id</span><span class=\"p\">,</span> <span class=\"s2\">&quot;upward&quot;</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Check for different procedures</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">downward_work</span> <span class=\"o\">=</span> <span class=\"n\">state_manager</span><span class=\"o\">.</span><span class=\"n\">get_unprocessed_nodes</span><span class=\"p\">(</span><span class=\"s2\">&quot;downward&quot;</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">custom_work</span> <span class=\"o\">=</span> <span class=\"n\">state_manager</span><span class=\"o\">.</span><span class=\"n\">get_unprocessed_nodes</span><span class=\"p\">(</span><span class=\"s2\">&quot;custom_search&quot;</span><span class=\"p\">)</span>\n</code></pre>\n  </div>\n</blockquote>\n\n<h6 id=\"notes\">Notes:</h6>\n\n<blockquote>\n  <ul>\n  <li>Results may change as nodes are marked as processed</li>\n  <li>Order of returned nodes is not guaranteed (may vary between calls)</li>\n  <li>Used by orchestrator for work discovery and job scheduling</li>\n  <li>Fast operation suitable for frequent polling during workflow execution</li>\n  </ul>\n</blockquote>\n", "signature": "<span class=\"signature pdoc-code condensed\">(<span class=\"param\"><span class=\"bp\">self</span>, </span><span class=\"param\"><span class=\"n\">procedure</span><span class=\"p\">:</span> <span class=\"nb\">str</span></span><span class=\"return-annotation\">) -> <span class=\"n\">List</span><span class=\"p\">[</span><span class=\"nb\">str</span><span class=\"p\">]</span>:</span></span>", "funcdef": "def"}, {"fullname": "dftscape.core.NodeStateManager.get_processed_nodes", "modulename": "dftscape.core", "qualname": "NodeStateManager.get_processed_nodes", "kind": "function", "doc": "<p>Get all nodes that have been processed by a specific search procedure.</p>\n\n<p>Returns a list of node IDs that have completed processing for the specified\nprocedure. This is useful for:</p>\n\n<ul>\n<li>Progress monitoring and reporting</li>\n<li>Avoiding duplicate processing</li>\n<li>Analyzing completed work</li>\n<li>Determining workflow completion status</li>\n</ul>\n\n<h6 id=\"arguments\">Arguments:</h6>\n\n<ul>\n<li><strong>procedure:</strong>  The search procedure name to find processed nodes for.</li>\n</ul>\n\n<h6 id=\"returns\">Returns:</h6>\n\n<blockquote>\n  <p>List of node IDs that have been marked as processed by the specified\n  procedure. Returns an empty list if no nodes have been processed\n  or if the procedure doesn't exist.</p>\n</blockquote>\n\n<h6 id=\"example\">Example:</h6>\n\n<blockquote>\n  <div class=\"pdoc-code codehilite\">\n<pre><span></span><code><span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Check progress</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">processed</span> <span class=\"o\">=</span> <span class=\"n\">state_manager</span><span class=\"o\">.</span><span class=\"n\">get_processed_nodes</span><span class=\"p\">(</span><span class=\"s2\">&quot;upward&quot;</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">total</span> <span class=\"o\">=</span> <span class=\"nb\">len</span><span class=\"p\">(</span><span class=\"n\">state_manager</span><span class=\"o\">.</span><span class=\"n\">graph</span><span class=\"o\">.</span><span class=\"n\">_graph</span><span class=\"o\">.</span><span class=\"n\">nodes</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">completion_rate</span> <span class=\"o\">=</span> <span class=\"nb\">len</span><span class=\"p\">(</span><span class=\"n\">processed</span><span class=\"p\">)</span> <span class=\"o\">/</span> <span class=\"n\">total</span> <span class=\"o\">*</span> <span class=\"mi\">100</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"sa\">f</span><span class=\"s2\">&quot;Upward search: </span><span class=\"si\">{</span><span class=\"n\">completion_rate</span><span class=\"si\">:</span><span class=\"s2\">.1f</span><span class=\"si\">}</span><span class=\"s2\">% complete&quot;</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Avoid reprocessing</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">unprocessed</span> <span class=\"o\">=</span> <span class=\"n\">state_manager</span><span class=\"o\">.</span><span class=\"n\">get_unprocessed_nodes</span><span class=\"p\">(</span><span class=\"s2\">&quot;upward&quot;</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">processed</span> <span class=\"o\">=</span> <span class=\"n\">state_manager</span><span class=\"o\">.</span><span class=\"n\">get_processed_nodes</span><span class=\"p\">(</span><span class=\"s2\">&quot;upward&quot;</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">all_candidates</span> <span class=\"o\">=</span> <span class=\"nb\">set</span><span class=\"p\">(</span><span class=\"n\">unprocessed</span><span class=\"p\">)</span> <span class=\"o\">|</span> <span class=\"nb\">set</span><span class=\"p\">(</span><span class=\"n\">processed</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"sa\">f</span><span class=\"s2\">&quot;Total nodes: </span><span class=\"si\">{</span><span class=\"nb\">len</span><span class=\"p\">(</span><span class=\"n\">all_candidates</span><span class=\"p\">)</span><span class=\"si\">}</span><span class=\"s2\">&quot;</span><span class=\"p\">)</span>\n</code></pre>\n  </div>\n</blockquote>\n\n<h6 id=\"notes\">Notes:</h6>\n\n<blockquote>\n  <ul>\n  <li>Includes all nodes marked as processed, regardless of success/failure</li>\n  <li>Results are complementary to get_unprocessed_nodes()</li>\n  <li>Used for progress tracking and completion verification</li>\n  <li>Order of returned nodes is not guaranteed</li>\n  </ul>\n</blockquote>\n", "signature": "<span class=\"signature pdoc-code condensed\">(<span class=\"param\"><span class=\"bp\">self</span>, </span><span class=\"param\"><span class=\"n\">procedure</span><span class=\"p\">:</span> <span class=\"nb\">str</span></span><span class=\"return-annotation\">) -> <span class=\"n\">List</span><span class=\"p\">[</span><span class=\"nb\">str</span><span class=\"p\">]</span>:</span></span>", "funcdef": "def"}, {"fullname": "dftscape.core.NodeStateManager.mark_processing", "modulename": "dftscape.core", "qualname": "NodeStateManager.mark_processing", "kind": "function", "doc": "<p>Mark a node as currently being processed by a specific search procedure.</p>\n\n<p>Updates the processing state to indicate that the specified node has\njobs spawned but not all jobs are complete for the given procedure.\nThis prevents duplicate job spawning while work is in progress.</p>\n\n<h6 id=\"arguments\">Arguments:</h6>\n\n<ul>\n<li><strong>node_id:</strong>  The unique identifier of the node that is being processed.\nMust exist in the underlying graph.</li>\n<li><strong>procedure:</strong>  The search procedure that is currently processing this node.</li>\n</ul>\n\n<h6 id=\"raises\">Raises:</h6>\n\n<ul>\n<li>May raise exceptions if the node_id doesn't exist in the graph</li>\n<li>or if the underlying graph operation fails.</li>\n</ul>\n\n<h6 id=\"example\">Example:</h6>\n\n<blockquote>\n  <div class=\"pdoc-code codehilite\">\n<pre><span></span><code><span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># After spawning jobs for a node</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"k\">try</span><span class=\"p\">:</span>\n<span class=\"gp\">... </span>    <span class=\"n\">jobs</span> <span class=\"o\">=</span> <span class=\"n\">orchestrator</span><span class=\"o\">.</span><span class=\"n\">_spawn_jobs_from_node</span><span class=\"p\">(</span><span class=\"n\">node_id</span><span class=\"p\">,</span> <span class=\"s2\">&quot;upward&quot;</span><span class=\"p\">)</span>\n<span class=\"gp\">... </span>    <span class=\"k\">if</span> <span class=\"n\">jobs</span><span class=\"p\">:</span>\n<span class=\"gp\">... </span>        <span class=\"n\">state_manager</span><span class=\"o\">.</span><span class=\"n\">mark_processing</span><span class=\"p\">(</span><span class=\"n\">node_id</span><span class=\"p\">,</span> <span class=\"s2\">&quot;upward&quot;</span><span class=\"p\">)</span>\n<span class=\"gp\">... </span>        <span class=\"n\">logger</span><span class=\"o\">.</span><span class=\"n\">info</span><span class=\"p\">(</span><span class=\"sa\">f</span><span class=\"s2\">&quot;Marked </span><span class=\"si\">{</span><span class=\"n\">node_id</span><span class=\"si\">}</span><span class=\"s2\"> as processing for upward&quot;</span><span class=\"p\">)</span>\n<span class=\"gp\">... </span><span class=\"k\">except</span> <span class=\"ne\">Exception</span> <span class=\"k\">as</span> <span class=\"n\">e</span><span class=\"p\">:</span>\n<span class=\"gp\">... </span>    <span class=\"n\">logger</span><span class=\"o\">.</span><span class=\"n\">error</span><span class=\"p\">(</span><span class=\"sa\">f</span><span class=\"s2\">&quot;Failed to mark node </span><span class=\"si\">{</span><span class=\"n\">node_id</span><span class=\"si\">}</span><span class=\"s2\"> as processing: </span><span class=\"si\">{</span><span class=\"n\">e</span><span class=\"si\">}</span><span class=\"s2\">&quot;</span><span class=\"p\">)</span>\n</code></pre>\n  </div>\n</blockquote>\n\n<h6 id=\"notes\">Notes:</h6>\n\n<blockquote>\n  <ul>\n  <li>State changes are permanent until mark_processed is called</li>\n  <li>Node will no longer appear in get_unprocessed_nodes() for this procedure</li>\n  <li>Safe to call multiple times (idempotent operation)</li>\n  <li>Logged for debugging and monitoring purposes</li>\n  </ul>\n</blockquote>\n", "signature": "<span class=\"signature pdoc-code condensed\">(<span class=\"param\"><span class=\"bp\">self</span>, </span><span class=\"param\"><span class=\"n\">node_id</span><span class=\"p\">:</span> <span class=\"nb\">str</span>, </span><span class=\"param\"><span class=\"n\">procedure</span><span class=\"p\">:</span> <span class=\"nb\">str</span></span><span class=\"return-annotation\">) -> <span class=\"kc\">None</span>:</span></span>", "funcdef": "def"}, {"fullname": "dftscape.core.NodeStateManager.get_processing_nodes", "modulename": "dftscape.core", "qualname": "NodeStateManager.get_processing_nodes", "kind": "function", "doc": "<p>Get all nodes that are currently being processed by a specific search procedure.</p>\n\n<p>Returns a list of node IDs that have jobs spawned but not all jobs are\ncomplete for the specified procedure. This is useful for:</p>\n\n<ul>\n<li>Monitoring work in progress</li>\n<li>Avoiding duplicate job spawning</li>\n<li>Progress tracking and reporting</li>\n<li>Resource allocation decisions</li>\n</ul>\n\n<h6 id=\"arguments\">Arguments:</h6>\n\n<ul>\n<li><strong>procedure:</strong>  The search procedure name to find processing nodes for.</li>\n</ul>\n\n<h6 id=\"returns\">Returns:</h6>\n\n<blockquote>\n  <p>List of node IDs that are currently being processed by the specified\n  procedure. Returns an empty list if no nodes are being processed\n  or if the procedure doesn't exist.</p>\n</blockquote>\n\n<h6 id=\"example\">Example:</h6>\n\n<blockquote>\n  <div class=\"pdoc-code codehilite\">\n<pre><span></span><code><span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Check work in progress</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">processing</span> <span class=\"o\">=</span> <span class=\"n\">state_manager</span><span class=\"o\">.</span><span class=\"n\">get_processing_nodes</span><span class=\"p\">(</span><span class=\"s2\">&quot;upward&quot;</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"k\">if</span> <span class=\"n\">processing</span><span class=\"p\">:</span>\n<span class=\"gp\">... </span>    <span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"sa\">f</span><span class=\"s2\">&quot;</span><span class=\"si\">{</span><span class=\"nb\">len</span><span class=\"p\">(</span><span class=\"n\">processing</span><span class=\"p\">)</span><span class=\"si\">}</span><span class=\"s2\"> nodes currently being processed&quot;</span><span class=\"p\">)</span>\n<span class=\"gp\">... </span>    <span class=\"k\">for</span> <span class=\"n\">node_id</span> <span class=\"ow\">in</span> <span class=\"n\">processing</span><span class=\"p\">[:</span><span class=\"mi\">3</span><span class=\"p\">]:</span>  <span class=\"c1\"># Show first 3</span>\n<span class=\"gp\">... </span>        <span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"sa\">f</span><span class=\"s2\">&quot;  Processing: </span><span class=\"si\">{</span><span class=\"n\">node_id</span><span class=\"si\">}</span><span class=\"s2\">&quot;</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Monitor multiple procedures</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"k\">for</span> <span class=\"n\">proc</span> <span class=\"ow\">in</span> <span class=\"p\">[</span><span class=\"s2\">&quot;upward&quot;</span><span class=\"p\">,</span> <span class=\"s2\">&quot;downward&quot;</span><span class=\"p\">]:</span>\n<span class=\"gp\">... </span>    <span class=\"n\">processing</span> <span class=\"o\">=</span> <span class=\"n\">state_manager</span><span class=\"o\">.</span><span class=\"n\">get_processing_nodes</span><span class=\"p\">(</span><span class=\"n\">proc</span><span class=\"p\">)</span>\n<span class=\"gp\">... </span>    <span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"sa\">f</span><span class=\"s2\">&quot;</span><span class=\"si\">{</span><span class=\"n\">proc</span><span class=\"si\">}</span><span class=\"s2\">: </span><span class=\"si\">{</span><span class=\"nb\">len</span><span class=\"p\">(</span><span class=\"n\">processing</span><span class=\"p\">)</span><span class=\"si\">}</span><span class=\"s2\"> nodes processing&quot;</span><span class=\"p\">)</span>\n</code></pre>\n  </div>\n</blockquote>\n\n<h6 id=\"notes\">Notes:</h6>\n\n<blockquote>\n  <ul>\n  <li>Results may change as nodes complete processing</li>\n  <li>Order of returned nodes is not guaranteed (may vary between calls)</li>\n  <li>Used for progress monitoring and job scheduling decisions</li>\n  <li>Fast operation suitable for frequent polling during workflow execution</li>\n  </ul>\n</blockquote>\n", "signature": "<span class=\"signature pdoc-code condensed\">(<span class=\"param\"><span class=\"bp\">self</span>, </span><span class=\"param\"><span class=\"n\">procedure</span><span class=\"p\">:</span> <span class=\"nb\">str</span></span><span class=\"return-annotation\">) -> <span class=\"n\">List</span><span class=\"p\">[</span><span class=\"nb\">str</span><span class=\"p\">]</span>:</span></span>", "funcdef": "def"}, {"fullname": "dftscape.core.NodeStateManager.is_processing", "modulename": "dftscape.core", "qualname": "NodeStateManager.is_processing", "kind": "function", "doc": "<p>Check if a specific node is currently being processed by a search procedure.</p>\n\n<p>Performs a fast lookup to determine whether the specified node has\njobs spawned but not all complete for the given procedure. This is\nuseful for:</p>\n\n<ul>\n<li>Conditional job spawning logic</li>\n<li>Avoiding duplicate work</li>\n<li>Progress verification</li>\n<li>Status checking</li>\n</ul>\n\n<h6 id=\"arguments\">Arguments:</h6>\n\n<ul>\n<li><strong>node_id:</strong>  The node identifier to check.</li>\n<li><strong>procedure:</strong>  The search procedure to check processing status for.</li>\n</ul>\n\n<h6 id=\"returns\">Returns:</h6>\n\n<blockquote>\n  <p>True if the node is currently being processed by this procedure.\n  False if the node is unprocessed, processed, or doesn't exist.</p>\n</blockquote>\n\n<h6 id=\"example\">Example:</h6>\n\n<blockquote>\n  <div class=\"pdoc-code codehilite\">\n<pre><span></span><code><span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Check before spawning jobs</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"k\">if</span> <span class=\"ow\">not</span> <span class=\"n\">state_manager</span><span class=\"o\">.</span><span class=\"n\">is_processing</span><span class=\"p\">(</span><span class=\"n\">node_id</span><span class=\"p\">,</span> <span class=\"s2\">&quot;upward&quot;</span><span class=\"p\">):</span>\n<span class=\"gp\">... </span>    <span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"sa\">f</span><span class=\"s2\">&quot;Node </span><span class=\"si\">{</span><span class=\"n\">node_id</span><span class=\"si\">}</span><span class=\"s2\"> is ready for upward processing&quot;</span><span class=\"p\">)</span>\n<span class=\"gp\">... </span>    <span class=\"c1\"># ... spawn jobs ...</span>\n<span class=\"gp\">... </span><span class=\"k\">else</span><span class=\"p\">:</span>\n<span class=\"gp\">... </span>    <span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"sa\">f</span><span class=\"s2\">&quot;Node </span><span class=\"si\">{</span><span class=\"n\">node_id</span><span class=\"si\">}</span><span class=\"s2\"> is already being processed&quot;</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Verify processing status</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">procedures</span> <span class=\"o\">=</span> <span class=\"p\">[</span><span class=\"s2\">&quot;upward&quot;</span><span class=\"p\">,</span> <span class=\"s2\">&quot;downward&quot;</span><span class=\"p\">,</span> <span class=\"s2\">&quot;custom&quot;</span><span class=\"p\">]</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"k\">for</span> <span class=\"n\">proc</span> <span class=\"ow\">in</span> <span class=\"n\">procedures</span><span class=\"p\">:</span>\n<span class=\"gp\">... </span>    <span class=\"n\">status</span> <span class=\"o\">=</span> <span class=\"s2\">&quot;processing&quot;</span> <span class=\"k\">if</span> <span class=\"n\">state_manager</span><span class=\"o\">.</span><span class=\"n\">is_processing</span><span class=\"p\">(</span><span class=\"n\">node_id</span><span class=\"p\">,</span> <span class=\"n\">proc</span><span class=\"p\">)</span> <span class=\"k\">else</span> <span class=\"s2\">&quot;not processing&quot;</span>\n<span class=\"gp\">... </span>    <span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"sa\">f</span><span class=\"s2\">&quot;</span><span class=\"si\">{</span><span class=\"n\">proc</span><span class=\"si\">}</span><span class=\"s2\">: </span><span class=\"si\">{</span><span class=\"n\">status</span><span class=\"si\">}</span><span class=\"s2\">&quot;</span><span class=\"p\">)</span>\n</code></pre>\n  </div>\n</blockquote>\n\n<h6 id=\"notes\">Notes:</h6>\n\n<blockquote>\n  <ul>\n  <li>Fast operation suitable for frequent status checks</li>\n  <li>Returns False for non-existent nodes or procedures</li>\n  <li>Consistent with get_processing_nodes() results</li>\n  <li>Used internally by other state management methods</li>\n  </ul>\n</blockquote>\n", "signature": "<span class=\"signature pdoc-code condensed\">(<span class=\"param\"><span class=\"bp\">self</span>, </span><span class=\"param\"><span class=\"n\">node_id</span><span class=\"p\">:</span> <span class=\"nb\">str</span>, </span><span class=\"param\"><span class=\"n\">procedure</span><span class=\"p\">:</span> <span class=\"nb\">str</span></span><span class=\"return-annotation\">) -> <span class=\"nb\">bool</span>:</span></span>", "funcdef": "def"}, {"fullname": "dftscape.core.NodeStateManager.mark_processed", "modulename": "dftscape.core", "qualname": "NodeStateManager.mark_processed", "kind": "function", "doc": "<p>Mark a node as fully processed by a specific search procedure.</p>\n\n<p>Updates the processing state to indicate that the specified node has\ncompleted processing for the given procedure. This prevents duplicate\nprocessing and enables progress tracking. The state change is permanent\nand immediately visible to all subsequent queries.</p>\n\n<p>This method should be called after successfully completing all work\nrelated to a node for a specific procedure. It's typically called by\nthe orchestrator after job completion and result processing.</p>\n\n<h6 id=\"arguments\">Arguments:</h6>\n\n<ul>\n<li><strong>node_id:</strong>  The unique identifier of the node that has been processed.\nMust exist in the underlying graph.</li>\n<li><strong>procedure:</strong>  The search procedure that was completed for this node.</li>\n</ul>\n\n<h6 id=\"raises\">Raises:</h6>\n\n<ul>\n<li>May raise exceptions if the node_id doesn't exist in the graph</li>\n<li>or if the underlying graph operation fails.</li>\n</ul>\n\n<h6 id=\"example\">Example:</h6>\n\n<blockquote>\n  <div class=\"pdoc-code codehilite\">\n<pre><span></span><code><span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># After completing upward search for a node</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"k\">try</span><span class=\"p\">:</span>\n<span class=\"gp\">... </span>    <span class=\"c1\"># ... perform upward search computations ...</span>\n<span class=\"gp\">... </span>    <span class=\"n\">state_manager</span><span class=\"o\">.</span><span class=\"n\">mark_processed</span><span class=\"p\">(</span><span class=\"n\">node_id</span><span class=\"p\">,</span> <span class=\"s2\">&quot;upward&quot;</span><span class=\"p\">)</span>\n<span class=\"gp\">... </span>    <span class=\"n\">logger</span><span class=\"o\">.</span><span class=\"n\">info</span><span class=\"p\">(</span><span class=\"sa\">f</span><span class=\"s2\">&quot;Completed upward search for node </span><span class=\"si\">{</span><span class=\"n\">node_id</span><span class=\"si\">}</span><span class=\"s2\">&quot;</span><span class=\"p\">)</span>\n<span class=\"gp\">... </span><span class=\"k\">except</span> <span class=\"ne\">Exception</span> <span class=\"k\">as</span> <span class=\"n\">e</span><span class=\"p\">:</span>\n<span class=\"gp\">... </span>    <span class=\"n\">logger</span><span class=\"o\">.</span><span class=\"n\">error</span><span class=\"p\">(</span><span class=\"sa\">f</span><span class=\"s2\">&quot;Failed to process node </span><span class=\"si\">{</span><span class=\"n\">node_id</span><span class=\"si\">}</span><span class=\"s2\">: </span><span class=\"si\">{</span><span class=\"n\">e</span><span class=\"si\">}</span><span class=\"s2\">&quot;</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Batch processing completion</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"k\">for</span> <span class=\"n\">node_id</span> <span class=\"ow\">in</span> <span class=\"n\">completed_nodes</span><span class=\"p\">:</span>\n<span class=\"gp\">... </span>    <span class=\"n\">state_manager</span><span class=\"o\">.</span><span class=\"n\">mark_processed</span><span class=\"p\">(</span><span class=\"n\">node_id</span><span class=\"p\">,</span> <span class=\"s2\">&quot;downward&quot;</span><span class=\"p\">)</span>\n<span class=\"gp\">... </span>    <span class=\"n\">logger</span><span class=\"o\">.</span><span class=\"n\">debug</span><span class=\"p\">(</span><span class=\"sa\">f</span><span class=\"s2\">&quot;Marked </span><span class=\"si\">{</span><span class=\"n\">node_id</span><span class=\"si\">}</span><span class=\"s2\"> as processed for downward&quot;</span><span class=\"p\">)</span>\n</code></pre>\n  </div>\n</blockquote>\n\n<h6 id=\"notes\">Notes:</h6>\n\n<blockquote>\n  <ul>\n  <li>State changes are permanent and cannot be undone</li>\n  <li>Node will no longer appear in get_unprocessed_nodes() for this procedure</li>\n  <li>Safe to call multiple times (idempotent operation)</li>\n  <li>Logged for debugging and monitoring purposes</li>\n  </ul>\n</blockquote>\n", "signature": "<span class=\"signature pdoc-code condensed\">(<span class=\"param\"><span class=\"bp\">self</span>, </span><span class=\"param\"><span class=\"n\">node_id</span><span class=\"p\">:</span> <span class=\"nb\">str</span>, </span><span class=\"param\"><span class=\"n\">procedure</span><span class=\"p\">:</span> <span class=\"nb\">str</span></span><span class=\"return-annotation\">) -> <span class=\"kc\">None</span>:</span></span>", "funcdef": "def"}, {"fullname": "dftscape.core.NodeStateManager.is_processed", "modulename": "dftscape.core", "qualname": "NodeStateManager.is_processed", "kind": "function", "doc": "<p>Check if a specific node has been processed by a search procedure.</p>\n\n<p>Performs a fast lookup to determine whether the specified node has\ncompleted processing for the given procedure. This is useful for:</p>\n\n<ul>\n<li>Conditional processing logic</li>\n<li>Avoiding duplicate work</li>\n<li>Progress verification</li>\n<li>Dependency checking</li>\n</ul>\n\n<h6 id=\"arguments\">Arguments:</h6>\n\n<ul>\n<li><strong>node_id:</strong>  The node identifier to check.</li>\n<li><strong>procedure:</strong>  The search procedure to check processing status for.</li>\n</ul>\n\n<h6 id=\"returns\">Returns:</h6>\n\n<blockquote>\n  <p>True if the node has been marked as processed for this procedure.\n  False if the node hasn't been processed or doesn't exist.</p>\n</blockquote>\n\n<h6 id=\"example\">Example:</h6>\n\n<blockquote>\n  <div class=\"pdoc-code codehilite\">\n<pre><span></span><code><span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Check before processing</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"k\">if</span> <span class=\"ow\">not</span> <span class=\"n\">state_manager</span><span class=\"o\">.</span><span class=\"n\">is_processed</span><span class=\"p\">(</span><span class=\"n\">node_id</span><span class=\"p\">,</span> <span class=\"s2\">&quot;upward&quot;</span><span class=\"p\">):</span>\n<span class=\"gp\">... </span>    <span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"sa\">f</span><span class=\"s2\">&quot;Node </span><span class=\"si\">{</span><span class=\"n\">node_id</span><span class=\"si\">}</span><span class=\"s2\"> needs upward processing&quot;</span><span class=\"p\">)</span>\n<span class=\"gp\">... </span>    <span class=\"c1\"># ... perform processing ...</span>\n<span class=\"gp\">... </span>    <span class=\"n\">state_manager</span><span class=\"o\">.</span><span class=\"n\">mark_processed</span><span class=\"p\">(</span><span class=\"n\">node_id</span><span class=\"p\">,</span> <span class=\"s2\">&quot;upward&quot;</span><span class=\"p\">)</span>\n<span class=\"gp\">... </span><span class=\"k\">else</span><span class=\"p\">:</span>\n<span class=\"gp\">... </span>    <span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"sa\">f</span><span class=\"s2\">&quot;Node </span><span class=\"si\">{</span><span class=\"n\">node_id</span><span class=\"si\">}</span><span class=\"s2\"> already processed for upward&quot;</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Verify processing status</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">procedures</span> <span class=\"o\">=</span> <span class=\"p\">[</span><span class=\"s2\">&quot;upward&quot;</span><span class=\"p\">,</span> <span class=\"s2\">&quot;downward&quot;</span><span class=\"p\">,</span> <span class=\"s2\">&quot;custom&quot;</span><span class=\"p\">]</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"k\">for</span> <span class=\"n\">proc</span> <span class=\"ow\">in</span> <span class=\"n\">procedures</span><span class=\"p\">:</span>\n<span class=\"gp\">... </span>    <span class=\"n\">status</span> <span class=\"o\">=</span> <span class=\"s2\">&quot;\u2713&quot;</span> <span class=\"k\">if</span> <span class=\"n\">state_manager</span><span class=\"o\">.</span><span class=\"n\">is_processed</span><span class=\"p\">(</span><span class=\"n\">node_id</span><span class=\"p\">,</span> <span class=\"n\">proc</span><span class=\"p\">)</span> <span class=\"k\">else</span> <span class=\"s2\">&quot;\u2717&quot;</span>\n<span class=\"gp\">... </span>    <span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"sa\">f</span><span class=\"s2\">&quot;</span><span class=\"si\">{</span><span class=\"n\">proc</span><span class=\"si\">}</span><span class=\"s2\">: </span><span class=\"si\">{</span><span class=\"n\">status</span><span class=\"si\">}</span><span class=\"s2\">&quot;</span><span class=\"p\">)</span>\n</code></pre>\n  </div>\n</blockquote>\n\n<h6 id=\"notes\">Notes:</h6>\n\n<blockquote>\n  <ul>\n  <li>Fast operation suitable for frequent status checks</li>\n  <li>Returns False for non-existent nodes or procedures</li>\n  <li>Consistent with get_processed_nodes() results</li>\n  <li>Used internally by other state management methods</li>\n  </ul>\n</blockquote>\n", "signature": "<span class=\"signature pdoc-code condensed\">(<span class=\"param\"><span class=\"bp\">self</span>, </span><span class=\"param\"><span class=\"n\">node_id</span><span class=\"p\">:</span> <span class=\"nb\">str</span>, </span><span class=\"param\"><span class=\"n\">procedure</span><span class=\"p\">:</span> <span class=\"nb\">str</span></span><span class=\"return-annotation\">) -> <span class=\"nb\">bool</span>:</span></span>", "funcdef": "def"}, {"fullname": "dftscape.core.NodeStateManager.get_processing_stats", "modulename": "dftscape.core", "qualname": "NodeStateManager.get_processing_stats", "kind": "function", "doc": "<p>Get comprehensive processing statistics for a search procedure.</p>\n\n<p>Returns detailed statistics about the processing state of all nodes\nfor the specified procedure. This provides a complete overview of\nwork completed, remaining, and total scope.</p>\n\n<h6 id=\"arguments\">Arguments:</h6>\n\n<ul>\n<li><strong>procedure:</strong>  The search procedure to get statistics for.</li>\n</ul>\n\n<h6 id=\"returns\">Returns:</h6>\n\n<blockquote>\n  <p>Dictionary containing processing statistics with keys:</p>\n  \n  <ul>\n  <li>'processed': Number of nodes that have been processed</li>\n  <li>'processing': Number of nodes that are currently being processed</li>\n  <li>'unprocessed': Number of nodes that haven't been processed</li>\n  <li>'total': Total number of nodes in the graph</li>\n  </ul>\n</blockquote>\n\n<h6 id=\"example\">Example:</h6>\n\n<blockquote>\n  <div class=\"pdoc-code codehilite\">\n<pre><span></span><code><span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Get comprehensive progress report</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">stats</span> <span class=\"o\">=</span> <span class=\"n\">state_manager</span><span class=\"o\">.</span><span class=\"n\">get_processing_stats</span><span class=\"p\">(</span><span class=\"s2\">&quot;upward&quot;</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">processed</span> <span class=\"o\">=</span> <span class=\"n\">stats</span><span class=\"p\">[</span><span class=\"s1\">&#39;processed&#39;</span><span class=\"p\">]</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">processing</span> <span class=\"o\">=</span> <span class=\"n\">stats</span><span class=\"p\">[</span><span class=\"s1\">&#39;processing&#39;</span><span class=\"p\">]</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">total</span> <span class=\"o\">=</span> <span class=\"n\">stats</span><span class=\"p\">[</span><span class=\"s1\">&#39;total&#39;</span><span class=\"p\">]</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">completion_pct</span> <span class=\"o\">=</span> <span class=\"p\">(</span><span class=\"n\">processed</span> <span class=\"o\">/</span> <span class=\"n\">total</span> <span class=\"o\">*</span> <span class=\"mi\">100</span><span class=\"p\">)</span> <span class=\"k\">if</span> <span class=\"n\">total</span> <span class=\"o\">&gt;</span> <span class=\"mi\">0</span> <span class=\"k\">else</span> <span class=\"mi\">0</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"sa\">f</span><span class=\"s2\">&quot;Upward search progress: </span><span class=\"si\">{</span><span class=\"n\">processed</span><span class=\"si\">}</span><span class=\"s2\">/</span><span class=\"si\">{</span><span class=\"n\">total</span><span class=\"si\">}</span><span class=\"s2\"> (</span><span class=\"si\">{</span><span class=\"n\">completion_pct</span><span class=\"si\">:</span><span class=\"s2\">.1f</span><span class=\"si\">}</span><span class=\"s2\">%)&quot;</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"sa\">f</span><span class=\"s2\">&quot;Currently processing: </span><span class=\"si\">{</span><span class=\"n\">processing</span><span class=\"si\">}</span><span class=\"s2\"> nodes&quot;</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"sa\">f</span><span class=\"s2\">&quot;Remaining work: </span><span class=\"si\">{</span><span class=\"n\">stats</span><span class=\"p\">[</span><span class=\"s1\">&#39;unprocessed&#39;</span><span class=\"p\">]</span><span class=\"si\">}</span><span class=\"s2\"> nodes&quot;</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Monitor multiple procedures</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">procedures</span> <span class=\"o\">=</span> <span class=\"p\">[</span><span class=\"s2\">&quot;upward&quot;</span><span class=\"p\">,</span> <span class=\"s2\">&quot;downward&quot;</span><span class=\"p\">]</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"k\">for</span> <span class=\"n\">proc</span> <span class=\"ow\">in</span> <span class=\"n\">procedures</span><span class=\"p\">:</span>\n<span class=\"gp\">... </span>    <span class=\"n\">stats</span> <span class=\"o\">=</span> <span class=\"n\">state_manager</span><span class=\"o\">.</span><span class=\"n\">get_processing_stats</span><span class=\"p\">(</span><span class=\"n\">proc</span><span class=\"p\">)</span>\n<span class=\"gp\">... </span>    <span class=\"n\">pct</span> <span class=\"o\">=</span> <span class=\"p\">(</span><span class=\"n\">stats</span><span class=\"p\">[</span><span class=\"s1\">&#39;processed&#39;</span><span class=\"p\">]</span> <span class=\"o\">/</span> <span class=\"n\">stats</span><span class=\"p\">[</span><span class=\"s1\">&#39;total&#39;</span><span class=\"p\">]</span> <span class=\"o\">*</span> <span class=\"mi\">100</span><span class=\"p\">)</span> <span class=\"k\">if</span> <span class=\"n\">stats</span><span class=\"p\">[</span><span class=\"s1\">&#39;total&#39;</span><span class=\"p\">]</span> <span class=\"o\">&gt;</span> <span class=\"mi\">0</span> <span class=\"k\">else</span> <span class=\"mi\">0</span>\n<span class=\"gp\">... </span>    <span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"sa\">f</span><span class=\"s2\">&quot;</span><span class=\"si\">{</span><span class=\"n\">proc</span><span class=\"si\">}</span><span class=\"s2\">: </span><span class=\"si\">{</span><span class=\"n\">pct</span><span class=\"si\">:</span><span class=\"s2\">.1f</span><span class=\"si\">}</span><span class=\"s2\">% complete (</span><span class=\"si\">{</span><span class=\"n\">stats</span><span class=\"p\">[</span><span class=\"s1\">&#39;processing&#39;</span><span class=\"p\">]</span><span class=\"si\">}</span><span class=\"s2\"> processing)&quot;</span><span class=\"p\">)</span>\n</code></pre>\n  </div>\n</blockquote>\n\n<h6 id=\"notes\">Notes:</h6>\n\n<blockquote>\n  <ul>\n  <li>Statistics are computed dynamically from current state</li>\n  <li>Total includes all nodes in the graph, regardless of procedure relevance</li>\n  <li>Used for progress monitoring, reporting, and completion detection</li>\n  <li>Consistent with individual node status queries</li>\n  </ul>\n</blockquote>\n", "signature": "<span class=\"signature pdoc-code condensed\">(<span class=\"param\"><span class=\"bp\">self</span>, </span><span class=\"param\"><span class=\"n\">procedure</span><span class=\"p\">:</span> <span class=\"nb\">str</span></span><span class=\"return-annotation\">) -> <span class=\"n\">Dict</span><span class=\"p\">[</span><span class=\"nb\">str</span><span class=\"p\">,</span> <span class=\"nb\">int</span><span class=\"p\">]</span>:</span></span>", "funcdef": "def"}, {"fullname": "dftscape.core.NodeStateManager.has_unprocessed_nodes", "modulename": "dftscape.core", "qualname": "NodeStateManager.has_unprocessed_nodes", "kind": "function", "doc": "<p>Check if there are any unprocessed nodes for a search procedure.</p>\n\n<p>Provides a fast boolean check for whether there's remaining work\nfor the specified procedure. This is more efficient than calling\nget_unprocessed_nodes() when you only need to know if work exists,\nnot the specific nodes.</p>\n\n<h6 id=\"arguments\">Arguments:</h6>\n\n<ul>\n<li><strong>procedure:</strong>  The search procedure to check for unprocessed nodes.</li>\n</ul>\n\n<h6 id=\"returns\">Returns:</h6>\n\n<blockquote>\n  <p>True if there are nodes that haven't been processed by this procedure.\n  False if all nodes have been processed or no nodes exist.</p>\n</blockquote>\n\n<h6 id=\"example\">Example:</h6>\n\n<blockquote>\n  <div class=\"pdoc-code codehilite\">\n<pre><span></span><code><span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Simple completion check</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"k\">if</span> <span class=\"n\">state_manager</span><span class=\"o\">.</span><span class=\"n\">has_unprocessed_nodes</span><span class=\"p\">(</span><span class=\"s2\">&quot;upward&quot;</span><span class=\"p\">):</span>\n<span class=\"gp\">... </span>    <span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"s2\">&quot;More upward work available&quot;</span><span class=\"p\">)</span>\n<span class=\"gp\">... </span>    <span class=\"c1\"># ... schedule more jobs ...</span>\n<span class=\"gp\">... </span><span class=\"k\">else</span><span class=\"p\">:</span>\n<span class=\"gp\">... </span>    <span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"s2\">&quot;All upward searches completed!&quot;</span><span class=\"p\">)</span>\n<span class=\"gp\">... </span>    <span class=\"c1\"># ... trigger next workflow phase ...</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Polling for work in a loop</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"k\">while</span> <span class=\"n\">state_manager</span><span class=\"o\">.</span><span class=\"n\">has_unprocessed_nodes</span><span class=\"p\">(</span><span class=\"s2\">&quot;downward&quot;</span><span class=\"p\">):</span>\n<span class=\"gp\">... </span>    <span class=\"n\">nodes</span> <span class=\"o\">=</span> <span class=\"n\">state_manager</span><span class=\"o\">.</span><span class=\"n\">get_unprocessed_nodes</span><span class=\"p\">(</span><span class=\"s2\">&quot;downward&quot;</span><span class=\"p\">)</span>\n<span class=\"gp\">... </span>    <span class=\"c1\"># Process a batch of nodes</span>\n<span class=\"gp\">... </span>    <span class=\"k\">for</span> <span class=\"n\">node_id</span> <span class=\"ow\">in</span> <span class=\"n\">nodes</span><span class=\"p\">[:</span><span class=\"n\">batch_size</span><span class=\"p\">]:</span>\n<span class=\"gp\">... </span>        <span class=\"n\">process_node</span><span class=\"p\">(</span><span class=\"n\">node_id</span><span class=\"p\">,</span> <span class=\"s2\">&quot;downward&quot;</span><span class=\"p\">)</span>\n<span class=\"gp\">... </span>        <span class=\"n\">state_manager</span><span class=\"o\">.</span><span class=\"n\">mark_processed</span><span class=\"p\">(</span><span class=\"n\">node_id</span><span class=\"p\">,</span> <span class=\"s2\">&quot;downward&quot;</span><span class=\"p\">)</span>\n</code></pre>\n  </div>\n</blockquote>\n\n<h6 id=\"notes\">Notes:</h6>\n\n<blockquote>\n  <ul>\n  <li>More efficient than len(get_unprocessed_nodes()) &gt; 0</li>\n  <li>Used for workflow completion detection and job scheduling decisions</li>\n  <li>Fast operation suitable for frequent polling</li>\n  <li>Consistent with get_unprocessed_nodes() results</li>\n  </ul>\n</blockquote>\n", "signature": "<span class=\"signature pdoc-code condensed\">(<span class=\"param\"><span class=\"bp\">self</span>, </span><span class=\"param\"><span class=\"n\">procedure</span><span class=\"p\">:</span> <span class=\"nb\">str</span></span><span class=\"return-annotation\">) -> <span class=\"nb\">bool</span>:</span></span>", "funcdef": "def"}, {"fullname": "dftscape.core.JobExecutor", "modulename": "dftscape.core", "qualname": "JobExecutor", "kind": "class", "doc": "<p>Job execution manager for DFTScape computational workflows.</p>\n\n<p>This class provides a unified interface for executing molecular optimization jobs,\nabstracting the complexities of job scheduling, error handling, and result collection.\nIt supports both individual job execution and batch processing, with built-in\nperformance monitoring and comprehensive error reporting.</p>\n\n<p>The JobExecutor works with HiSD (High index Saddle Dynamics) runners to\nperform saddle point searches and critical point location in molecular potential\nenergy surfaces. It handles the coordination between job submission, execution\nmonitoring, and result aggregation.</p>\n\n<p>Key Features:</p>\n\n<ul>\n<li>Single job and batch job execution</li>\n<li>Configurable concurrency limits</li>\n<li>Automatic error handling and recovery</li>\n<li>Execution time tracking and performance metrics</li>\n<li>Integration with logging system for monitoring</li>\n<li>Result validation and status reporting</li>\n</ul>\n\n<h6 id=\"attributes\">Attributes:</h6>\n\n<ul>\n<li><strong>hisd_runner (HiSDRunner):</strong>  Computational backend for executing HiSD dynamics</li>\n<li><strong>max_concurrent (int):</strong>  Maximum number of concurrent jobs (currently 1 for serial)</li>\n</ul>\n\n<h6 id=\"example\">Example:</h6>\n\n<blockquote>\n  <div class=\"pdoc-code codehilite\">\n<pre><span></span><code><span class=\"gp\">&gt;&gt;&gt; </span><span class=\"kn\">from</span><span class=\"w\"> </span><span class=\"nn\">dftscape.core.job_executor</span><span class=\"w\"> </span><span class=\"kn\">import</span> <span class=\"n\">JobExecutor</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"kn\">from</span><span class=\"w\"> </span><span class=\"nn\">dftscape.core.interfaces</span><span class=\"w\"> </span><span class=\"kn\">import</span> <span class=\"n\">HiSDRunner</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Create executor with HiSD runner</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">executor</span> <span class=\"o\">=</span> <span class=\"n\">JobExecutor</span><span class=\"p\">(</span><span class=\"n\">hisd_runner</span><span class=\"o\">=</span><span class=\"n\">my_hisd_runner</span><span class=\"p\">,</span> <span class=\"n\">max_concurrent</span><span class=\"o\">=</span><span class=\"mi\">1</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Execute a single job</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">result</span> <span class=\"o\">=</span> <span class=\"n\">executor</span><span class=\"o\">.</span><span class=\"n\">execute_job</span><span class=\"p\">(</span><span class=\"n\">run_condition</span><span class=\"p\">,</span> <span class=\"s2\">&quot;job_001&quot;</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"k\">if</span> <span class=\"n\">result</span><span class=\"o\">.</span><span class=\"n\">success</span><span class=\"p\">:</span>\n<span class=\"gp\">... </span>    <span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"sa\">f</span><span class=\"s2\">&quot;Found critical point at energy </span><span class=\"si\">{</span><span class=\"n\">result</span><span class=\"o\">.</span><span class=\"n\">critical_point</span><span class=\"o\">.</span><span class=\"n\">energy</span><span class=\"si\">}</span><span class=\"s2\">&quot;</span><span class=\"p\">)</span>\n<span class=\"gp\">... </span><span class=\"k\">else</span><span class=\"p\">:</span>\n<span class=\"gp\">... </span>    <span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"sa\">f</span><span class=\"s2\">&quot;Job failed: </span><span class=\"si\">{</span><span class=\"n\">result</span><span class=\"o\">.</span><span class=\"n\">error</span><span class=\"si\">}</span><span class=\"s2\">&quot;</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Execute multiple jobs</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">batch_jobs</span> <span class=\"o\">=</span> <span class=\"p\">[(</span><span class=\"s2\">&quot;job_001&quot;</span><span class=\"p\">,</span> <span class=\"n\">cond1</span><span class=\"p\">),</span> <span class=\"p\">(</span><span class=\"s2\">&quot;job_002&quot;</span><span class=\"p\">,</span> <span class=\"n\">cond2</span><span class=\"p\">)]</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">results</span> <span class=\"o\">=</span> <span class=\"n\">executor</span><span class=\"o\">.</span><span class=\"n\">execute_batch</span><span class=\"p\">(</span><span class=\"n\">batch_jobs</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">success_rate</span> <span class=\"o\">=</span> <span class=\"nb\">sum</span><span class=\"p\">(</span><span class=\"mi\">1</span> <span class=\"k\">for</span> <span class=\"n\">r</span> <span class=\"ow\">in</span> <span class=\"n\">results</span> <span class=\"k\">if</span> <span class=\"n\">r</span><span class=\"o\">.</span><span class=\"n\">success</span><span class=\"p\">)</span> <span class=\"o\">/</span> <span class=\"nb\">len</span><span class=\"p\">(</span><span class=\"n\">results</span><span class=\"p\">)</span>\n</code></pre>\n  </div>\n</blockquote>\n\n<p>Notes:</p>\n\n<ul>\n<li>Currently implements serial execution (max_concurrent=1)</li>\n<li>Future versions will support true parallel execution</li>\n<li>Error handling captures both HiSD convergence failures and runtime exceptions</li>\n<li>Execution times are tracked for performance analysis</li>\n</ul>\n"}, {"fullname": "dftscape.core.JobExecutor.__init__", "modulename": "dftscape.core", "qualname": "JobExecutor.__init__", "kind": "function", "doc": "<p>Initialize the JobExecutor with computational backend and concurrency settings.</p>\n\n<h6 id=\"arguments\">Arguments:</h6>\n\n<ul>\n<li><strong>hisd_runner (HiSDRunner):</strong>  The HiSD runner instance that will execute the\ncomputational jobs. This should implement the HiSDRunner protocol\nand be capable of running HiSD dynamics simulations.</li>\n<li><strong>max_concurrent (int, optional):</strong>  Maximum number of jobs that can execute\nconcurrently. Currently limited to 1 (serial execution), but designed\nfor future parallel execution support. Defaults to 1.</li>\n</ul>\n\n<h6 id=\"raises\">Raises:</h6>\n\n<ul>\n<li><strong>ValueError:</strong>  If max_concurrent is less than 1</li>\n<li><strong>TypeError:</strong>  If hisd_runner doesn't implement HiSDRunner protocol</li>\n</ul>\n\n<h6 id=\"example\">Example:</h6>\n\n<blockquote>\n  <div class=\"pdoc-code codehilite\">\n<pre><span></span><code><span class=\"gp\">&gt;&gt;&gt; </span><span class=\"kn\">from</span><span class=\"w\"> </span><span class=\"nn\">dftscape.core.job_executor</span><span class=\"w\"> </span><span class=\"kn\">import</span> <span class=\"n\">JobExecutor</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">executor</span> <span class=\"o\">=</span> <span class=\"n\">JobExecutor</span><span class=\"p\">(</span><span class=\"n\">hisd_runner</span><span class=\"o\">=</span><span class=\"n\">my_hisd</span><span class=\"p\">,</span> <span class=\"n\">max_concurrent</span><span class=\"o\">=</span><span class=\"mi\">1</span><span class=\"p\">)</span>\n</code></pre>\n  </div>\n</blockquote>\n", "signature": "<span class=\"signature pdoc-code multiline\">(<span class=\"param\">\t<span class=\"n\">hisd_runner</span><span class=\"p\">:</span> <span class=\"n\">dftscape</span><span class=\"o\">.</span><span class=\"n\">core</span><span class=\"o\">.</span><span class=\"n\">interfaces</span><span class=\"o\">.</span><span class=\"n\">HiSDRunner</span>,</span><span class=\"param\">\t<span class=\"n\">max_concurrent</span><span class=\"p\">:</span> <span class=\"nb\">int</span> <span class=\"o\">=</span> <span class=\"mi\">1</span></span>)</span>"}, {"fullname": "dftscape.core.JobExecutor.hisd_runner", "modulename": "dftscape.core", "qualname": "JobExecutor.hisd_runner", "kind": "variable", "doc": "<p></p>\n"}, {"fullname": "dftscape.core.JobExecutor.max_concurrent", "modulename": "dftscape.core", "qualname": "JobExecutor.max_concurrent", "kind": "variable", "doc": "<p></p>\n"}, {"fullname": "dftscape.core.JobExecutor.execute_job", "modulename": "dftscape.core", "qualname": "JobExecutor.execute_job", "kind": "function", "doc": "<p>Execute a single computational job using the configured HiSD runner.</p>\n\n<p>This method handles the complete lifecycle of a single job execution,\nincluding timing, error handling, and result packaging. It delegates\nthe actual computational work to the HiSD runner while providing\ncomprehensive monitoring and error recovery.</p>\n\n<h6 id=\"arguments\">Arguments:</h6>\n\n<ul>\n<li><strong>run_condition (RunCondition):</strong>  The run parameters defining the job,\nincluding initial state, perturbation settings, and convergence\ncriteria for the HiSD dynamics simulation.</li>\n<li><strong>job_id (str):</strong>  Unique identifier for this job, used for logging and\nresult tracking. Should be unique within the current execution context.</li>\n</ul>\n\n<h6 id=\"returns\">Returns:</h6>\n\n<blockquote>\n  <p>JobResult: Complete result object containing:\n      - job_id: The provided job identifier\n      - run_condition: The original run parameters\n      - critical_point: The found critical point (None if failed)\n      - success: Boolean indicating successful completion\n      - error: Error message if execution failed\n      - execution_time: Time taken for job execution in seconds</p>\n</blockquote>\n\n<h6 id=\"raises\">Raises:</h6>\n\n<ul>\n<li>No exceptions are raised - all errors are captured in JobResult</li>\n</ul>\n\n<h6 id=\"example\">Example:</h6>\n\n<blockquote>\n  <div class=\"pdoc-code codehilite\">\n<pre><span></span><code><span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">run_cond</span> <span class=\"o\">=</span> <span class=\"n\">RunCondition</span><span class=\"p\">(</span><span class=\"n\">index</span><span class=\"o\">=</span><span class=\"mi\">1</span><span class=\"p\">,</span> <span class=\"n\">state</span><span class=\"o\">=</span><span class=\"n\">initial_coords</span><span class=\"p\">,</span> <span class=\"o\">...</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">result</span> <span class=\"o\">=</span> <span class=\"n\">executor</span><span class=\"o\">.</span><span class=\"n\">execute_job</span><span class=\"p\">(</span><span class=\"n\">run_cond</span><span class=\"p\">,</span> <span class=\"s2\">&quot;optimization_001&quot;</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"k\">if</span> <span class=\"n\">result</span><span class=\"o\">.</span><span class=\"n\">success</span><span class=\"p\">:</span>\n<span class=\"gp\">... </span>    <span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"sa\">f</span><span class=\"s2\">&quot;Found saddle point at E=</span><span class=\"si\">{</span><span class=\"n\">result</span><span class=\"o\">.</span><span class=\"n\">critical_point</span><span class=\"o\">.</span><span class=\"n\">energy</span><span class=\"si\">:</span><span class=\"s2\">.4f</span><span class=\"si\">}</span><span class=\"s2\">&quot;</span><span class=\"p\">)</span>\n<span class=\"gp\">... </span>    <span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"sa\">f</span><span class=\"s2\">&quot;Execution time: </span><span class=\"si\">{</span><span class=\"n\">result</span><span class=\"o\">.</span><span class=\"n\">execution_time</span><span class=\"si\">:</span><span class=\"s2\">.2f</span><span class=\"si\">}</span><span class=\"s2\">s&quot;</span><span class=\"p\">)</span>\n<span class=\"gp\">... </span><span class=\"k\">else</span><span class=\"p\">:</span>\n<span class=\"gp\">... </span>    <span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"sa\">f</span><span class=\"s2\">&quot;Job failed: </span><span class=\"si\">{</span><span class=\"n\">result</span><span class=\"o\">.</span><span class=\"n\">error</span><span class=\"si\">}</span><span class=\"s2\">&quot;</span><span class=\"p\">)</span>\n</code></pre>\n  </div>\n</blockquote>\n\n<h6 id=\"notes\">Notes:</h6>\n\n<blockquote>\n  <ul>\n  <li>Execution time includes all overhead (setup, computation, cleanup)</li>\n  <li>HiSD convergence failures are treated as normal failures, not exceptions</li>\n  <li>All exceptions during execution are caught and returned in JobResult</li>\n  <li>Logging provides detailed execution information for debugging</li>\n  </ul>\n</blockquote>\n", "signature": "<span class=\"signature pdoc-code multiline\">(<span class=\"param\">\t<span class=\"bp\">self</span>,</span><span class=\"param\">\t<span class=\"n\">run_condition</span><span class=\"p\">:</span> <span class=\"n\">dftscape</span><span class=\"o\">.</span><span class=\"n\">core</span><span class=\"o\">.</span><span class=\"n\">search_primitives</span><span class=\"o\">.</span><span class=\"n\">RunCondition</span>,</span><span class=\"param\">\t<span class=\"n\">job_id</span><span class=\"p\">:</span> <span class=\"nb\">str</span></span><span class=\"return-annotation\">) -> <span class=\"n\">dftscape</span><span class=\"o\">.</span><span class=\"n\">core</span><span class=\"o\">.</span><span class=\"n\">job_result</span><span class=\"o\">.</span><span class=\"n\">JobResult</span>:</span></span>", "funcdef": "def"}, {"fullname": "dftscape.core.JobExecutor.execute_batch", "modulename": "dftscape.core", "qualname": "JobExecutor.execute_batch", "kind": "function", "doc": "<p>Execute a batch of computational jobs sequentially.</p>\n\n<p>This method provides batch processing capabilities for multiple jobs,\nexecuting them one after another and collecting all results. Currently\nimplements serial execution, but is designed for future parallelization\nbased on the max_concurrent setting.</p>\n\n<h6 id=\"arguments\">Arguments:</h6>\n\n<ul>\n<li><strong>jobs (List[Tuple[str, RunCondition]]):</strong>  List of (job_id, run_condition)\npairs to execute. Each tuple contains:\n<ul>\n<li>job_id (str): Unique identifier for the job</li>\n<li>run_condition (RunCondition): Parameters for the job execution</li>\n</ul></li>\n</ul>\n\n<h6 id=\"returns\">Returns:</h6>\n\n<blockquote>\n  <p>List[JobResult]: List of JobResult objects in the same order as input jobs.\n      Each result contains complete execution information including success\n      status, execution time, and any errors encountered.</p>\n</blockquote>\n\n<h6 id=\"example\">Example:</h6>\n\n<blockquote>\n  <div class=\"pdoc-code codehilite\">\n<pre><span></span><code><span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Prepare batch of jobs</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">jobs</span> <span class=\"o\">=</span> <span class=\"p\">[</span>\n<span class=\"gp\">... </span>    <span class=\"p\">(</span><span class=\"s2\">&quot;saddle_search_1&quot;</span><span class=\"p\">,</span> <span class=\"n\">RunCondition</span><span class=\"p\">(</span><span class=\"n\">index</span><span class=\"o\">=</span><span class=\"mi\">1</span><span class=\"p\">,</span> <span class=\"n\">state</span><span class=\"o\">=</span><span class=\"n\">state1</span><span class=\"p\">,</span> <span class=\"o\">...</span><span class=\"p\">)),</span>\n<span class=\"gp\">... </span>    <span class=\"p\">(</span><span class=\"s2\">&quot;saddle_search_2&quot;</span><span class=\"p\">,</span> <span class=\"n\">RunCondition</span><span class=\"p\">(</span><span class=\"n\">index</span><span class=\"o\">=</span><span class=\"mi\">1</span><span class=\"p\">,</span> <span class=\"n\">state</span><span class=\"o\">=</span><span class=\"n\">state2</span><span class=\"p\">,</span> <span class=\"o\">...</span><span class=\"p\">)),</span>\n<span class=\"gp\">... </span>    <span class=\"p\">(</span><span class=\"s2\">&quot;min_search_1&quot;</span><span class=\"p\">,</span> <span class=\"n\">RunCondition</span><span class=\"p\">(</span><span class=\"n\">index</span><span class=\"o\">=</span><span class=\"mi\">0</span><span class=\"p\">,</span> <span class=\"n\">state</span><span class=\"o\">=</span><span class=\"n\">state3</span><span class=\"p\">,</span> <span class=\"o\">...</span><span class=\"p\">))</span>\n<span class=\"gp\">... </span><span class=\"p\">]</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Execute batch</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">results</span> <span class=\"o\">=</span> <span class=\"n\">executor</span><span class=\"o\">.</span><span class=\"n\">execute_batch</span><span class=\"p\">(</span><span class=\"n\">jobs</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Analyze results</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">successful</span> <span class=\"o\">=</span> <span class=\"p\">[</span><span class=\"n\">r</span> <span class=\"k\">for</span> <span class=\"n\">r</span> <span class=\"ow\">in</span> <span class=\"n\">results</span> <span class=\"k\">if</span> <span class=\"n\">r</span><span class=\"o\">.</span><span class=\"n\">success</span><span class=\"p\">]</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">failed</span> <span class=\"o\">=</span> <span class=\"p\">[</span><span class=\"n\">r</span> <span class=\"k\">for</span> <span class=\"n\">r</span> <span class=\"ow\">in</span> <span class=\"n\">results</span> <span class=\"k\">if</span> <span class=\"ow\">not</span> <span class=\"n\">r</span><span class=\"o\">.</span><span class=\"n\">success</span><span class=\"p\">]</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"sa\">f</span><span class=\"s2\">&quot;Batch complete: </span><span class=\"si\">{</span><span class=\"nb\">len</span><span class=\"p\">(</span><span class=\"n\">successful</span><span class=\"p\">)</span><span class=\"si\">}</span><span class=\"s2\">/</span><span class=\"si\">{</span><span class=\"nb\">len</span><span class=\"p\">(</span><span class=\"n\">results</span><span class=\"p\">)</span><span class=\"si\">}</span><span class=\"s2\"> successful&quot;</span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Process successful results</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"k\">for</span> <span class=\"n\">result</span> <span class=\"ow\">in</span> <span class=\"n\">successful</span><span class=\"p\">:</span>\n<span class=\"gp\">... </span>    <span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"sa\">f</span><span class=\"s2\">&quot;Job </span><span class=\"si\">{</span><span class=\"n\">result</span><span class=\"o\">.</span><span class=\"n\">job_id</span><span class=\"si\">}</span><span class=\"s2\">: E=</span><span class=\"si\">{</span><span class=\"n\">result</span><span class=\"o\">.</span><span class=\"n\">critical_point</span><span class=\"o\">.</span><span class=\"n\">energy</span><span class=\"si\">:</span><span class=\"s2\">.4f</span><span class=\"si\">}</span><span class=\"s2\">&quot;</span><span class=\"p\">)</span>\n</code></pre>\n  </div>\n</blockquote>\n\n<h6 id=\"notes\">Notes:</h6>\n\n<blockquote>\n  <ul>\n  <li>Jobs are executed in the order provided</li>\n  <li>Currently uses serial execution (one job at a time)</li>\n  <li>Future versions will support parallel execution based on max_concurrent</li>\n  <li>All jobs in the batch are attempted, regardless of individual failures</li>\n  <li>Results maintain the same ordering as input jobs for easy correlation</li>\n  <li>Execution times are tracked per job for performance analysis</li>\n  </ul>\n</blockquote>\n", "signature": "<span class=\"signature pdoc-code multiline\">(<span class=\"param\">\t<span class=\"bp\">self</span>,</span><span class=\"param\">\t<span class=\"n\">jobs</span><span class=\"p\">:</span> <span class=\"n\">List</span><span class=\"p\">[</span><span class=\"nb\">tuple</span><span class=\"p\">[</span><span class=\"nb\">str</span><span class=\"p\">,</span> <span class=\"n\">dftscape</span><span class=\"o\">.</span><span class=\"n\">core</span><span class=\"o\">.</span><span class=\"n\">search_primitives</span><span class=\"o\">.</span><span class=\"n\">RunCondition</span><span class=\"p\">]]</span></span><span class=\"return-annotation\">) -> <span class=\"n\">List</span><span class=\"p\">[</span><span class=\"n\">dftscape</span><span class=\"o\">.</span><span class=\"n\">core</span><span class=\"o\">.</span><span class=\"n\">job_result</span><span class=\"o\">.</span><span class=\"n\">JobResult</span><span class=\"p\">]</span>:</span></span>", "funcdef": "def"}, {"fullname": "dftscape.core.SearchOrchestratorRegistry", "modulename": "dftscape.core", "qualname": "SearchOrchestratorRegistry", "kind": "class", "doc": "<p>Registry for search orchestrator implementations.</p>\n\n<p>This registry provides a centralized system for managing different search\norchestrator implementations, enabling dynamic instantiation and configuration\nof orchestrators by name. It extends the BaseRegistry to provide type-safe\norchestrator creation and management.</p>\n\n<p>The registry supports:</p>\n\n<ul>\n<li><strong>Dynamic Instantiation</strong>: Create orchestrators by registered name</li>\n<li><strong>Type Safety</strong>: Generic typing for SearchOrchestrator instances</li>\n<li><strong>Extensibility</strong>: Easy registration of new orchestrator implementations</li>\n<li><strong>Configuration Management</strong>: Pass-through of initialization parameters</li>\n</ul>\n\n<p>Currently registered orchestrators:</p>\n\n<ul>\n<li>\"serial\": Standard serial execution SearchOrchestrator</li>\n</ul>\n\n<h6 id=\"usage-examples\">Usage Examples:</h6>\n\n<blockquote>\n  <div class=\"pdoc-code codehilite\">\n<pre><span></span><code><span class=\"gp\">&gt;&gt;&gt; </span><span class=\"kn\">from</span><span class=\"w\"> </span><span class=\"nn\">dftscape.core.search_orchestrator</span><span class=\"w\"> </span><span class=\"kn\">import</span> <span class=\"n\">SearchOrchestratorRegistry</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"kn\">from</span><span class=\"w\"> </span><span class=\"nn\">dftscape.core.graph</span><span class=\"w\"> </span><span class=\"kn\">import</span> <span class=\"n\">SearchableCriticalPointGraph</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"kn\">from</span><span class=\"w\"> </span><span class=\"nn\">dftscape.core.job_queues</span><span class=\"w\"> </span><span class=\"kn\">import</span> <span class=\"n\">JobQueues</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Create orchestrator by name</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">orchestrator</span> <span class=\"o\">=</span> <span class=\"n\">SearchOrchestratorRegistry</span><span class=\"o\">.</span><span class=\"n\">create</span><span class=\"p\">(</span>\n<span class=\"gp\">... </span>    <span class=\"s2\">&quot;serial&quot;</span><span class=\"p\">,</span>\n<span class=\"gp\">... </span>    <span class=\"n\">graph</span><span class=\"o\">=</span><span class=\"n\">SearchableCriticalPointGraph</span><span class=\"p\">(</span><span class=\"o\">...</span><span class=\"p\">),</span>\n<span class=\"gp\">... </span>    <span class=\"n\">job_queues</span><span class=\"o\">=</span><span class=\"n\">JobQueues</span><span class=\"p\">(),</span>\n<span class=\"gp\">... </span>    <span class=\"n\">hisd_runner</span><span class=\"o\">=</span><span class=\"n\">HiSDRunner</span><span class=\"p\">(</span><span class=\"o\">...</span><span class=\"p\">)</span>\n<span class=\"gp\">... </span><span class=\"p\">)</span>\n<span class=\"gp\">&gt;&gt;&gt;</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Verify type</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"nb\">isinstance</span><span class=\"p\">(</span><span class=\"n\">orchestrator</span><span class=\"p\">,</span> <span class=\"n\">SearchOrchestrator</span><span class=\"p\">)</span>\n<span class=\"go\">True</span>\n</code></pre>\n  </div>\n</blockquote>\n\n<h6 id=\"registration-example\">Registration Example:</h6>\n\n<blockquote>\n  <div class=\"pdoc-code codehilite\">\n<pre><span></span><code><span class=\"gp\">&gt;&gt;&gt; </span><span class=\"c1\"># Register a custom orchestrator</span>\n<span class=\"gp\">&gt;&gt;&gt; </span><span class=\"nd\">@SearchOrchestratorRegistry</span><span class=\"o\">.</span><span class=\"n\">register</span><span class=\"p\">(</span><span class=\"s2\">&quot;parallel&quot;</span><span class=\"p\">)</span>\n<span class=\"gp\">... </span><span class=\"k\">class</span><span class=\"w\"> </span><span class=\"nc\">ParallelSearchOrchestrator</span><span class=\"p\">(</span><span class=\"n\">SearchOrchestrator</span><span class=\"p\">):</span>\n<span class=\"gp\">... </span>    <span class=\"k\">def</span><span class=\"w\"> </span><span class=\"fm\">__init__</span><span class=\"p\">(</span><span class=\"bp\">self</span><span class=\"p\">,</span> <span class=\"o\">*</span><span class=\"n\">args</span><span class=\"p\">,</span> <span class=\"n\">max_workers</span><span class=\"o\">=</span><span class=\"mi\">4</span><span class=\"p\">,</span> <span class=\"o\">**</span><span class=\"n\">kwargs</span><span class=\"p\">):</span>\n<span class=\"gp\">... </span>        <span class=\"nb\">super</span><span class=\"p\">()</span><span class=\"o\">.</span><span class=\"fm\">__init__</span><span class=\"p\">(</span><span class=\"o\">*</span><span class=\"n\">args</span><span class=\"p\">,</span> <span class=\"o\">**</span><span class=\"n\">kwargs</span><span class=\"p\">)</span>\n<span class=\"gp\">... </span>        <span class=\"bp\">self</span><span class=\"o\">.</span><span class=\"n\">max_workers</span> <span class=\"o\">=</span> <span class=\"n\">max_workers</span>\n</code></pre>\n  </div>\n</blockquote>\n\n<h6 id=\"notes\">Notes:</h6>\n\n<blockquote>\n  <ul>\n  <li>Registry inherits from BaseRegistry for core functionality</li>\n  <li>The \"serial\" orchestrator is pre-registered and available by default</li>\n  <li>Custom orchestrators can be registered using the @register decorator</li>\n  <li>All initialization parameters are passed through to the orchestrator constructor</li>\n  </ul>\n</blockquote>\n", "bases": "dftscape.common.registry.BaseRegistry[ForwardRef('SearchOrchestrator')]"}, {"fullname": "dftscape.core.SearchOrchestratorRegistry.create", "modulename": "dftscape.core", "qualname": "SearchOrchestratorRegistry.create", "kind": "function", "doc": "<p>Create an instance of a search orchestrator by name.</p>\n\n<p>This method instantiates a registered orchestrator implementation,\npassing through all provided arguments to the constructor.</p>\n\n<h6 id=\"arguments\">Arguments:</h6>\n\n<ul>\n<li><strong>name:</strong>  Name of the registered orchestrator implementation</li>\n<li><strong>*args:</strong>  Positional arguments to pass to the orchestrator constructor</li>\n<li><strong>**kwargs:</strong>  Keyword arguments to pass to the orchestrator constructor</li>\n</ul>\n\n<h6 id=\"returns\">Returns:</h6>\n\n<blockquote>\n  <p>SearchOrchestrator: Instantiated orchestrator instance</p>\n</blockquote>\n\n<h6 id=\"raises\">Raises:</h6>\n\n<ul>\n<li><strong>ValueError:</strong>  If the specified orchestrator name is not registered</li>\n<li><strong>TypeError:</strong>  If constructor arguments are invalid</li>\n</ul>\n\n<h6 id=\"example\">Example:</h6>\n\n<blockquote>\n  <div class=\"pdoc-code codehilite\">\n<pre><span></span><code><span class=\"gp\">&gt;&gt;&gt; </span><span class=\"n\">orchestrator</span> <span class=\"o\">=</span> <span class=\"n\">SearchOrchestratorRegistry</span><span class=\"o\">.</span><span class=\"n\">create</span><span class=\"p\">(</span>\n<span class=\"gp\">... </span>    <span class=\"s2\">&quot;serial&quot;</span><span class=\"p\">,</span>\n<span class=\"gp\">... </span>    <span class=\"n\">graph</span><span class=\"o\">=</span><span class=\"n\">my_graph</span><span class=\"p\">,</span>\n<span class=\"gp\">... </span>    <span class=\"n\">job_queues</span><span class=\"o\">=</span><span class=\"n\">my_queues</span><span class=\"p\">,</span>\n<span class=\"gp\">... </span>    <span class=\"n\">hisd_runner</span><span class=\"o\">=</span><span class=\"n\">my_runner</span><span class=\"p\">,</span>\n<span class=\"gp\">... </span>    <span class=\"n\">d_max</span><span class=\"o\">=</span><span class=\"mi\">5</span>\n<span class=\"gp\">... </span><span class=\"p\">)</span>\n</code></pre>\n  </div>\n</blockquote>\n", "signature": "<span class=\"signature pdoc-code multiline\">(<span class=\"param\">\t<span class=\"bp\">cls</span>,</span><span class=\"param\">\t<span class=\"n\">name</span><span class=\"p\">:</span> <span class=\"nb\">str</span>,</span><span class=\"param\">\t<span class=\"o\">*</span><span class=\"n\">args</span>,</span><span class=\"param\">\t<span class=\"o\">**</span><span class=\"n\">kwargs</span></span><span class=\"return-annotation\">) -> <span class=\"n\">dftscape</span><span class=\"o\">.</span><span class=\"n\">core</span><span class=\"o\">.</span><span class=\"n\">search_orchestrator</span><span class=\"o\">.</span><span class=\"n\">SearchOrchestrator</span>:</span></span>", "funcdef": "def"}];

    // mirrored in build-search-index.js (part 1)
    // Also split on html tags. this is a cheap heuristic, but good enough.
    elasticlunr.tokenizer.setSeperator(/[\s\-.;&_'"=,()]+|<[^>]*>/);

    let searchIndex;
    if (docs._isPrebuiltIndex) {
        console.info("using precompiled search index");
        searchIndex = elasticlunr.Index.load(docs);
    } else {
        console.time("building search index");
        // mirrored in build-search-index.js (part 2)
        searchIndex = elasticlunr(function () {
            this.pipeline.remove(elasticlunr.stemmer);
            this.pipeline.remove(elasticlunr.stopWordFilter);
            this.addField("qualname");
            this.addField("fullname");
            this.addField("annotation");
            this.addField("default_value");
            this.addField("signature");
            this.addField("bases");
            this.addField("doc");
            this.setRef("fullname");
        });
        for (let doc of docs) {
            searchIndex.addDoc(doc);
        }
        console.timeEnd("building search index");
    }

    return (term) => searchIndex.search(term, {
        fields: {
            qualname: {boost: 4},
            fullname: {boost: 2},
            annotation: {boost: 2},
            default_value: {boost: 2},
            signature: {boost: 2},
            bases: {boost: 2},
            doc: {boost: 1},
        },
        expand: true
    });
